const e=[{id:"williams-learning-the-law",title:"Glanville Williams: Learning the Law",author:"Glanville Williams",editor:"A. T. H. Smith",edition:"18th",publisher:"Sweet & Maxwell",role:"method",tier:0,modules:["m00-foundations","m02-legal-research","m13-legal-reasoning"],jurisdictionFocus:"England & Wales",verified:"confirmed",studentEdition:!1,notes:"Covers reading statutes and case law, solving legal problems, study methods, exam prep, legal research. English legal system framing, but the method transfers to Malaysia. Highest-priority purchase.",priority:1},{id:"mcbride-letters",title:"Letters to a Law Student",author:"Nicholas J. McBride",edition:null,publisher:"Pearson",role:"method",tier:0,modules:["m00-foundations"],jurisdictionFocus:"England & Wales",verified:"unconfirmed",notes:"Informal guide to reading, arguing and structuring legal answers. Good motivational entry point.",priority:2},{id:"mckinney-reading-like-a-lawyer",title:"Reading Like a Lawyer: Time-Saving Strategies for Reading Law Like an Expert",author:"Ruth Ann McKinney",edition:null,publisher:"Carolina Academic Press",role:"method",tier:0,modules:["m00-foundations","m02-legal-research"],jurisdictionFocus:"US (skill-transferable)",verified:"unconfirmed",notes:"Directly addresses the novice/expert legal reading gap identified in the research (Deegan; Christensen). Read early and re-read.",priority:3},{id:"schauer-thinking-like-a-lawyer",title:"Thinking Like a Lawyer: A New Introduction to Legal Reasoning",author:"Frederick Schauer",edition:null,publisher:"Harvard University Press",role:"method",tier:0,modules:["m13-legal-reasoning","m14-statutory-interpretation"],jurisdictionFocus:"General common law",verified:"unconfirmed",notes:"Precedent, analogy, authority, rules. Read AFTER briefing several cases, not before.",priority:6},{id:"bingham-rule-of-law",title:"The Rule of Law",author:"Tom Bingham",edition:null,publisher:"Penguin",role:"context",tier:0,modules:["m00-foundations","m03-constitutional"],jurisdictionFocus:"England & Wales",verified:"unconfirmed",notes:"Short, plain-language entry into public law thinking. Cheap.",priority:7},{id:"make-it-stick",title:"Make It Stick: The Science of Successful Learning",author:"Peter C. Brown, Henry L. Roediger III, Mark A. McDaniel",edition:null,publisher:"Harvard University Press",role:"method",tier:0,modules:["m-study-method"],jurisdictionFocus:null,verified:"unconfirmed",notes:"Retrieval practice and spacing evidence in readable form. Read before building any flashcards.",priority:4},{id:"ashgar-malaysian-legal-system",title:"Malaysian Legal System",author:"Various contributors",editor:"Ashgar Ali Ali Mohamed (General Editor)",edition:"2nd",publisher:"CLJ Publication",role:"primary",tier:1,modules:["m01-malaysian-legal-system"],jurisdictionFocus:"MY",verified:"confirmed",notes:"36 chapters, multi-author, incorporating recent updates on the Malaysian legal system. More current than Wu Min Aun.",priority:5},{id:"wu-malaysian-legal-system",title:"The Malaysian Legal System",author:"Wu Min Aun",edition:"3rd",publisher:"Pearson Malaysia",year:2005,isbn:"9789837436565",role:"reference",tier:1,modules:["m01-malaysian-legal-system"],jurisdictionFocus:"MY",verified:"confirmed",staleness:"high",notes:"Still the most-cited student text on Malaysian LLB reading lists, but 20 years old. Use for structure and legal history only. DO NOT rely on it for current law.",priority:12},{id:"wan-arfah-first-look",title:"A First Look at the Malaysian Legal System",author:"Wan Arfah Hamzah",edition:null,publisher:"Oxford Fajar",role:"primary",tier:1,modules:["m01-malaysian-legal-system"],jurisdictionFocus:"MY",verified:"unconfirmed",notes:"Gentler entry point than Wu or Ashgar. Verify current edition.",priority:13},{id:"faruqi-our-constitution",title:"Our Constitution",author:"Shad Saleem Faruqi",edition:"1st",publisher:"Sweet & Maxwell",year:2019,isbn:"9789672187059",format:"Paperback",priceMYR:50,role:"primary",tier:3,modules:["m03-constitutional"],jurisdictionFocus:"MY",verified:"confirmed",notes:"9 parts, 36 chapters: characteristics of the Federal Constitution, separation of powers, fundamental liberties, citizenship, Conference of Rulers, Yang di-Pertuan Agong, ministerial responsibility, making of laws, judiciary, electoral process, powers to combat subversion. Written for the general reader — ideal starting point.",priority:8},{id:"faruqi-document-of-destiny",title:"Document of Destiny: The Constitution of the Federation of Malaysia",author:"Shad Saleem Faruqi",edition:null,publisher:"Star Publications / Thomson Reuters",role:"reference",tier:3,modules:["m03-constitutional"],jurisdictionFocus:"MY",verified:"unconfirmed",notes:"The deep treatment. Buy after Our Constitution. Author was reported to be updating this — check for a newer edition.",priority:20},{id:"yeo-morgan-chan-criminal-law",title:"Criminal Law in Malaysia and Singapore",author:"Stanley Yeo, Neil Morgan, Chan Wing Cheong",edition:null,publisher:"LexisNexis",role:"primary",tier:4,modules:["m04-criminal-law"],jurisdictionFocus:"MY/SG",verified:"unconfirmed",notes:"Leading academic treatment of the Penal Code. VERIFY CURRENT EDITION — must post-date the Abolition of Mandatory Death Penalty Act 2023.",priority:14},{id:"janab-criminal-procedure",title:"Janab's Key to Criminal Procedure",author:"Hamid Sultan bin Abu Backer",editor:"Mah Weng Kwai, Ravinthran Paramaguru (revising editors)",edition:"4th",publisher:"Janab (M) Sdn Bhd",year:2018,isbn:"9789839880212",format:"Hardcover",pages:832,role:"primary",tier:5,modules:["m05-criminal-procedure"],jurisdictionFocus:"MY",verified:"confirmed",staleness:"medium",notes:"Two parts: criminal procedure in 70 sub-chapters, plus commentary on all 445 CPC sections. Includes MY/SG/India comparison chart. Updated only to Q3 2018 — does NOT include the 2023 death-penalty reforms. Verify all sentencing separately.",priority:15},{id:"cheong-contract-law-malaysia",title:"Contract Law in Malaysia",author:"Cheong May Fong, Choong Shaw Mei, Yong Kai Jie",edition:"2nd",publisher:"Sweet & Maxwell",year:2025,publicationDate:"2025-11-15",isbn:"9786297700892",role:"primary",tier:6,modules:["m06-contract"],jurisdictionFocus:"MY",verified:"confirmed",studentEdition:!0,notes:"Most current major Malaysian doctrinal text available. Covers the full contract life cycle: formation, terms, voidable contracts, void agreements, discharge, remedies. Case law updated from 2010 onwards with Federal Court decisions. ASK FOR THE STUDENT EDITION — substantially cheaper.",priority:9},{id:"sinnadurai-law-of-contract",title:"The Law of Contract",author:"Visu Sinnadurai",edition:"5th",publisher:"LexisNexis",role:"reference",tier:6,modules:["m06-contract"],jurisdictionFocus:"MY",verified:"confirmed",notes:"The leading Malaysian contract treatise; first port of call for students, practitioners and judges. Reference work, not a first read. Companion: Contracts Act: A Commentary (2015).",priority:21},{id:"norchaya-torts",title:"Norchaya Talib on Torts in Malaysia",author:"Norchaya Talib (original)",editor:"Ahnaf Azmi and expert contributors",edition:"4th",publisher:"Sweet & Maxwell",year:2021,publicationDate:"2021-10",isbn:"9789672919650",format:"Softcover",role:"primary",tier:7,modules:["m07-tort"],jurisdictionFocus:"MY",verified:"confirmed",studentEdition:!0,notes:"Negligence, nuisance, trespass, strict liability, defamation. New material: tort of harassment, defence of illegality, exclusion clauses, damages, developments in defamation, extension of vicarious liability. Student Edition available.",priority:10},{id:"teo-khaw-land-law",title:"Land Law in Malaysia: Cases and Commentary",author:"Teo Keang Sood, Khaw Lake Tee",edition:null,publisher:"LexisNexis",role:"primary",tier:8,modules:["m08-property"],jurisdictionFocus:"MY",verified:"unconfirmed",notes:"VERIFY CURRENT EDITION before buying.",priority:22},{id:"salleh-buang-torrens",title:"Malaysian Torrens System",author:"Salleh Buang",edition:null,publisher:"Dewan Bahasa dan Pustaka",role:"reference",tier:8,modules:["m08-property"],jurisdictionFocus:"MY",verified:"unconfirmed",notes:"VERIFY CURRENT EDITION.",priority:23},{id:"companies-act-annotation",title:"Companies Act of Malaysia: An Annotation (Desk Edition)",author:null,edition:"2024 Desk Edition",publisher:null,year:2024,role:"reference",tier:9,modules:["m09-company"],jurisdictionFocus:"MY",verified:"unconfirmed",notes:"Seen listed as a current annotation by Malaysian law booksellers; publisher and author details need checking. NOTE: Walter Woon on Company Law is SINGAPORE law — do not substitute it.",priority:24},{id:"malaysian-law-of-evidence-student",title:"Malaysian Law of Evidence (Student Edition)",author:null,edition:null,publisher:"Sweet & Maxwell",role:"primary",tier:10,modules:["m10-evidence"],jurisdictionFocus:"MY",verified:"confirmed",studentEdition:!0,notes:"Case law updated to July 2023. Covers documentary evidence in depth, child witnesses including the 2023 amendments to the Evidence of Child Witness Act 2007 and the Sexual Offences Against Children Act 2017. Most current student evidence option found. Author/edition details need confirming with the bookseller.",priority:11},{id:"mazlina-law-of-evidence",title:"Law of Evidence in Malaysia",author:"Mazlina Mahali",edition:"2nd",publisher:"Sweet & Maxwell",isbn:"9789672187370",role:"primary",tier:10,modules:["m10-evidence"],jurisdictionFocus:"MY",verified:"confirmed",notes:"Explicitly aimed at undergraduates and CLP candidates. Explains differences between common law and the Malaysian position under the Evidence Act 1950.",priority:16},{id:"sarkar-evidence-malaysia",title:"Sarkar's Law of Evidence (Second Malaysia Edition)",author:"Sarkar",edition:"2nd Malaysia Edition",publisher:"LexisNexis",volumes:3,role:"reference",tier:10,modules:["m10-evidence"],jurisdictionFocus:"MY/India",verified:"confirmed",notes:"Places the Evidence Act 1950 within Sarkar's scheme; Malaysian provisions and commentary follow the corresponding Indian sections. Updated to August 2019. Expensive 3-volume reference — skip unless going deep.",priority:30},{id:"janab-civil-procedure",title:"Janab's Key to Civil Procedure",author:"Hamid Sultan bin Abu Backer",editor:"Mah Weng Kwai, Arun Kasi (revising editors)",edition:"6th",publisher:"Janab (M) Sdn Bhd",role:"primary",tier:11,modules:["m11-civil-procedure"],jurisdictionFocus:"MY",verified:"confirmed",staleness:"medium",notes:"Readable introduction to civil procedure. Updated to Q3 2018 — check Rules of Court amendments since.",priority:17},{id:"malaysian-civil-procedure-white-book",title:"Malaysian Civil Procedure (the 'White Book')",author:null,edition:"Current year",publisher:"Sweet & Maxwell",role:"reference",tier:11,modules:["m11-civil-procedure"],jurisdictionFocus:"MY",verified:"confirmed",notes:"The practitioner's authoritative annotation of the Rules of Court 2012. Published annually. Expensive — buy the current year only if budget allows.",priority:31},{id:"wade-forsyth-admin-law",title:"Administrative Law",author:"William Wade, Christopher Forsyth",edition:null,publisher:"Oxford University Press",role:"primary",tier:12,modules:["m12-administrative"],jurisdictionFocus:"England & Wales",verified:"unconfirmed",notes:"INTERIM SUBSTITUTE. No dominant current Malaysian student text on administrative law was found. Use an English text for principles (legality, procedural fairness, natural justice, legitimate expectation, reasonableness, ultra vires) and read Malaysian judicial review judgments directly for the local position. Flagged gap — revisit.",priority:25}],t=[{id:"federal-constitution",title:"Federal Constitution of Malaysia",citation:null,modules:["m01-malaysian-legal-system","m03-constitutional"],source:"https://lom.agc.gov.my",cost:"free",notes:"Also available as a printed reprint from PNMB/ILBS — worth buying for annotation."},{id:"contracts-act-1950",title:"Contracts Act 1950",citation:"Act 136",modules:["m06-contract"],source:"https://lom.agc.gov.my",cost:"free",notes:"In pari materia with the Indian Contract Act 1872. Read section by section alongside Cheong."},{id:"penal-code",title:"Penal Code",citation:"Act 574",modules:["m04-criminal-law"],source:"https://lom.agc.gov.my",cost:"free",notes:"Amended by the Abolition of Mandatory Death Penalty Act 2023 (Act 846), effective 4 July 2023."},{id:"criminal-procedure-code",title:"Criminal Procedure Code",citation:"Act 593",modules:["m05-criminal-procedure"],source:"https://lom.agc.gov.my",cost:"free",notes:"Also amended by Act 846 (2023)."},{id:"evidence-act-1950",title:"Evidence Act 1950",citation:"Act 56",modules:["m10-evidence"],source:"https://lom.agc.gov.my",cost:"free",notes:"3 Parts, 11 chapters, 167 sections. Part I Relevancy, Part II Proof, Part III Production and Effect of Evidence."},{id:"rules-of-court-2012",title:"Rules of Court 2012",citation:null,modules:["m11-civil-procedure"],source:"https://lom.agc.gov.my",cost:"free"},{id:"companies-act-2016",title:"Companies Act 2016",citation:"Act 777",modules:["m09-company"],source:"https://lom.agc.gov.my",cost:"free"},{id:"national-land-code",title:"National Land Code",citation:"Act 828",modules:["m08-property"],source:"https://lom.agc.gov.my",cost:"free",notes:"Confirm current Act number after revision."},{id:"interpretation-acts",title:"Interpretation Acts 1948 and 1967",citation:"Act 388",modules:["m14-statutory-interpretation"],source:"https://lom.agc.gov.my",cost:"free",notes:"Essential for the statutory interpretation module."},{id:"civil-law-act-1956",title:"Civil Law Act 1956",citation:"Act 67",modules:["m01-malaysian-legal-system"],source:"https://lom.agc.gov.my",cost:"free",notes:"Governs the reception of English common law and equity into Malaysia."},{id:"courts-of-judicature-act-1964",title:"Courts of Judicature Act 1964",citation:"Act 91",modules:["m01-malaysian-legal-system"],source:"https://lom.agc.gov.my",cost:"free",notes:"Superior court jurisdiction. Pair with the Subordinate Courts Act 1948."},{id:"subordinate-courts-act-1948",title:"Subordinate Courts Act 1948",citation:"Act 92",modules:["m01-malaysian-legal-system"],source:"https://lom.agc.gov.my",cost:"free"}],a=[{id:"m-study-method",level:null,title:"How to Study Law",primary:["williams-learning-the-law","make-it-stick"],reference:["mckinney-reading-like-a-lawyer"],statutes:[]},{id:"m00-foundations",level:0,title:"Legal Foundations",primary:["williams-learning-the-law","mcbride-letters"],reference:["bingham-rule-of-law","mckinney-reading-like-a-lawyer"],statutes:[]},{id:"m01-malaysian-legal-system",level:1,title:"The Malaysian Legal System",primary:["ashgar-malaysian-legal-system","wan-arfah-first-look"],reference:["wu-malaysian-legal-system"],statutes:["federal-constitution","civil-law-act-1956","courts-of-judicature-act-1964","subordinate-courts-act-1948"]},{id:"m02-legal-research",level:2,title:"Legal Research",primary:["williams-learning-the-law"],reference:["mckinney-reading-like-a-lawyer"],statutes:[]},{id:"m03-constitutional",level:3,title:"Constitutional Law",primary:["faruqi-our-constitution"],reference:["faruqi-document-of-destiny","bingham-rule-of-law"],statutes:["federal-constitution"]},{id:"m04-criminal-law",level:4,title:"Criminal Law",primary:["yeo-morgan-chan-criminal-law"],reference:[],statutes:["penal-code"]},{id:"m05-criminal-procedure",level:5,title:"Criminal Procedure",primary:["janab-criminal-procedure"],reference:[],statutes:["criminal-procedure-code"]},{id:"m06-contract",level:6,title:"Contract Law",primary:["cheong-contract-law-malaysia"],reference:["sinnadurai-law-of-contract"],statutes:["contracts-act-1950"]},{id:"m07-tort",level:7,title:"Tort Law",primary:["norchaya-torts"],reference:[],statutes:[]},{id:"m08-property",level:8,title:"Property Law",primary:["teo-khaw-land-law"],reference:["salleh-buang-torrens"],statutes:["national-land-code"]},{id:"m09-company",level:9,title:"Company & Commercial Law",primary:[],reference:["companies-act-annotation"],statutes:["companies-act-2016"]},{id:"m10-evidence",level:10,title:"Evidence",primary:["malaysian-law-of-evidence-student","mazlina-law-of-evidence"],reference:["sarkar-evidence-malaysia"],statutes:["evidence-act-1950"]},{id:"m11-civil-procedure",level:11,title:"Civil Procedure",primary:["janab-civil-procedure"],reference:["malaysian-civil-procedure-white-book"],statutes:["rules-of-court-2012"]},{id:"m12-administrative",level:12,title:"Administrative Law",primary:["wade-forsyth-admin-law"],reference:[],statutes:[],gap:"No current Malaysian student text identified. Read Malaysian judicial review judgments directly."},{id:"m13-legal-reasoning",level:13,title:"Advanced Legal Reasoning",primary:["schauer-thinking-like-a-lawyer"],reference:["williams-learning-the-law"],statutes:[]},{id:"m14-statutory-interpretation",level:14,title:"Statutory Interpretation",primary:["schauer-thinking-like-a-lawyer"],reference:[],statutes:["interpretation-acts"]},{id:"m15-equity-trusts",level:15,title:"Equity and Trusts",primary:[],reference:[],statutes:["civil-law-act-1956"]},{id:"m16-family",level:16,title:"Family Law",primary:[],reference:[],statutes:[]},{id:"m17-syariah",level:17,title:"Syariah Law",primary:[],reference:[],statutes:["federal-constitution"]},{id:"m18-jurisprudence",level:18,title:"Jurisprudence",primary:[],reference:[],statutes:[]},{id:"m19-commercial",level:19,title:"Commercial Law",primary:[],reference:[],statutes:["contracts-act-1950"]},{id:"m20-employment",level:20,title:"Employment Law",primary:[],reference:[],statutes:[]},{id:"m21-international",level:21,title:"Public International Law",primary:[],reference:[],statutes:[]},{id:"m22-ethics",level:22,title:"Professional Practice and Ethics",primary:[],reference:[],statutes:[]}],i=[{id:"joshua",name:"Joshua Legal Art Gallery",url:"https://www.joshualegalartgallery.com",location:"Kuala Lumpur & Kota Kinabalu",notes:"Specialist law bookseller. Free shipping in Malaysia and Singapore. Stocks student editions."},{id:"marsden",name:"Marsden Law Book",url:"https://marsdenlawbook.com",location:"Malaysia",notes:"Specialist law bookseller. Good for current editions and student editions."},{id:"kinokuniya-my",name:"Kinokuniya Malaysia",url:"https://malaysia.kinokuniya.com",location:"KLCC",notes:"General bookstore with a law section."},{id:"mph",name:"MPH Online",url:"https://mphonline.com",location:"Malaysia",notes:"Stocks Our Constitution and similar general-reader titles."},{id:"agc-lom",name:"AGC — Laws of Malaysia portal",url:"https://lom.agc.gov.my",location:"Online",cost:"free",notes:"All federal statutes as PDF. The only official publication of the laws of Malaysia, but a print-out is NOT a copy of the Gazette and does not constitute prima facie evidence."}],n=["Always ask for the STUDENT EDITION — same content, typically far cheaper than the practitioner edition.","Download every statute free from lom.agc.gov.my before buying any textbook.","Several standard Malaysian student texts are 5-20 years old. Pair every textbook with the current statute text.","Free sources have no citator: you cannot confirm from lom.agc.gov.my or CommonLII alone that a case is still good law. Budget for CLJ/LexisNexis access, or use Westlaw Asia if you obtain Bar-member access.","Verify every entry marked 'unconfirmed' with the bookseller before paying."],Q={books:e,statutes:t,modules:a,vendors:i,purchasingNotes:n},o="1.0",s="Atomic cards, one fact each (Wozniak minimum information principle). Every card carries a `source` so you can re-verify it. Cards marked type 'trigger' are issue-spotting cues — the closest SRS gets to reasoning, and still only recognition.",r={term:"Defined term or Latin maxim. Irreducible pair.",rule:"A black-letter rule or a single element of one.",ratio:"The principle a case stands for.",structure:"Institutional or hierarchical fact.",source:"Where a rule comes from — statute, section, or authority.",trigger:"A fact cue that should make you think of a doctrine."},d=[{id:"f-ratio-01",moduleId:"m00-foundations",type:"term",front:"Ratio decidendi — what is it?",back:"The legal principle a court's decision actually rests on. It is the binding part of a judgment.",tags:["precedent","threshold-concept"],source:"Standard common law doctrine"},{id:"f-ratio-02",moduleId:"m00-foundations",type:"term",front:"Obiter dictum — what is it?",back:"A statement in a judgment not necessary to the decision. Persuasive only, never binding.",tags:["precedent","threshold-concept"],source:"Standard common law doctrine"},{id:"f-ratio-03",moduleId:"m00-foundations",type:"rule",front:"Which part of a judgment binds a lower court — ratio or obiter?",back:"The ratio only.",tags:["precedent"],source:"Standard common law doctrine"},{id:"f-stare-01",moduleId:"m00-foundations",type:"term",front:"Stare decisis — what does it mean?",back:"Stand by decided matters. Courts follow the rulings of higher courts on the same point of law.",tags:["precedent","latin"],source:"Standard common law doctrine"},{id:"f-auth-01",moduleId:"m00-foundations",type:"rule",front:"Binding authority vs persuasive authority — what is the difference?",back:"Binding authority must be followed. Persuasive authority may be followed but need not be.",tags:["precedent","authority"],source:"Standard common law doctrine"},{id:"f-auth-02",moduleId:"m00-foundations",type:"rule",front:"Is a foreign judgment ever binding on a Malaysian court?",back:"No. Foreign judgments are persuasive at most, however senior the foreign court.",tags:["precedent","authority"],source:"Standard common law doctrine"},{id:"f-factlaw-01",moduleId:"m00-foundations",type:"term",front:"The fact/law distinction — why does it matter?",back:"Questions of fact are about what happened; questions of law are about what the rule is. Appeals generally lie on law, not on findings of fact.",tags:["threshold-concept"],source:"Standard common law doctrine"},{id:"f-pubpriv-01",moduleId:"m00-foundations",type:"structure",front:"Public law vs private law — what divides them?",back:"Public law governs the relationship between the state and the individual. Private law governs relationships between persons.",tags:["taxonomy"],source:"Standard legal taxonomy"},{id:"f-civcrim-01",moduleId:"m00-foundations",type:"rule",front:"Who brings a criminal case, and who brings a civil case?",back:"Criminal: the state, through the prosecution. Civil: the aggrieved person, as plaintiff or claimant.",tags:["taxonomy"],source:"Standard legal taxonomy"},{id:"f-standard-01",moduleId:"m00-foundations",type:"rule",front:"Standard of proof in a criminal case?",back:"Beyond reasonable doubt.",tags:["proof"],source:"Standard common law doctrine"},{id:"f-standard-02",moduleId:"m00-foundations",type:"rule",front:"Standard of proof in a civil case?",back:"On the balance of probabilities.",tags:["proof"],source:"Standard common law doctrine"},{id:"f-latin-01",moduleId:"m00-foundations",type:"term",front:"Ultra vires — what does it mean?",back:"Beyond the powers. An act done outside the authority granted by law.",tags:["latin","admin-law"],source:"Standard common law doctrine"},{id:"f-latin-02",moduleId:"m00-foundations",type:"term",front:"Audi alteram partem — what does it mean?",back:"Hear the other side. The rule that a person must be given a chance to be heard before a decision against them.",tags:["latin","natural-justice"],source:"Standard common law doctrine"},{id:"f-latin-03",moduleId:"m00-foundations",type:"term",front:"Nemo judex in causa sua — what does it mean?",back:"No one should be a judge in their own cause. The rule against bias.",tags:["latin","natural-justice"],source:"Standard common law doctrine"},{id:"f-latin-04",moduleId:"m00-foundations",type:"term",front:"Actus reus — what does it mean?",back:"The physical element of an offence: the prohibited conduct, circumstances or result.",tags:["latin","criminal"],source:"Standard criminal law doctrine"},{id:"f-latin-05",moduleId:"m00-foundations",type:"term",front:"Mens rea — what does it mean?",back:"The mental element of an offence: the state of mind the offence requires.",tags:["latin","criminal"],source:"Standard criminal law doctrine"},{id:"f-latin-06",moduleId:"m00-foundations",type:"term",front:"Obiter vs per incuriam — what does per incuriam mean?",back:"Through lack of care. A decision reached in ignorance of a binding authority or statute, and therefore not binding.",tags:["latin","precedent"],source:"Standard common law doctrine"},{id:"my-court-01",moduleId:"m01-malaysian-legal-system",type:"structure",front:"Name the Malaysian civil courts from lowest to highest.",back:"Magistrates' Court, Sessions Court, High Court, Court of Appeal, Federal Court.",tags:["courts","hierarchy"],source:"Subordinate Courts Act 1948 (Act 92); Courts of Judicature Act 1964 (Act 91)"},{id:"my-court-02",moduleId:"m01-malaysian-legal-system",type:"structure",front:"Which is Malaysia's apex court?",back:"The Federal Court.",tags:["courts","hierarchy"],source:"Courts of Judicature Act 1964 (Act 91)"},{id:"my-court-03",moduleId:"m01-malaysian-legal-system",type:"structure",front:"How many High Courts does Malaysia have, and what are they?",back:"Two co-ordinate High Courts: the High Court in Malaya, and the High Court in Sabah and Sarawak.",tags:["courts","hierarchy"],source:"Federal Constitution, Art 121"},{id:"my-court-04",moduleId:"m01-malaysian-legal-system",type:"structure",front:"Which two Acts set out the jurisdiction of the Malaysian courts?",back:"The Subordinate Courts Act 1948 for the lower courts, and the Courts of Judicature Act 1964 for the superior courts.",tags:["courts","statute"],source:"Act 92; Act 91"},{id:"my-court-05",moduleId:"m01-malaysian-legal-system",type:"structure",front:"Name the Syariah court hierarchy from lowest to highest.",back:"Syariah Subordinate Court, Syariah High Court, Syariah Court of Appeal.",tags:["courts","syariah"],source:"State enactments; see Federal Constitution, Ninth Schedule, State List"},{id:"my-court-06",moduleId:"m01-malaysian-legal-system",type:"source",front:"Which Article bars the civil courts from matters within Syariah court jurisdiction?",back:"Article 121(1A) of the Federal Constitution.",tags:["courts","syariah","constitution"],source:"Federal Constitution, Art 121(1A)",note:"Scholars dispute how far this creates a genuinely parallel system, since Syariah courts are state courts of limited jurisdiction. Boundary disputes remain live."},{id:"my-court-07",moduleId:"m01-malaysian-legal-system",type:"rule",front:"Over whom do the Syariah courts have jurisdiction?",back:"Muslims only, and only in the matters assigned to the States — chiefly Islamic personal and family law, and certain religious offences.",tags:["courts","syariah"],source:"Federal Constitution, Art 74(2) and Ninth Schedule, State List"},{id:"my-source-01",moduleId:"m01-malaysian-legal-system",type:"structure",front:"What is the supreme law of Malaysia?",back:"The Federal Constitution.",tags:["sources","constitution"],source:"Federal Constitution"},{id:"my-source-02",moduleId:"m01-malaysian-legal-system",type:"source",front:"Which Act governs the reception of English common law and equity into Malaysia?",back:"The Civil Law Act 1956 (Act 67).",tags:["sources","statute"],source:"Civil Law Act 1956 (Act 67)"},{id:"my-source-03",moduleId:"m01-malaysian-legal-system",type:"structure",front:"What is subsidiary legislation?",back:"Law made by a body other than Parliament under power delegated by a statute — rules, regulations, orders, by-laws.",tags:["sources"],source:"Interpretation Acts 1948 and 1967 (Act 388)"},{id:"my-parl-01",moduleId:"m01-malaysian-legal-system",type:"structure",front:"Name the two houses of the Malaysian Parliament.",back:"The Dewan Rakyat (House of Representatives) and the Dewan Negara (Senate).",tags:["parliament"],source:"Federal Constitution, Part IV"},{id:"my-research-01",moduleId:"m02-legal-research",type:"source",front:"Where do you get the official text of a Malaysian Act, free?",back:"The AGC Laws of Malaysia portal at lom.agc.gov.my.",tags:["research","sources"],source:"Attorney General's Chambers",note:"A print-out from the portal is not a copy of the Gazette and does not constitute prima facie evidence."},{id:"my-research-02",moduleId:"m02-legal-research",type:"rule",front:"Can you confirm from free Malaysian sources alone that a case is still good law?",back:"No. Free sources have no reliable citator. You need Westlaw Citator, LexisNexis CaseBase, or equivalent.",tags:["research","noting-up"],source:"See research report, section 5"},{id:"my-research-03",moduleId:"m02-legal-research",type:"term",front:"What does 'noting up' a case mean?",back:"Checking how later courts have treated it — followed, distinguished, doubted, or overruled.",tags:["research","noting-up"],source:"Standard legal research practice"},{id:"t-contract-01",moduleId:"m00-foundations",type:"trigger",front:"Fact cue: two friends agree over dinner that one will sell the other a car. Which doctrine should you reach for first?",back:"Intention to create legal relations — social and domestic agreements raise a presumption against it.",tags:["issue-spotting","contract"],source:"Contract doctrine"},{id:"t-tort-01",moduleId:"m00-foundations",type:"trigger",front:"Fact cue: someone is injured and asks who should have prevented it. Which doctrine should you reach for first?",back:"Negligence — start with whether a duty of care was owed.",tags:["issue-spotting","tort"],source:"Tort doctrine"},{id:"t-admin-01",moduleId:"m00-foundations",type:"trigger",front:"Fact cue: a government body cancels a licence with no hearing. Which doctrine should you reach for first?",back:"Natural justice — the right to be heard (audi alteram partem), via judicial review.",tags:["issue-spotting","admin-law"],source:"Administrative law doctrine"}],X={schemaVersion:o,note:s,cardTypes:r,cards:d},h=1,c="Cards for the method, foundations, research, reasoning and interpretation lessons written in the second pass. One fact per card; every card is planted by exactly one lesson.",l={term:"Defined term or Latin maxim. Irreducible pair.",rule:"A black-letter rule or a single element of one.",ratio:"The principle a case stands for.",structure:"Institutional or hierarchical fact.",source:"Where a rule comes from — statute, section, or authority.",trigger:"A fact cue that should make you think of a doctrine."},u=[{id:"mm-brief-01",moduleId:"m-study-method",type:"term",front:"What makes a fact 'material' in a case brief?",back:"A fact the decision turned on — one whose change might change the result.",tags:["brief","ratio"],source:"Standard common law method"},{id:"mm-brief-02",moduleId:"m-study-method",type:"rule",front:"Why is a headnote never citable?",back:"It is written by an editor and is not part of the judgment.",tags:["brief","citation"],source:"Standard research practice"},{id:"mm-brief-03",moduleId:"m-study-method",type:"rule",front:"What single test separates ratio from obiter?",back:"Necessity: would the result stand without the proposition?",tags:["brief","ratio"],source:"Standard common law doctrine",note:"Length and emphasis are not evidence of ratio."},{id:"mm-brief-04",moduleId:"m-study-method",type:"trigger",front:"A judgment says the court 'heard no argument and expresses no view' on a point. What follows?",back:"That point is obiter and undecided; the case is no authority on it.",tags:["brief","obiter"],source:"Standard common law doctrine"},{id:"mm-exam-01",moduleId:"m-study-method",type:"rule",front:"What is the characteristic failure mode of an IRAC answer?",back:"A long Rule section and a thin Application — recall proved, reasoning not.",tags:["technique","irac"],source:"Standard examination technique"},{id:"mm-exam-02",moduleId:"m-study-method",type:"trigger",front:"A problem question gives an oddly specific date or sum. What does that signal?",back:"It does legal work. An unused specific is usually a missed issue.",tags:["technique","issue-spotting"],source:"Standard examination technique"},{id:"mm-exam-03",moduleId:"m-study-method",type:"rule",front:"How is writing time allocated across questions?",back:"In proportion to the marks. Overrunning costs more elsewhere than it earns here.",tags:["technique","timing"],source:"Standard examination technique"},{id:"mm-civcrim-01",moduleId:"m00-foundations",type:"rule",front:"What is the civil standard of proof?",back:"The balance of probabilities — more likely than not.",tags:["civil-criminal","proof"],source:"Standard common law"},{id:"mm-civcrim-02",moduleId:"m00-foundations",type:"source",front:"Who has the constitutional discretion to institute or discontinue a prosecution in Malaysia?",back:"The Public Prosecutor, under Article 145(3) of the Federal Constitution.",tags:["civil-criminal","prosecution"],source:"Federal Constitution Art 145(3)"},{id:"mm-civcrim-03",moduleId:"m00-foundations",type:"rule",front:"Does an acquittal prevent a civil claim on the same facts?",back:"No. The acquittal means the case was not proved beyond reasonable doubt; the civil standard is lower.",tags:["civil-criminal","proof"],source:"Standard common law"},{id:"mm-civcrim-04",moduleId:"m00-foundations",type:"term",front:"Which words belong to criminal proceedings and which to civil?",back:"Criminal: prosecution, accused, charge, conviction, sentence. Civil: plaintiff, defendant, claim, liability, judgment.",tags:["civil-criminal","vocabulary"],source:"Standard usage"},{id:"mm-cite-01",moduleId:"m02-legal-research",type:"rule",front:"What do square brackets around the year in a citation mean?",back:"The year is needed to locate the volume — [2010] 2 MLJ 1 is volume 2 of the 2010 MLJ.",tags:["citation"],source:"Standard citation practice"},{id:"mm-cite-02",moduleId:"m02-legal-research",type:"structure",front:"What do MLJ, CLJ and AMR stand for?",back:"Malayan Law Journal, Current Law Journal, All Malaysia Reports.",tags:["citation"],source:"Standard Malaysian report series"},{id:"mm-cite-03",moduleId:"m02-legal-research",type:"rule",front:"What can a citation never tell you?",back:"Whether the case is still good law. That needs a citator, and there is no free Malaysian one.",tags:["citation","citator"],source:"Standard research practice"},{id:"mm-cite-04",moduleId:"m02-legal-research",type:"rule",front:"What makes a note of a statutory provision complete?",back:"The section, plus which version of the text you read and the date you read it.",tags:["citation","statute"],source:"Standard research practice"},{id:"mm-analogy-01",moduleId:"m13-legal-reasoning",type:"rule",front:"What makes a difference between two cases a genuine distinction?",back:"The earlier court's reasoning must depend on the fact that differs.",tags:["precedent","distinguishing"],source:"Standard common law method"},{id:"mm-analogy-02",moduleId:"m13-legal-reasoning",type:"rule",front:"What may a High Court judge do with a Federal Court decision he thinks is wrong?",back:"Distinguish it if the facts allow; otherwise follow it. He cannot decline to follow it.",tags:["precedent","hierarchy"],source:"Standard doctrine of precedent"},{id:"mm-analogy-03",moduleId:"m13-legal-reasoning",type:"trigger",front:"Why are English contract authorities used with care in Malaysia?",back:"Contract is codified in the Contracts Act 1950, so the starting point is the Act's words.",tags:["precedent","codification"],source:"Contracts Act 1950"},{id:"mm-analogy-04",moduleId:"m13-legal-reasoning",type:"term",front:"What does it mean to 'confine a case to its facts'?",back:"To read the earlier decision as narrowly as its result allows — legitimate, but a signal of discomfort.",tags:["precedent"],source:"Standard common law method"},{id:"mm-interp-01",moduleId:"m14-statutory-interpretation",type:"source",front:"Which provision directs a purposive construction of Malaysian statutes?",back:"Section 17A of the Interpretation Acts 1948 and 1967.",tags:["interpretation","purposive"],source:"Interpretation Acts 1948 and 1967, s 17A"},{id:"mm-interp-02",moduleId:"m14-statutory-interpretation",type:"rule",front:"When does the purposive approach become relevant?",back:"Once the words are capable of more than one reading. It chooses between available constructions; it does not create one.",tags:["interpretation","purposive"],source:"Interpretation Acts 1948 and 1967, s 17A"},{id:"mm-interp-03",moduleId:"m14-statutory-interpretation",type:"term",front:"Ejusdem generis — what does it do?",back:"General words following a list of specifics are read as confined to the same class.",tags:["interpretation","canons"],source:"Standard canon of construction"},{id:"mm-interp-04",moduleId:"m14-statutory-interpretation",type:"rule",front:"What weight does a marginal note carry?",back:"It indicates arrangement. It is not enacted text and cannot control a clear provision.",tags:["interpretation","internal-aids"],source:"Standard canon of construction"},{id:"mm-interp-05",moduleId:"m14-statutory-interpretation",type:"rule",front:"How is an ouster clause construed?",back:"Narrowly. Courts start from a presumption against the ouster of their jurisdiction and require clear words.",tags:["interpretation","presumptions"],source:"Standard presumption of construction"}],ee={schemaVersion:h,note:c,cardTypes:l,cards:u},m=1,p="Cards for the substantive lessons written in the second pass. Section numbers are the point of most of these, and every one carries the source it came from.",f={term:"Defined term or Latin maxim. Irreducible pair.",rule:"A black-letter rule or a single element of one.",ratio:"The principle a case stands for.",structure:"Institutional or hierarchical fact.",source:"Where a rule comes from — statute, section, or authority.",trigger:"A fact cue that should make you think of a doctrine."},g=[{id:"ms-fed-01",moduleId:"m03-constitutional",type:"source",front:"Which Article makes federal law prevail over inconsistent State law?",back:"Article 75. The State law is void to the extent of the inconsistency.",tags:["federalism"],source:"Federal Constitution Art 75"},{id:"ms-fed-02",moduleId:"m03-constitutional",type:"structure",front:"What are the three lists in the Ninth Schedule?",back:"List I Federal, List II State, List III Concurrent — with supplementary lists for Sabah and Sarawak.",tags:["federalism"],source:"Federal Constitution, Ninth Schedule"},{id:"ms-fed-03",moduleId:"m03-constitutional",type:"rule",front:"Land is a State matter. How can the National Land Code be a federal statute?",back:"Article 76 lets Parliament legislate on State matters for uniformity; the law takes effect in a State on adoption by its legislature.",tags:["federalism","land"],source:"Federal Constitution Art 76"},{id:"ms-fed-04",moduleId:"m03-constitutional",type:"source",front:"What does Article 4(1) provide?",back:"The Constitution is the supreme law; law inconsistent with it is void to the extent of the inconsistency.",tags:["federalism","supremacy"],source:"Federal Constitution Art 4(1)"},{id:"ms-fed-05",moduleId:"m03-constitutional",type:"trigger",front:"A federal statute is passed on a List II subject. What is the first question?",back:"Competence, not Article 75. An ultra vires federal law prevails over nothing.",tags:["federalism","competence"],source:"Federal Constitution Arts 4(1) and 74"},{id:"ms-jud-01",moduleId:"m03-constitutional",type:"rule",front:"What did the 1988 amendment do to Article 121(1)?",back:"It replaced the vesting of judicial power in the courts with jurisdiction 'conferred by or under federal law'.",tags:["judicial-power"],source:"Constitution (Amendment) Act 1988"},{id:"ms-jud-02",moduleId:"m03-constitutional",type:"source",front:"What does Article 121(1A) do?",back:"It removes from the civil courts jurisdiction over matters within the jurisdiction of the Syariah courts.",tags:["judicial-power","syariah"],source:"Federal Constitution Art 121(1A)",note:"It is a subtraction from the civil courts, not a grant to the Syariah courts."},{id:"ms-jud-03",moduleId:"m03-constitutional",type:"term",front:"What is the basic structure doctrine?",back:"The argument that certain fundamental features cannot be removed even by a valid constitutional amendment.",tags:["judicial-power","basic-structure"],source:"Malaysian and Indian constitutional case law"},{id:"ms-jud-04",moduleId:"m03-constitutional",type:"source",front:"Which court decides whether a law is invalid for want of legislative competence?",back:"The Federal Court, exclusively, under Article 128.",tags:["judicial-power","jurisdiction"],source:"Federal Constitution Art 128"},{id:"ms-exc-01",moduleId:"m04-criminal-law",type:"source",front:"Where does the burden of proving a general exception lie, and to what standard?",back:"On the accused, on the balance of probabilities — s 105 of the Evidence Act 1950.",tags:["exceptions","burden"],source:"Evidence Act 1950, s 105"},{id:"ms-exc-02",moduleId:"m04-criminal-law",type:"source",front:"Which section makes every Penal Code offence subject to the general exceptions?",back:"Section 6 of the Penal Code.",tags:["exceptions"],source:"Penal Code, s 6"},{id:"ms-exc-03",moduleId:"m04-criminal-law",type:"rule",front:"Section 79 of the Penal Code excuses a mistake of what?",back:"A mistake of fact, made in good faith. Mistake of law does not excuse.",tags:["exceptions","mistake"],source:"Penal Code, s 79"},{id:"ms-exc-04",moduleId:"m04-criminal-law",type:"rule",front:"When is there no right of private defence under s 99(3)?",back:"Where there is no reasonable apprehension of death or grievous hurt and there is time to have recourse to the public authorities.",tags:["exceptions","private-defence"],source:"Penal Code, s 99(3)"},{id:"ms-exc-05",moduleId:"m04-criminal-law",type:"trigger",front:"An accused kills while exceeding the right of private defence. What should you reach for?",back:"Exception 2 to s 300 — murder may be reduced to culpable homicide not amounting to murder.",tags:["exceptions","homicide"],source:"Penal Code, Exception 2 to s 300"},{id:"ms-crimpro-01",moduleId:"m05-criminal-procedure",type:"term",front:"What does 'non-bailable offence' mean?",back:"Bail is in the court's discretion, subject to s 388 — not that bail is unavailable.",tags:["bail"],source:"Criminal Procedure Code, s 388"},{id:"ms-crimpro-02",moduleId:"m05-criminal-procedure",type:"structure",front:"Where is an offence classified as bailable or non-bailable?",back:"The First Schedule to the Criminal Procedure Code, offence by offence.",tags:["bail"],source:"Criminal Procedure Code, First Schedule"},{id:"ms-crimpro-03",moduleId:"m05-criminal-procedure",type:"source",front:"How long may a person be held after arrest without a Magistrate's authority?",back:"Twenty-four hours — Article 5(4) of the Federal Constitution. Longer needs a remand order under s 117 CPC.",tags:["arrest","remand"],source:"Federal Constitution Art 5(4); Criminal Procedure Code s 117"},{id:"ms-crimpro-04",moduleId:"m05-criminal-procedure",type:"source",front:"What is the question at the close of the prosecution case?",back:"Whether a prima facie case has been made out — s 180 of the Criminal Procedure Code.",tags:["trial"],source:"Criminal Procedure Code, s 180"},{id:"ms-crimpro-05",moduleId:"m05-criminal-procedure",type:"term",front:"What is a discharge not amounting to an acquittal?",back:"A discharge that leaves the accused liable to be recharged on the same facts.",tags:["trial","prosecution"],source:"Criminal Procedure Code"},{id:"ms-vit-01",moduleId:"m06-contract",type:"source",front:"Which section lists what makes consent not free?",back:"Section 14 of the Contracts Act 1950: coercion, undue influence, fraud, misrepresentation, mistake.",tags:["consent"],source:"Contracts Act 1950, s 14"},{id:"ms-vit-02",moduleId:"m06-contract",type:"rule",front:"What is the effect of coercion, fraud or misrepresentation on an agreement?",back:"It is voidable at the option of the party whose consent was so caused — s 19(1).",tags:["consent","voidable"],source:"Contracts Act 1950, s 19(1)"},{id:"ms-vit-03",moduleId:"m06-contract",type:"rule",front:"What is the effect of a bilateral mistake as to an essential fact?",back:"The agreement is void — s 21. There is nothing to affirm.",tags:["consent","mistake"],source:"Contracts Act 1950, s 21"},{id:"ms-vit-04",moduleId:"m06-contract",type:"rule",front:"When is silence fraud under s 17?",back:"Where there is a duty to speak, or where silence is in itself equivalent to speech.",tags:["consent","fraud"],source:"Contracts Act 1950, s 17"},{id:"ms-vit-05",moduleId:"m06-contract",type:"source",front:"Which section requires restoration of an advantage received under a void agreement?",back:"Section 66 of the Contracts Act 1950.",tags:["consent","restitution"],source:"Contracts Act 1950, s 66"},{id:"ms-rem-01",moduleId:"m06-contract",type:"source",front:"Which section measures damages for breach of contract in Malaysia?",back:"Section 74 of the Contracts Act 1950 — the rule in Hadley v Baxendale, enacted.",tags:["remedies","damages"],source:"Contracts Act 1950, s 74; Hadley v Baxendale (1854) 9 Exch 341"},{id:"ms-rem-02",moduleId:"m06-contract",type:"source",front:"Which section governs a sum named in the contract as payable on breach?",back:"Section 75 of the Contracts Act 1950 — reasonable compensation, not exceeding the sum named.",tags:["remedies","liquidated-damages"],source:"Contracts Act 1950, s 75"},{id:"ms-rem-03",moduleId:"m06-contract",type:"ratio",front:"What did Cubic Electronics v Mars Telecommunications decide about s 75?",back:"It reformulated the Malaysian approach, moving away from the strict proof-of-actual-loss requirement in Selva Kumar and asking whether the clause protects a legitimate interest.",tags:["remedies","liquidated-damages"],source:"Cubic Electronics Sdn Bhd v Mars Telecommunications Sdn Bhd [2019] 6 MLJ 15 (FC)",note:"Verify this citation and check for anything decided since."},{id:"ms-rem-04",moduleId:"m06-contract",type:"source",front:"Which statute governs specific performance in Malaysia?",back:"The Specific Relief Act 1950 — not the Contracts Act.",tags:["remedies","specific-performance"],source:"Specific Relief Act 1950"},{id:"ms-rem-05",moduleId:"m06-contract",type:"rule",front:"What does s 40 give a promisee faced with an entire refusal to perform?",back:"The right to put an end to the contract, unless he has acquiesced in its continuance.",tags:["remedies","termination"],source:"Contracts Act 1950, s 40"},{id:"ms-tort-01",moduleId:"m07-tort",type:"rule",front:"State the but-for test.",back:"But for the defendant's breach, would the damage have occurred? If it would, causation fails.",tags:["negligence","causation"],source:"Standard common law"},{id:"ms-tort-02",moduleId:"m07-tort",type:"source",front:"Which provision governs contributory negligence in Malaysia?",back:"Section 12 of the Civil Law Act 1956 — apportionment, not a complete defence.",tags:["negligence","apportionment"],source:"Civil Law Act 1956, s 12"},{id:"ms-tort-03",moduleId:"m07-tort",type:"rule",front:"State the remoteness rule.",back:"The kind of damage must be reasonably foreseeable; the extent need not be.",tags:["negligence","remoteness"],source:"The Wagon Mound (No 1) [1961] AC 388"},{id:"ms-tort-04",moduleId:"m07-tort",type:"term",front:"Novus actus interveniens versus contributory negligence — what is the difference?",back:"The first breaks the chain and defeats the claim; the second reduces the damages.",tags:["negligence","causation"],source:"Standard common law"},{id:"ms-def-01",moduleId:"m07-tort",type:"rule",front:"What are the three elements of defamation?",back:"The words are defamatory, they refer to the plaintiff, and they were published to a third party.",tags:["defamation"],source:"Standard common law"},{id:"ms-def-02",moduleId:"m07-tort",type:"term",front:"What is publication in defamation?",back:"Communication to at least one person other than the plaintiff.",tags:["defamation"],source:"Standard common law"},{id:"ms-def-03",moduleId:"m07-tort",type:"rule",front:"Where does malice bite in a defamation action?",back:"It defeats qualified privilege and fair comment. It is not an element of the tort.",tags:["defamation","defences"],source:"Standard common law"},{id:"ms-def-04",moduleId:"m07-tort",type:"source",front:"What does s 8 of the Defamation Act 1957 do?",back:"Justification does not fail merely because every charge is not proved true, if the rest do not materially injure reputation.",tags:["defamation","defences"],source:"Defamation Act 1957, s 8"},{id:"ms-land-01",moduleId:"m08-property",type:"rule",front:"When does a dealing pass an interest in registered land?",back:"On registration. Before that the purchaser has contractual and equitable rights only.",tags:["torrens","dealings"],source:"National Land Code"},{id:"ms-land-02",moduleId:"m08-property",type:"source",front:"Who may enter a private caveat?",back:"A person claiming title, or any registrable interest, or to be beneficially entitled under a trust affecting the land — s 323.",tags:["caveats"],source:"National Land Code, s 323"},{id:"ms-land-03",moduleId:"m08-property",type:"rule",front:"What must a caveator show on an application to remove a private caveat?",back:"A serious question to be tried, and that the balance of convenience favours maintaining the caveat.",tags:["caveats"],source:"Malaysian case law on private caveats"},{id:"ms-land-04",moduleId:"m08-property",type:"structure",front:"Where does a chargee apply for an order for sale?",back:"Registry title: the High Court. Land Office title: the Land Administrator.",tags:["charges"],source:"National Land Code, the order-for-sale provisions"},{id:"ms-land-05",moduleId:"m08-property",type:"ratio",front:"What did Tan Ying Hong v Tan Sian San decide?",back:"It restored deferred indefeasibility under s 340, departing from Adorna Properties.",tags:["torrens","indefeasibility"],source:"Tan Ying Hong v Tan Sian San [2010] 2 MLJ 1 (FC)"},{id:"ms-co-01",moduleId:"m09-company",type:"source",front:"Which provision states a director's duty to act in good faith in the company's best interest?",back:"Section 213(1) of the Companies Act 2016. Section 213(2) is the duty of care.",tags:["directors"],source:"Companies Act 2016, s 213"},{id:"ms-co-02",moduleId:"m09-company",type:"rule",front:"What does a statutory derivative action require?",back:"Leave of the court, good faith, and that the action is prima facie in the company's best interest.",tags:["remedies","derivative"],source:"Companies Act 2016, ss 347-350"},{id:"ms-co-03",moduleId:"m09-company",type:"source",front:"Which section gives the oppression remedy?",back:"Section 346 of the Companies Act 2016.",tags:["remedies","oppression"],source:"Companies Act 2016, s 346"},{id:"ms-co-04",moduleId:"m09-company",type:"term",front:"What is reflective loss?",back:"A fall in share value caused by harm to the company. The claim belongs to the company, not the member.",tags:["remedies","standing"],source:"Standard company law"},{id:"ms-ev-01",moduleId:"m10-evidence",type:"source",front:"Which section places the legal burden on the person who would fail if no evidence were given?",back:"Section 102 of the Evidence Act 1950.",tags:["burden"],source:"Evidence Act 1950, s 102"},{id:"ms-ev-02",moduleId:"m10-evidence",type:"rule",front:"What is the scope of s 106?",back:"A specific fact especially within a person's knowledge. It cannot reverse the general burden.",tags:["burden"],source:"Evidence Act 1950, s 106"},{id:"ms-ev-03",moduleId:"m10-evidence",type:"term",front:"'May presume', 'shall presume', 'conclusive proof' — what is the difference?",back:"A discretion; mandatory unless disproved; and admitting no evidence in rebuttal.",tags:["presumptions"],source:"Evidence Act 1950, s 4"},{id:"ms-ev-04",moduleId:"m10-evidence",type:"source",front:"What is illustration (g) to s 114?",back:"That evidence which could be and is not produced would, if produced, be unfavourable to the person who withholds it.",tags:["presumptions","adverse-inference"],source:"Evidence Act 1950, s 114 illustration (g)"},{id:"ms-ev-05",moduleId:"m10-evidence",type:"rule",front:"What must be established before any question of burden arises?",back:"Admissibility. Relevance is defined by the Act, not at large.",tags:["relevancy"],source:"Evidence Act 1950, s 5"},{id:"ms-civ-01",moduleId:"m11-civil-procedure",type:"rule",front:"What must a defendant show to resist summary judgment under Order 14?",back:"A triable issue, or some other reason why there ought to be a trial — not that the defence will succeed.",tags:["summary-judgment"],source:"Rules of Court 2012, O 14"},{id:"ms-civ-02",moduleId:"m11-civil-procedure",type:"rule",front:"On a strike-out for no reasonable cause of action, what evidence is admissible?",back:"None. The question is taken on the pleading as it stands.",tags:["striking-out"],source:"Rules of Court 2012, O 18 r 19"},{id:"ms-civ-03",moduleId:"m11-civil-procedure",type:"rule",front:"State the interlocutory injunction test.",back:"A serious question to be tried; damages an inadequate remedy; balance of convenience — with an undertaking in damages.",tags:["injunctions"],source:"Rules of Court 2012, O 29; American Cyanamid as applied in Malaysia"},{id:"ms-civ-04",moduleId:"m11-civil-procedure",type:"source",front:"What is the general limitation period for contract and tort?",back:"Six years from the accrual of the cause of action, under the Limitation Act 1953.",tags:["limitation"],source:"Limitation Act 1953, s 6"},{id:"ms-adm-01",moduleId:"m12-administrative",type:"term",front:"Audi alteram partem — what does it require?",back:"Notice of the case against you and a fair opportunity to answer it.",tags:["natural-justice"],source:"Standard common law"},{id:"ms-adm-02",moduleId:"m12-administrative",type:"rule",front:"What is the practical test for bias?",back:"Whether a fair-minded and informed observer would conclude there was a real danger, or real possibility, of bias.",tags:["natural-justice"],source:"Malaysian and English case law on bias",note:"Check which formulation the Malaysian courts currently use."},{id:"ms-adm-03",moduleId:"m12-administrative",type:"rule",front:"Can a legitimate expectation arise from a representation outside the decision-maker's power?",back:"No. A public body cannot bind itself to act unlawfully.",tags:["legitimate-expectation"],source:"Standard administrative law"},{id:"ms-adm-04",moduleId:"m12-administrative",type:"structure",front:"What are the three classic grounds of judicial review?",back:"Illegality, irrationality, procedural impropriety — with proportionality argued as a fourth.",tags:["judicial-review"],source:"The GCHQ classification as received in Malaysia"},{id:"ms-adm-05",moduleId:"m12-administrative",type:"source",front:"What are the two procedural thresholds under Order 53?",back:"Leave of the court, and an applicant who is adversely affected by the decision — within the prescribed time.",tags:["judicial-review","procedure"],source:"Rules of Court 2012, O 53"}],te={schemaVersion:m,note:p,cardTypes:f,cards:g},y="1.0",w="Cards for the beginner on-ramp lessons in the four skill modules. These are habits and method rather than doctrine: how to run a study session, how to judge a source, how to build an argument, and how to take a section apart. Each is planted by one lesson in content/lessons/gap-method-reasoning.json.",b={term:"Defined term or Latin maxim. Irreducible pair.",rule:"A black-letter rule or a single element of one.",ratio:"The principle a case stands for.",structure:"Institutional or hierarchical fact.",source:"Where a rule comes from — statute, section, or authority.",trigger:"A fact cue that should make you think of a doctrine."},v=[{id:"pf-study-01",moduleId:"m-study-method",type:"rule",front:"Why does re-reading feel like it is working?",back:"The second pass is easier than the first, and the brain reads ease as knowing. That feeling is fluency, not memory.",tags:["method","retrieval"],source:"Make It Stick; the retrieval practice literature"},{id:"pf-study-02",moduleId:"m-study-method",type:"rule",front:"What should the first ten minutes of a study session be?",back:"Answering questions on old material from memory, before you look at anything. Testing comes before reviewing.",tags:["method","retrieval"],source:"Make It Stick; the retrieval practice literature"},{id:"pf-study-03",moduleId:"m-study-method",type:"rule",front:"Four half-hours across a week, or one two-hour session?",back:"Four half-hours. The gaps let you forget a little, and pulling it back is what makes the memory last.",tags:["method","spacing"],source:"Make It Stick; the spacing literature"},{id:"pf-study-04",moduleId:"m-study-method",type:"rule",front:"Why mix topics inside one sitting instead of doing one topic per week?",back:"Real facts never say which rule they belong to. Mixing feels worse and trains you to choose.",tags:["method","interleaving"],source:"Make It Stick; the interleaving literature"},{id:"pf-study-05",moduleId:"m-study-method",type:"rule",front:"How do you restart after missing a week of study?",back:"Ten minutes on material you already know, not a new topic. Restarting is a habit problem, not a knowledge problem.",tags:["method","habit"],source:"Standard study practice"},{id:"pf-study-06",moduleId:"m-study-method",type:"rule",front:"What is the strongest way to test your own understanding when you study alone?",back:"Explain it to somebody with no legal training. If you cannot say it in ordinary words, you do not have it yet.",tags:["method","self-testing"],source:"Standard study practice"},{id:"pf-res-01",moduleId:"m02-legal-research",type:"rule",front:"Is a page printed from the government statute portal the same as the Gazette?",back:"No. It is the official published text and it is right for study, but a print-out is not a copy of the Gazette.",tags:["research","sources"],source:"Attorney General's Chambers, Malaysia"},{id:"pf-res-02",moduleId:"m02-legal-research",type:"rule",front:"What are the three kinds of thing you find when you search for law?",back:"The law itself, the record of what a court decided, and somebody talking about the law. Only the first two are sources.",tags:["research","sources"],source:"Standard research practice"},{id:"pf-res-03",moduleId:"m02-legal-research",type:"trigger",front:"An article says the law says something but names no Act and no section. What follows?",back:"You cannot check it, so you cannot rely on it. Use it only as a lead to the primary text.",tags:["research","sources"],source:"Standard research practice"},{id:"pf-res-04",moduleId:"m02-legal-research",type:"term",front:"What is a citation for?",back:"It is an address. It tells any reader where to find the same words, and usually which court decided the case.",tags:["research","citation"],source:"Standard research practice"},{id:"pf-res-05",moduleId:"m02-legal-research",type:"rule",front:"What must a research note contain to be worth keeping?",back:"The source, the exact provision, the words you relied on, and the date you read it. Research you cannot retrace is not research.",tags:["research","method"],source:"Standard research practice"},{id:"pf-res-06",moduleId:"m02-legal-research",type:"trigger",front:"A search hands you a case first. What do you do before reading it?",back:"Look for the Act that governs the point. A case is evidence of what the law is; the Act is the law.",tags:["research","order-of-work"],source:"Standard research practice"},{id:"pf-reason-01",moduleId:"m13-legal-reasoning",type:"term",front:"What makes a question an issue?",back:"The facts leave it genuinely open and both answers are arguable. If only one answer is possible, it is not the issue.",tags:["reasoning","issue-spotting"],source:"Standard problem-question technique"},{id:"pf-reason-02",moduleId:"m13-legal-reasoning",type:"rule",front:"What is the first thing to do with a rule before applying it?",back:"Split it into its elements and list them, one per line. Each element is a separate question that has to be answered.",tags:["reasoning","structure"],source:"Standard problem-question technique"},{id:"pf-reason-03",moduleId:"m13-legal-reasoning",type:"rule",front:"What does application actually mean?",back:"Putting one specific fact next to one specific element of the rule. Retelling the story is not application.",tags:["reasoning","application"],source:"Standard problem-question technique"},{id:"pf-reason-04",moduleId:"m13-legal-reasoning",type:"trigger",front:"A sentence in your answer would still be true if the facts changed. What is it?",back:"Padding. Application only counts when it depends on these facts and no others.",tags:["reasoning","application"],source:"Standard problem-question technique"},{id:"pf-reason-05",moduleId:"m13-legal-reasoning",type:"rule",front:"Why write out the other side's best argument?",back:"A real issue has two arguable sides, and stating the stronger one against you shows you saw the difficulty. Then you decide.",tags:["reasoning","argument"],source:"Standard problem-question technique"},{id:"pf-reason-06",moduleId:"m13-legal-reasoning",type:"rule",front:"Before using an earlier case, what must you identify?",back:"The facts the earlier decision actually turned on. Only those facts make it close to yours.",tags:["reasoning","analogy"],source:"Standard common law reasoning"},{id:"pf-sec-01",moduleId:"m14-statutory-interpretation",type:"rule",front:"What is the first physical step in reading a hard section?",back:"Copy it out with one clause per line, breaking at every and, or, if, unless and subject to.",tags:["interpretation","method"],source:"Standard statutory reading practice"},{id:"pf-sec-02",moduleId:"m14-statutory-interpretation",type:"rule",front:"What four things are you hunting for in a section?",back:"Who it applies to, what it requires or allows, the conditions, and the consequence of breaking it.",tags:["interpretation","method"],source:"Standard statutory reading practice"},{id:"pf-sec-03",moduleId:"m14-statutory-interpretation",type:"rule",front:"In a list of conditions, what separates and from or?",back:"**And** requires every item. **Or** requires any one. Changing the word can reverse the answer.",tags:["interpretation","language"],source:"Standard statutory construction"},{id:"pf-sec-04",moduleId:"m14-statutory-interpretation",type:"rule",front:"A definition says includes rather than means. What follows?",back:"**Means** gives a closed list. **Includes** adds to the ordinary meaning without shutting it down.",tags:["interpretation","definitions"],source:"Standard statutory construction"},{id:"pf-sec-05",moduleId:"m14-statutory-interpretation",type:"term",front:"What is a proviso?",back:"A clause that cuts a piece out of the provision it is attached to, usually starting with *provided that*. It does not reach other sections.",tags:["interpretation","structure"],source:"Standard statutory construction"},{id:"pf-sec-06",moduleId:"m14-statutory-interpretation",type:"source",front:"Where do you look for the meaning of a word used in an Act?",back:"The section itself, then the Act's own interpretation section, then the Interpretation Acts 1948 and 1967.",tags:["interpretation","definitions"],source:"Interpretation Acts 1948 and 1967"}],ae={schemaVersion:y,note:w,cardTypes:b,cards:v},k="1.0",A="Beginner cards for criminal procedure and property, planted by the on-ramp lessons in gap-procedure-property.json. One fact each. Every card carries a `source` so you can re-verify it. Cards marked type 'trigger' are issue-spotting cues.",C={term:"Defined term or Latin maxim. Irreducible pair.",rule:"A black-letter rule or a single element of one.",ratio:"The principle a case stands for.",structure:"Institutional or hierarchical fact.",source:"Where a rule comes from — statute, section, or authority.",trigger:"A fact cue that should make you think of a doctrine."},T=[{id:"pd-c-cp-01",moduleId:"m05-criminal-procedure",type:"term",front:"What turns a police stop into an arrest?",back:"You are taken into custody and are no longer free to leave. No particular words are needed.",tags:["arrest","everyday"],source:"Criminal Procedure Code (Act 593); standard practice"},{id:"pd-c-cp-02",moduleId:"m05-criminal-procedure",type:"rule",front:"What must the police tell you when they arrest you?",back:"The grounds of the arrest, as soon as may be.",tags:["arrest","rights"],source:"Federal Constitution, Art 5(3)"},{id:"pd-c-cp-03",moduleId:"m05-criminal-procedure",type:"rule",front:"After an arrest, who may you ask to contact?",back:"A lawyer of your choice, and a relative or friend to be told where you are.",tags:["arrest","rights"],source:"Federal Constitution, Art 5(3); Criminal Procedure Code (Act 593), s 28A",note:"When access to a lawyer must be allowed in practice is contested in the case law. Ask, ask again, and record the time."},{id:"pd-c-cp-04",moduleId:"m05-criminal-procedure",type:"rule",front:"Must you answer every question the police ask?",back:"You must answer truthfully, but you need not answer a question whose answer would expose you to a criminal charge.",tags:["arrest","statements"],source:"Criminal Procedure Code (Act 593), provisions on police statements"},{id:"pd-c-cp-05",moduleId:"m05-criminal-procedure",type:"trigger",front:"Fact cue: a relative is still in the lock-up on the second night. What do you check first?",back:"Whether a Magistrate has made a remand order. Twenty-four hours is the limit without one.",tags:["issue-spotting","detention"],source:"Federal Constitution, Art 5(4); Criminal Procedure Code (Act 593), s 117"},{id:"pd-c-cp-06",moduleId:"m05-criminal-procedure",type:"term",front:"What is a remand order?",back:"A Magistrate's order allowing the police to hold a person longer, for the purposes of the investigation.",tags:["detention","remand"],source:"Criminal Procedure Code (Act 593), s 117"},{id:"pd-c-cp-07",moduleId:"m05-criminal-procedure",type:"rule",front:"What must a charge tell the accused?",back:"The offence, with enough detail of time, place and person for him to know what he is answering.",tags:["charge"],source:"Criminal Procedure Code (Act 593), provisions on the form of charges"},{id:"pd-c-cp-08",moduleId:"m05-criminal-procedure",type:"term",front:"What does 'claiming trial' mean?",back:"Pleading not guilty, so that the prosecution must prove the charge.",tags:["plea","everyday"],source:"Criminal Procedure Code (Act 593); standard court usage"},{id:"pd-c-cp-09",moduleId:"m05-criminal-procedure",type:"term",front:"What is a surety (penjamin) promising?",back:"That the accused will attend court. If he does not, the surety's money is at risk.",tags:["bail","everyday"],source:"Criminal Procedure Code (Act 593), bail provisions"},{id:"pd-c-cp-10",moduleId:"m05-criminal-procedure",type:"structure",front:"In what order does a criminal trial run?",back:"Prosecution witnesses, then a ruling on whether there is a case to answer, then the defence, then the decision and any sentence.",tags:["trial","structure"],source:"Criminal Procedure Code (Act 593)"},{id:"pd-c-ld-01",moduleId:"m08-property",type:"rule",front:"Who is the owner of a piece of registered land in Malaysia?",back:"The person registered as proprietor. The register is the title, not merely evidence of it.",tags:["torrens","registration"],source:"National Land Code (Act 828)"},{id:"pd-c-ld-02",moduleId:"m08-property",type:"term",front:"What is an official land search?",back:"An extract of the register for one lot, applied for at the district land office by anyone who has the lot number.",tags:["practice","everyday"],source:"National Land Code (Act 828); State land rules"},{id:"pd-c-ld-03",moduleId:"m08-property",type:"structure",front:"Name four things a land search will show you.",back:"The registered proprietor, the category of land use, any restriction in interest, and anything registered against the land such as a charge, lease or caveat.",tags:["practice"],source:"National Land Code (Act 828)"},{id:"pd-c-ld-04",moduleId:"m08-property",type:"term",front:"What is a temporary occupation licence (TOL)?",back:"Yearly permission to occupy State land. It is permission, not ownership, and it can end.",tags:["occupation","kampung"],source:"National Land Code (Act 828)"},{id:"pd-c-ld-05",moduleId:"m08-property",type:"trigger",front:"Fact cue: a family has lived on land for forty years with no title in their name. What do you check first?",back:"Whose name is on the register, and on what footing the family occupies. Long use alone gives no title under the Code.",tags:["issue-spotting","kampung"],source:"National Land Code (Act 828)"},{id:"pd-c-ld-06",moduleId:"m08-property",type:"term",front:"What is a charge in Malaysian land law?",back:"A registered security over land, given for a debt. Malaysian law says charge, not mortgage.",tags:["dealings","security"],source:"National Land Code (Act 828)"},{id:"pd-c-ld-07",moduleId:"m08-property",type:"rule",front:"Does a charge make the bank the owner of the house?",back:"No. The borrower stays the registered proprietor, and the bank must apply for an order for sale to enforce.",tags:["dealings","security"],source:"National Land Code (Act 828)"},{id:"pd-c-ld-08",moduleId:"m08-property",type:"term",front:"What does a private caveat actually do?",back:"It blocks further dealings from being registered while it stands. It creates no interest in the land.",tags:["caveat"],source:"National Land Code (Act 828)"},{id:"pd-c-ld-09",moduleId:"m08-property",type:"rule",front:"What is the risk of lodging a caveat with no proper claim?",back:"A person who suffers loss because of it can claim compensation from the caveator.",tags:["caveat"],source:"National Land Code (Act 828)"},{id:"pd-c-ld-10",moduleId:"m08-property",type:"structure",front:"A grandfather has died and his name is still on the title. How does the land move to the family?",back:"Through a distribution of his estate — at the Land Office for a small estate, otherwise in court — which is then registered against the title.",tags:["succession","kampung"],source:"National Land Code (Act 828); Small Estates (Distribution) Act 1955"}],ie={schemaVersion:k,note:A,cardTypes:C,cards:T},S="1.0",I="Beginner cards for company law, evidence and civil procedure, planted by the on-ramp lessons in content/lessons/gap-company-evidence-civil.json. One fact each. Every card carries a `source` so you can re-verify it.",x={term:"Defined term or Latin maxim. Irreducible pair.",rule:"A black-letter rule or a single element of one.",ratio:"The principle a case stands for.",structure:"Institutional or hierarchical fact.",source:"Where a rule comes from — statute, section, or authority.",trigger:"A fact cue that should make you think of a doctrine."},M=[{id:"pe-c-co-01",moduleId:"m09-company",type:"term",front:"What does it mean to say a company is a separate legal person?",back:"The company is treated as a person in its own right. It owns its property and owes its debts, not the people who set it up.",tags:["company","separate-personality","threshold-concept"],source:"Companies Act 2016"},{id:"pe-c-co-02",moduleId:"m09-company",type:"rule",front:"A Sdn Bhd cannot pay its supplier. Who does the supplier sue?",back:"The company. A member is not liable for the company's debts merely because they are a member.",tags:["company","limited-liability"],source:"Companies Act 2016"},{id:"pe-c-co-03",moduleId:"m09-company",type:"ratio",front:"What does Salomon v A Salomon and Co Ltd stand for?",back:"A properly registered company is a person separate from its owner, even where one man holds almost every share and runs everything.",tags:["company","separate-personality"],source:"Salomon v A Salomon and Co Ltd"},{id:"pe-c-co-04",moduleId:"m09-company",type:"trigger",front:"A bank asks a company's owner to sign a personal guarantee. Why does that matter?",back:"The guarantee is a separate contract of her own. It makes her personally liable, so limited liability no longer protects her.",tags:["company","guarantee","limited-liability"],source:"Ordinary contract law; Companies Act 2016 on the position of members"},{id:"pe-c-co-05",moduleId:"m09-company",type:"rule",front:"What two core duties does s 213 of the Companies Act 2016 place on a director?",back:"To act for a proper purpose and in good faith in the best interest of the company, and to exercise reasonable care, skill and diligence.",tags:["company","directors-duties"],source:"Companies Act 2016, s 213"},{id:"pe-c-co-06",moduleId:"m09-company",type:"structure",front:"The company made a profit. Can a shareholder simply take a share of it?",back:"No. Profit reaches shareholders only as a dividend the company declares and is permitted to pay. Until then it is the company's money.",tags:["company","shareholders","dividend"],source:"Companies Act 2016"},{id:"pe-c-co-07",moduleId:"m09-company",type:"rule",front:"Is owning every share and making every decision a reason to lift the corporate veil?",back:"No. Control alone is never a ground. That is the situation Salomon held to be perfectly lawful.",tags:["company","corporate-veil"],source:"Salomon v A Salomon and Co Ltd; standard doctrine"},{id:"pe-c-co-08",moduleId:"m09-company",type:"trigger",front:"A director diverts to himself a contract that was offered to the company. Who is the proper claimant?",back:"The company, because the duty is owed to it. A member's route is a derivative action or, for a wrong to himself, an oppression claim.",tags:["company","directors-duties","remedies"],source:"Companies Act 2016, ss 213 and 346"},{id:"pe-c-ev-01",moduleId:"m10-evidence",type:"term",front:"What is a fact in issue?",back:"A fact the case actually turns on, asserted by one side and denied by the other.",tags:["evidence","relevancy"],source:"Evidence Act 1950"},{id:"pe-c-ev-02",moduleId:"m10-evidence",type:"rule",front:"Under the Evidence Act 1950, when may a fact be proved?",back:"Only when it is a fact in issue, or a fact the Act itself declares relevant. There is no general residual category.",tags:["evidence","relevancy"],source:"Evidence Act 1950, s 5"},{id:"pe-c-ev-03",moduleId:"m10-evidence",type:"term",front:"What is hearsay?",back:"A second-hand account of what an absent person said, offered to prove that what they said was true.",tags:["evidence","hearsay"],source:"Evidence Act 1950; standard doctrine"},{id:"pe-c-ev-04",moduleId:"m10-evidence",type:"rule",front:"What is an admission, and who may it be used against?",back:"A statement by a party suggesting a fact against their own interest. It may be proved against the person who made it.",tags:["evidence","admissions"],source:"Evidence Act 1950"},{id:"pe-c-ev-05",moduleId:"m10-evidence",type:"rule",front:"In a civil claim, who carries the burden of proving a fact?",back:"Whoever asserts it. Section 102 places it on the party who would fail if no evidence at all were given on either side.",tags:["evidence","burden-of-proof"],source:"Evidence Act 1950, ss 101 and 102"},{id:"pe-c-ev-06",moduleId:"m10-evidence",type:"term",front:"What is the difference between the legal burden and the evidential burden?",back:"The legal burden is the risk of not persuading the court, and it does not shift. The evidential burden is the need to put up some evidence, and it moves during the trial.",tags:["evidence","burden-of-proof"],source:"Evidence Act 1950, Part II; standard doctrine"},{id:"pe-c-ev-07",moduleId:"m10-evidence",type:"rule",front:"What are the two standards of proof?",back:"Balance of probabilities in a civil case. Beyond reasonable doubt for the prosecution in a criminal case.",tags:["evidence","standard-of-proof"],source:"Standard doctrine under the Evidence Act 1950, Part II"},{id:"pe-c-ev-08",moduleId:"m10-evidence",type:"rule",front:"What does illustration (g) to s 114 of the Evidence Act 1950 allow?",back:"A court may presume that evidence a party could have produced, and did not, would have been unfavourable to that party. It is permissive, not automatic.",tags:["evidence","presumptions"],source:"Evidence Act 1950, s 114 illustration (g)"},{id:"pe-c-cp-01",moduleId:"m11-civil-procedure",type:"term",front:"Who are the plaintiff and the defendant?",back:"The plaintiff is the person who starts the claim. The defendant is the person it is brought against.",tags:["civil-procedure","parties"],source:"Rules of Court 2012"},{id:"pe-c-cp-02",moduleId:"m11-civil-procedure",type:"rule",front:"What is the general limitation period for a claim in contract or tort in Malaysia?",back:"Six years from the date the cause of action accrued, under the Limitation Act 1953. Accrual is not the date of discovery.",tags:["civil-procedure","limitation"],source:"Limitation Act 1953"},{id:"pe-c-cp-03",moduleId:"m11-civil-procedure",type:"structure",front:"When do you start a case by writ rather than by originating summons?",back:"By writ where the facts are disputed and witnesses are needed. By originating summons where the facts are agreed and the question is what a document means.",tags:["civil-procedure","commencement"],source:"Rules of Court 2012"},{id:"pe-c-cp-04",moduleId:"m11-civil-procedure",type:"trigger",front:"A defendant says he never received the court papers. Why is that serious?",back:"Service is a formal requirement. A judgment obtained without proper service can be set aside on that ground alone.",tags:["civil-procedure","service"],source:"Rules of Court 2012"},{id:"pe-c-cp-05",moduleId:"m11-civil-procedure",type:"rule",front:"What must a pleading contain?",back:"The material facts relied on. Not the evidence that proves them, and not the legal argument.",tags:["civil-procedure","pleadings"],source:"Rules of Court 2012"},{id:"pe-c-cp-06",moduleId:"m11-civil-procedure",type:"term",front:"What is discovery in a civil case?",back:"The stage where each side discloses the relevant documents it holds, including those that damage its own case. Privileged documents are listed but not produced.",tags:["civil-procedure","discovery"],source:"Rules of Court 2012"},{id:"pe-c-cp-07",moduleId:"m11-civil-procedure",type:"rule",front:"How does striking out differ from summary judgment?",back:"Striking out attacks the pleading on its face and assumes the pleaded facts are true. Summary judgment looks at the evidence and asks whether there is a triable issue.",tags:["civil-procedure","summary-disposal"],source:"Rules of Court 2012, Order 14 and Order 18 rule 19"},{id:"pe-c-cp-08",moduleId:"m11-civil-procedure",type:"trigger",front:"You have won judgment for RM20,000. Why might you still receive nothing?",back:"A judgment is not money. It has to be enforced, and enforcement fails where the defendant has no goods, land or bank balance to reach.",tags:["civil-procedure","enforcement"],source:"Rules of Court 2012"}],ne={schemaVersion:S,note:I,cardTypes:x,cards:M},j=1,q="Problem questions for the method modules. Facts are hypothetical unless a real case is named. Every problem carries the authorities its rubric relies on and a `verify` line naming what must be checked against a current source. The rubric is for self-marking; nothing here is an authority.",L={issue:"Did you find the question the facts actually raise?",rule:"Did you state the governing rule, with its source, accurately?",application:"Did you apply the rule to these facts rather than restate it?",conclusion:"Did you answer the question that was asked?",method:"Did you work in the right order?"},R=[{id:"pm-ratio-01",moduleId:"m00-foundations",title:"What the drainage case decides",kind:"analysis",minutes:30,marks:12,scenario:["The following is a hypothetical Court of Appeal judgment, written for this exercise. Puan Tan owns a shop lot. The local authority had for years maintained the storm drain running behind the row of shops. It stopped clearing the drain, the drain blocked, and floodwater ruined Puan Tan's stock. She sued in negligence and succeeded at first instance. The Court of Appeal dismissed the authority's appeal. Four passages from the leading judgment:","(1) “A public authority which has in fact assumed the task of maintaining a drainage system owes a duty of care to occupiers whose property is foreseeably at risk if that task is abandoned without warning. On these facts the duty was owed, and it was breached.”","(2) “Had the respondent's loss been purely economic — lost trade, say, with no damage to goods or premises — different considerations would arise. We have not heard argument on the point and express no view upon it.”","(3) “We would add that the statutory protection in the Street, Drainage and Building Act 1974 was not pleaded before us, and we say nothing about whether it would have availed the appellant.”","(4) “The appellant's submission that it lacked the funds to clear the drain is, in our judgment, irrelevant. A want of resources is no answer to a duty the authority has already taken upon itself.”"],task:"State the ratio decidendi of the case. Identify which passages are obiter and say why. Then advise a High Court judge who is hearing a claim by a neighbouring shopkeeper for lost trade only, with no physical damage, on how far this decision binds them.",rubric:[{id:"r1",band:"issue",marks:2,criterion:"Frames the exercise as separating the proposition the decision actually rested on from statements not necessary to it — not as summarising the case.",authority:"Ratio decidendi / obiter dictum"},{id:"r2",band:"rule",marks:2,criterion:"States the test: the ratio is the rule the court applied to the material facts to reach its result; a statement is obiter if the outcome would stand without it.",authority:"Standard common law doctrine"},{id:"r3",band:"application",marks:3,criterion:"Identifies passage (1) as the ratio — an assumed task of maintenance gives rise to a duty to foreseeably affected occupiers — and formulates it at a workable level of generality rather than reciting the passage.",authority:"Passage (1)"},{id:"r4",band:"application",marks:2,criterion:"Treats passage (4) as part of the ratio, not obiter, giving the reason: the lack of funds was argued and had to be rejected for the appeal to fail.",authority:"Passage (4)"},{id:"r5",band:"application",marks:2,criterion:"Identifies (2) and (3) as obiter, and notes that both are expressly reserved — the court says it heard no argument, which is the clearest possible marker.",authority:"Passages (2) and (3)"},{id:"r6",band:"conclusion",marks:1,criterion:"Concludes that the High Court is bound by the ratio but that the case decides nothing about pure economic loss; passage (2) is persuasive at most, and arguably not even that.",authority:"Court of Appeal binds the High Court"}],modelAnswer:[{h:"Issue",p:["Which proposition in the judgment was necessary to the result, and what is left for a later court to decide."]},{h:"Rule",p:["The ratio decidendi is the rule of law the court applied to the material facts in order to reach its decision. A statement is obiter dictum if the result would have been the same without it. The test is necessity, not emphasis: a long passage can be obiter and a single sentence can be the ratio."]},{h:"Application",p:["Passage (1) is the ratio. The authority had assumed the task of maintaining the drain; it abandoned it; Puan Tan's property was foreseeably at risk; the duty was owed and breached. Every element of the result rests on that proposition, and stated at a usable level of generality it is: a public authority that has in fact assumed a maintenance task owes a duty of care to occupiers foreseeably at risk if it abandons the task without warning.","Passage (4) is also part of the ratio, and it is the passage most often mis-sorted. The authority argued that it had no funds. If that argument were good the appeal would have succeeded, so rejecting it was necessary to the outcome. It is a second limb of the ratio, not a remark.","Passages (2) and (3) are obiter, and the court has said so in terms. On pure economic loss it states that it has heard no argument and expresses no view. On the statutory protection it notes the point was not pleaded and says nothing about its effect. A court that expressly declines to decide a point has not decided it, however suggestive its language.","For the neighbouring shopkeeper, the claim is for lost trade with no physical damage. That is precisely the case passage (2) reserved. The Court of Appeal's decision binds the High Court on the ratio — the assumed-task duty and the irrelevance of resources — but the ratio was reached on facts involving physical damage to goods, and the court flagged the distinction itself."]},{h:"Conclusion",p:["The High Court judge is bound by passages (1) and (4). On pure economic loss the case is not authority either way; passage (2) is at most a signal that the point is open, and the judge must decide it on principle and on whatever other authority exists. Citing passage (2) as though it decided anything would be an error."]}],traps:["Treating the resources point as obiter because it reads like an aside. It was argued and rejected; the appeal turned on it.","Reading passage (2) as authority that pure economic loss is not recoverable. It is authority for nothing — the court reserved the point.","Stating the ratio at the level of the facts (“the council is liable for the blocked drain”). A ratio that only fits one case binds no later one."],source:"Hypothetical facts. The doctrine is standard common law; no Malaysian statute is engaged.",lastVerified:"2026-09-07",verify:"Nothing here needs a citator. If you extend the exercise to the Street, Drainage and Building Act 1974 point, check the current text of that Act."},{id:"pm-sources-01",moduleId:"m00-foundations",title:"Which source governs",kind:"problem",minutes:40,marks:16,scenario:["You are asked to advise on two unrelated matters in the same afternoon.","First: a dispute in Negeri Sembilan over ancestral land held under adat perpatih. The parties are Malays of the same tribe. One side says the land descends through the female line under the adat; the other says the ordinary rules of inheritance in the Distribution Act 1958 should apply. There is no statute directly resolving the conflict on the facts you are given.","Second: a commercial agency dispute. There is no Malaysian decision on the precise point. There is an English Court of Appeal decision from 1950 that is squarely on point, and a decision of the English Court of Appeal from 1990 that reaches the opposite conclusion and describes the 1950 case as “no longer good law in this country”.","The junior drafting the opinion has cited the 1990 English decision as though it were binding."],task:"Advise on the sources of law that govern each matter, and correct the junior. Deal specifically with the status of the two English decisions.",rubric:[{id:"r1",band:"issue",marks:2,criterion:"Separates the two questions: what counts as law in Malaysia at all, and what weight an English decision carries once it does.",authority:"Art 160(2); Civil Law Act 1956 s 3"},{id:"r2",band:"rule",marks:3,criterion:"Cites Art 160(2) of the Federal Constitution: “law” includes written law, the common law so far as it is in operation, and any custom or usage having the force of law.",authority:"Federal Constitution, Art 160(2)"},{id:"r3",band:"rule",marks:3,criterion:"States s 3(1) of the Civil Law Act 1956 accurately, including the cut-off date for West Malaysia (7 April 1956) and the qualification that it applies only so far as local circumstances and the inhabitants permit.",authority:"Civil Law Act 1956, s 3(1)(a)"},{id:"r4",band:"application",marks:3,criterion:"Applies Art 160(2) to the adat: a custom with the force of law is law, and the adat perpatih is applied by the civil courts rather than displaced by the general law of distribution.",authority:"Art 160(2); customary tenure legislation of Negeri Sembilan"},{id:"r5",band:"application",marks:3,criterion:"Applies the cut-off to the two English cases: the 1950 decision is within the s 3 reception; the 1990 decision is after it and is at most persuasive, whatever it says about English law.",authority:"Civil Law Act 1956, s 3(1)(a)"},{id:"r6",band:"application",marks:1,criterion:"Notes the honest complication: Malaysian courts do in practice cite post-1956 English authority as persuasive, and some judgments treat later English cases as declaring what the common law always was.",authority:"Practice; contested"},{id:"r7",band:"conclusion",marks:1,criterion:"Concludes without overstating: the junior's citation is not wrong to make, but it is wrong to make as though it bound the court.",authority:"—"}],modelAnswer:[{h:"Issue",p:["Two questions. What sources are law in Malaysia for a matter of custom, and how far the English common law is received for a matter on which there is no local authority."]},{h:"Rule",p:["Article 160(2) of the Federal Constitution defines “law” as including written law, the common law in so far as it is in operation in the Federation or any part of it, and any custom or usage having the force of law. Custom is therefore not an inferior source that yields to statute by default; it is law.","Section 3(1) of the Civil Law Act 1956 provides that the court shall apply the common law of England and the rules of equity as administered in England on 7 April 1956 for West Malaysia (1 December 1951 for Sabah, 12 December 1949 for Sarawak), so far only as the circumstances of the States and their inhabitants permit and subject to such qualifications as local circumstances render necessary. Section 6 excludes English land law."]},{h:"Application",p:["On the first matter, adat perpatih is a custom having the force of law in Negeri Sembilan and falls within Art 160(2). It is applied by the civil courts as law, not received as evidence of a practice. The Distribution Act 1958 does not simply override it; the customary tenure legislation of the State governs land held on that tenure, and the question is one of characterising the land and the parties rather than of choosing between a modern statute and an old habit.","On the second matter, the 1950 English Court of Appeal decision was part of the common law as administered in England on 7 April 1956. It is received under s 3(1) subject to the local-circumstances qualification, and a Malaysian court would treat it as the received rule.","The 1990 decision is not received. It postdates the cut-off, and s 3 fixes reception at a date rather than creating a rolling link to English law. It may be cited as persuasive reasoning and often is; what it cannot do is displace the received rule by its own force. That the English court says the 1950 case is no longer good law in England is a statement about English law, and English law after 1956 is not our law.","The complication should be stated rather than hidden. Malaysian courts cite post-1956 English authority regularly, and there is a line of reasoning that treats a later English decision as declaring what the common law always was, which would pull it back inside the cut-off. That argument is available to the other side and the opinion should meet it."]},{h:"Conclusion",p:["The adat governs the first matter as law under Art 160(2). On the second, the 1950 decision is the received rule under s 3(1) of the Civil Law Act 1956 and the 1990 decision is persuasive only. The junior may cite it — but as an argument, not as an authority that binds."]}],traps:["Treating custom as something a statute automatically beats. Art 160(2) puts custom in the definition of law.","Forgetting that s 3(1) has three different cut-off dates, and using the West Malaysian one for a Sabah or Sarawak matter.","Citing a post-1956 English case without saying what its status is. The citation is not the error; the silence about its weight is."],source:"Federal Constitution Art 160(2); Civil Law Act 1956 ss 3, 6.",lastVerified:"2026-09-07",verify:"Check s 3(1) of the Civil Law Act 1956 against a current reprint for the exact dates and wording. Check which Negeri Sembilan customary tenure enactment applies before relying on the first limb in practice."},{id:"pm-precedent-01",moduleId:"m01-malaysian-legal-system",title:"Four decisions, one point",kind:"problem",minutes:35,marks:14,scenario:["You are advising a High Court judge who must decide a point of contract law. Four decisions bear on it, and they do not agree.","(i) A Federal Court decision from 1979, squarely on the point, deciding it one way.","(ii) A Privy Council decision from 1983, on a civil appeal from Malaysia, on the same point, deciding it the other way. It does not mention the 1979 decision.","(iii) A Court of Appeal decision from 2016 which follows the Privy Council and distinguishes the Federal Court decision on grounds the judge thinks are thin.","(iv) A High Court decision from 2021 by another judge which follows the 1979 Federal Court decision and does not cite the 2016 Court of Appeal case at all.","Counsel for the defendant argues that the Federal Court decision is the highest Malaysian authority and must prevail."],task:"Advise the judge which decisions bind them and which do not, and what they should do. Address counsel's argument directly.",rubric:[{id:"r1",band:"issue",marks:2,criterion:"Identifies the real question as the standing of pre-abolition Privy Council decisions relative to the Federal Court, not simply as a hierarchy exercise.",authority:"—"},{id:"r2",band:"rule",marks:3,criterion:"States the hierarchy — Federal Court, Court of Appeal, High Court — and that each is bound by those above it.",authority:"Courts of Judicature Act 1964"},{id:"r3",band:"rule",marks:3,criterion:"States that appeals to the Privy Council were abolished in stages, civil appeals last, and that a Privy Council decision delivered while it still sat at the apex on a Malaysian appeal binds courts below as if it were the apex court — so a 1983 civil decision is within that period.",authority:"Abolition of Privy Council appeals; civil appeals ended 1 January 1985"},{id:"r4",band:"application",marks:3,criterion:"Concludes that the 1983 Privy Council decision displaces the 1979 Federal Court decision on the point, and that counsel's argument fails because it treats the Federal Court as the apex for the whole period.",authority:"—"},{id:"r5",band:"application",marks:2,criterion:"Holds that the 2016 Court of Appeal decision binds the High Court whether or not the judge finds the distinction convincing — a lower court may not decline to follow a binding decision because it thinks the reasoning weak.",authority:"Vertical stare decisis"},{id:"r6",band:"conclusion",marks:1,criterion:"Treats the 2021 High Court decision as persuasive only, notes judicial comity, and says why it carries little weight here: it did not consider the binding Court of Appeal case.",authority:"Sundralingam v Ramanathan Chettiar [1967] 2 MLJ 211"}],modelAnswer:[{h:"Issue",p:["Which of the four decisions bind a judge of the High Court, and how the pre-1985 Privy Council decision fits the Malaysian hierarchy."]},{h:"Rule",p:["The superior courts run Federal Court, Court of Appeal, High Court, and each is bound by the courts above it. Appeals to the Privy Council were abolished in stages, criminal and constitutional appeals first and civil appeals last, with civil appeals ending on 1 January 1985. Until then the Privy Council was the final court on a Malaysian appeal, and a decision it gave in that period binds the Malaysian courts below in the ordinary way. It is not foreign authority; it is a decision of the apex court of this legal system as that system then stood.","A judge of the High Court is not bound by another judge of the High Court. Comity favours following a decision of coordinate jurisdiction unless convinced it is wrong: Sundralingam v Ramanathan Chettiar."]},{h:"Application",p:["Counsel's argument treats the Federal Court as the apex throughout. In 1983 it was not. The Privy Council decision is later and higher, and it displaces the 1979 Federal Court decision on the point even though it does not mention it — a superior court need not distinguish a decision it supersedes.","The 2016 Court of Appeal decision follows that line and binds the High Court. The judge's view that the distinction drawn is thin does not release them. A lower court that departs from a binding decision because it finds the reasoning weak has substituted itself for the appellate structure. If the reasoning is genuinely poor the remedy is to say so and give leave to appeal, not to disregard it.","The 2021 High Court decision is persuasive only, and here barely that. It follows a decision that had been superseded and it does not appear to have considered the 2016 Court of Appeal case, so it was reached per incuriam of authority that bound it."]},{h:"Conclusion",p:["The judge is bound by the 2016 Court of Appeal decision and should decide the point in accordance with it. Counsel's submission fails. The judge may record disagreement with the reasoning; they may not act on it."]}],traps:["Assuming a Privy Council decision is merely persuasive because the Privy Council is an English court. Before abolition it sat at the top of this hierarchy.","Letting the judge “prefer” the Federal Court decision because it is a Malaysian court and higher in name.","Missing that the 2021 decision is per incuriam of the Court of Appeal case, which is what removes almost all of its persuasive value."],source:"Courts of Judicature Act 1964; abolition of Privy Council appeals; Sundralingam v Ramanathan Chettiar [1967] 2 MLJ 211.",lastVerified:"2026-09-07",verify:"Confirm the abolition dates and the instruments that effected them (criminal and constitutional appeals ended before civil ones). Confirm Sundralingam's citation and that it is still relied on for comity between High Court judges."},{id:"pm-121a-01",moduleId:"m01-malaysian-legal-system",title:"Two courts, one child",kind:"problem",minutes:45,marks:18,scenario:["Suresh and Kavitha married in 2014 under the Law Reform (Marriage and Divorce) Act 1976. They have two children, aged six and nine. Both parents and both children were Hindu.","In January Suresh converted to Islam. In March, without telling Kavitha and without her presence or consent, he obtained certificates of conversion for both children from the State Islamic religious department. In May he obtained an order from the Syariah High Court granting him custody of both children.","Kavitha applies to the civil High Court for judicial review to quash the two conversion certificates, and for custody under the 1976 Act.","The religious department objects that the civil High Court has no jurisdiction. It relies on Article 121(1A) of the Federal Constitution and says that the conversion of a person to Islam and the custody of Muslim children are matters within the jurisdiction of the Syariah courts."],task:"Advise Kavitha on the jurisdictional objection and on the validity of the conversion certificates.",rubric:[{id:"r1",band:"issue",marks:2,criterion:"Separates the jurisdictional question from the merits: whether the civil court may hear her at all, and whether the certificates are valid.",authority:"—"},{id:"r2",band:"rule",marks:3,criterion:"States Art 121(1A) accurately — the civil High Courts have no jurisdiction in respect of any matter within the jurisdiction of the Syariah courts — and does not paraphrase it as a general ouster in religious matters.",authority:"Federal Constitution, Art 121(1A)"},{id:"r3",band:"rule",marks:4,criterion:"Relies on Indira Gandhi for the two propositions that decide the objection: judicial review is inherent in the civil courts and is part of the basic structure, and Art 121(1A) does not remove it.",authority:"Indira Gandhi a/p Mutho v Pengarah Jabatan Agama Islam Perak [2018] 1 MLJ 545 (FC)"},{id:"r4",band:"application",marks:3,criterion:"Makes the point that the Syariah courts' jurisdiction is over persons professing the religion of Islam, so a Syariah order cannot bind Kavitha, who is not one.",authority:"Ninth Schedule, List II, Item 1"},{id:"r5",band:"rule",marks:3,criterion:"States the consent point: Art 12(4) leaves the religion of a person under eighteen to be decided by their parent or guardian, and “parent” is read as requiring the consent of both where both are living.",authority:"Federal Constitution, Art 12(4); Eleventh Schedule"},{id:"r6",band:"application",marks:2,criterion:"Applies the consent point to the facts: Kavitha's consent was neither sought nor given, so the certificates are liable to be quashed.",authority:"—"},{id:"r7",band:"conclusion",marks:1,criterion:"Advises on remedy and forum, and does not claim the civil court will decide questions of Islamic law — only that it decides its own jurisdiction and the legality of the department's act.",authority:"—"}],modelAnswer:[{h:"Issue",p:["Whether Art 121(1A) prevents the civil High Court from hearing Kavitha's application, and whether conversion certificates obtained on one parent's application are valid."]},{h:"Rule",p:["Article 121(1A) provides that the civil High Courts shall have no jurisdiction in respect of any matter within the jurisdiction of the Syariah courts. It is a rule about overlap, not a general withdrawal of the civil courts from anything with a religious element.","In Indira Gandhi the Federal Court held that judicial review of administrative action is inherent in the civil courts and forms part of the basic structure of the Constitution, and that Art 121(1A) does not oust it. The Syariah courts are creatures of State law with jurisdiction over persons professing the religion of Islam, conferred by the Ninth Schedule, List II, Item 1.","Article 12(4) provides that the religion of a person under the age of eighteen shall be decided by his parent or guardian. Read with the Eleventh Schedule, under which the singular includes the plural, “parent” requires the consent of both parents where both are living."]},{h:"Application",p:["The objection misdescribes what Kavitha asks. She does not ask the civil court to rule on Islamic law. She asks it to review the legality of an administrative act — the issue of two certificates by a State department. That is judicial review, and Indira Gandhi holds that Art 121(1A) does not take it away.","The Syariah custody order cannot be an answer either. The Syariah courts' jurisdiction is over persons professing the religion of Islam. Kavitha does not, was not a party, and could not have been. An order obtained in a forum that has no jurisdiction over her cannot determine her rights against her.","On the certificates, the consent of both parents was required and Kavitha's was neither sought nor given. She was not told. On that ground the certificates are liable to be quashed.","The marriage remains one contracted under the 1976 Act, and the civil court retains jurisdiction over its dissolution and over custody as between these parties."]},{h:"Conclusion",p:["The jurisdictional objection should fail. The civil High Court may hear the judicial review, the certificates are vulnerable for want of the mother's consent, and the Syariah custody order does not bind Kavitha. Advise her to proceed by judicial review of the certificates and by an application under the 1976 Act for custody."]}],traps:["Reading Art 121(1A) as “if Islam is involved, the civil court is out”. It is about matters within Syariah jurisdiction, and the Syariah courts' jurisdiction has its own limits.","Arguing the merits of the conversion under Islamic law. That is exactly what the civil court will not do, and it is not what the application asks.","Forgetting that Kavitha's own status as a non-Muslim is what puts the Syariah order out of reach."],source:"Federal Constitution Arts 12(4), 121(1A), Ninth Schedule List II Item 1, Eleventh Schedule; Indira Gandhi a/p Mutho v Pengarah Jabatan Agama Islam Perak [2018] 1 MLJ 545 (FC).",lastVerified:"2026-09-07",verify:"Indira Gandhi is the controlling authority and its citation should be checked in a report you can hold. Read the Federal Court's reasoning on basic structure directly rather than through a summary — the case is cited for more than it decides. Check whether any later Federal Court decision has qualified it."},{id:"pm-research-01",moduleId:"m02-legal-research",title:"One case, found on a free portal",kind:"method",minutes:30,marks:14,scenario:["A senior asks you a question over the partition: “Can a landlord here distrain for rent without going to court first?”","You search a free case portal and find a High Court decision from 1989 which says, in a passage you can quote, that the landlord may proceed. You have found nothing else. The portal shows the judgment text and nothing more — no subsequent history, no note of any appeal, no list of cases citing it.","The senior wants an answer in an hour."],task:"Set out how you would verify the proposition before advising, in the order you would do it, and say what you would tell the senior at the end of the hour if you cannot complete every step.",rubric:[{id:"r1",band:"issue",marks:2,criterion:"Recognises that the first move is to find the governing statute, not to work outwards from the case. A case is evidence of what the law is; the Act is the law.",authority:"Distress Act 1951"},{id:"r2",band:"rule",marks:3,criterion:"Identifies the Distress Act 1951 as the governing instrument and that the statutory route runs through an application to the court for a warrant of distress, which answers the question directly.",authority:"Distress Act 1951"},{id:"r3",band:"application",marks:2,criterion:"Checks the currency of the Act itself — latest reprint, amending Acts, commencement of any amendment — rather than assuming the 1951 text is the operative text.",authority:"—"},{id:"r4",band:"application",marks:3,criterion:"States plainly that a free portal has no citator, so the case cannot be confirmed as good law from that source: no subsequent history, no overruling, no judicial consideration.",authority:"CLJ, LexisNexis CaseBase, Westlaw Asia"},{id:"r5",band:"application",marks:2,criterion:"Weighs the court level: a 1989 High Court decision binds nobody, and later Court of Appeal or Federal Court authority would displace it.",authority:"—"},{id:"r6",band:"application",marks:1,criterion:"Checks the report: whether the text is from an authorised series or an unreported transcript, and whether the passage is ratio or obiter.",authority:"—"},{id:"r7",band:"conclusion",marks:1,criterion:"Gives the senior a defensible answer with its limits stated — what is verified, what is not, and what would change the advice — rather than either a bare yes or a refusal to answer.",authority:"—"}],modelAnswer:[{h:"Issue",p:["Whether a single unverified High Court decision found on a free portal can support advice, and what must be done before it can."]},{h:"Method",p:["Start with the statute. Distress for rent in West Malaysia is governed by the Distress Act 1951, and the Act sets out the route: the landlord applies to a judge for a warrant of distress. That answers the senior's question at the level of the primary source, and it also tells me what the 1989 case can and cannot be about — it cannot authorise a landlord to bypass a procedure the Act lays down.","Then check the currency of the Act. Find the latest reprint, list the amending Acts, and confirm that any amendment relevant to the point is in force. An out-of-date statute text is the failure mode that a case search will never catch.","Then place the case. A 1989 High Court decision binds no court. It is persuasive. If there is later Court of Appeal or Federal Court authority the High Court decision is displaced, and the free portal will not tell me whether there is.","Then confront the gap directly. There is no citator on free Malaysian sources. I cannot establish from that portal that the case has not been overruled, reversed on appeal, distinguished into irrelevance, or superseded by amendment. That check needs CLJ, LexisNexis CaseBase or Westlaw Asia, and it is the one step I cannot do without a subscription.","Finally, read the judgment rather than the passage. Check whether the sentence I found is the ratio or an aside, what the pleaded issue was, and whether the report is an authorised one or an unreported transcript."]},{h:"Advice",p:["At the end of the hour I would tell the senior: the governing instrument is the Distress Act 1951 and it requires an application to the court for a warrant, so on the primary source the answer is no. I have one 1989 High Court decision that appears to say otherwise; it binds nobody, I have read it in full, and I have not been able to confirm whether it is still good law because the free sources have no citator. Before this goes to a client we need a citator check, and I would not advise a landlord to distrain without a warrant on the strength of what I have."]}],traps:["Answering from the case. The case was found first; that is an accident of the search, not an order of authority.","Treating “not overruled” as established because nothing came up. A free portal not showing an overruling is not evidence that there was none.","Refusing to advise at all. The senior asked a question with a deadline; the skill is a bounded answer with its limits on the face of it."],source:"Distress Act 1951. Method points are general research practice.",lastVerified:"2026-09-07",verify:"Confirm the section of the Distress Act 1951 that requires application to a judge, and confirm the Act's territorial application, before treating the statutory answer as settled. The point of this exercise is the method; do not carry the substantive answer into practice unchecked."}],oe={schemaVersion:j,note:q,bands:L,problems:R},P=1,E="Problem questions for the substantive modules. Facts are hypothetical; the authorities are real and are named in each rubric criterion. Every problem carries a `verify` line naming what must be checked against a current source before the reasoning is relied on. The rubric is for self-marking; nothing here is an authority.",W=[{id:"ps-art10-01",moduleId:"m03-constitutional",title:"The statement likely to cause disquiet",kind:"problem",minutes:45,marks:18,scenario:["Parliament enacts the Public Information (Amendment) Act 2026, a hypothetical statute. Section 4A makes it an offence, punishable by two years' imprisonment, to “publish any statement likely to cause public disquiet concerning the conduct of the police”. The long title says the Act is to preserve public order.","Aminah, a Malaysian citizen and a journalist, publishes a documented investigation into three deaths in police custody. Every fact in it is accurate. She is charged under s 4A.","The Deputy Public Prosecutor says that Article 10(2)(a) allows Parliament to impose such restrictions as it deems necessary or expedient in the interest of public order, that the word “deems” makes the question one for Parliament, and that the court's role is exhausted once the restriction is shown to fall under a permitted head."],task:"Advise Aminah on a constitutional challenge to s 4A. Address the Deputy Public Prosecutor's argument on the effect of the word “deems”.",rubric:[{id:"r1",band:"issue",marks:2,criterion:"Frames the issue as whether s 4A is a restriction Art 10(2)(a) permits, and how far the court may review Parliament's judgment that it is — not simply as whether free speech was infringed.",authority:"Federal Constitution, Art 10"},{id:"r2",band:"rule",marks:3,criterion:"States Art 10(1)(a) as a right of citizens, and confirms Aminah qualifies. States Art 4(1): the Constitution is the supreme law and a law inconsistent with it is void to the extent of the inconsistency.",authority:"Federal Constitution, Arts 4(1), 10(1)(a)"},{id:"r3",band:"rule",marks:3,criterion:"Sets out Art 10(2)(a) and the closed list of permitted heads, and does not treat the list as open-ended.",authority:"Federal Constitution, Art 10(2)(a)"},{id:"r4",band:"rule",marks:3,criterion:"States both sides of the authority: the deferential reading in Pung Chen Choon, and the reasonableness and proportionality reading in Sivarasa Rasiah, with Muhammad Hilman as an instance of a restriction actually struck down.",authority:"PP v Pung Chen Choon [1994] 1 MLJ 566 (FC); Sivarasa Rasiah v Badan Peguam Malaysia [2010] 2 MLJ 333 (FC); Muhammad Hilman bin Idham v Kerajaan Malaysia [2011] 6 MLJ 507 (CA)"},{id:"r5",band:"application",marks:3,criterion:"Argues the head first: “public disquiet concerning the conduct of the police” is not public order. Disquiet is a state of opinion; public order is about disorder. A restriction that does not fall within a permitted head fails whatever the standard of review.",authority:"Art 10(2)(a)"},{id:"r6",band:"application",marks:2,criterion:"Meets the “deems” argument rather than ignoring it: the word governs the necessity of the restriction, not whether it falls within a head at all, and Art 4(1) would be empty if Parliament's own characterisation were conclusive.",authority:"Art 4(1)"},{id:"r7",band:"application",marks:1,criterion:"Takes the point that truth is no defence under s 4A, and uses it — a provision that catches accurate reporting is hard to justify as proportionate on any view.",authority:"—"},{id:"r8",band:"conclusion",marks:1,criterion:"Advises realistically on the forum and the odds, and does not promise the challenge will succeed.",authority:"—"}],modelAnswer:[{h:"Issue",p:["Whether s 4A is a restriction that Art 10(2)(a) authorises, and how far a court may go behind Parliament's own view that it is."]},{h:"Rule",p:["Article 10(1)(a) guarantees to every citizen the right to freedom of speech and expression. Aminah is a citizen, so the right is engaged; the qualification matters because Art 10(1)(a) is not a right of everyone.","Article 10(2)(a) permits Parliament to impose by law such restrictions as it deems necessary or expedient in the interest of the security of the Federation, friendly relations with other countries, public order or morality, and restrictions designed to protect the privileges of Parliament or to provide against contempt of court, defamation, or incitement to any offence. The list is closed.","Article 4(1) makes the Constitution the supreme law and any inconsistent law void to the extent of the inconsistency.","The authority pulls in two directions. In Pung Chen Choon the Federal Court took a deferential view, treating “deems necessary or expedient” as leaving the necessity of a restriction to Parliament, with the court asking whether the restriction falls within a permitted head. In Sivarasa Rasiah the Federal Court held that fundamental liberties are to be read generously and that restrictions must be reasonable, importing proportionality. In Muhammad Hilman the Court of Appeal applied that approach and struck down a statutory restriction on student political expression."]},{h:"Application",p:["The strongest ground is the one that does not depend on which standard of review wins. Section 4A restricts speech “likely to cause public disquiet concerning the conduct of the police”. Public disquiet is a state of public opinion. Public order is the absence of disorder. A provision aimed at preventing people from becoming uneasy about the police is aimed at opinion, not at order, and it therefore does not fall within Art 10(2)(a) at all. A statute cannot bring itself within a permitted head by writing “public order” in the long title.","That is also the answer to the Deputy Public Prosecutor. “Deems necessary or expedient” goes to whether a restriction within a permitted head is needed. It does not make Parliament the judge of whether the head applies. If it did, Art 10(2) would impose no limit and Art 4(1) would have nothing to bite on, since every restriction would be validated by the legislature's own characterisation of it. Even on the deferential reading in Pung Chen Choon the court decides the head; deference operates inside it.","If the court reaches proportionality, Aminah's case is stronger still. Section 4A admits no defence of truth. It catches accurate reporting of deaths in custody — speech about the conduct of the State, which is the speech the guarantee most obviously exists to protect. On Sivarasa and Muhammad Hilman a restriction of that width is not a reasonable one, and it is not saved by a two-year penalty attached to publication alone.","The counter-argument should be faced. Pung Chen Choon is a Federal Court decision upholding a restriction on publication, and the prosecution will say Sivarasa concerned Art 10(1)(c) and Art 8 and did not displace it. The reply is that the two can be read together: the head question is for the court on either authority, and s 4A fails it."]},{h:"Conclusion",p:["Aminah has a real challenge. The best ground is that s 4A does not fall within any head permitted by Art 10(2)(a), with unreasonableness and disproportion as an alternative. Raise the constitutional point in the criminal proceedings and seek a reference of the constitutional question; do not advise her that the challenge is certain to succeed, because the deferential line of authority has not been overruled."]}],traps:["Arguing only that the right was infringed. Article 10(1) is always infringed by a restriction; the question is whether Art 10(2) permits it.","Conceding the head because the long title says public order. The characterisation is for the court.","Forgetting that Art 10(1)(a) protects citizens only, and not checking that the client is one.","Citing Sivarasa as though it had overruled Pung Chen Choon. It did not, and a good answer holds both."],source:"Federal Constitution Arts 4(1), 10(1)(a), 10(2)(a); PP v Pung Chen Choon [1994] 1 MLJ 566 (FC); Sivarasa Rasiah v Badan Peguam Malaysia [2010] 2 MLJ 333 (FC); Muhammad Hilman bin Idham v Kerajaan Malaysia [2011] 6 MLJ 507 (CA).",lastVerified:"2026-09-07",verify:"Check all three citations in a report you can hold, and check whether any later Federal Court decision has resolved the tension between Pung Chen Choon and Sivarasa. This is a live area; the balance may have moved. Article 10(4) is not engaged on these facts but read it before relying on the answer elsewhere."},{id:"ps-homicide-01",moduleId:"m04-criminal-law",title:"One blow with a brass lamp",kind:"problem",minutes:45,marks:18,scenario:["Hakim and Lim have been business partners for eleven years. Hakim comes to Lim's house to discuss a shortfall in the accounts. Lim, laughing, tells him that he has been taking money out of the company for two years, that there is nothing Hakim can do about it, and that Hakim's wife has known throughout and helped him hide it.","Hakim picks up a heavy brass lamp from the side table and strikes Lim once on the head. Lim falls and dies before the ambulance arrives.","The pathologist's evidence is that there was a single blow, that it fractured the skull, and that an injury of that kind is sufficient in the ordinary course of nature to cause death. There is no evidence that Hakim knew Lim had a thin skull or any other vulnerability.","Hakim's account in his cautioned statement is: “I did not plan anything. When he said that about my wife I saw red. I do not remember picking it up.”"],task:"Advise on Hakim's liability. Deal with the offence, with any exception he may rely on, and with the consequence if the exception succeeds.",rubric:[{id:"r1",band:"issue",marks:2,criterion:"Identifies the structure: culpable homicide is the genus, murder is culpable homicide plus one of the s 300 limbs, and the exceptions reduce murder back to culpable homicide not amounting to murder.",authority:"Penal Code ss 299, 300"},{id:"r2",band:"rule",marks:3,criterion:"States s 300(c) accurately: intention to cause the bodily injury actually caused, and that injury being sufficient in the ordinary course of nature to cause death.",authority:"Penal Code s 300(c)"},{id:"r3",band:"application",marks:3,criterion:"Applies the two limbs of s 300(c) separately, and identifies that the second limb is objective — it turns on the pathologist's evidence and not on what Hakim foresaw.",authority:"PP v Visuvanathan [1978] 1 MLJ 159, applying Virsa Singh"},{id:"r4",band:"application",marks:2,criterion:"Deals with the intention limb on the facts: a deliberate blow to the head with a heavy object supports an intention to cause that injury, and “I saw red” does not negate it.",authority:"—"},{id:"r5",band:"rule",marks:3,criterion:"States Exception 1 to s 300 with its elements — grave and sudden provocation, deprivation of the power of self-control, and death caused to the person who gave the provocation — and notes that whether provocation was grave and sudden is a question of fact.",authority:"Penal Code s 300, Exception 1 and its Explanation"},{id:"r6",band:"application",marks:3,criterion:"Argues Exception 1 on the facts in both directions: gravity is arguable on the accusation about the wife; suddenness is the weaker limb because Hakim came to the house to discuss the accounts, and the prosecution will say the words were a revelation rather than a provocation.",authority:"—"},{id:"r7",band:"conclusion",marks:1,criterion:"Reaches the right consequence if the exception succeeds: culpable homicide not amounting to murder under s 304, and identifies which limb of s 304 applies given the finding of intention.",authority:"Penal Code s 304(a)"},{id:"r8",band:"conclusion",marks:1,criterion:"States the sentencing position for murder with the correct caveat that the death penalty is no longer mandatory, without asserting the detail of the range from memory.",authority:"Penal Code s 302; Abolition of Mandatory Death Penalty Act 2023"}],modelAnswer:[{h:"Issue",p:["Whether Hakim committed murder, and whether the provocation exception reduces it."]},{h:"Rule",p:["Section 299 defines culpable homicide: causing death by an act done with the intention of causing death, or with the intention of causing such bodily injury as is likely to cause death, or with the knowledge that the act is likely to cause death. Section 300 defines when culpable homicide is murder, in four limbs. Section 300(c) is engaged where the act is done with the intention of causing bodily injury to any person, and the bodily injury intended to be inflicted is sufficient in the ordinary course of nature to cause death.","Section 300(c) has been read as two questions, the first subjective and the second objective: did the accused intend to inflict the injury that was in fact inflicted, and is that injury, objectively, sufficient in the ordinary course of nature to cause death. The accused's own view of how dangerous it was is irrelevant to the second.","Exception 1 to s 300 provides that culpable homicide is not murder if the offender, whilst deprived of the power of self-control by grave and sudden provocation, causes the death of the person who gave the provocation. The Explanation makes it a question of fact whether the provocation was grave and sudden enough to prevent the offence from being murder. The provisos exclude provocation sought or voluntarily provoked by the offender, provocation from an act done in obedience to the law, and provocation from an act done in the lawful exercise of the right of private defence."]},{h:"Application",p:["Death was caused by Hakim's act, so culpable homicide under s 299 is made out.","On s 300(c), the first limb asks whether Hakim intended the injury he inflicted. He picked up a heavy brass lamp and struck Lim on the head. That supports an intention to cause a head injury of that kind. “I saw red” goes to self-control, not to whether the blow was aimed; and “I do not remember picking it up” is a claim about memory rather than about intention. The second limb is answered by the pathologist: an injury of that kind is sufficient in the ordinary course of nature to cause death. That Hakim did not appreciate this does not assist him, and the absence of any known vulnerability in Lim removes the argument that the death was attributable to something unforeseeable rather than to the injury. Section 300(c) is made out and the offence is prima facie murder.","Exception 1 is Hakim's real case. On gravity, being told in his own partner's house that the partner has stolen from him for two years and that his wife was complicit is capable of amounting to grave provocation, and the Explanation leaves that to the tribunal of fact. Words alone are not excluded.","Suddenness is weaker, and it is where the case will be lost or won. Hakim went to the house to discuss a shortfall in the accounts, so the theft was already suspected. The prosecution will say the theft was a confirmation rather than a shock, and that what was genuinely new — the allegation about his wife — was an assertion by a man he had just found out was a thief. Against that, the reaction was immediate, there was no interval in which passion could cool, the weapon was to hand rather than fetched, and there was one blow rather than a sustained attack. On the facts as given, the defence has a real argument on suddenness but not an easy one.","None of the provisos applies: Hakim did not provoke the statement, and Lim was not acting in obedience to law or in private defence."]},{h:"Conclusion",p:["The prosecution can establish murder under s 300(c). Hakim's answer is Exception 1, which if accepted reduces the offence to culpable homicide not amounting to murder. Because the finding on s 300(c) is one of intention, the applicable limb is s 304(a) rather than the knowledge limb. On murder, the death penalty is no longer mandatory following the 2023 reform, so a plea in mitigation is worth making even on a murder conviction — but check the current sentencing provision before advising on the range."]}],traps:["Running s 300(a) — intention to cause death — because someone died. On one blow with an object picked up in the moment, s 300(c) is the natural limb, and it is easier for the prosecution.","Arguing that Hakim did not realise the blow could kill. Under s 300(c) that is not the question.","Treating provocation as a defence that acquits. It reduces the offence; it does not answer it.","Assuming words cannot be provocation. Under the Explanation it is a question of fact.","Stating the murder sentence from memory. The mandatory death penalty was abolished in 2023 and the provision must be read as it now stands."],source:"Penal Code (Act 574) ss 299, 300 and Exception 1, 302, 304; PP v Visuvanathan [1978] 1 MLJ 159, applying Virsa Singh v State of Punjab AIR 1958 SC 465; Abolition of Mandatory Death Penalty Act 2023.",lastVerified:"2026-09-07",verify:"Read ss 299, 300, 302 and 304 in a current reprint of Act 574 — the sentencing provisions were amended in 2023 and the ranges should not be quoted from memory. Confirm Visuvanathan's citation and check for a more recent Federal Court statement of the s 300(c) test."},{id:"ps-property-01",moduleId:"m04-criminal-law",title:"Three takings at the hardware shop",kind:"problem",minutes:40,marks:16,scenario:["Meera works as a cashier at a hardware shop. She is authorised to take payment from customers, issue receipts, and put the money in the till at the end of each transaction. Three things happen on the same Saturday.","(a) A customer pays her RM200 in cash for a set of tools. Meera issues no receipt, does not record the sale, and puts the RM200 in her own pocket.","(b) On her way out at closing time she takes a cordless drill from the display shelf, puts it in her bag, and leaves without paying. The shop has not consented.","(c) Earlier in the day she told a customer that the shop offers a delivery service for RM80. It does not. The customer paid her RM80 and she kept it.","She is arrested. The investigating officer proposes to charge all three as theft."],task:"Advise on the correct offence for each of (a), (b) and (c), and explain what distinguishes them. Say whether the investigating officer's proposal is right.",rubric:[{id:"r1",band:"issue",marks:2,criterion:"Identifies the organising question as how possession was obtained in each case, rather than what was taken or how much.",authority:"—"},{id:"r2",band:"rule",marks:3,criterion:"States s 378 theft: dishonestly taking movable property out of the possession of another, without that person's consent, and moving it in order to take it.",authority:"Penal Code s 378"},{id:"r3",band:"rule",marks:3,criterion:"States s 405 criminal breach of trust: being entrusted with property or with dominion over it, and dishonestly misappropriating or converting it to one's own use.",authority:"Penal Code s 405"},{id:"r4",band:"rule",marks:2,criterion:"States s 415 cheating: deceiving a person and thereby fraudulently or dishonestly inducing that person to deliver property, and identifies s 420 as the relevant punishment section where delivery is induced.",authority:"Penal Code ss 415, 420"},{id:"r5",band:"application",marks:2,criterion:"Classifies (a) as criminal breach of trust: Meera received the money lawfully in her capacity as cashier, so she was entrusted with it before she misappropriated it — there was no taking out of anyone's possession.",authority:"Penal Code s 405, and the aggravated form for a clerk or servant"},{id:"r6",band:"application",marks:2,criterion:"Classifies (b) as theft: the drill was in the shop's possession, Meera was never entrusted with it, and she moved it dishonestly without consent.",authority:"Penal Code s 378"},{id:"r7",band:"application",marks:1,criterion:"Classifies (c) as cheating: the customer parted with the money because of a deception, so consent was obtained rather than absent.",authority:"Penal Code ss 415, 420"},{id:"r8",band:"conclusion",marks:1,criterion:"Answers the officer directly and gives the reason in one line: consent, and how possession passed, separate the three offences.",authority:"—"}],modelAnswer:[{h:"Issue",p:["Whether all three takings are theft, and if not, what distinguishes them."]},{h:"Rule",p:["Section 378 defines theft: whoever, intending to take dishonestly any movable property out of the possession of any person without that person's consent, moves that property in order to such taking. The property must be taken out of another's possession, and it must be without consent.","Section 405 defines criminal breach of trust: whoever, being in any manner entrusted with property, or with any dominion over property, dishonestly misappropriates or converts it to his own use, or dishonestly uses or disposes of it in violation of any direction of law or legal contract. The offender begins with the property lawfully. Where the offender is a clerk or servant the offence is charged in its aggravated form.","Section 415 defines cheating: whoever, by deceiving any person, fraudulently or dishonestly induces the person so deceived to deliver any property to any person. Where the deception induces delivery, s 420 provides the punishment. Here the victim consents — but the consent is procured by deception."]},{h:"Application",p:["(a) Meera was authorised to take payment from customers. The RM200 therefore came into her hands lawfully, in her capacity as the shop's cashier; she held it for the shop. She did not take it out of anyone's possession, because she already had it. What she did was misappropriate property entrusted to her, which is criminal breach of trust under s 405, and as a servant of the shop it is the aggravated form. Failing to issue a receipt and failing to record the sale go to dishonesty and are strong evidence of it.","(b) The drill is different. It sat on the display shelf in the shop's possession. Meera was never entrusted with it — being a cashier does not put the stock in her hands. She moved it, dishonestly and without the shop's consent, in order to take it. That is theft under s 378.","(c) The RM80 is different again. The customer handed it over willingly. There was consent, so theft is out; and Meera was not entrusted with the money before it was paid, so criminal breach of trust is out. What made the customer part with it was a deception — a delivery service that does not exist. That is cheating, and because the deception induced delivery of property the charge falls under s 420."]},{h:"Conclusion",p:["The investigating officer is wrong on two of the three. Only (b) is theft. (a) is criminal breach of trust and (c) is cheating. The distinguishing question in every case is how the accused came to have the property: taken from another's possession without consent is theft; received lawfully and then misappropriated is criminal breach of trust; obtained by consent procured through deception is cheating."]}],traps:["Charging (a) as theft because the money belonged to the shop. Ownership is not the test — possession is, and Meera had it lawfully.","Charging (c) as theft because Meera ended up with money she was not entitled to. The customer consented; the vice is the deception, not the absence of consent.","Treating the cashier's authority as covering the stock. It covers the transactions she is authorised to handle and nothing else.","Forgetting the aggravated form of criminal breach of trust where the accused is a clerk or servant."],source:"Penal Code (Act 574) ss 378, 379, 405, 408, 415, 420.",lastVerified:"2026-09-07",verify:"Read ss 378, 405, 408, 415 and 420 in a current reprint of Act 574 before relying on the section numbers for the aggravated forms and the punishment provisions. The classification reasoning is settled; the numbering is what to check."},{id:"ps-formation-01",moduleId:"m06-contract",title:"Two letters in the post",kind:"problem",minutes:40,marks:16,scenario:["On 3 March, Syarikat Bina Jaya Sdn Bhd posts a letter to Ravi, a sand supplier in Ipoh, offering to buy 200 tonnes of river sand at RM95 a tonne. The letter states: “This offer is open until 17 March.” Ravi receives it on 5 March.","On 10 March Bina Jaya's director changes his mind. He posts a letter to Ravi revoking the offer. It is delivered to Ravi's office on 12 March in the afternoon. Ravi is away at a site and does not read it until 14 March.","On 12 March at 9 in the morning, Ravi posts a letter accepting the offer. It reaches Bina Jaya on 14 March.","Bina Jaya now refuses to take the sand. It says the offer had been revoked before Ravi accepted, and that in any event Ravi read the revocation before Bina Jaya read the acceptance. Ravi says the offer was open until 17 March and could not be withdrawn."],task:"Advise Ravi whether there is a contract. Deal with both parties' arguments.",rubric:[{id:"r1",band:"issue",marks:2,criterion:"Identifies the issue as when each communication became complete against the party it is being used against, not as who posted or read first.",authority:"Contracts Act 1950 s 4"},{id:"r2",band:"rule",marks:3,criterion:"States s 4(2)(a): communication of an acceptance is complete as against the proposer when it is put in a course of transmission to him, so as to be out of the power of the acceptor.",authority:"Contracts Act 1950 s 4(2)(a)"},{id:"r3",band:"rule",marks:3,criterion:"States s 4(3)(b): communication of a revocation is complete as against the person to whom it is made when it comes to his knowledge — not when it is delivered.",authority:"Contracts Act 1950 s 4(3)(b)"},{id:"r4",band:"rule",marks:2,criterion:"States s 5(1): a proposal may be revoked at any time before the communication of its acceptance is complete as against the proposer, but not afterwards.",authority:"Contracts Act 1950 s 5(1)"},{id:"r5",band:"application",marks:3,criterion:"Applies the sections to the dates and gets the order right: acceptance complete against Bina Jaya on 12 March when posted; revocation complete against Ravi on 14 March when read; so the revocation came too late.",authority:"—"},{id:"r6",band:"application",marks:2,criterion:"Disposes of Ravi's own argument as well: a promise to keep an offer open is not binding without consideration, so Bina Jaya could have revoked in time. Ravi wins on the timing, not on the promise.",authority:"Macon Works & Trading Sdn Bhd v Phang Hon Chin [1976] 2 MLJ 177"},{id:"r7",band:"conclusion",marks:1,criterion:"Concludes that a contract was formed on 12 March and advises on the practical consequence.",authority:"—"}],modelAnswer:[{h:"Issue",p:["Whether Bina Jaya's revocation took effect before Ravi's acceptance was complete."]},{h:"Rule",p:["Section 4 of the Contracts Act 1950 fixes when a communication is complete, and it fixes different moments depending on whom the communication is being used against.","By s 4(2)(a), the communication of an acceptance is complete as against the proposer when it is put in a course of transmission to him, so as to be out of the power of the acceptor. By s 4(2)(b), it is complete as against the acceptor only when it comes to the knowledge of the proposer.","By s 4(3)(a), the communication of a revocation is complete as against the person who makes it when it is put into a course of transmission. By s 4(3)(b), it is complete as against the person to whom it is made when it comes to his knowledge.","By s 5(1), a proposal may be revoked at any time before the communication of its acceptance is complete as against the proposer, but not afterwards."]},{h:"Application",p:["Take the acceptance first. Ravi posted it at 9am on 12 March. Under s 4(2)(a) it was complete as against Bina Jaya, the proposer, at that moment — when it left his hands. It does not matter that Bina Jaya did not receive it until 14 March.","Now the revocation. Bina Jaya is seeking to use it against Ravi, so the operative provision is s 4(3)(b): complete as against the person to whom it is made when it comes to his knowledge. Ravi did not read it until 14 March. Delivery to his office on the afternoon of 12 March is not knowledge, and s 4(3)(b) says knowledge.","Section 5(1) then decides the case. The proposal could be revoked at any time before communication of the acceptance was complete as against the proposer — that is, before 9am on 12 March. The revocation did not become effective against Ravi until 14 March. It was too late.","Bina Jaya's second argument, that Ravi read the revocation on 14 March before Bina Jaya read the acceptance on the same day, is beside the point. Section 4(2)(b) fixes when the acceptance binds the acceptor; it has nothing to do with whether the proposer may still revoke, which is governed by s 4(2)(a) and s 5(1).","Ravi's own argument should also be corrected, because it is wrong even though he wins. A promise to keep an offer open until a stated date is not binding without consideration: Macon Works & Trading Sdn Bhd v Phang Hon Chin. Had the revocation reached Ravi's knowledge on 11 March it would have been effective, and the words “open until 17 March” would not have saved him. He is protected by the postal rule in s 4(2)(a), not by the promise."]},{h:"Conclusion",p:["A contract was formed at 9am on 12 March when Ravi posted his acceptance. The revocation was ineffective. Bina Jaya is in breach by refusing to take the sand, and Ravi may claim under s 74 for the loss naturally arising from the breach, subject to his duty to mitigate by reselling the sand if he can."]}],traps:["Using one completion rule for everything. Section 4 gives different moments for acceptance and revocation, and different moments depending on which party the communication is used against.","Treating delivery to the office as communication of the revocation. Section 4(3)(b) says knowledge.","Accepting Ravi's argument that the offer could not be withdrawn before 17 March. It could; he simply won the race.","Comparing the two 14 March events as though the later reader loses. That is not what any of the subsections says."],source:"Contracts Act 1950 (Act 136) ss 4, 5(1), 6, 74; Macon Works & Trading Sdn Bhd v Phang Hon Chin [1976] 2 MLJ 177.",lastVerified:"2026-09-07",verify:"Read ss 4 and 5 in a current reprint of Act 136 and check the subsection lettering against your text before relying on it. Confirm the Macon Works citation."},{id:"ps-consideration-01",moduleId:"m06-contract",title:"Three promises Aishah has not kept",kind:"problem",minutes:40,marks:16,scenario:["Three separate promises, all made by or to Aishah.","(a) Aishah's dog went missing. Her neighbour Chong found it wandering two streets away and brought it back. Nobody had asked him to. A week later Aishah wrote and signed a note: “Thank you for finding Bobo. I will pay you RM500.” She has not paid. Chong sues.","(b) Aishah's father told her, in front of the family at dinner, that he would give her RM20,000 “out of natural love and affection” when she finished her degree. Nothing was written down. She finished the degree. He has not paid. Aishah wants to sue.","(c) Aishah borrowed RM3,000 from Devi in 2018 and never repaid it. The limitation period has expired. In 2025 Aishah signed a note reading: “I acknowledge that I owe Devi RM3,000 and I will pay it.” She has not paid. Devi sues.","A junior advises that all three promises fail for want of consideration, on the grounds that a past act is not consideration, that a family promise is not intended to create legal relations, and that a time-barred debt is unenforceable."],task:"Advise on each promise. Say where the junior is right and where the junior has applied English law to a Malaysian statute.",rubric:[{id:"r1",band:"issue",marks:2,criterion:"Recognises that consideration in Malaysia is defined by statute and that the English rules cannot be assumed to carry over.",authority:"Contracts Act 1950 ss 2(d), 26"},{id:"r2",band:"rule",marks:3,criterion:"Quotes or accurately paraphrases s 2(d), and draws out the two features that differ from English law: the act may be one the promisee 'has done', and it may be done by the promisee 'or any other person'.",authority:"Contracts Act 1950 s 2(d)"},{id:"r3",band:"rule",marks:3,criterion:"States s 26 and its three exceptions with their formalities: near relation with natural love and affection requires writing and registration; compensation for a voluntary past act; and a written signed promise to pay a statute-barred debt.",authority:"Contracts Act 1950 s 26(a), (b), (c)"},{id:"r4",band:"application",marks:3,criterion:"Advises that (a) succeeds, and gives both routes: past consideration is good consideration under s 2(d), and s 26(b) independently saves a promise to compensate for something already voluntarily done.",authority:"s 2(d); s 26(b); Kepong Prospecting Ltd v Schmidt [1968] 1 MLJ 170 (PC)"},{id:"r5",band:"application",marks:3,criterion:"Advises that (b) fails, and fails on the formality rather than on intention: s 26(a) requires writing and registration, and the promise was oral.",authority:"Contracts Act 1950 s 26(a)"},{id:"r6",band:"application",marks:1,criterion:"Advises that (c) succeeds under s 26(c), the promise being in writing and signed by the person to be charged.",authority:"Contracts Act 1950 s 26(c)"},{id:"r7",band:"conclusion",marks:1,criterion:"Answers the junior specifically, naming which of the three propositions is an English rule that s 2(d) displaces.",authority:"—"}],modelAnswer:[{h:"Issue",p:["Whether each promise is supported by consideration, or falls within an exception to the requirement."]},{h:"Rule",p:["Section 2(d) of the Contracts Act 1950 defines consideration: when, at the desire of the promisor, the promisee or any other person has done or abstained from doing, or does or abstains from doing, or promises to do or to abstain from doing, something, such act or abstinence or promise is called a consideration for the promise. Two things follow that English law does not give. Consideration may be past — the definition says “has done”. And it need not move from the promisee — the definition says “the promisee or any other person”.","Section 26 provides that an agreement made without consideration is void, unless it falls within one of three exceptions: (a) it is in writing and registered, and made on account of natural love and affection between parties standing in a near relation to each other; (b) it is a promise to compensate, wholly or in part, a person who has already voluntarily done something for the promisor; or (c) it is a promise, in writing and signed by the person to be charged, to pay wholly or in part a debt of which the creditor might have enforced payment but for the law of limitation.","Explanation 2 to s 26 adds that an agreement is not void merely because the consideration is inadequate, though inadequacy may be evidence on the question of free consent."]},{h:"Application",p:["(a) Chong found the dog before any promise was made, so on English principles this is past consideration and would fail. It does not fail here. Section 2(d) expressly includes an act the promisee “has done”, and the Privy Council in Kepong Prospecting Ltd v Schmidt treated services rendered before the agreement as good consideration under that definition. There is also an independent route: Chong acted voluntarily and for Aishah's benefit, and s 26(b) saves a promise to compensate a person who has already voluntarily done something for the promisor. Chong should succeed. The requirement in s 2(d) that the act be “at the desire of the promisor” is the point to watch, since Chong was not asked — which is why s 26(b) is the safer of the two arguments and should be pleaded first.","(b) The father's promise is unsupported by consideration in the ordinary sense: finishing a degree she was going to finish anyway was not requested as the price of the promise. It must therefore come within an exception, and the only candidate is s 26(a). That exception has two limbs and both must be satisfied — natural love and affection between parties in a near relation, and writing and registration. Father and daughter are in a near relation and the words “out of natural love and affection” are as clear as they could be. But the promise was made orally at dinner and nothing was written down, let alone registered. It fails on the formality. Aishah cannot sue.","(c) The debt is time-barred, so Devi could not have sued on the loan. Aishah's note of 2025 is a promise to pay a debt of which the creditor might have enforced payment but for the law of limitation, it is in writing, and it is signed by the person to be charged. It falls squarely within s 26(c) and Devi may enforce it."]},{h:"Conclusion",p:["(a) succeeds, (b) fails, (c) succeeds. The junior is right about (b), though for the wrong reason: it fails on the writing and registration required by s 26(a), not on intention to create legal relations. The junior is wrong about (a) and (c). The proposition that a past act is not consideration is English law; s 2(d) says otherwise, and it is the section that governs. The proposition that a statute-barred debt is unenforceable ignores s 26(c), which exists precisely for this case."]}],traps:["Importing the English rule against past consideration. Section 2(d) says “has done”, and the statute displaces the English position.","Failing s 26(a) on intention to create legal relations rather than on the missing formality. The Act gives a formality; use it.","Forgetting that s 26(a) needs registration as well as writing. Writing alone is not enough.","Missing that s 2(d) also allows consideration to move from a person other than the promisee — not in issue here, but the other half of the same sentence."],source:"Contracts Act 1950 (Act 136) ss 2(d), 26 and Explanation 2; Kepong Prospecting Ltd v Schmidt [1968] 1 MLJ 170 (PC).",lastVerified:"2026-09-07",verify:"Read s 26 and its exceptions in a current reprint of Act 136 — the registration requirement in exception (a) and the exact wording of (c) are what the answer turns on. Confirm the Kepong Prospecting citation and read what it actually decided about s 2(d), since the case is more often cited for privity."}],se={schemaVersion:P,note:E,problems:W},F=1,H="Problem questions written in the second pass, covering legal reasoning, statutory interpretation, contract remedies, negligence and judicial review. Every scenario is invented; no judgment quoted here is a real decision.",N=[{id:"pa-distinguish-01",moduleId:"m13-legal-reasoning",title:"The case that is nearly yours",kind:"analysis",minutes:35,marks:14,scenario:["The following are two hypothetical judgments written for this exercise. Neither is a real decision and neither should be cited.","In *Chandra v Perbadanan Kemajuan* (Federal Court, hypothetical), a statutory corporation ran a night market. It had for six years employed a marshal to control vehicle access to the loading bay. It stopped doing so without notice. A trader was struck by a reversing lorry in the bay and injured. The Federal Court held the corporation liable. The leading judgment said: 'Where a body has in fact assumed the task of controlling a known danger, and those who use the place have arranged their conduct on the footing that it continues to do so, it owes a duty to take reasonable care in the manner of its withdrawal. It was not obliged to employ a marshal. Having employed one for six years without qualification, it was obliged to say that it would stop.' The judgment added, in a separate paragraph: 'Whether a duty would arise where the body had never assumed the task at all is a different question, on which we have heard no argument.'","Your client is a stallholder at a different market run by the same corporation. The corporation has never employed a marshal there. Last month a delivery van reversed into her stall and destroyed her stock. She has no personal injury: her loss is the stock, and the four days of trade she lost while replacing it. She asks whether Chandra decides her case.","You are a pupil in chambers. Your master wants a note, not an opinion, and has asked specifically for the reasoning rather than the conclusion."],task:"State the ratio of Chandra. Identify what in it is obiter and why. Then say whether the decision binds a court hearing your client's claim, distinguishing it if it does not, and identify what further argument would be needed to succeed. Do not write a general essay on the duty of care.",rubric:[{id:"d1",band:"issue",marks:2,criterion:"Frames the question as whether the reasoning in Chandra extends to these facts — not as whether the client will win, and not as a general duty-of-care question.",authority:"Ratio decidendi / scope of precedent"},{id:"d2",band:"rule",marks:2,criterion:"States the test for ratio and obiter: the proposition the result required, with a statement being obiter if the outcome would stand without it.",authority:"Standard common law doctrine"},{id:"d3",band:"rule",marks:2,criterion:"States the test for distinguishing: a difference is material only if the earlier reasoning depends on it.",authority:"Standard common law method"},{id:"d4",band:"application",marks:3,criterion:"Formulates the ratio of Chandra at a workable level of generality — a duty arising from an assumed task of controlling a known danger, coupled with reliance, and going to the manner of withdrawal — rather than reciting the passage.",authority:"The leading judgment in Chandra"},{id:"d5",band:"application",marks:2,criterion:"Identifies the reservation on a body that never assumed the task as obiter, and gives the reason: the court expressly heard no argument on it.",authority:"The separate paragraph in Chandra"},{id:"d6",band:"application",marks:2,criterion:"Applies the distinction to the client's facts: the corporation never assumed the task at this market, so the fact the reasoning depends on is absent, and Chandra does not decide her case.",authority:"Application to the facts"},{id:"d7",band:"conclusion",marks:1,criterion:"Answers the question asked — Chandra does not bind on these facts — and identifies what would have to be argued instead rather than stopping at the negative.",authority:"Conclusion"}],modelAnswer:[{h:"Issue",p:["Whether the reasoning in Chandra reaches facts in which the corporation never assumed the task at all, and if not, what is left of the client's claim."]},{h:"Rule",p:["The ratio decidendi is the proposition of law the court applied to the material facts in order to reach its result. A statement is obiter if the result would have stood without it; necessity is the test, not emphasis or length.","To distinguish a binding decision, the difference identified between its facts and yours must be one the earlier reasoning depended on. Pointing to a difference the reasoning did not turn on is not distinguishing."]},{h:"Application",p:["The ratio of Chandra is that a body which has in fact assumed the task of controlling a known danger, in circumstances where users of the place have arranged their conduct on the footing that it continues, owes a duty to take reasonable care in the manner of its withdrawal. Two elements do the work: the assumption of the task, and the reliance built on it over six years. The court was explicit that the corporation was under no obligation to employ a marshal in the first place — the duty was about withdrawing, not about providing.","The final paragraph is obiter and the court says so in terms. It raises the case of a body that never assumed the task and states that it heard no argument on it. A court that expressly declines to decide a point has not decided it.","The client's facts fall squarely within that reservation. The corporation never employed a marshal at her market. There is therefore no assumed task and no reliance on its continuation, and the two facts the Chandra reasoning depends on are both absent. The difference is material in the strict sense: remove the assumption of the task and the reasoning has nothing to operate on.","It is worth noting what does not distinguish the case. That the client's loss is property and lost trade rather than personal injury is a difference, but Chandra did not turn on the type of damage, so standing alone it would not be a distinction — it may matter to remoteness or to recoverability of the trading loss, which is a separate question."]},{h:"Conclusion",p:["Chandra does not bind a court hearing this claim. It is distinguishable on the ground the Federal Court itself identified and reserved.","That is not the end of the client's claim. It means she cannot argue from an assumed task, and must instead establish a duty on ordinary principles — the relationship between an occupier or operator of premises and those invited to trade on them, and the foreseeability of vehicles reversing in a space shared with stalls. That is a different argument, and the note should say so rather than leaving the client with the impression that a favourable Federal Court decision covers her."]}],traps:["Treating the difference in the kind of damage as the distinction. It is a difference, but the Chandra reasoning did not depend on it, so on its own it distinguishes nothing.","Concluding that because Chandra does not bind, the claim fails. Distinguishing removes an authority; it does not decide the case.","Writing a general essay on the duty of care. The task asked for the reasoning about precedent, and marks follow the task."],source:"Standard common law doctrine on ratio decidendi, obiter dictum and distinguishing. Both judgments in the scenario are invented for this exercise.",lastVerified:"2026-09-07",verify:"The exercise is about method, so nothing here needs a citation check. What does need checking is any real authority you bring to the final paragraph: if you argue a duty on ordinary principles, cite a current Malaysian decision on the duty of care and confirm it in a report you can hold."},{id:"pa-interpretation-01",moduleId:"m14-statutory-interpretation",title:"Vehicles in the park",kind:"problem",minutes:40,marks:16,scenario:["The Recreational Grounds (Control) Enactment (a hypothetical State enactment, written for this exercise) provides:","Section 4(1): 'No person shall bring or permit to be brought into a public recreational ground any motor car, motor cycle, lorry, van or other vehicle.'","Section 4(2): 'Subsection (1) shall not apply to a vehicle used by an officer of the local authority in the performance of his duties.'","Section 9: 'Any person who contravenes section 4 commits an offence and shall on conviction be liable to a fine not exceeding two thousand ringgit.'","The long title of the Enactment is 'An Enactment to provide for the control of public recreational grounds and for the safety and quiet enjoyment of persons using them'.","Three prosecutions are brought. Encik Rahim wheeled a child's pram across the grounds. Puan Lim rode an electric mobility scooter, on which she depends to move at all, along the perimeter path. A group of volunteers carried in a decommissioned army jeep on a trailer and set it on a concrete plinth as a war memorial; the jeep has no engine and cannot move under its own power."],task:"Advise the prosecutor whether each of the three is caught by section 4(1). Set out the approach to construction you apply and the material you rely on, and reach a conclusion in each case.",rubric:[{id:"i1",band:"issue",marks:2,criterion:"Identifies the question as the scope of 'other vehicle' in s 4(1), and recognises that all three cases turn on that phrase rather than on three separate questions.",authority:"Section 4(1)"},{id:"i2",band:"rule",marks:3,criterion:"States the statutory direction to prefer a construction promoting the purpose or object of the Act, and correctly locates it in s 17A of the Interpretation Acts 1948 and 1967.",authority:"Interpretation Acts 1948 and 1967, s 17A"},{id:"i3",band:"rule",marks:2,criterion:"States ejusdem generis: general words following a list of specifics are read as confined to the same class as the specifics.",authority:"Standard canon of construction"},{id:"i4",band:"method",marks:2,criterion:"Establishes that the words are capable of more than one reading before turning to purpose, rather than beginning with purpose.",authority:"Order of construction"},{id:"i5",band:"application",marks:2,criterion:"Uses the long title, and the exemption in s 4(2) for vehicles used by officers on duty, as internal indications that the class contemplated is motorised vehicles capable of being driven — the exemption would be unnecessary otherwise.",authority:"Long title; s 4(2)"},{id:"i6",band:"application",marks:2,criterion:"Reaches a defensible answer on the pram, reasoning from the class established rather than asserting: not within the class of motorised vehicles, and outside the mischief of safety and quiet enjoyment.",authority:"Application"},{id:"i7",band:"application",marks:2,criterion:"Treats the mobility scooter as the genuinely arguable case and argues it both ways — motorised and rideable, and so arguably within the class; but excluding it would defeat the purpose of enjoyment of the grounds by those who depend on it, and a penal provision is construed strictly.",authority:"Application; strict construction of penal provisions"},{id:"i8",band:"conclusion",marks:1,criterion:"Answers on all three, including the memorial jeep, and takes a position rather than listing considerations.",authority:"Conclusion"}],modelAnswer:[{h:"Issue",p:["Whether a pram, an electric mobility scooter and an immobilised jeep on a plinth each fall within 'other vehicle' in s 4(1). All three turn on the same phrase, and the answer to each depends on the class the specific words establish."]},{h:"Rule",p:["Section 17A of the Interpretation Acts 1948 and 1967 requires that a construction which would promote the purpose or object underlying the Act be preferred to one which would not. That direction operates to choose between constructions the words can bear; where the language admits of only one meaning it does not displace it.","Where general words follow an enumeration of specific ones, the ejusdem generis principle reads the general words as confined to the same class as the specifics — provided a genus can be identified.","Section 4 is a penal provision, s 9 attaching a fine to its contravention. A penal provision is construed strictly, and an ambiguity that survives the ordinary process of construction is resolved in favour of the subject."]},{h:"Application",p:["The words are capable of more than one reading. 'Other vehicle' read at large would cover anything that carries a person or goods, including a pram and a wheelbarrow; read as limited by the preceding list it covers motorised vehicles only. Both readings are available, which is what makes s 17A relevant at all.","Two internal indications point to the narrower class. The specifics — motor car, motor cycle, lorry, van — are all motorised road vehicles, which supplies a genus. And s 4(2) exempts vehicles used by officers of the local authority in the performance of their duties: an exemption that makes sense for a works van and no sense at all for a pram, and which would be unnecessary if the class were as wide as the literal reading suggests. The long title confirms the purpose: safety and the quiet enjoyment of users, which is a mischief motorised vehicles create and prams do not.","The pram is therefore outside s 4(1). It is not of the same class as the specifics, and prohibiting it would not advance the purpose of the Enactment.","The mobility scooter is the difficult case, and an answer that disposes of it in a line has not seen the question. It is motorised and it is ridden, so it is closer to the genus than a pram is. Against that: the purpose of the Enactment is the enjoyment of the grounds by those using them, and a construction that excludes from a public recreational ground the only means by which a person can be present at all works against that purpose rather than for it. The provision is penal and is construed strictly. The better view is that it falls outside s 4(1), but the argument is genuinely two-sided and the prosecutor should be told that a court could go the other way.","The jeep on the plinth has no engine and cannot move. It is not brought into the grounds as a vehicle but installed as a monument, and it creates none of the risk the Enactment addresses. On a purposive construction it is not within the prohibition. A prosecutor advised otherwise should be reminded what the court would be asked to find: that a war memorial is a lorry, van or other vehicle."]},{h:"Conclusion",p:["Encik Rahim is not caught. The memorial jeep is not caught. Puan Lim is, on the better view, not caught, but that is the one of the three on which the prosecutor should expect argument, and it should not be brought on the assumption that it is clear."]}],traps:["Beginning with purpose. Section 17A chooses between available constructions; an answer that never shows the words are ambiguous has skipped the step that makes it apply.","Using ejusdem generis without identifying the genus. The principle needs a class, and saying so is part of the marks.","Disposing of the mobility scooter in a sentence. It is the one genuinely arguable case in the question and it carries the application marks.","Forgetting that s 4 is penal. Strict construction is a live point where an ambiguity survives."],source:"Interpretation Acts 1948 and 1967, s 17A; standard canons of construction (ejusdem generis, noscitur a sociis) and the presumption of strict construction of penal provisions. The Enactment is invented for this exercise.",lastVerified:"2026-09-07",verify:"Check the current text of s 17A of the Interpretation Acts 1948 and 1967 before quoting it, and check current Malaysian authority on the strict construction of penal provisions — the strength with which it is stated varies between judgments."},{id:"pa-remedies-01",moduleId:"m06-contract",title:"The sum in clause 11",kind:"problem",minutes:45,marks:18,scenario:["Seri Bina Sdn Bhd contracted with Datuk Farid to build a boutique hotel on his land. The contract price was RM6,000,000, and completion was fixed for 1 March. Clause 11 provided: 'In the event of delay in completion the Contractor shall pay to the Employer the sum of RM8,000 for each day of delay, which sum the parties agree is a genuine pre-estimate of the loss the Employer will suffer.'","Seri Bina completed on 30 April, sixty days late. Datuk Farid had intended to open the hotel on 15 March. He had taken no bookings, because his marketing manager had resigned in January and had not been replaced; the hotel in fact opened for business on 1 June, a month after the building was handed over, because of that.","Datuk Farid has withheld RM480,000 from the final payment, being sixty days at RM8,000. Seri Bina says it is entitled to the full balance. Datuk Farid's evidence of loss is a one-page projection of room revenue prepared by himself after the dispute arose.","In separate correspondence, Seri Bina says that the delay was caused by Datuk Farid's own late instructions on the facade, and that it wrote on 20 February asking for an extension of time, to which Datuk Farid never replied."],task:"Advise Seri Bina on its liability for the sum withheld. Deal with the effect of clause 11 and with what Datuk Farid must show to retain the money. You are not asked to advise on the extension of time claim, but say what you would need in order to advise on it.",rubric:[{id:"m1",band:"issue",marks:2,criterion:"Identifies the issue as the operation of s 75 on a sum named in the contract, and not as whether clause 11 is a 'penalty' at common law.",authority:"Contracts Act 1950, s 75"},{id:"m2",band:"rule",marks:3,criterion:"Sets out s 75: reasonable compensation not exceeding the sum named, whether or not actual damage is proved to have been caused.",authority:"Contracts Act 1950, s 75"},{id:"m3",band:"rule",marks:3,criterion:"Identifies that the Malaysian approach to s 75 changed: the strict requirement of proof of actual loss in Selva Kumar, and the reformulation in Cubic Electronics directing attention to legitimate interest and proportionality. Names both.",authority:"Selva Kumar v Thiagarajah; Cubic Electronics v Mars Telecommunications"},{id:"m4",band:"method",marks:2,criterion:"Treats the parties' own label — 'a genuine pre-estimate' — as evidence and not as conclusive, and says why.",authority:"Construction of clause 11"},{id:"m5",band:"application",marks:3,criterion:"Applies the reformulated approach: identifies the employer's legitimate interest in timely completion of a hotel, and asks whether RM8,000 a day is out of all proportion to it, using the contract price and the nature of the project as the measure.",authority:"Application"},{id:"m6",band:"application",marks:2,criterion:"Deals with the causation problem in the employer's own evidence: the hotel did not open because of the marketing manager's resignation, so a substantial part of the claimed loss was not caused by the delay.",authority:"Application; s 74 on remoteness and causation"},{id:"m7",band:"application",marks:2,criterion:"Assesses the quality of the evidence — a self-prepared post-dispute projection — and says what Datuk Farid would need instead.",authority:"Evidence of loss"},{id:"m8",band:"conclusion",marks:1,criterion:"Advises Seri Bina on the likely outcome and states what is needed to advise on the extension of time: the contract's EOT machinery, the notice provisions, and whether the 20 February letter complied with them.",authority:"Conclusion"}],modelAnswer:[{h:"Issue",p:["Whether Datuk Farid may retain RM480,000 under clause 11, and what he must establish to do so. The starting point is s 75 of the Contracts Act 1950, not the English distinction between liquidated damages and penalties."]},{h:"Rule",p:["Section 75 provides that where a sum is named in the contract as the amount to be paid in case of breach, the party complaining of the breach is entitled to receive reasonable compensation not exceeding the amount so named, whether or not actual damage or loss is proved to have been caused thereby.","The Malaysian gloss on that section has moved. In Selva Kumar the Federal Court required a plaintiff to prove actual loss and confined recovery to what was proved, subject to the named sum as a ceiling; the clause operated as a cap and little more. In Cubic Electronics the Federal Court revisited the approach, drawing on Cavendish Square Holding BV v Makdessi, and directed attention to whether the clause protects a legitimate interest of the innocent party and whether the sum stipulated is out of all proportion to that interest.","Section 74 remains the measure for loss otherwise, with its two limbs and its exclusion of remote and indirect loss."]},{h:"Application",p:["The clause describes itself as a genuine pre-estimate. That is evidence of the parties' intention and it is not conclusive: a label cannot convert a sum that is out of all proportion into one that is not, and the court looks at substance.","Datuk Farid has a legitimate interest in timely completion. A hotel is a revenue-producing asset and delay in handover is a real loss, which is precisely why parties to construction contracts stipulate daily rates. RM8,000 a day on a RM6,000,000 contract is roughly 0.13% of the contract price per day. That is not obviously extravagant for a hotel project, and on the Cubic Electronics approach Seri Bina would have difficulty showing the sum is out of all proportion to the interest protected.","The employer's difficulty is elsewhere, and it is causation. The hotel did not open on 15 March, but neither would it have opened then had the building been handed over on time: it opened on 1 June because there was no marketing manager from January, and the building was available from 30 April. On the employer's own account a month of the claimed loss flows from his own staffing and not from the delay. Even on the more generous reading of s 75, compensation must be reasonable, and compensating an employer for a loss the breach did not cause is not.","The evidence is also weak. A one-page projection prepared by the claimant after the dispute arose is the least persuasive form of evidence of loss available. What Datuk Farid would need is contemporaneous material: bookings actually cancelled, a rate card, occupancy at comparable properties in the period, and accounts showing the hotel's performance once open."]},{h:"Conclusion",p:["Seri Bina should expect Datuk Farid to be entitled to something under clause 11 — the interest protected is legitimate and the daily rate is not obviously disproportionate — but not to the full RM480,000 on the material as it stands. The causation point and the quality of the evidence are the two lines of attack, and they are stronger than an argument that the clause is unenforceable.","To advise on the extension of time I would need the contract's EOT provisions: what events entitle the contractor to an extension, what notice the contractor must give and within what period, whether the 20 February letter complied with those requirements, and what the consequences of the employer's silence are under the machinery. Without the contract, the letter proves only that a request was made."]}],traps:["Answering out of the English penalty cases and never citing s 75. The section is the source of the rule and the marks follow it.","Giving only Selva Kumar, or only Cubic Electronics. The sequence is the point: an answer with one and not the other has not shown it knows the position changed.","Treating the parties' description of the sum as a genuine pre-estimate as conclusive.","Missing that a month of the claimed loss was caused by the employer's own staffing, not by the delay."],source:"Contracts Act 1950 ss 74 and 75; Selva Kumar a/l Murugiah v Thiagarajah a/l Retnasamy [1995] 1 MLJ 817 (FC); Cubic Electronics Sdn Bhd (in liquidation) v Mars Telecommunications Sdn Bhd [2019] 6 MLJ 15 (FC); Cavendish Square Holding BV v Talal El Makdessi [2015] UKSC 67. The facts are invented for this exercise.",lastVerified:"2026-09-07",verify:"Both case citations must be confirmed in a report you can hold, and you must check whether any Federal Court decision since Cubic Electronics has qualified the approach. This is the single most movable point in the contract module and an answer relying on a stale statement of it is worse than one that says it does not know."},{id:"pa-negligence-01",moduleId:"m07-tort",title:"The scaffolding and the second fall",kind:"problem",minutes:45,marks:18,scenario:["Bina Kukuh Sdn Bhd erected scaffolding at a shoplot renovation. It omitted the toe boards required by its own method statement. A tin of paint was kicked off the platform by one of its workers and struck Mr Suresh, a passer-by, on the shoulder. He suffered a fracture.","At the hospital, a junior doctor read the wrong X-ray and discharged him without immobilising the arm. The fracture displaced and Mr Suresh now has permanent restricted movement. A consultant's report says that with correct treatment he would have made a full recovery in eight weeks; the misreading was, in her words, 'a serious departure from any acceptable standard'.","Mr Suresh had been walking in the roadway rather than on the five-foot way, which was clear and unobstructed, because he was looking at his telephone. Had he been on the five-foot way he would have been under the covered walkway and out of the line of the falling tin.","Mr Suresh is a freelance illustrator. He claims for the injury, for eleven months of lost commissions, and for the cost of retraining in a field that does not require fine motor control."],task:"Advise Mr Suresh on his claim against Bina Kukuh: whether the elements of negligence are made out, what damage the company is answerable for, and what reduction if any he should expect. Deal expressly with the hospital's treatment.",rubric:[{id:"n1",band:"issue",marks:2,criterion:"Identifies the issues as duty and breach against Bina Kukuh, the effect of the negligent medical treatment on causation, and apportionment for the claimant's own conduct — rather than treating it as a single question of liability.",authority:"Elements of negligence"},{id:"n2",band:"rule",marks:3,criterion:"States the elements in order — duty, breach, factual causation, legal causation, remoteness, damage — and states the but-for test accurately.",authority:"Standard common law"},{id:"n3",band:"rule",marks:2,criterion:"States the remoteness rule correctly: the kind of damage must be foreseeable, the extent need not be.",authority:"The Wagon Mound (No 1)"},{id:"n4",band:"rule",marks:2,criterion:"Identifies s 12 of the Civil Law Act 1956 as the source of apportionment for contributory negligence, and that it reduces rather than defeats the claim.",authority:"Civil Law Act 1956, s 12"},{id:"n5",band:"application",marks:3,criterion:"Applies duty and breach: a contractor erecting scaffolding over a public way owes a duty to passers-by, and departure from its own method statement is strong evidence of breach though not conclusive of it.",authority:"Application"},{id:"n6",band:"application",marks:3,criterion:"Addresses the medical treatment as a possible novus actus: negligent medical treatment does not ordinarily break the chain, but grossly negligent treatment may, and the consultant's characterisation is the material fact to argue from — both ways.",authority:"Novus actus interveniens"},{id:"n7",band:"application",marks:2,criterion:"Applies contributory negligence to walking in the roadway while looking at a telephone, and proposes a reasoned proportion rather than asserting that damages will be reduced.",authority:"Civil Law Act 1956, s 12"},{id:"n8",band:"conclusion",marks:1,criterion:"Advises on the heads of loss, distinguishing the eight weeks Bina Kukuh is answerable for from the permanent restriction if the chain is broken, and takes a position on the retraining claim.",authority:"Conclusion"}],modelAnswer:[{h:"Issue",p:["Three questions. Whether Bina Kukuh is liable in negligence at all. Whether it is answerable for the permanent restriction, or only for the injury as it would have resolved with proper treatment. And by what proportion any award should be reduced for Mr Suresh's own conduct."]},{h:"Rule",p:["The elements are duty, breach, factual causation, legal causation, remoteness and damage, and they are taken in that order because each assumes the one before.","Factual causation is the but-for test: would the damage have occurred but for the breach? Legal causation asks whether a later event broke the chain. Negligent conduct by a third party does not ordinarily do so where it was foreseeable; grossly negligent conduct may.","Remoteness: the defendant is liable for damage of a kind reasonably foreseeable, and it is no answer that the extent was greater than could have been foreseen.","Section 12(1) of the Civil Law Act 1956 provides that where a person suffers damage partly through his own fault and partly through the fault of another, the claim is not defeated but the damages are reduced to such extent as the court thinks just and equitable having regard to his share in the responsibility."]},{h:"Application",p:["Duty and breach are straightforward. A contractor erecting scaffolding over a public thoroughfare owes a duty to those passing beneath it; the risk of objects falling is the paradigm case. The omission of toe boards required by the company's own method statement is strong evidence of breach — a defendant that has identified the precaution itself and then not taken it is poorly placed to argue that a reasonable contractor would not have taken it. It is evidence and not conclusive: the standard is that of the reasonable contractor, and a method statement can set a standard above it.","Factual causation of the initial fracture is clear on the but-for test. The difficulty is the second injury. The junior doctor's misreading is negligent, and on the consultant's evidence it is 'a serious departure from any acceptable standard'. Ordinary negligent medical treatment following an injury is treated as foreseeable and does not break the chain; the tortfeasor takes the risk that treatment will be imperfect. Grossly negligent treatment is capable of breaking it, and the consultant's characterisation is the fact from which that argument is built. The argument runs both ways and should be presented both ways: for Mr Suresh, that the treatment was a misreading rather than an act of a different character, and that the defendant should not escape the consequences of an injury it caused; for Bina Kukuh, that the permanent restriction is attributable entirely to the hospital's failure and that a full recovery in eight weeks was the natural course of the injury it caused.","Remoteness does not assist Bina Kukuh on the injury itself. Physical injury from a falling object is the very kind of damage the missing toe boards would have prevented, and the extent of it is irrelevant to foreseeability.","Contributory negligence is made out. Mr Suresh was in the roadway, on his telephone, when a clear covered walkway was available, and had he used it he would not have been struck. That is a failure to take reasonable care for his own safety which contributed to the damage. On facts of this kind a reduction in the region of twenty to twenty-five per cent would be defensible; the figure should be reasoned from his share in the responsibility, not asserted."]},{h:"Conclusion",p:["Bina Kukuh is liable in negligence for the fracture. Whether it is answerable for the permanent restriction turns on the medical evidence about the character of the hospital's failure, and Mr Suresh should be advised that this is genuinely uncertain and that the hospital or its employer is a proper additional defendant.","On damages: the eight weeks of lost commissions are recoverable in any event. The remaining lost commissions and the retraining costs depend on whether the chain was broken. The retraining claim is in principle recoverable as the cost of mitigating a permanent loss of earning capacity, but it must be shown to be reasonable, and it stands or falls with the permanence of the restriction."]}],traps:["Treating the hospital's negligence as automatically breaking the chain. The ordinary rule is the opposite, and the argument is about whether this was gross enough to be an exception.","Using novus actus and contributory negligence as if they were the same idea. One defeats, the other reduces.","Asserting that damages 'will be reduced' without proposing a proportion and reasoning to it.","Forgetting to advise that the hospital or its employer should be joined."],source:"Standard common law elements of negligence; The Wagon Mound (No 1) [1961] AC 388 on remoteness; Civil Law Act 1956 s 12 on apportionment. The facts are invented for this exercise.",lastVerified:"2026-09-07",verify:"Check s 12 of the Civil Law Act 1956 against the current text, and find current Malaysian authority on the duty of care test and on whether grossly negligent medical treatment breaks the chain of causation — the English cases are persuasive only and should not be cited as if they settled the Malaysian position."},{id:"pa-jr-01",moduleId:"m12-administrative",title:"The licence revoked on a Friday",kind:"problem",minutes:45,marks:18,scenario:["The Hawkers and Petty Traders Board of a local authority has for eleven years renewed Puan Kamala's licence to trade from a fixed stall. Each renewal has followed a written application and, where any complaint has been made, a meeting at which the trader has been heard. That practice is not in any regulation; it is what the Board has always done, and it is described in a leaflet the Board publishes for applicants.","On a Friday afternoon Puan Kamala received a letter revoking her licence with immediate effect. The letter said only: 'Following consideration of complaints received, the Board has resolved to revoke the licence.' She has not been told what the complaints were or who made them, and she was not invited to any meeting.","She has since learned two things. The first is that the complaints came from the proprietor of a restaurant beside her stall. The second is that the chairman of the Board is that proprietor's brother-in-law, and that he chaired the meeting at which the revocation was resolved and voted on it.","The revocation was on 4 April. She consulted you on 20 September, having spent the intervening months writing to the Board and to her assemblyman."],task:"Advise Puan Kamala on an application for judicial review: the grounds available, the relief to seek, and the procedural obstacles. Advise on the prospects honestly, including anything that may defeat the application regardless of its merits.",rubric:[{id:"j1",band:"issue",marks:2,criterion:"Identifies both substantive grounds — breach of the right to be heard and apparent bias — and recognises that the delay is a threshold problem to be dealt with first, not an afterthought.",authority:"Order 53; natural justice"},{id:"j2",band:"rule",marks:3,criterion:"States the two rules of natural justice accurately: notice of the case and an opportunity to answer; and no person a judge in his own cause, tested objectively.",authority:"Audi alteram partem; nemo judex in causa sua"},{id:"j3",band:"rule",marks:2,criterion:"States the requirements for a legitimate expectation: a clear representation or settled practice, and that a procedural expectation is the more secure form.",authority:"Legitimate expectation"},{id:"j4",band:"method",marks:3,criterion:"Identifies Order 53 as the route, the requirement of leave, the requirement that the applicant be adversely affected, and the time limit running from when the grounds arose — and applies the time limit to the six-month delay.",authority:"Rules of Court 2012, O 53"},{id:"j5",band:"application",marks:3,criterion:"Applies audi alteram partem: a revocation affecting livelihood, given without notice of the substance of the complaints or any opportunity to answer, and against a settled practice of hearing the trader, is a clear breach.",authority:"Application"},{id:"j6",band:"application",marks:2,criterion:"Applies the bias rule: the chairman's relationship to the complainant and his participation in and vote on the decision would lead a fair-minded and informed observer to see a real danger of bias; actual bias need not be shown.",authority:"Application"},{id:"j7",band:"application",marks:2,criterion:"Identifies the relief — certiorari to quash, and remitter for reconsideration by a differently constituted Board — and explains why the court will not ordinarily substitute its own decision on the licence.",authority:"Relief"},{id:"j8",band:"conclusion",marks:1,criterion:"Gives an honest overall assessment, including that the merits may not be reached if leave is refused for delay, and advises what must be filed and how quickly.",authority:"Conclusion"}],modelAnswer:[{h:"Issue",p:["Whether the revocation is amenable to judicial review on the grounds of breach of natural justice and apparent bias, and whether an application made more than five months after the decision can get past the threshold requirements of Order 53."]},{h:"Rule",p:["Audi alteram partem requires that a person liable to be affected by a decision be given notice of the case against him and a fair opportunity to answer it. What fairness requires varies with the decision; a decision removing a livelihood attracts a high level of protection.","Nemo judex in causa sua: no person may be a judge in his own cause. Actual bias need not be shown. The test is objective — whether a fair-minded and informed observer would conclude that there was a real danger, or real possibility, of bias.","A legitimate expectation may arise from a clear and unambiguous representation or from a settled practice. A procedural expectation — that a person will be heard, or consulted, before a decision is taken — is the more secure form and does not require the substantive benefit to be conferred.","Judicial review is brought under Order 53 of the Rules of Court 2012. Leave is required; the applicant must be adversely affected by the decision; and the application must be made within the period the rule prescribes, running from the date when the grounds for the application first arose. Relief includes certiorari, prohibition, mandamus, declaration and injunction."]},{h:"Application",p:["The substantive grounds are strong. Puan Kamala was told only that complaints had been considered. She was not told what was alleged, by whom, or when, and she was given no opportunity to answer. A decision terminating an eleven-year livelihood on that basis is a breach of the right to be heard on any view of what fairness required here.","The Board's settled practice reinforces it. For eleven years the Board has held a meeting where a complaint was made, and it publishes that practice in a leaflet. That is a settled practice and a representation, and it founds a procedural legitimate expectation that she would be heard before her licence was revoked. Departing from it without notice is itself reviewable.","The bias ground is at least as strong. The chairman is the complainant's brother-in-law; he chaired the meeting and voted. A fair-minded and informed observer, knowing those facts, would conclude there was a real danger that the decision was affected. Nothing turns on whether the chairman was in fact influenced, and it would be a mistake to plead the case as one of actual bias.","The relief to seek is certiorari to quash the revocation, together with a declaration if useful, and remitter to a differently constituted Board for reconsideration according to law. The court reviews the process; it will not ordinarily decide for itself whether Puan Kamala should hold a licence, because that is the decision Parliament has entrusted to the Board.","The obstacle is delay. The revocation was on 4 April and she consulted you on 20 September. Under Order 53 the application for leave must be made within the prescribed period from the date the grounds arose, and correspondence with the Board and with an assemblyman does not stop time running. Whether an extension is available, and on what basis, must be checked against the current text of the rule and current authority; the explanation for the delay, the absence of prejudice to third parties, and the strength of the merits are the material an application to extend would be built on."]},{h:"Conclusion",p:["On the merits the application is strong on both grounds, and either alone would justify quashing the decision. The realistic risk is that the merits are never reached: leave may be refused because the application is out of time, and that must be put to her plainly rather than mentioned at the end.","The immediate step is to file the leave application without any further delay, supported by an affidavit exhibiting the leaflet describing the Board's practice, the revocation letter, and the evidence of the relationship between the chairman and the complainant, together with a full and candid explanation of the five months. Every further week weakens the application to extend time."]}],traps:["Leaving the time limit to the end, or omitting it. It is capable of ending the case regardless of the merits, and an advice that buries it has not advised the client.","Pleading actual bias. The objective test is easier to satisfy and does not require an allegation of dishonesty against the chairman.","Asking the court to restore the licence. Review goes to the process; the remedy is to quash and remit.","Treating the leaflet and the eleven-year practice as irrelevant because they are not in any regulation. That is precisely what founds the legitimate expectation."],source:"Rules of Court 2012, Order 53; the rules of natural justice and the doctrine of legitimate expectation as received in Malaysia. The facts are invented for this exercise.",lastVerified:"2026-09-07",verify:"Check the current Order 53 for the leave requirement, the standing formula and the time limit, including any power to extend. Check current Malaysian authority for the formulation of the bias test and for the reception of legitimate expectation, and cite Malaysian decisions rather than English ones."}],re={schemaVersion:F,note:H,problems:N},B=1,O="Practice for the four skill modules, sitting between a five-minute card and a full unassisted problem. Three of the four are guided: the task walks you through the steps in order and does part of the reasoning for you, and they carry fewer marks because less of the work is yours. Do the guided one first, then the open one in the same module. All facts are invented unless a real source is named.",D=[{id:"pf-prob-study",moduleId:"m-study-method",title:"A week you can actually keep",kind:"guided",minutes:20,marks:8,scenario:["Suraya is twenty-nine. She works six days a week at a pharmacy in Seremban and is home by seven. Sunday belongs to her mother. She has decided to work through the first modules of this site on her own, with nobody to answer to.","Her honest guess at free time: about forty minutes on most weeknights, and two hours on a Saturday afternoon. Some weeks she will get none of it, and she knows it.","Her plan so far is one line long. Read one lesson every night until the module is finished.","This exercise walks you through fixing that plan. The first two steps are largely done for you. Write your answers down rather than doing them in your head."],task:"Work through five steps in order, writing a short answer to each. Step 1: name the single biggest weakness in Suraya's plan. The hint is that her plan is all input — ask yourself which part of her evening would ever tell her whether anything stayed. Step 2: rewrite one weeknight as a timed session in three parts, ten minutes, twenty minutes and ten minutes. Say which part is which, and say why the order matters. Step 3: decide what goes in the Saturday session that cannot go in a weeknight, and say why it needs the longer block. Step 4: write three questions Suraya could ask herself from memory next week about a lesson she reads tonight. They must be questions rather than topics, and each must have a short answer she can check. Step 5: write the one rule she will follow on the first night back after a week when she did nothing. One sentence, and it must be small enough to do while tired.",rubric:[{id:"pf-r-study-1",band:"method",marks:2,criterion:"Names the weakness as retrieval, not time: the plan is reading only, so it produces fluency rather than memory and gives Suraya no way of knowing what she has lost.",authority:"Retrieval practice; Make It Stick"},{id:"pf-r-study-2",band:"method",marks:2,criterion:"Builds a session that opens with recall of old material from memory, reads new material in the middle, and closes with writing from a shut book. Explains that testing before reviewing is what makes the reading stick.",authority:"Retrieval practice; Make It Stick"},{id:"pf-r-study-3",band:"method",marks:1,criterion:"Gives the Saturday block a job a weeknight cannot do — a full problem question written under time, or a long judgment read properly — rather than simply more of the same reading.",authority:"Standard study practice"},{id:"pf-r-study-4",band:"application",marks:2,criterion:"Writes three real questions with short checkable answers. A question begins with what, why, which or how; a topic is a noun phrase and earns nothing here.",authority:"Retrieval practice"},{id:"pf-r-study-5",band:"conclusion",marks:1,criterion:"The restart rule is small, concrete, and starts with old material. Any answer that involves catching up or a bigger week loses this mark.",authority:"Standard study practice"}],modelAnswer:[{h:"Step 1 — the weakness",p:["The plan is all input. Reading a lesson is the only thing in it, so there is no moment at which Suraya finds out whether anything stayed. She will finish the module feeling informed and will not be able to produce much of it a fortnight later.","It is also brittle. A plan built on doing something every night breaks the first time a night is lost, and she has told us that nights will be lost."]},{h:"Step 2 — one weeknight",p:["Ten minutes of cards and self-questions on last week's material, from memory, before anything is opened. Twenty minutes reading one section of a lesson slowly, stopping to write. Ten minutes with the screen shut, writing down what she can recall and three questions she could not answer.","The order matters because the recall has to happen while the material is still partly forgotten. If she reads first, the answers are fresh and she will only be recognising them. Recognition is easy and it is not the skill she needs."]},{h:"Step 3 — Saturday",p:["The Saturday block gets a full problem question, written out under time, without notes. That cannot be done in forty tired minutes on a weeknight, because it needs an unbroken stretch and a fresh head.","Marking it herself against the rubric comes in the same block, while she can still remember what she meant."]},{h:"Step 4 — three questions",p:["Which court is at the top of the civil hierarchy? What makes a fact material? What is the difference between binding and persuasive authority?","Each is a question, each has a one-line answer, and each can be checked against the lesson. Chapter three or Precedent would be topics, and a topic cannot be got right or wrong."]},{h:"Step 5 — the restart rule",p:["On the first night back, do fifteen cards she already knows and nothing else.","It is small enough to do while tired, it needs no decision, and it puts her back in the habit before it asks her to learn anything."]}],traps:["Fixing the plan by adding hours. She does not have them, and a plan she cannot keep fails twice over.","Writing topics instead of questions in step 4. A topic cannot be answered, so it cannot be checked.","Making the restart rule ambitious. The whole value of it is that it is too small to argue with."],source:"Retrieval practice, spacing and interleaving research as summarised in Make It Stick. The facts are invented.",lastVerified:"2026-09-07",verify:"Nothing here is a rule of law and no citator applies. The learning claims are empirical rather than legal; the underlying studies are cited in Make It Stick.",selfMarkNote:"Mark step 4 hardest. Most people write topics, believe they wrote questions, and lose both marks without noticing."},{id:"pf-prob-research",moduleId:"m02-legal-research",title:"Tracing a forwarded message",kind:"guided",minutes:20,marks:9,scenario:["A message reaches you after being forwarded three times. It reads: NEW LAW — from this month a landlord in Malaysia may keep your whole deposit if you move out before the end of your tenancy. Share this with everyone.","It names no Act, no section and no court. It carries no date. It ends with the name of a page that sells tenancy agreement templates.","Your cousin is moving out of a rented room in Cheras three weeks early. He wants to know whether to expect his eight hundred ringgit back.","You have a phone, no subscription to any legal database, and about an hour. This exercise walks you through the steps. The first two are partly done for you."],task:"Write a short answer to each step, in order. Step 1: sort the message into one of the three piles from the lesson — the law itself, a record of what a court decided, or somebody talking about the law. It is the third. Say what that means for the weight it can carry, and say what it is still useful for. Step 2: list the four questions you ask of any source before trusting it, and apply each one to this message in a single line. Step 3: say where you would go for the primary text and name the body that publishes it free. You do not have an Act name yet, so also say how you would get one. Step 4: write out the note you would keep of whatever you find. List the fields and say why each one is there. Step 5: write the two sentences you would send your cousin at the end of the hour. One says what you have checked. One says plainly what you could not check, and why.",rubric:[{id:"pf-r-research-1",band:"method",marks:2,criterion:"Classifies the message as comment rather than a source, and gives the reason that decides it: naming no Act and no section, it cannot be checked, so it can only be a lead to the primary text.",authority:"Standard research practice"},{id:"pf-r-research-2",band:"method",marks:2,criterion:"Applies all four tests — who published it, whether a provision is named, whether it is dated and versioned, and whether the writer is selling something — and notices the template seller at the end.",authority:"Standard research practice"},{id:"pf-r-research-3",band:"rule",marks:2,criterion:"Goes to the official free text published by the Attorney General's Chambers, and describes a workable route to an Act name: the words of the tenancy agreement, the subject matter of the dispute, or a provision named in any secondary article.",authority:"Attorney General's Chambers, Malaysia"},{id:"pf-r-research-4",band:"method",marks:1,criterion:"Keeps a retraceable note — the source, the exact provision, the words relied on, and the date read — and says that the point of it is being able to find it again and show how it was found.",authority:"Standard research practice"},{id:"pf-r-research-5",band:"conclusion",marks:2,criterion:"Gives a bounded answer rather than a bare yes or a refusal: what is verified, what is not, and the fact that free sources carry no citator, so no case found on one can be confirmed as still good law.",authority:"CLJ; LexisNexis CaseBase; Westlaw Asia"}],modelAnswer:[{h:"Step 1 — which pile",p:["It is somebody talking about the law, and not a very careful somebody. It is not the law itself and it is not the record of a decision.","That matters because a claim naming no Act and no section cannot be traced. Nobody can confirm or refute it without doing the work again from scratch. Its only proper use is as a lead: it tells me the subject is deposits and early departure, and that is where I start looking."]},{h:"Step 2 — the four tests",p:["Who published it: unknown, forwarded three times, no author.","Does it name a provision: no, and that is the fatal one.","Is it dated and versioned: no date at all, and from this month means nothing without one.","Is anything being sold: yes, tenancy agreement templates, which is a reason to be sceptical rather than proof of anything."]},{h:"Step 3 — the primary text",p:["The Attorney General's Chambers publishes the official text of federal Acts free, and that is where I go for statute.","To get an Act name I work from the subject rather than the rumour. A deposit under a room tenancy is a term of an agreement, so the general law of contract is the first place to look, and I would read the agreement itself for the clause about the deposit. If any article names a specific provision, I use the name and then read the provision rather than the article."]},{h:"Step 4 — the note",p:["Four fields. The name and year of the Act, so I can find it again. The exact provision and the words I relied on, because a paraphrase drifts. Where I found it, so somebody else can check me. The date I read it, because the law changes and my note must say how old it is."]},{h:"Step 5 — what I send",p:["I have read the official text of the Act on the government portal and the clause in your tenancy agreement, and nothing in either says a landlord simply keeps the whole deposit for early departure; what a landlord may keep depends on the agreement and on what loss he can actually show.","What I have not been able to do is check whether any court decision changes that, because the free sources do not tell you what happened to a case afterwards, so treat this as a starting point rather than settled advice."]}],traps:["Answering the question from the message, or from a second article that repeats it. Two unsourced claims are not one sourced claim.","Treating an absence of contrary information as confirmation. Nothing came up is not the same as nothing exists.","Refusing to answer because the check is incomplete. Your cousin moves out in three weeks; a bounded answer with its limits on the face of it is the professional response."],source:"General research practice. The Attorney General's Chambers portal is the official free publication of federal statute. Facts are invented.",lastVerified:"2026-09-07",verify:"Confirm the current address of the Attorney General's Chambers portal. Do not carry the substantive point about deposits out of this exercise — it is here to be researched, not to be relied on, and the answer on any real facts depends on the agreement and on the governing Act.",selfMarkNote:"Step 5 is where marks are lost. Check that your second sentence names the limit, not just the fact that you were rushed."},{id:"pf-prob-section",moduleId:"m14-statutory-interpretation",title:"Taking a clause apart",kind:"guided",minutes:25,marks:10,scenario:["The text below is a fictional by-law written for this exercise. It is not the law of any State, and you should not go looking for it.","Clause 4. (1) No person shall keep a live animal on any premises within the market area unless he holds a permit issued by the Council: Provided that a person who holds a permit for the same animal under any written law relating to livestock need not hold a permit under this subclause.","(2) A person who contravenes subclause (1) commits an offence and shall be liable to a fine not exceeding five hundred ringgit.","(3) Subclause (1) does not apply to a guide dog while it is accompanying a person who needs it.","(4) In this clause, animal includes a bird, and premises means a building or a stall, whether or not enclosed.","Three people are in the market. Encik Ganesan keeps two hens in a wire cage behind his stall and holds no Council permit; he does hold a licence for those hens under a livestock scheme run by another body. Puan Lily brings her guide dog in every morning and holds no permit. A third trader keeps a goldfish in a bowl on the counter of his stall and holds no permit."],task:"Work through five steps in order. Step 1: copy subclause (1) out with one clause per line, breaking at every unless and at the colon. You should finish with the main prohibition on one line and the proviso on another. Step 2: for subclause (1) alone, name four things — who it applies to, what it forbids, the condition that lifts the prohibition, and where the consequence of breaking it is found. Step 3: read subclause (4). Say what it does to the word animal and what it does to the word premises, and say why the two are treated differently; one uses includes and one uses means, and that difference is the whole of the answer. Step 4: apply the clause to each of the three people, one or two lines each. Are they within subclause (1), and does anything take them out of it? Step 5: say which of the three is the hardest and why, in two sentences.",rubric:[{id:"pf-r-section-1",band:"method",marks:2,criterion:"Separates the main prohibition from the proviso on the page, with one clause per line, and treats the proviso as an exception carved out of that subclause rather than as a free-standing rule.",authority:"Standard statutory reading practice"},{id:"pf-r-section-2",band:"rule",marks:2,criterion:"Identifies the subject as no person, the prohibited conduct as keeping a live animal on premises within the market area, the lifting condition as holding a Council permit, and notices that the penalty sits in subclause (2) rather than in (1).",authority:"Clause 4(1) and 4(2)"},{id:"pf-r-section-3",band:"rule",marks:2,criterion:"Reads includes as extending the ordinary meaning of animal without closing it, and means as a closed definition of premises which admits only a building or a stall.",authority:"Clause 4(4)"},{id:"pf-r-section-4",band:"application",marks:3,criterion:"Applies the clause to all three. Puan Lily is taken out by subclause (3). Encik Ganesan is within (1) and is saved only if his livestock scheme is under a written law, which the facts do not establish. The goldfish turns on whether a fish falls within the ordinary meaning of animal, which the open definition does not settle.",authority:"Clause 4(1), 4(3), 4(4)"},{id:"pf-r-section-5",band:"conclusion",marks:1,criterion:"Picks a hardest case and gives a reason tied to the wording — the open definition, or the words under any written law — rather than to sympathy or to what seems fair.",authority:"—"}],modelAnswer:[{h:"Step 1 — cut at the joints",p:["No person shall keep a live animal.","On any premises within the market area.","Unless he holds a permit issued by the Council.","Provided that a person holding a permit for the same animal under any written law relating to livestock need not hold a permit under this subclause."]},{h:"Step 2 — the four things",p:["Who: no person, which means everybody. What it forbids: keeping a live animal on premises inside the market area. The condition that lifts it: holding a permit issued by the Council, with a second route out in the proviso.","The consequence is not in subclause (1) at all. It is in subclause (2), which turns a contravention into an offence and fixes a maximum fine. Reading (1) alone would tell you the rule and not the sanction."]},{h:"Step 3 — the two definitions",p:["Animal includes a bird. That is an extending definition. It adds birds to whatever animal ordinarily means, and it leaves the ordinary meaning intact and arguable.","Premises means a building or a stall. That is a closed definition. Anything that is neither a building nor a stall is outside the clause, however much it looks like premises in ordinary speech.","The difference is deliberate. The drafter wanted certainty about the place and wanted room to move about the creature."]},{h:"Step 4 — the three people",p:["Puan Lily is out. Her guide dog is a live animal on premises in the market area, so she is inside subclause (1) on its face, but subclause (3) disapplies (1) to a guide dog accompanying a person who needs it. The exception does the work, not the permit.","Encik Ganesan is inside subclause (1). Hens are live animals, a stall is premises under the closed definition, and he holds no Council permit. His only escape is the proviso, and the proviso is narrow: it requires a permit under any written law relating to livestock. A scheme run by another body may or may not be under a written law, and on these facts we are not told. That is the point on which his liability turns.","The goldfish is the open question. A stall is premises, the fish is alive, and there is no permit. Whether it is an animal depends on the ordinary meaning of that word, because subclause (4) only tells us that birds are included. Includes does not shut the door, so the ordinary sense still governs, and there is a real argument on each side."]},{h:"Step 5 — the hardest",p:["The goldfish is the hardest, because the drafter told us birds count and said nothing about fish, and an open definition leaves that silence unresolved.","Encik Ganesan runs it close, but his difficulty is a missing fact rather than a doubtful word: find out whether the livestock scheme rests on a written law and the answer follows."]}],traps:["Reading the proviso as a separate rule. It cuts a piece out of subclause (1) and reaches nothing else.","Treating includes and means as the same word. One extends the ordinary meaning and one replaces it.","Looking for the penalty in subclause (1). The prohibition and the sanction are in different places, which is normal drafting."],source:"Fictional by-law written for this exercise. The reading method and the treatment of provisos and definitions are standard statutory construction; the Interpretation Acts 1948 and 1967 supply general meanings where an Act is silent.",lastVerified:"2026-09-07",verify:"The by-law is invented and must never be cited. If you want to test the method on real text, take any short section from a current reprint on the Attorney General's Chambers portal and run the same five steps.",selfMarkNote:"If you reached step 4 without having written out step 1, mark yourself down. The habit is the thing being practised."},{id:"pf-prob-reason",moduleId:"m13-legal-reasoning",title:"The bike outside the kedai",kind:"analysis",minutes:30,marks:14,scenario:["Rosli parks his motorbike on the five-foot way outside a kedai runcit in Klang, close to the door. He has done this most mornings for a year and the owner, Encik Chandran, has never objected.","On Tuesday a delivery lorry arrives and Chandran needs the doorway clear. He wheels the bike about four metres along the walkway on his own. The walkway is wet. The bike tips over. The mirror and one indicator break, and the repair comes to two hundred and forty ringgit.","Chandran says he was only helping, that Rosli should not have left the bike against the door, and that a shopkeeper cannot be expected to become the keeper of every bike outside his shop.","Rosli says that a person who takes hold of somebody else's property has to take care with it, and that Chandran could have waited thirty seconds and asked either of the two men standing beside him.","Assume no statute is in play, and that you are reasoning from ordinary principle. Nothing turns on knowing a case."],task:"Set out the argument in visible steps. State the issue or issues as legal questions. State the rule you are applying and break it into its elements. Apply each element to a specific fact. Then put the strongest version of Chandran's case, and say who you think should win and why. Keep it to one page.",rubric:[{id:"pf-r-reason-1",band:"issue",marks:2,criterion:"States at least two issues, each as a legal question with two arguable answers — whether Chandran took charge of the bike at all, and whether what he did fell below the care required. Was Chandran in the wrong is not an issue.",authority:"Standard problem-question technique"},{id:"pf-r-reason-2",band:"rule",marks:3,criterion:"States the rule at a workable level of generality and splits it into elements: taking charge of another's property, a standard of care attaching to that, a falling short of it, and loss caused by the falling short.",authority:"Standard problem-question technique"},{id:"pf-r-reason-3",band:"application",marks:3,criterion:"Puts one specific fact against each element — taking hold and wheeling it four metres, the wet walkway, doing it alone with two men beside him, the broken mirror and indicator — rather than retelling the story or restating the rule.",authority:"The facts"},{id:"pf-r-reason-4",band:"application",marks:2,criterion:"Puts the strongest version of Chandran's case, not a weak one: nobody asked him to take charge, Rosli created the obstruction, the act was short and ordinary and done to let a delivery through, and a year of silent acquiescence cuts both ways.",authority:"The facts"},{id:"pf-r-reason-5",band:"method",marks:2,criterion:"Keeps the steps separate and visible on the page, so a reader can check each one, and does not fold the rule into the application or the application into the conclusion.",authority:"Standard problem-question technique"},{id:"pf-r-reason-6",band:"conclusion",marks:2,criterion:"Reaches a decided answer, tentative if necessary, with the reason attached and tied to the element that carried it. An answer that sets out both sides and stops earns nothing here.",authority:"—"}],modelAnswer:[{h:"Issues",p:["Did Chandran take charge of the bike, so that any duty to take care of it arose at all?","If he did, did wheeling a loaded bike alone across a wet walkway fall below the care such a person must take?","A third question sits behind both. Does it change anything that Rosli had left the bike where it blocked the door?"]},{h:"Rule",p:["The principle relied on is that a person who takes charge of another's property must take reasonable care of it, and answers for loss caused by failing to do so.","That is four elements, and each has to be met. First, taking charge of the thing. Second, that it belonged to somebody else. Third, conduct falling below the care a reasonable person would take in those circumstances. Fourth, loss caused by that shortfall rather than by something else."]},{h:"Application",p:["Taking charge. Chandran did not merely stand near the bike. He took hold of it and moved it four metres. Once he had control of it and Rosli did not, he was the person in a position to protect it, which is what taking charge means on any view.","Another's property. Not in dispute. The bike is Rosli's.","Falling short. This is where the case is won. He moved a loaded motorbike on his own, on a walkway he could see was wet, when two men were standing beside him and the delay in asking would have been seconds. A reasonable person in his position would have asked, or would have waited, or would have moved it more slowly. Each of those was open to him and cost him almost nothing.","Causation. The bike tipped while he was moving it, and the mirror and indicator broke in that fall. The loss is the direct result of the way he moved it, not of any earlier event."]},{h:"The other side",p:["Chandran's best case is that he never took charge in the sense the rule means. He was clearing an obstruction that Rosli had created, doing something short and ordinary, and a shopkeeper who moves a bike out of his own doorway is not thereby made its keeper.","He can add that Rosli's own conduct set the whole thing up. The bike was against the door, the lorry was waiting, and the choice Chandran faced was one Rosli had given him.","The year of silent acquiescence is genuinely double-edged. Rosli will say it shows he was permitted to park there. Chandran will say it shows he had been tolerant for a year and was not volunteering to be responsible for the machine."]},{h:"Conclusion",p:["On balance Rosli should recover the two hundred and forty ringgit.","The reason is the third element rather than the first. Even accepting that Chandran was clearing his own doorway, once he had his hands on the bike he had a choice about how to move it, and the safer choice was free. Rosli's own conduct in blocking the door is a real point and might reduce what he recovers, but it does not answer what happened after Chandran took hold."]}],traps:["Starting with the rule and never returning to the facts. The marks here are in the application, and application means one fact against one element.","Writing Chandran's case in a weak form so that it is easy to knock down. A straw man is visible from across the room and it costs you.","Ending with it depends. It may depend, and you must still say which way you would go and why."],source:"Invented facts. The principle used is stated as a shape for reasoning, not as an authority of Malaysian law.",lastVerified:"2026-09-07",verify:"This exercise is about structure, not doctrine. Do not carry the rule used here into real advice: on real facts you would have to find the governing statute and the actual case law, and check that the case law is still good.",selfMarkNote:"Mark the application band first and hardest. If a sentence in it would survive a change in the facts, it is not application."}],de={schemaVersion:B,note:O,problems:D},J=1,G="Practice for the criminal procedure and property on-ramp lessons. Facts are hypothetical unless a real case is named. The first problem is guided: the steps are given and part of the reasoning is done, so that a beginner has something between a flashcard and an unassisted question. The rubric is for self-marking; nothing here is an authority.",V=[{id:"pd-p-guided-arrest",moduleId:"m05-criminal-procedure",title:"Guided: Rahim is still in the lock-up",kind:"guided",minutes:20,marks:8,scenario:["This is a guided problem. The steps are set out for you and part of the reasoning is done. Answer each step in a sentence or two, in order, and only then read the model answer.","Rahim is thirty-four and works as a lorry attendant in Klang. On Sunday night at about nine, police stop his motorcycle near a row of shops. They tell him there has been a snatch theft nearby.","They handcuff him and put him in the car. He asks what he is supposed to have done. Nobody answers. At the station his phone is taken and he is put in the lock-up.","On Monday afternoon he is questioned for two hours. He asks to telephone his wife, Sarah, and he asks for a lawyer. He is told both can wait until the questioning is finished.","It is now Tuesday at noon. Rahim is still in the lock-up. He has not been taken before a Magistrate and he has not been charged. Sarah has heard nothing from anyone."],task:"Work through five steps. Step 1 — fix the start of the clock. The arrest happened at about nine on Sunday night, because that is the moment Rahim stopped being free to leave; write down the time at which twenty-four hours runs out. Step 2 — Rahim was never told why he was taken. State in one sentence what Article 5(3) requires about the grounds of arrest, and say whether it was met here. Step 3 — he asked for two different things, a call home and a lawyer. Name both rights and say where each comes from; one is in Article 5(3) and one is in the Criminal Procedure Code. Step 4 — by Tuesday at noon about thirty-nine hours have passed. State what Article 5(4) required to happen before the limit expired, and name the order the police would need in order to hold him any longer. Step 5 — write two sentences of practical advice for Sarah: what she should ask for, and where she should go.",rubric:[{id:"pd-r-ga1",band:"issue",marks:1,criterion:"Fixes the arrest at about nine on Sunday night and gives the expiry of the twenty-four hours as about nine on Monday night — not from the time of questioning or of arrival at the station.",authority:"Federal Constitution, Art 5(4)"},{id:"pd-r-ga2",band:"rule",marks:2,criterion:"States Article 5(3): an arrested person must be informed as soon as may be of the grounds of his arrest, and must be allowed to consult and be defended by a lawyer of his choice.",authority:"Federal Constitution, Art 5(3)"},{id:"pd-r-ga3",band:"rule",marks:2,criterion:"States the twenty-four hour limit under Article 5(4), and identifies a remand order from a Magistrate under s 117 of the Criminal Procedure Code as the only way to hold him longer.",authority:"Federal Constitution, Art 5(4); Criminal Procedure Code (Act 593), s 117"},{id:"pd-r-ga4",band:"application",marks:2,criterion:"Applies both rules to these facts: no grounds were given at all, the lawyer and the call home were put off, and about thirty-nine hours have passed with no production before a Magistrate.",authority:"The facts as given"},{id:"pd-r-ga5",band:"conclusion",marks:1,criterion:"Gives Sarah something she can actually do: go to the station, ask what offence he is held for, ask whether a remand order was made and for how long, and get a lawyer or legal aid.",authority:"Practical advice"}],modelAnswer:[{h:"Step 1 — the clock",p:["The arrest was at about nine on Sunday night. Twenty-four hours runs out at about nine on Monday night.","The clock starts at the arrest, not at the questioning and not at the moment the paperwork is opened. That is why fixing the time first is worth doing before anything else."]},{h:"Step 2 — the grounds",p:["Article 5(3) requires that a person arrested be informed as soon as may be of the grounds of his arrest.","It was not met. Rahim asked and got no answer, and he still did not know on Tuesday. Being told there was a snatch theft nearby is not being told what he is held for."]},{h:"Step 3 — the two requests",p:["The right to consult and be defended by a lawyer of his choice is in Article 5(3) of the Federal Constitution.","The right to have a relative or friend told where he is comes from the Criminal Procedure Code, in s 28A. They are separate rights, and answering only one of them does not satisfy the other.","Note honestly that when access to a lawyer must be given effect is contested in the courts. Police often say after questioning. That does not make the request pointless: it should be made, repeated, and the time recorded."]},{h:"Step 4 — the limit",p:["Article 5(4) required that Rahim be released, or produced before a Magistrate, within twenty-four hours of the arrest. That is by about nine on Monday night.","To hold him beyond that the police needed a remand order from a Magistrate under s 117 of the Criminal Procedure Code. On the facts none was obtained, and about thirty-nine hours have now passed."]},{h:"Step 5 — what Sarah should do",p:["Go to the station where he is held and ask, in these words, what offence Rahim is being held for and whether a remand order has been made and for how long.","Get a lawyer. If the family cannot pay, ask about legal aid or the Bar Council legal aid centre, and keep a written note of every time and every name."]}],traps:["Starting the clock at the questioning rather than the arrest. The moment of arrest is when he stopped being free to leave, on the roadside.","Treating the lawyer and the call home as one right. They come from different places and each has to be answered.","Arguing that Rahim did not do it. Nothing in this problem turns on guilt; it turns on time and on what he was told."],source:"Federal Constitution Arts 5(3) and 5(4); Criminal Procedure Code (Act 593), ss 28A and 117. Facts are hypothetical.",lastVerified:"2026-09-07",verify:"Read Arts 5(3) and 5(4) in a current reprint of the Federal Constitution, and read s 28A of the Criminal Procedure Code in a current reprint before relying on the detail — it has been amended. The case law on when access to counsel must be allowed is live; do not treat the position in the model answer as settled."},{id:"pd-p-remand-bail",moduleId:"m05-criminal-procedure",title:"Five days, then a charge",kind:"problem",minutes:40,marks:16,scenario:["Suriani works in a factory in Seremban. Her son Danial is nineteen and in his first year at a local college. He lives at home.","On Thursday morning police arrest Danial over an alleged break-in at a hardware shop two streets away. The family are told nothing until a neighbour telephones that evening.","On Friday morning Danial is taken before a Magistrate. The investigating officer asks for seven days, saying that witnesses have still to be traced and a recording has to be recovered. Nobody appears for Danial and he says nothing. The Magistrate allows five days.","On the fifth day Danial is produced in court and a charge under the Penal Code is read to him. He claims trial. The prosecution objects to bail, saying he may interfere with a witness, because one of the shop workers lives on the same road.","Danial has no previous record. Suriani has held her factory job for eleven years and the family has about three thousand ringgit in savings. She asks you what she should have done, and what she should do now."],task:"Advise Suriani. Deal with the remand hearing and what could have been said at it; whether bail is available and on what basis; what she is committing to if she stands surety; and what happens now that the charge has been read. Say plainly what you cannot answer without checking the charge itself.",rubric:[{id:"pd-r-rb1",band:"issue",marks:2,criterion:"Separates the three stages the facts run through — detention before charge, bail after charge, and the trial — instead of answering the single question 'will he get out'.",authority:"Structure of the Criminal Procedure Code"},{id:"pd-r-rb2",band:"rule",marks:3,criterion:"States the detention rule accurately: twenty-four hours under Art 5(4), and beyond that a remand order from a Magistrate under s 117 of the Code, made for the investigation and for the period the Magistrate thinks fit.",authority:"Federal Constitution, Art 5(4); Criminal Procedure Code (Act 593), s 117"},{id:"pd-r-rb3",band:"rule",marks:3,criterion:"States the bail rule by classification: the First Schedule marks each offence bailable or non-bailable; for a bailable offence release on bail is an entitlement, for a non-bailable one it is a discretion under s 388.",authority:"Criminal Procedure Code (Act 593), First Schedule and s 388"},{id:"pd-r-rb4",band:"application",marks:3,criterion:"Applies the remand rule to the hearing: the officer had to show why more time was needed, and Danial could have asked for a shorter period, pointed to his age and fixed address, and asked what remained to be done. Notes that guilt was not the question.",authority:"Criminal Procedure Code (Act 593), s 117"},{id:"pd-r-rb5",band:"application",marks:3,criterion:"Applies the bail discretion to these facts: no record, a fixed address, a mother in steady work, a college place — and meets the witness objection with a proposed condition rather than a denial that any risk exists.",authority:"Criminal Procedure Code (Act 593), s 388"},{id:"pd-r-rb6",band:"method",marks:1,criterion:"Looks at the Act the charge is brought under before applying the Code's scheme, because special legislation carries its own bail provisions and some exclude bail.",authority:"Criminal Procedure Code (Act 593), First Schedule; special legislation"},{id:"pd-r-rb7",band:"conclusion",marks:1,criterion:"Ends with something Suriani can act on, and states its limits: what a surety commits to, what the money is for, and what cannot be advised without seeing the charge.",authority:"Practical advice"}],modelAnswer:[{h:"Issue",p:["Three questions, and they belong to three different stages. Was the five day detention properly ordered, and what could have been said about it. Is bail available now that a charge has been read, and on what terms. What is Suriani taking on if she stands surety."]},{h:"Rule",p:["Detention. Article 5(4) of the Federal Constitution allows the police twenty-four hours before an arrested person must be released or produced before a Magistrate. Longer detention needs a remand order under s 117 of the Criminal Procedure Code. The order is made for the purposes of the investigation, for the period the Magistrate thinks fit within the statutory maximum, and the maximum is graduated by the sentence the offence carries.","Bail. The First Schedule to the Code classifies each offence. For a bailable offence the accused is entitled to be released on bail. For a non-bailable offence bail is in the discretion of the court, subject to s 388. So the first question is never whether bail ought to be granted; it is which classification the offence falls into.","Where the discretion is exercised, the question the court is answering is whether the accused will attend, and whether any risk from his release can be managed by conditions."]},{h:"Application",p:["The remand hearing was a real hearing, not a formality. The officer had to show why the investigation needed more time. Danial, or anyone speaking for him, could have asked what specifically remained to be done, pointed out that he is nineteen, lives at home, and is at college, and asked for a shorter period. The Magistrate cut seven days to five without hearing any of that, which suggests a shorter period was available for the asking.","What would not have helped is a protest that Danial did not do it. Guilt is not the question at a remand hearing, and spending the only opportunity on it is the standard mistake.","On bail, the first step is to look the offence up rather than argue about it. If it is bailable, release on bail is an entitlement and the objection goes only to the amount and the conditions. If it is non-bailable, the court has a discretion and the prosecution's objection has to be met.","The objection here is interference with a witness who lives on the same road. The answer is not to say there is no risk. It is to propose conditions that manage it: an undertaking not to contact or approach the shop or its workers, reporting to the station weekly, and surrender of any travel document. A concrete set of conditions is a better answer than an assertion of good character.","Everything else on the facts points towards release. There is no record, the address is fixed, the mother has eleven years in the same job and can stand surety, and the sum available is modest but real."]},{h:"Method",p:["Before any of this is applied, check which Act the charge is brought under. The facts say the Penal Code, which puts the ordinary scheme of the Code in play. Had it been brought under security or drugs legislation, that Act might have its own bail provisions and could shut bail out altogether. This check comes first, and it is the one most often skipped."]},{h:"Conclusion",p:["Advise Suriani that a lawyer should have been at the remand hearing and can be at the next one, and that the point to argue there is necessity rather than innocence.","On bail, find the classification of the offence charged. If bail is available, apply with a concrete set of conditions aimed at the witness objection. If she stands surety, she is promising the court that Danial will attend on every date; if he does not, the money she has put up is at risk, and it comes back at the end of the case if the dates are kept.","State the limit honestly. Without seeing the charge itself, nobody can tell her whether the offence is bailable or what the likely amount will be. That is the first thing to get a copy of."]}],traps:["Arguing innocence at the remand hearing. The question there is whether further detention is needed for the investigation.","Assuming 'non-bailable' means no bail. It means the court has a discretion.","Meeting a witness-interference objection by denying the risk instead of proposing a condition that manages it.","Applying the Code's bail scheme without first checking which Act the charge is brought under."],source:"Federal Constitution Art 5(4); Criminal Procedure Code (Act 593), s 117, s 388 and the First Schedule. Facts are hypothetical.",lastVerified:"2026-09-07",verify:"Check the current text of s 117 for the maximum remand periods, which are graduated and have been amended. Check the First Schedule classification of the actual offence charged, and check the Act the charge is brought under for its own bail provisions before applying s 388. Bail amounts and local practice vary between courts."},{id:"pd-p-kampung-title",moduleId:"m08-property",title:"The land still in grandfather's name",kind:"problem",minutes:45,marks:18,scenario:["Pak Hamid died in 2009. He left a lot of about half a hectare in Kuala Selangor, held under agricultural category. The title has never changed: the register still shows him as proprietor.","He had four children. Rosli, the eldest, has lived on the land since 1998 and grows oil palm on it. There was never any written agreement; the family simply understood that Rosli would work the land and look after it.","In 2024 Salmah, the second child, produced a transfer form dated 2008 bearing what is said to be Pak Hamid's signature, and was registered as sole proprietor. Rosli, Azman and Kalsom say the signature is nothing like their father's, and that he was in hospital for most of that month.","Salmah has now signed an agreement to sell the land to Sinar Maju Sdn Bhd, a small developer. The company has paid a deposit and is waiting for the transfer to be presented at the land office.","Rosli arrives with a plastic bag of fertiliser receipts, an old quit rent receipt, and no title document. He wants to know whether twenty-six years on the land count for anything, and how to stop the sale."],task:"Advise Rosli. Deal with whether his occupation gives him anything; how the land should have passed when Pak Hamid died; what the alleged forgery does to Salmah's registration; whether the developer would be safe once it is registered; and what he should do this week, in order.",rubric:[{id:"pd-r-kt1",band:"issue",marks:2,criterion:"Identifies three separate questions — occupation, succession, and a registration obtained by a defective instrument — and notices that a pending sale puts the whole matter under time pressure.",authority:"National Land Code (Act 828)"},{id:"pd-r-kt2",band:"rule",marks:3,criterion:"States title by registration under the National Land Code, and that long occupation does not by itself give title to registered land however many years it has run.",authority:"National Land Code (Act 828)"},{id:"pd-r-kt3",band:"rule",marks:3,criterion:"States the succession position: land registered in a dead proprietor's name moves only when a distribution of the estate is obtained and registered against the title — at the Land Office for a small estate, otherwise through the court.",authority:"National Land Code (Act 828); Small Estates (Distribution) Act 1955"},{id:"pd-r-kt4",band:"rule",marks:3,criterion:"States s 340: a registered title is indefeasible, subject to exceptions including fraud, forgery and a void or insufficient instrument; and that Tan Ying Hong restored deferred indefeasibility.",authority:"National Land Code (Act 828), s 340; Tan Ying Hong v Tan Sian San (FC)"},{id:"pd-r-kt5",band:"application",marks:3,criterion:"Applies the exception to Salmah: if the transfer was forged, her registration falls within s 340(2) and her title is defeasible in her own hands, whatever the register now shows.",authority:"National Land Code (Act 828), s 340"},{id:"pd-r-kt6",band:"application",marks:2,criterion:"Applies the proviso to the developer: a subsequent purchaser in good faith and for valuable consideration may take an indefeasible title, so registration of the sale could leave the family suing for money instead of recovering the land.",authority:"National Land Code (Act 828), s 340 proviso"},{id:"pd-r-kt7",band:"method",marks:1,criterion:"Works in the right order — official land search first to see what the register actually shows today, then protective steps, then proceedings — rather than starting from the family's account.",authority:"Standard practice"},{id:"pd-r-kt8",band:"conclusion",marks:1,criterion:"Concludes honestly: Rosli's own occupation gives him nothing, his standing comes from being one of his father's heirs, and a caveat carries a compensation risk if the claim is not a proper one.",authority:"National Land Code (Act 828)"}],modelAnswer:[{h:"Issue",p:["Three questions, and a clock running behind all of them. Does twenty-six years of occupation give Rosli any title. How should the land have moved when Pak Hamid died. And what does an allegedly forged transfer do to the registration Salmah now holds, and to the sale she has agreed."]},{h:"Rule",p:["Malaysia has a Torrens system under the National Land Code. A person becomes the owner of land by being registered as proprietor. The register is the title. Long occupation does not by itself give title to registered land, so the years and the receipts do not make Rosli an owner.","When a registered proprietor dies, the land does not pass to the children by itself. The register keeps showing the dead person until a distribution of the estate is obtained and registered against the title. A small estate is distributed at the Land Office; where there is a will, or the estate is larger, the matter goes to the court for a grant.","Section 340 gives the registered proprietor an indefeasible title, but it sets out exceptions. Registration obtained by fraud or misrepresentation to which the proprietor was a party, or by forgery, or by a void or insufficient instrument, is open to challenge. The proviso then protects a purchaser in good faith and for valuable consideration. In Tan Ying Hong v Tan Sian San the Federal Court restored that deferred position, departing from Adorna Properties."]},{h:"Application",p:["Rosli's occupation gives him nothing as such. He has no title document, no registered interest, and no written agreement. The fertiliser receipts prove he worked the land, which is not the same as owning it. What he does have is a claim as one of the four children of the registered proprietor, and that is the footing on which everything else stands.","The land should have gone through a distribution of Pak Hamid's estate after 2009. Nothing was done for fifteen years, which is exactly the delay that makes these cases hard. Had the distribution been taken out, the four children's shares would have been registered and there would have been no title standing in a dead man's name for anyone to move.","Salmah's registration rests on a transfer said to be forged. If that is made out, it falls squarely within the exceptions in s 340(2), and her title is defeasible in her own hands. The register showing her name today does not settle the question; that is what the exceptions are for.","The developer is the real danger. If the sale is registered and Sinar Maju is a purchaser in good faith and for valuable consideration, the proviso may protect it, and the family would be left with a claim for money against Salmah rather than a claim to the land. Every day the transfer is not stopped, that risk grows.","So the family's interest is in stopping registration now, not in winning an argument later."]},{h:"Method",p:["Do the steps in this order. First, an official land search on the lot, to see what the register actually shows today and whether anything has already been presented for registration. Facts told across a kitchen table are not the register.","Second, protect the position. A private caveat is the standard urgent step, lodged on the footing of the claim to a share of Pak Hamid's estate. Be straight with Rosli about the price of getting this wrong: a caveat entered without a proper claim exposes the caveator to compensation, and whether a particular claim qualifies can be argued about.","Third, take out the distribution of Pak Hamid's estate, so that the family's entitlement is on a formal footing rather than an oral one.","Fourth, proceedings to set aside the 2024 transfer, with the forgery as the ground and evidence on the signature and the hospital records."]},{h:"Conclusion",p:["Tell Rosli plainly that his twenty-six years give him no title. His standing is as one of his father's heirs, and that is enough to act on.","The urgent thing is a search and then a caveat, because the sale is the event that could put the land out of reach. The forgery claim, if it can be proved, meets the registration Salmah obtained; it does not automatically defeat an innocent buyer who gets registered first.","None of this can be finalised without the search, sight of the 2024 instrument, and advice on the caveat from someone who has seen both."]}],traps:["Advising that twenty-six years of occupation founds a claim to the land. It does not, against registered title under the Code.","Treating the register as the end of the argument because Salmah's name is on it. Section 340 has exceptions, and forgery is one of them.","Leaving the developer out of the answer. The proviso protecting a later purchaser in good faith for value is what makes the timing urgent.","Recommending a caveat as a free holding move. It carries a compensation risk if the claim behind it is not a proper one."],source:"National Land Code (Act 828), including s 340; Small Estates (Distribution) Act 1955; Tan Ying Hong v Tan Sian San (FC), departing from Adorna Properties Sdn Bhd v Boonsom Boonyanit. Facts are hypothetical.",lastVerified:"2026-09-07",verify:"Read s 340 of the National Land Code, including subsection (2) and the proviso, in a current reprint, and confirm the Act number after revision. Confirm the citations of Tan Ying Hong and Adorna Properties in reports you can hold, and check whether anything later has qualified them. Confirm the current small estates procedure and the value threshold, which is statutory and has been raised. Sabah and Sarawak have separate land legislation and this analysis does not carry across."}],he={schemaVersion:J,note:G,problems:V},K=1,Y="Practice problems for the company, evidence and civil procedure on-ramp lessons. Facts are hypothetical; the people are invented and ordinary. The first problem is `guided` — a scaffolded worked exercise that walks the steps in order and hands you part of the reasoning, so that the jump from a five-minute card to an unassisted problem is not made in one leap. Every problem carries the authorities its rubric relies on and a `verify` line naming what must be checked against a current source. The rubric is for self-marking; nothing here is an authority.",_=[{id:"pe-p-company-01",moduleId:"m09-company",title:"The bakery, the oven and the two friends",kind:"guided",minutes:20,marks:8,scenario:["This is a guided exercise. Part of the reasoning is done for you and the steps are set out in order. Write two or three sentences for each step, in the order given. Do not write an essay.","Siti and Farid have run a small bakery in Ipoh for two years. Eighteen months ago they registered Roti Siti Sdn Bhd with SSM. They are the only two shareholders, holding 50 shares each at RM1 a share, fully paid. Both are directors.","Everything since then has been done in the company's name. The shop lease, the supplier accounts and the bank account are all in the name of Roti Siti Sdn Bhd.","In January the company bought a commercial oven from Mesin Baik Enterprise for RM24,000, payable by instalments. The purchase order was signed 'Farid, Director, for and on behalf of Roti Siti Sdn Bhd'. Nobody signed a guarantee for it.","Separately, when the company took a RM30,000 overdraft from the bank, Siti signed a personal guarantee. Farid signed nothing.","Sales have collapsed. The company has RM900 in its account. It owes Mesin Baik RM19,000 and owes the bank RM28,000. The owner of Mesin Baik has come to the shop and told them both that he will take their houses. Siti owns a small flat. Farid owns nothing.","There is no suggestion anywhere in these facts of fraud, of a sham, or of the company being set up to escape a debt that already existed."],task:"Work through the five steps below in order. Step 1 — name the parties. There are more persons in this story than Siti, Farid, the bank and Mesin Baik. Say who else the law treats as a person here, and give the reason in one sentence. Step 2 — the oven debt. We give you the first half: the buyer of the oven was the company, because Farid signed for and on behalf of it. Your job is the second half. Say what follows for Siti's flat, and name the rule you are relying on. Step 3 — the bank debt. Siti and Farid hold identical shares and identical offices. Explain why the bank can reach one of them and not the other, and be precise about what makes the difference. Step 4 — the threat. Say whether the owner of Mesin Baik can take their houses, and state in one sentence what he would have to establish to get past the company. Step 5 — answer what they actually asked. In two sentences, tell Siti and Farid what each of them personally stands to lose.",rubric:[{id:"pe-r1",band:"issue",marks:1,criterion:"Names the company as a third legal person in the story, distinct from Siti and from Farid, rather than treating the bakery as a partnership between two friends.",authority:"Companies Act 2016; Salomon v A Salomon and Co Ltd"},{id:"pe-r2",band:"rule",marks:2,criterion:"States both halves of the rule: a registered company has legal personality separate from its members, and a member is not liable for the company's debts merely by being a member, beyond any amount unpaid on the shares.",authority:"Companies Act 2016; Salomon v A Salomon and Co Ltd"},{id:"pe-r3",band:"application",marks:2,criterion:"Applies that to the oven: the contract is between Mesin Baik and the company, so the company's RM900 is available and Siti's flat is not. Says so about these facts rather than restating the rule.",authority:"Companies Act 2016; the purchase order signed for and on behalf of the company"},{id:"pe-r4",band:"application",marks:1,criterion:"Explains the difference between Siti and Farid on the bank debt by the guarantee, and treats the guarantee as a separate contract Siti made rather than as a consequence of her shareholding or her office.",authority:"The personal guarantee Siti signed"},{id:"pe-r5",band:"method",marks:1,criterion:"Answers the five steps in the order given, one short answer each, instead of writing a general account of company law and hoping the steps are covered somewhere inside it.",authority:"The instruction in the task"},{id:"pe-r6",band:"conclusion",marks:1,criterion:"Concludes for each person separately: Farid risks nothing personally, Siti risks up to her guarantee to the bank, and both lose the RM50 they paid for their shares. Rejects the threat to the houses on the Mesin Baik debt.",authority:"Companies Act 2016"}],modelAnswer:[{h:"Step 1 — the parties",p:["There are five persons here, not four. Siti, Farid, the bank, Mesin Baik Enterprise, and Roti Siti Sdn Bhd.","The company is a person because it was registered under the Companies Act 2016. Registration gives it a legal personality of its own, separate from the people who own and run it."]},{h:"Step 2 — the oven debt",p:["The buyer was the company, so the debt is the company's debt. Mesin Baik's remedy is against the company and against what the company owns, which is RM900 and whatever equipment is left.","Siti's flat is not available to Mesin Baik. A member is not liable for the company's debts merely because she is a member, and her shares are fully paid, so nothing further is owed on them."]},{h:"Step 3 — the bank debt",p:["Siti and Farid are in identical positions as shareholders and as directors. Neither position makes either of them liable for the overdraft.","What separates them is a document. Siti signed a personal guarantee, which is a separate contract in which she promised to pay if the company did not. The bank sues her on that contract, not on her shares. Farid signed nothing, so the bank has nothing to sue him on."]},{h:"Step 4 — the threat",p:["He cannot take their houses on these facts. To reach Siti or Farid personally he would have to get past the company's separate personality.","That would require a ground for lifting the corporate veil — a statute imposing personal liability, fraud, or the use of the company as a device to escape an obligation that already existed. The facts state that none of those is present. Control of the company is not a ground, and nor is the company being short of money."]},{h:"Step 5 — what each of them stands to lose",p:["Farid loses the RM50 he paid for his shares and, in practice, the business. He owes the bank and Mesin Baik nothing personally.","Siti loses her RM50 as well, and is personally exposed to the bank up to her guarantee. Her flat is at risk from the bank on that guarantee, and from nobody else on these facts."]}],traps:["Treating the bakery as a partnership because two friends run it. The moment it was registered it stopped being one.","Saying the veil should be lifted because Siti and Farid control the company completely. Control is never a ground; that is what Salomon decided.","Explaining Siti's exposure by her directorship or her shareholding. It is the guarantee, and only the guarantee.","Forgetting the shares. Both of them do lose their RM50, and an answer that says they lose nothing is wrong.","Answering Step 2 by repeating the rule instead of saying what happens to the flat."],source:"Companies Act 2016 (Act 777); Salomon v A Salomon and Co Ltd.",lastVerified:"2026-09-07",verify:"Read the incorporation provisions of the Companies Act 2016 in the current text at lom.agc.gov.my. The grounds on which a Malaysian court will lift the corporate veil are judge-made and move; check current authority before advancing or rejecting any of them in a real matter."},{id:"pe-p-evidence-01",moduleId:"m10-evidence",title:"The deposit, the message and the cousin",kind:"problem",minutes:30,marks:13,scenario:["Nurul rented a room from Encik Ghani for a year and paid a deposit of RM800. She moved out in good order, as she says. He refuses to return the deposit, saying she broke a cupboard door. She sues him for the RM800 in the Magistrates' Court.","Five things arise before the hearing.","(1) Encik Ghani sent Nurul a message three weeks after she moved out: 'I will return your deposit after Raya.' He now says he wrote it to keep the peace.","(2) Nurul wants to call her cousin Adam. Adam never lived there. He will say that a former tenant told him Encik Ghani never returns anybody's deposit.","(3) Nurul also wants to tell the court that she once heard Encik Ghani shouting at another tenant about a water bill.","(4) Encik Ghani has photographs of a broken cupboard door. He says he paid RM650 to repair it. He has the repair invoice but will not produce it, and gives no reason.","(5) Encik Ghani says it is for Nurul to prove that she left the room undamaged."],task:"Advise Nurul. Take the five items in turn. For each, say what it is worth and why, naming the rule or the section that governs it. Then state separately who has to prove what in this case, and to what standard. Do not simply list rules — say what happens to each item.",rubric:[{id:"pe-r7",band:"issue",marks:1,criterion:"Separates the two questions the facts raise, and says so: first, what may the court receive at all; second, who must prove what and how convincingly. Does not run them together.",authority:"Evidence Act 1950, s 5 and Part II"},{id:"pe-r8",band:"rule",marks:2,criterion:"States the relevancy gate accurately — evidence may be given of facts in issue and of facts the Act declares relevant, and of no others — and states the burden rule, that whoever asserts a fact must prove it and that the burden lies on the party who would fail on an empty record.",authority:"Evidence Act 1950, ss 5, 101 and 102"},{id:"pe-r9",band:"application",marks:2,criterion:"Item (1): identifies the message as an admission by a party, provable against him, and does not overclaim — it is evidence he may seek to explain, not a concession that ends the case.",authority:"Evidence Act 1950, on admissions"},{id:"pe-r10",band:"application",marks:2,criterion:"Item (2): identifies two problems, not one. Adam repeats what an absent person said in order to prove it true, which is hearsay; and what the former tenant said goes to Encik Ghani's general habits rather than to a fact in issue in this case.",authority:"Evidence Act 1950, ss 5 and the provisions on oral evidence"},{id:"pe-r11",band:"application",marks:1,criterion:"Item (3): rejects it, and gives the reason in terms of the facts in issue — whether the room was damaged and whether the deposit is repayable. A quarrel with another tenant about a water bill answers neither.",authority:"Evidence Act 1950, s 5"},{id:"pe-r12",band:"application",marks:2,criterion:"Item (4): invites the court to presume that the withheld invoice would be unfavourable to Encik Ghani, and states the limits — the presumption is permissive, and Nurul must show the document was available and material. Notes that without it his RM650 figure is unsupported.",authority:"Evidence Act 1950, s 114 illustration (g)"},{id:"pe-r13",band:"application",marks:2,criterion:"Item (5): corrects the burden rather than accepting it. Nurul proves the tenancy, the deposit and the terms on which it is repayable. Encik Ghani asserts the damage and the deduction, so he must prove them.",authority:"Evidence Act 1950, ss 101 to 103"},{id:"pe-r14",band:"conclusion",marks:1,criterion:"States the standard — balance of probabilities, this being a civil claim — and reaches an answer on whether Nurul is likely to recover, rather than stopping at a list of rulings on the five items.",authority:"Standard of proof in civil proceedings"}],modelAnswer:[{h:"Issue",p:["Two questions, and they must be kept apart. Which of these five items may the court receive at all, and who has to prove what once it has them."]},{h:"Rule",p:["Evidence may be given of facts in issue and of such other facts as the Evidence Act 1950 declares relevant, and of no others. The question about any item is which section lets it in.","Whoever wants judgment on a right depending on facts he asserts must prove those facts. The burden lies on the party who would fail if no evidence at all were given. In a civil claim the standard is the balance of probabilities."]},{h:"Item (1) — the message",p:["This is an admission. Encik Ghani is a party, and his own words point against his interest by acknowledging that the deposit is to be returned.","It may be proved against him. It does not end the case: he may give evidence about why he wrote it, and the court will weigh that. But it is the strongest single item Nurul has."]},{h:"Item (2) — the cousin",p:["Adam did not live there and saw nothing. He wants to repeat what a former tenant told him, in order to prove that it is true. That is hearsay, and it does not come in unless a provision of the Act lets it in.","There is a second objection, independent of the first. What the former tenant said is about Encik Ghani's general habits with other people's deposits. That is not a fact in issue in Nurul's case."]},{h:"Item (3) — the shouting",p:["Rejected. The facts in issue are whether the room was left damaged and whether the deposit is repayable.","An argument with a different tenant about a water bill does not make either of those more or less likely. It may be true, and it is still not relevant within the meaning of the Act."]},{h:"Item (4) — the withheld invoice",p:["Nurul should invite the court to presume that the invoice, which Encik Ghani has and will not produce, would be unfavourable to him.","The presumption is permissive. She must show that the document was available and that it mattered, and here both are plain: it is the only document that would prove the RM650 he claims to have spent. He offers no explanation for withholding it.","Even without the presumption, his figure is asserted and unsupported."]},{h:"Item (5) — who proves what",p:["Encik Ghani has the rule backwards. Nurul must prove the tenancy, the payment of RM800, and the terms on which the deposit was to be returned.","The damage and the deduction are his assertions. He wants the court to hold that he may keep RM650, so he must prove the damage and the cost. If he proves neither, he keeps neither."]},{h:"Conclusion",p:["On the balance of probabilities Nurul is likely to recover. She has an admission from the defendant, and his only positive case rests on a document he is withholding.","Items (2) and (3) should be abandoned. They are inadmissible, and pressing them wastes the court's patience on a small claim she can win without them."]}],traps:["Arguing that item (2) is 'relevant because it shows a pattern'. Relevancy under the Act is not a feeling; a section has to let it in.","Treating the admission as conclusive. It is evidence, and the maker may explain it.","Saying the s 114 illustration (g) presumption 'must' be drawn. It may be drawn, and only where the evidence was available and material.","Accepting Encik Ghani's version of the burden because he sounds confident. He asserts the damage, so he proves it.","Applying the criminal standard. This is a civil claim for RM800 and the standard is the balance of probabilities."],source:"Evidence Act 1950 (Act 56), ss 5, 101, 102, 103 and 114 illustration (g); the provisions on oral evidence and on admissions.",lastVerified:"2026-09-07",verify:"Read ss 5, 17 to 21, 60, 101 to 106 and 114 in the current text at lom.agc.gov.my. This answer describes the admission and hearsay rules generally rather than pinning them to a section; identify the exact provisions before relying on the analysis in a real matter."},{id:"pe-p-civil-01",moduleId:"m11-civil-procedure",title:"Seven months, and a tiler who waited",kind:"problem",minutes:35,marks:14,scenario:["Ravi is a tiler. He laid the floor of a café for its owner, Puan Zaiton, and finished the work on 3 April 2021. The agreed price was RM18,000, payable within 30 days of completion.","Puan Zaiton paid RM6,000 in April 2021 and nothing since. Ravi chased her by telephone a few times and then let it go.","He comes to you in September 2026 and wants his RM12,000.","He has a message thread. In August 2022 Puan Zaiton wrote to him: 'I know I still owe you for the tiles, give me time.'","He also tells you that the café is now run by a company, Kafe Zaiton Sdn Bhd, incorporated in 2023. The tiling contract was made with Puan Zaiton personally, before that company existed. The café premises are rented, not owned. Puan Zaiton owns a car and has a bank account at a local branch.","Puan Zaiton has stopped replying to messages. Ravi expects her to ignore anything he sends. He wants to know how long all this takes and what he gets at the end."],task:"Advise Ravi on the steps from here to payment. Deal with these in order: (a) whether he is in time, showing how you worked the date out and identifying anything in the facts that might affect it; (b) whom he should sue; (c) which court and which originating document, and why; (d) what has to happen after filing before the case can move; (e) what he can do if she files nothing; (f) what he will have to do after judgment to actually be paid. Name the rule or the source you are relying on at each step.",rubric:[{id:"pe-r15",band:"method",marks:2,criterion:"Works in the sequence the question sets and the procedure requires: time, party, court and document, service, default, enforcement. Does not begin with the merits of the tiling work.",authority:"Rules of Court 2012; ordinary practice"},{id:"pe-r16",band:"issue",marks:1,criterion:"Puts limitation first, and gives the reason: a time-barred claim makes every other step pointless, so it is checked before anything is filed.",authority:"Limitation Act 1953"},{id:"pe-r17",band:"rule",marks:2,criterion:"States the six-year period for an action founded on contract, running from accrual, and does the arithmetic: payment fell due about 3 May 2021, so the period runs to about May 2027 and the claim is in time but not by much. Flags the August 2022 written acknowledgment as something that may bear on the period and needs checking in the Act.",authority:"Limitation Act 1953"},{id:"pe-r18",band:"application",marks:2,criterion:"Sues Puan Zaiton personally, not Kafe Zaiton Sdn Bhd, and gives the reason: the contract was made with her before the company existed, and a company is a separate legal person that did not take over her debts by being incorporated later.",authority:"Companies Act 2016; Salomon v A Salomon and Co Ltd"},{id:"pe-r19",band:"application",marks:2,criterion:"Chooses a writ, with the reason: the price, the completion and the quality of the work are disputes of fact needing witnesses. Identifies the court by reference to the current monetary limits in the Subordinate Courts Act 1948, and says the figure must be looked up rather than guessing one.",authority:"Rules of Court 2012; Subordinate Courts Act 1948"},{id:"pe-r20",band:"application",marks:2,criterion:"Identifies service as the necessary next step, treats it as a formal requirement rather than a courtesy, and notes that the periods for entering appearance and filing a defence run from service.",authority:"Rules of Court 2012"},{id:"pe-r21",band:"application",marks:2,criterion:"Advises judgment in default if she enters no appearance or files no defence, and warns that a default judgment may be set aside, most easily where service was defective. Draws the practical conclusion that service must be done properly the first time.",authority:"Rules of Court 2012"},{id:"pe-r22",band:"conclusion",marks:1,criterion:"Ends on enforcement rather than on judgment. States that a judgment is not money, and picks at least one route matched to what Puan Zaiton actually has — a garnishee over the bank account, or seizure and sale of the car.",authority:"Rules of Court 2012"}],modelAnswer:[{h:"(a) Time",p:["This comes first, because a claim out of time is worth nothing however good it is.","The claim is founded on contract, so the period is six years from accrual. The cause of action accrued when payment fell due, which is 30 days after completion on 3 April 2021, so about 3 May 2021. Six years takes that to about May 2027. Ravi is in time, with roughly eight months left.","The August 2022 message may matter. The Limitation Act 1953 contains provisions under which a written acknowledgment of a debt affects the running of the period. Read them before relying on them either way. Either way, Ravi should not wait: the safe course is to file now."]},{h:"(b) Whom to sue",p:["Puan Zaiton personally. The contract was made with her in 2021.","Kafe Zaiton Sdn Bhd is not liable. It is a separate legal person and it did not exist when the contract was made. Incorporating a company in 2023 does not move a 2021 debt onto it. Suing the company would waste the filing fee and the time Ravi does not have."]},{h:"(c) Court and document",p:["A writ. There is a dispute about facts — what was agreed, whether the work was completed, and whether the tiling was up to standard. Facts of that kind need witnesses who can be cross-examined, and that is what a writ action provides.","The court depends on the amount claimed, RM12,000 plus interest and costs, measured against the current monetary limits of the Magistrates' and Sessions Courts under the Subordinate Courts Act 1948. Those limits have been raised over the years, so look up the current figure rather than repeating one from a textbook."]},{h:"(d) After filing",p:["Filing gets a case number. It does not put Puan Zaiton under any obligation.","The writ must be served on her in the manner the Rules of Court 2012 prescribe, and service must be capable of being proved. Her time to enter an appearance, and then to file a defence, runs from service, not from filing."]},{h:"(e) If she files nothing",p:["If she enters no appearance, or enters one and files no defence within time, Ravi may apply for judgment in default. That is judgment without a trial.","It is not the end. A default judgment can be set aside, and the easiest ground is that service was bad. This is why the service must be done carefully now rather than quickly."]},{h:"(f) Getting paid",p:["A judgment is a piece of paper saying she owes him RM12,000. It is not the money.","Ravi will have to enforce it. On these facts there are two obvious routes: garnishee proceedings against her bank account, and seizure and sale of the car. The café premises are rented, so there is no land to charge.","Advise him now, before he spends anything, that enforcement can fail. If she has emptied the account and the car is on hire purchase, he may win and still collect nothing."]}],traps:["Starting with whether the tiling was any good. Limitation comes first, and on these facts it is close.","Suing Kafe Zaiton Sdn Bhd because it is the business that operates the café today. It is a separate person and it was not a party to the 2021 contract.","Running limitation from the date the work finished rather than the date payment fell due.","Asserting that the 2022 message restarted the clock without checking the Limitation Act 1953. It may; go and read it.","Choosing an originating summons because the claim is a simple debt. The facts are disputed, and that makes it a writ.","Stopping at judgment. The question asked how Ravi gets paid, and that is a separate exercise."],source:"Rules of Court 2012; Limitation Act 1953; Subordinate Courts Act 1948; Companies Act 2016 (Act 777); Salomon v A Salomon and Co Ltd.",lastVerified:"2026-09-07",verify:"Check the current Rules of Court 2012 at lom.agc.gov.my for the modes of commencement, service, the time to enter appearance and to file a defence, and the enforcement procedures. Read the acknowledgment provisions of the Limitation Act 1953 before relying on the point about the 2022 message. Look up the current monetary limits of the subordinate courts; no figure is given here on purpose."}],ce={schemaVersion:K,note:Y,problems:_},U={latin:"A Latin maxim or term of art.",doctrine:"A rule or principle of substantive law.",statute:"A named Act, or a section pinned to one.",institution:"A court, office or body.",method:"How law is studied, researched or argued."},z=[{id:"absolute-privilege",term:"absolute privilege",kind:"doctrine",gloss:"Protection that no malice defeats.",intermediate:"Statements in Parliament and in the course of judicial proceedings, among others. The protection is complete regardless of motive.",advanced:"Its scope is narrow precisely because it is absolute: a person defamed on a privileged occasion has no remedy at all, which is a price the law pays for candour in those settings. Statements to the police and in preparation for litigation raise harder questions about how far the protection extends.",source:"Standard common law; parliamentary privilege under the Federal Constitution",see:["qualified-privilege","defamation"],aliases:["absolute privilege"]},{id:"ac",term:"AC",kind:"method",gloss:"Appeal Cases — the English law reports.",intermediate:"An English series carrying decisions of the House of Lords, the Privy Council and now the UK Supreme Court. Pepper v Hart [1993] AC 593 is one.",advanced:"An English citation signals a decision that is at most persuasive here. Use it for structure and vocabulary, which travel; do not assume the substantive position is Malaysian law without checking.",source:"English law report series",aliases:["AC"],see:["hl","pc"]},{id:"acceptance",term:"acceptance",kind:"doctrine",gloss:"Assent to a proposal, turning it into a promise.",intermediate:"Signifying assent to the proposal. Once communicated in the manner the Act specifies, the proposal becomes a promise and the agreement is formed.",advanced:"The moment of completion is what decides the race with a revocation, and s 4(2) splits it: as against the proposer, communication is complete when the acceptance is put into a course of transmission out of the acceptor's power; as against the acceptor, when it comes to the proposer's knowledge. That split is the statutory form of the postal rule and is the step most answers get wrong.",source:"Contracts Act 1950 ss 2(b) and 4(2)",see:["proposal","communication-complete","revocation"],aliases:["acceptance","acceptor"]},{id:"accused",term:"accused",kind:"doctrine",gloss:"The person charged in a criminal case.",intermediate:"The person the prosecution says committed the offence. Not a defendant — that word belongs to civil cases.",advanced:"The accused carries no burden to prove innocence. Where a General Exception is raised, the burden of bringing the case within it falls on the accused on the balance of probabilities, and the prosecution's own burden beyond reasonable doubt is untouched by that.",source:"Criminal Procedure Code",aliases:["accused"],see:["defendant","prosecution"]},{id:"acquittal",term:"acquittal",kind:"doctrine",gloss:"A finding that the accused is not guilty.",intermediate:"The prosecution did not reach its standard. It does not mean the court found the person innocent, and it is not a finding that nothing happened.",advanced:"An acquittal may come at the close of the prosecution case, where no prima facie case is made out, or at the end of the whole trial. Reading it as a finding of innocence is the commonest misunderstanding of a verdict.",source:"Criminal Procedure Code",aliases:["acquittal","acquittals"],see:["conviction","prima-facie"]},{id:"actus-reus",term:"actus reus",kind:"latin",gloss:"The guilty act — the physical element of an offence.",intermediate:"The conduct, together with any circumstances and consequences the offence requires. It must coincide with the mental element.",advanced:"As with mens rea, the Code states the physical element offence by offence, so the useful question is which limb of the section the facts satisfy. Omissions are criminal only where a duty to act exists, and causation questions — whether the accused's act caused the prohibited result — belong here rather than to the mental element.",source:"Penal Code",see:["mens-rea","penal-code"],aliases:["actus reus"]},{id:"admissibility",term:"admissibility",kind:"doctrine",gloss:"Whether evidence may be received at all.",intermediate:"A question logically prior to weight. Under the Evidence Act it is answered by finding the section that declares the fact relevant.",advanced:"Admissibility and weight are routinely conflated in answers. Evidence that gets in may still be worth very little, and a court that admits it is not obliged to act on it; conversely, compelling material that no section admits simply cannot be used. Illegally obtained evidence is generally admissible in Malaysia if relevant, which surprises students trained on other systems.",source:"Evidence Act 1950 s 5",see:["relevancy","evidence-act"],aliases:["admissibility","admissible"]},{id:"adverse-inference",term:"adverse inference",kind:"doctrine",gloss:"Illustration (g) to s 114 — withheld evidence would have been unfavourable.",intermediate:"The court may presume that evidence which could be and is not produced would, if produced, be unfavourable to the person withholding it.",advanced:"It is permissive, not automatic, and it is not drawn from every gap in the evidence. The party inviting it must show that the evidence was available and material and that no explanation for its absence has been given; failing to call a witness whose evidence would merely repeat what is already proved does not attract it.",source:"Evidence Act 1950 s 114 illustration (g)",see:["presumption","legal-burden"],aliases:["adverse inference","section 114","s 114"]},{id:"affidavit",term:"affidavit",kind:"doctrine",gloss:"Written evidence, sworn or affirmed to be true.",intermediate:"A statement of facts put in writing and sworn. Most applications before trial are decided on affidavits rather than on witnesses giving evidence aloud.",advanced:"Because the maker is not cross-examined, an affidavit is weak where the facts are genuinely disputed — which is why a real dispute of fact points towards a writ and a trial rather than an originating summons.",source:"Rules of Court 2012",aliases:["affidavit","affidavits"],see:["writ"]},{id:"affirmation",term:"affirmation",kind:"doctrine",gloss:"Electing to keep a contract alive despite a right to end it.",intermediate:"Signifying by words or conduct that the contract continues, which extinguishes the right to terminate for that breach.",advanced:"Affirmation is easier to commit than students expect: continuing to demand performance, accepting further benefits, or simply delaying can all amount to it. It matters equally in rescission for misrepresentation, where affirming after discovering the truth bars avoidance.",source:"Contracts Act 1950 s 40; general principle",see:["repudiation","rescission","voidable"],aliases:["acquiescence","affirmation","affirmed","affirm"]},{id:"agc",term:"AGC",kind:"institution",gloss:"Attorney General's Chambers.",intermediate:"The government body that publishes the official text of Malaysian Acts, free, on its portal. That is the source to use for statute.",advanced:"A page printed from the portal is not a copy of the Gazette, which matters only where something formal turns on the exact printed text. For study and ordinary research it is exactly what you want.",source:"Attorney General's Chambers portal",aliases:["AGC"],see:["statute"]},{id:"agm",term:"AGM",kind:"doctrine",gloss:"Annual general meeting.",intermediate:"The yearly meeting of a company's members. It is where accounts are laid, directors appointed and resolutions voted on.",advanced:"Notice, quorum and the majority required are conditions of a valid resolution rather than formalities. A private company under the 2016 Act is not required to hold one, which older textbooks do not reflect.",source:"Companies Act 2016",aliases:["AGM"],see:["resolution","shareholder"]},{id:"agreement",term:"agreement",kind:"doctrine",gloss:"A promise or set of promises the parties have made to each other.",intermediate:"What the two sides have agreed. Not every agreement is a contract: it becomes one only when the Act's requirements are met.",advanced:"Section 2 builds it in steps — proposal, acceptance, promise, agreement — and s 10 then adds what turns an agreement into a contract: free consent, capacity, lawful consideration and a lawful object. Naming the step you are on keeps the analysis straight.",source:"Contracts Act 1950 s 2",aliases:["agreement","agreements"],see:["consideration"]},{id:"air",term:"AIR",kind:"method",gloss:"All India Reporter.",intermediate:"The main Indian law report series. Indian authority matters here more than in most jurisdictions, because the Penal Code and the Evidence Act share Indian ancestry.",advanced:"Where a Malaysian provision descends from the Indian original, Indian decisions on the same wording are genuinely useful. That is a reason to read them with care, not a licence to treat them as binding.",source:"Indian law report series",aliases:["AIR"],see:["penal-code","evidence-act"]},{id:"amr",term:"AMR",kind:"method",gloss:"All Malaysia Reports.",intermediate:"A third Malaysian law report series. Seeing a case cited to AMR rather than MLJ or CLJ does not make it any less authoritative.",advanced:"Which series a judgment appears in is a publishing fact, not a legal one. What decides weight is the court that decided it, which is why a citation without the court in brackets cannot be weighed.",source:"Malaysian law report series",aliases:["AMR"],see:["mlj","clj"]},{id:"appeal",term:"appeal",kind:"doctrine",gloss:"Asking a higher court to reconsider a decision.",intermediate:"A challenge to a decision, heard by a court above the one that made it. The question is whether the decision was right — which is not the question judicial review asks.",advanced:"An appeal is a creature of statute: there is no inherent right to one, so the first question is always which provision gives it and whether leave is required. An appeal against a finding of fact faces a heavy burden, because the trial court saw the witnesses and the appellate court does not.",source:"Courts of Judicature Act 1964",aliases:["appeal","appeals"],see:["judicial-review"]},{id:"appellant",term:"appellant",kind:"doctrine",gloss:"The party who brings an appeal.",intermediate:"Whoever is asking the higher court to change the decision. That may be either side, depending on who lost.",advanced:"The label follows the appeal rather than the original action, so a plaintiff who won at trial becomes the respondent on the defendant's appeal. Getting this backwards makes a procedural history unreadable.",source:"Courts of Judicature Act 1964",aliases:["appellant","appellants"],see:["respondent","appeal"]},{id:"application",term:"application",kind:"method",gloss:"Putting the rule against these facts, rather than restating it.",intermediate:"The part of an answer that does the reasoning: taking the rule you have stated and working out what it means for the facts in front of you, both ways where the point is arguable.",advanced:"This is where most marks sit and where most are lost. The test of a real application paragraph is whether it could be moved to another problem without alteration — if it could, it is still rule statement. Arguing both ways and then deciding is what separates it from assertion.",source:"Rubric band used throughout this app",see:["irac","calibration"],aliases:["application"]},{id:"apportionment",term:"apportionment",kind:"doctrine",gloss:"Dividing responsibility between claimant and defendant.",intermediate:"The exercise s 12 of the Civil Law Act 1956 requires: reducing damages to the extent just and equitable having regard to the claimant's share in the responsibility for the damage.",advanced:"Share in the responsibility takes account of both blameworthiness and the causative potency of each party's conduct, so a small piece of carelessness that made a large difference can attract a substantial reduction. Appellate courts are reluctant to interfere with a trial judge's apportionment, which is why the reasoning behind the figure matters more than the figure.",source:"Civil Law Act 1956 s 12",see:["contributory-negligence"],aliases:["apportionment","apportioned"]},{id:"arrest",term:"arrest",kind:"doctrine",gloss:"Taking a person into custody, with constitutional safeguards attached.",intermediate:"Article 5(3) requires that the person be told the grounds as soon as may be and allowed to consult a legal practitioner of his choice; Art 5(4) sets the twenty-four hour limit.",advanced:"Whether the arrest was lawful matters beyond the arrest itself: it affects the admissibility of what followed, the lawfulness of any resistance, and any claim for false imprisonment. The right to counsel under Art 5(3) is not always given effect at the moment of arrest, and the case law on when access must be allowed is worth reading rather than summarising.",source:"Federal Constitution Art 5(3) and 5(4); Criminal Procedure Code",see:["remand","article-5","seizable"],aliases:["arrested","arrest"]},{id:"article-10",term:"Article 10",kind:"statute",gloss:"Freedom of speech, assembly and association — and the restrictions on them.",intermediate:"Article 10(1) confers the rights on citizens; Article 10(2) allows Parliament to impose such restrictions as it deems necessary or expedient on a closed list of grounds.",advanced:"Whether a restriction falls within a permitted head is for the court, not for Parliament's own characterisation of it; how hard the court may look beyond that is the unresolved argument in the area, with Pung Chen Choon and Sivarasa Rasiah pulling in different directions and neither overruling the other. The effect of a law matters more than its form: a statute that never mentions speech can restrict it, and the court looks at what it does.",source:"Federal Constitution Art 10; PP v Pung Chen Choon [1994] 1 MLJ 566 (FC); Sivarasa Rasiah v Badan Peguam Malaysia [2010] 2 MLJ 333 (FC)",see:["fundamental-liberties","proportionality","article-8"],aliases:["Article 10(2)","Article 10","Art 10"]},{id:"article-121a",term:"Article 121(1A)",kind:"statute",gloss:"Civil courts have no jurisdiction over matters within Syariah jurisdiction.",intermediate:"Inserted in 1988. It subtracts jurisdiction from the civil courts where a matter already lies within the Syariah courts' jurisdiction — it does not grant the Syariah courts anything.",advanced:"Because it is a subtraction, the clause does nothing unless the matter is within Syariah jurisdiction in the first place, and that jurisdiction comes from State enactments under List II and reaches only persons professing the religion of Islam. Indira Gandhi held that the clause does not oust the civil courts' inherent power of judicial review. The common misstatement — 'if Islam is involved the civil court has no jurisdiction' — is neither what it says nor what it does.",source:"Federal Constitution Art 121(1A); Indira Gandhi a/p Mutho v Pengarah Jabatan Agama Islam Perak [2018] 1 MLJ 545 (FC)",see:["syariah-court","judicial-power","judicial-review"],aliases:["Article 121(1A)","Art 121(1A)","121(1A)"]},{id:"article-128",term:"Article 128",kind:"statute",gloss:"The Federal Court's exclusive constitutional jurisdiction.",intermediate:"The Federal Court alone determines whether a law is invalid for want of legislative competence, and disputes between States or between the Federation and a State.",advanced:"A constitutional question arising in the High Court may be referred upward rather than decided there, and the mechanism and its limits sit in the Constitution and the Courts of Judicature Act 1964. Reaching the right constitutional conclusion in the wrong forum has not advised the client, which is why forum is a method point rather than a formality.",source:"Federal Constitution Art 128; Courts of Judicature Act 1964",see:["federal-court","legislative-competence","article-4"],aliases:["Article 128","Art 128"]},{id:"article-4",term:"Article 4(1)",kind:"statute",gloss:"The supremacy clause.",intermediate:"'This Constitution is the supreme law of the Federation and any law passed after Merdeka Day which is inconsistent with this Constitution shall, to the extent of the inconsistency, be void.'",advanced:"Clauses (3) and (4) then restrict how a challenge on the ground of legislative competence may be brought, including a leave requirement for proceedings in the Federal Court. That is a procedural trap rather than a substantive one, and it is where otherwise competent answers lose marks — check the current text and practice before saying how such a challenge is commenced.",source:"Federal Constitution Art 4",see:["supremacy","legislative-competence","article-128"],aliases:["Article 4(1)","Article 4","Art 4(1)"]},{id:"article-5",term:"Article 5",kind:"statute",gloss:"Liberty of the person, and the safeguards on arrest.",intermediate:"No person may be deprived of life or personal liberty save in accordance with law; an arrested person must be told the grounds, allowed counsel, and produced before a magistrate within twenty-four hours.",advanced:"Article 5 speaks of persons, not citizens, so it protects anyone within the jurisdiction. 'In accordance with law' has carried a good deal of weight in the case law: read thinly it means any validly enacted procedure, read thickly it imports a requirement that the law itself be fair, and which reading applies is one of the live questions in Malaysian constitutional law.",source:"Federal Constitution Art 5",see:["fundamental-liberties","remand","habeas-corpus"],aliases:["Article 5(3)","Article 5(4)","Article 5","Art 5"]},{id:"article-75",term:"Article 75",kind:"statute",gloss:"Federal law prevails over inconsistent State law.",intermediate:"Where a State law is inconsistent with a federal law, the federal law prevails and the State law is void to the extent of the inconsistency.",advanced:"Article 75 presupposes a valid federal law: if the federal statute is itself outside List I and List III it prevails over nothing and is void under Art 4(1). Answers that reach for Art 75 first have skipped the question that usually decides the case.",source:"Federal Constitution Art 75",see:["ninth-schedule","legislative-competence","article-76"],aliases:["Article 75","Art 75"]},{id:"article-76",term:"Article 76",kind:"statute",gloss:"Parliament legislating on State matters for uniformity.",intermediate:"The provision that lets Parliament make law on a State subject for the purpose of promoting uniformity, with the law taking effect in a State only when adopted by its legislature.",advanced:"This is the answer to the obvious objection that land is a State matter and the National Land Code is federal. It is also the reason the Code's application is not uniform across the whole Federation — Sabah and Sarawak have their own land legislation, and the position there is not a footnote to the Code but a different statutory scheme.",source:"Federal Constitution Art 76",see:["ninth-schedule","article-75","national-land-code"],aliases:["Article 76","Art 76"]},{id:"article-8",term:"Article 8",kind:"statute",gloss:"Equality before the law and equal protection.",intermediate:"All persons are equal before the law and entitled to its equal protection, with express exceptions the Constitution itself provides for.",advanced:"Equality does not require identical treatment: the working doctrine is reasonable classification, asking whether the distinction rests on an intelligible differentia and whether that differentia bears a rational relation to the object of the law. Sivarasa Rasiah is the route by which proportionality has been argued into Malaysian constitutional analysis through Art 8(1).",source:"Federal Constitution Art 8",see:["proportionality","fundamental-liberties","article-10"],aliases:["Article 8(1)","Article 8","Art 8"]},{id:"audi-alteram-partem",term:"audi alteram partem",kind:"latin",gloss:"Hear the other side.",intermediate:"A person liable to be affected by a decision must be given notice of the case against him and a fair opportunity to answer it.",advanced:"The content is variable but the core is not: notice of the substance of the allegations, and a real chance to respond. Telling someone only that 'complaints have been considered' fails it on any view, because there is nothing to answer. Whether an oral hearing or legal representation is required is the arguable part.",source:"Standard administrative law",see:["natural-justice","nemo-judex","judicial-review"],aliases:["audi alteram partem"]},{id:"bailable",term:"bailable offence",kind:"doctrine",gloss:"An offence for which bail is available as of right.",intermediate:"A person accused of a bailable offence shall be released on bail under s 387. It is not a discretion.",advanced:"The confusing label is the next one: 'non-bailable' does not mean bail is unavailable, only that it lies in the court's discretion under s 388. A third category, where the offence is punishable with death or imprisonment for life, attracts the restrictions in s 388(1) subject to its provisos for young persons, women and the sick or infirm.",source:"Criminal Procedure Code ss 387 and 388, First Schedule",see:["non-bailable","criminal-procedure-code","seizable"],aliases:["bailable offence","bailable"]},{id:"bailii",term:"BAILII",kind:"method",gloss:"British and Irish Legal Information Institute.",intermediate:"A free website carrying the full text of British and Irish judgments. Useful for reading an English case you have seen cited.",advanced:"Free databases give you the text and not the later history. Nothing on a free portal tells you a case was later reversed, and silence there is not evidence that it was not.",source:"Free case-law database",aliases:["BAILII"],see:["citator"]},{id:"balance-of-probabilities",term:"balance of probabilities",kind:"doctrine",gloss:"The civil standard: more likely than not.",intermediate:"What a plaintiff must establish to succeed, and the standard to which an accused discharges any burden a statute places on him.",advanced:"Because it is lower than the criminal standard, the same facts can lose a prosecution and win a suit — that is the system working as designed, not an inconsistency. Fraud alleged in civil proceedings is proved to this standard in Malaysia rather than the criminal one, though that is a point whose current statement should be checked.",source:"Standard common law; Evidence Act 1950",see:["beyond-reasonable-doubt","legal-burden","fraud"],aliases:["balance of probabilities"]},{id:"basic-structure",term:"basic structure",kind:"doctrine",gloss:"The argument that some constitutional features survive even a valid amendment.",intermediate:"That certain features — judicial power, the rule of law, the separation of powers — are so fundamental that Parliament cannot remove them by amending the Constitution.",advanced:"Its origin is Indian and its reception in Malaysia has changed direction more than once, with Federal Court decisions both rejecting and applying it. It is an argument of last resort against an amendment, not a general licence to strike down legislation, and conflating the two is the commonest error in an answer. If you write about it, write about the sequence of authority and give the citations.",source:"Malaysian and Indian constitutional case law",see:["judicial-power","article-121a","supremacy"],aliases:["basic structure doctrine","basic structure"]},{id:"beyond-reasonable-doubt",term:"beyond reasonable doubt",kind:"doctrine",gloss:"The criminal standard of proof.",intermediate:"The prosecution must prove its case to that standard on the whole of the evidence. A defence that raises a reasonable doubt succeeds; it does not have to be believed.",advanced:"The burden does not shift, except where a statute places one on the accused — s 105 of the Evidence Act for the general exceptions being the main example, and that is discharged on the balance of probabilities. Writing that the accused must 'prove' his defence at the close of the case is wrong outside those statutory instances.",source:"Evidence Act 1950 s 105; Criminal Procedure Code s 182A",see:["balance-of-probabilities","section-105","legal-burden"],aliases:["beyond reasonable doubt"]},{id:"binding-authority",term:"binding authority",kind:"doctrine",gloss:"A decision a court has no choice but to follow.",intermediate:"A decision of a superior court in the same hierarchy, on the same point of law. A court faced with one must either follow it or distinguish it.",advanced:"Only the ratio binds; the rest of the judgment is persuasive. Decisions of courts of coordinate jurisdiction — one High Court on another — are not binding, though in practice they are followed unless there is good reason not to, because inconsistency at the same level is itself a mischief.",source:"Standard common law doctrine",see:["persuasive-authority","stare-decisis","ratio-decidendi"],aliases:["binding authority","binding"]},{id:"breach",term:"breach of contract",kind:"doctrine",gloss:"Failing to perform what the contract required.",intermediate:"Non-performance, defective performance, or a refusal to perform. It gives the innocent party a right to damages, and sometimes a right to terminate.",advanced:"Not every breach permits termination. Section 40 gives the right to put an end to the contract where a party has refused to perform, or disabled himself from performing, his promise in its entirety — and that right is an election which is lost by acquiescence in the contract's continuance. A party who keeps pressing for performance after a repudiation may be held to have affirmed and left himself with damages only.",source:"Contracts Act 1950 ss 40 and 74",see:["repudiation","affirmation","section-74"],aliases:["breach of contract","breach","broken"]},{id:"breach-of-duty",term:"breach of duty",kind:"doctrine",gloss:"Falling below the standard the law required.",intermediate:"The second element of negligence, measured against the reasonable person in the defendant's position — with the standard raised where the defendant holds himself out as having a skill.",advanced:"The standard is objective, so inexperience is no answer, and it is fixed by what was reasonable at the time rather than with hindsight. A defendant's departure from its own written procedure is strong evidence of breach without being conclusive: the standard is the reasonable person's, and a method statement can set the bar higher than the law does.",source:"Standard common law",see:["duty-of-care","negligence","causation"],aliases:["standard of care","breach of duty"]},{id:"business-judgement-rule",term:"business judgement rule",kind:"doctrine",gloss:"A safe harbour for honest, informed commercial decisions.",intermediate:"Section 214: a director who makes a business judgement in good faith for a proper purpose, without a material personal interest, on a reasonably informed basis and in the reasonable belief that it is in the company's best interest, is taken to have met the duty of care.",advanced:"Its point is that courts should not second-guess commercial risk with hindsight. Each condition has to be satisfied, and the two that most often fail are the absence of a material personal interest and the requirement of a reasonably informed basis — a decision taken without inquiry does not qualify however honestly it was made.",source:"Companies Act 2016 s 214",see:["directors-duty","fiduciary-duty"],aliases:["business judgement rule","business judgment rule"]},{id:"but-for",term:"but-for test",kind:"doctrine",gloss:"Would the damage have happened anyway?",intermediate:"The test of factual causation: but for the defendant's breach, would the claimant have suffered the loss? If it would have happened anyway, causation fails.",advanced:"The classic illustration is a casualty officer who negligently sends away a man already fatally poisoned: the breach is plain and the claim fails, because correct treatment would have made no difference. Establishing the counterfactual is an evidential question, and in clinical cases it usually requires expert evidence about what proper treatment would have achieved.",source:"Standard common law",see:["causation","novus-actus"],aliases:["but-for test","but for"]},{id:"calibration",term:"calibration",kind:"method",gloss:"The gap between the mark you predicted and the mark you gave yourself.",intermediate:"A measure of whether your sense of your own work matches what a rubric says about it. This app records the prediction before the rubric is shown, and cannot let you revise it.",advanced:"A consistent over-estimate is the failure mode that survives a whole degree, because it is invisible from the inside: you cannot correct a gap you do not believe is there. Under-estimating costs less but makes a good answer hard to tell from a lucky one. The figure only compares one judgment against another you made minutes later, so it catches drift, not a learner who is generously wrong about both.",source:"The problem-question layer of this app",see:["irac","application"],aliases:["calibration"]},{id:"causation",term:"causation",kind:"doctrine",gloss:"Whether the breach actually caused the damage — in fact and in law.",intermediate:"Factual causation uses the but-for test; legal causation asks whether a later event broke the chain.",advanced:"The but-for test breaks down in two recognised situations: multiple sufficient causes, and scientific uncertainty about which of several exposures caused the injury. Both have generated exceptional approaches, and both should be identified as exceptions rather than used as the general rule. A breach that caused no loss defeats the claim however plain the carelessness.",source:"Standard common law",see:["but-for","novus-actus","remoteness","negligence"],aliases:["causation"]},{id:"cause-of-action",term:"cause of action",kind:"doctrine",gloss:"The set of facts giving a right to sue.",intermediate:"Every element that must be proved for the claim to succeed. It is what a pleading must disclose and what limitation runs from.",advanced:"The date of accrual is the date the last necessary element falls into place — which in negligence means damage, not carelessness. That is why a claim can be time-barred before the claimant knew there was anything to complain about, and why latent damage is such a persistent problem.",source:"Limitation Act 1953; Rules of Court 2012 O 18 r 19",see:["limitation","pleading","striking-out"],aliases:["cause of action"]},{id:"cause-to-the-contrary",term:"cause to the contrary",kind:"doctrine",gloss:"The narrow ground on which a chargor resists an order for sale.",intermediate:"What the chargor must show to prevent sale: not a general discretion, but a defect going to the chargee's right to the order.",advanced:"The recognised categories are narrow — that the chargee has failed to meet a condition precedent, that the charge is unlawful or unenforceable, or that the order would be contrary to some rule of law or equity. Financial hardship is not cause to the contrary, however sympathetic, and advising otherwise raises expectations the statute will not meet.",source:"National Land Code; the Malaysian case law on cause to the contrary",see:["order-for-sale","charge"],aliases:["cause to the contrary"]},{id:"caveat",term:"caveat",kind:"doctrine",gloss:"An entry freezing dealings while a claim is worked out.",intermediate:"A private caveat may be entered by a person claiming title, a registrable interest, or a beneficial entitlement under a trust affecting the land. It prevents registration of dealings while in force.",advanced:"A caveat creates no interest — it is a freeze, not a right — and it lapses after the statutory period unless extended. On an application to remove it the caveator must show a serious question to be tried and that the balance of convenience favours maintaining it, which is the interlocutory injunction shape for the same reason. Entering one without reasonable cause exposes the caveator to compensation, so it is not a costless holding move.",source:"National Land Code s 323 and the caveat provisions",see:["torrens","dealing","lien-holders-caveat","interlocutory-injunction"],aliases:["private caveat","caveator","caveats","caveat"]},{id:"certiorari",term:"certiorari",kind:"latin",gloss:"An order quashing a decision.",intermediate:"The principal remedy in judicial review: the decision is set aside, and the matter is generally remitted for reconsideration according to law.",advanced:"It goes with the other prerogative orders — prohibition to restrain a decision not yet made, and mandamus to compel the performance of a public duty. In Malaysia they are sought under Order 53 together with declarations and injunctions, and damages may be claimed in the same proceedings in the circumstances the rule allows.",source:"Rules of Court 2012 O 53",see:["judicial-review","mandamus","order-53"],aliases:["certiorari"]},{id:"charge",term:"charge",kind:"doctrine",gloss:"The Code's security interest over registered land.",intermediate:"Created by a registered instrument. It gives the chargee no possession — the security is the ability to enforce, not to occupy.",advanced:"On default the chargee serves the statutory notice and, if it is not remedied, applies for an order for sale. The route depends on the title: Registry title goes to the High Court, Land Office title to the Land Administrator. Identifying which before saying where the application goes is where the method marks in a charge question sit.",source:"National Land Code, the charge provisions",see:["order-for-sale","cause-to-the-contrary","torrens"],aliases:["chargee","chargor","charge"]},{id:"cheating",term:"cheating",kind:"doctrine",gloss:"Inducing delivery of property by deception.",intermediate:"Section 415. The accused deceived a person and thereby fraudulently or dishonestly induced that person to deliver property, or to do or omit something he would not otherwise have done.",advanced:"Consent is present but vitiated by the deception, which places it on the third branch of the possession question. The deception must have induced the delivery, so a lie that made no difference to the victim's decision is not cheating however dishonest — causation matters here as much as it does in tort.",source:"Penal Code s 415",see:["theft","criminal-breach-of-trust","dishonestly"],aliases:["cheating"]},{id:"citator",term:"citator",kind:"method",gloss:"A tool that tells you whether a case is still good law.",intermediate:"A service tracking a judgment's subsequent judicial treatment — whether it has been followed, distinguished, doubted or overruled.",advanced:"There is no free Malaysian citator, which is the hard limit on free research in this jurisdiction: the AGC portal and CommonLII give you the text and say nothing about status. A portal showing no overruling is not evidence that there was none; it is evidence that the portal does not track it. That check needs a paid service or a systematic search for later cases citing the decision.",source:"Standard research practice",see:["noting-up","persuasive-authority"],aliases:["citator"]},{id:"civil-law-act",term:"Civil Law Act 1956",kind:"statute",gloss:"The statute receiving English common law, with cut-off dates.",intermediate:"Section 3(1) directs the courts to apply the common law of England and the rules of equity as administered there on stated dates — 7 April 1956 for West Malaysia, with different dates for Sabah and Sarawak.",advanced:"The reception is subject to two qualifications that do real work: it applies only so far as local circumstances permit, and only where no local statute makes provision. Section 6 excludes English land law altogether, which is what protects the Torrens system from being undercut by imported doctrines of notice. In practice Malaysian courts cite post-1956 English decisions constantly, and how that squares with the section is a respectable argument rather than a settled one.",source:"Civil Law Act 1956 ss 3(1), 6 and 12",see:["reception","torrens","contributory-negligence"],aliases:["Civil Law Act 1956","Civil Law Act"]},{id:"clj",term:"CLJ",kind:"method",gloss:"Current Law Journal.",intermediate:"A Malaysian law report series, alongside the MLJ. The same case is often reported in both, with different volume and page numbers.",advanced:"CLJ also runs one of the subscription citators, which is the tool that tells you what later courts did with a case. That check cannot be done from free sources alone.",source:"Malaysian law report series",aliases:["CLJ"],see:["mlj","citator"]},{id:"clr",term:"CLR",kind:"method",gloss:"Commonwealth Law Reports — the Australian series.",intermediate:"The main Australian law reports. Rogers v Whitaker (1992) 175 CLR 479 is cited in the negligence material.",advanced:"Australian authority carries no more weight here than English, and sometimes less familiarity. It is worth citing where a Malaysian court has actually adopted the reasoning, which is the case with Rogers v Whitaker on advice and disclosure.",source:"Australian law report series",aliases:["CLR"],see:["ac"]},{id:"codification",term:"codification",kind:"doctrine",gloss:"A subject governed by a statute that states the rules, not by case law.",intermediate:"Contract, criminal law and evidence in Malaysia are codified: the Contracts Act 1950, the Penal Code and the Evidence Act 1950 state the rules, and reasoning begins with their words.",advanced:"The consequence is a discipline about authority. An English case is useful where the Act raises the same question and worthless where it does not, and a proposition drawn from English law that contradicts the section is simply wrong — the frequent example is treating past consideration as no consideration when s 2(d) says otherwise. Codes are also read as a whole, so a definition section governs the whole Act.",source:"Contracts Act 1950; Penal Code; Evidence Act 1950",see:["reception","persuasive-authority","contracts-act"],aliases:["codification","codified"]},{id:"coercion",term:"coercion",kind:"doctrine",gloss:"Committing a Penal Code offence, or unlawfully detaining property, to force an agreement.",intermediate:"Section 15's definition, which is considerably narrower than the ordinary idea of pressure or the English concept of duress.",advanced:"Because the definition is tied to the Penal Code, commercial pressure that would be argued as economic duress in England has no obvious home in s 15, and how far Malaysian law recognises economic duress is a question to check rather than assume. Where coercion is made out the agreement is voidable at the option of the party coerced, and s 73 provides for repayment of money paid under coercion.",source:"Contracts Act 1950 ss 15, 19 and 73",see:["free-consent","voidable","undue-influence"],aliases:["coercion"]},{id:"communication-complete",term:"communication complete",kind:"doctrine",gloss:"The moment the Act fixes for a proposal, an acceptance or a revocation taking effect.",intermediate:"Section 4 gives each kind of communication its own moment, and different moments as against each party. Getting the right one is the whole of a formation-race problem.",advanced:"The trap sits in s 4(3)(b): a revocation is complete as against the person to whom it is made when it comes to his knowledge — not when it is delivered. A letter sitting unopened on a desk has been delivered and not communicated, and a problem that mentions an unopened envelope is testing exactly that.",source:"Contracts Act 1950 s 4",see:["acceptance","revocation","proposal"],aliases:["communication is complete","communication complete"]},{id:"companies-act",term:"Companies Act 2016",kind:"statute",gloss:"The statute governing companies in Malaysia.",intermediate:"Act 777, which repealed the Companies Act 1965 and changed a great deal: a single optional constitution, no authorised capital, no par value, and single-member private companies.",advanced:"This is the module where an out-of-date text does the most damage. A source that refers to the memorandum and articles, or to authorised capital, as current law is describing a repealed statute. Directors' duties are now stated in ss 213 and 218, with a business judgement rule in s 214, and the members' remedies in ss 346 to 350.",source:"Companies Act 2016 (Act 777)",see:["separate-legal-personality","directors-duty","oppression","derivative-action"],aliases:["Companies Act 2016","Companies Act"]},{id:"company",term:"company",kind:"doctrine",gloss:"A body corporate with a legal personality of its own.",intermediate:"A separate legal person, distinct from the people who own and run it. It can own property, sign contracts, sue and be sued in its own name — and it owes its own debts.",advanced:"Separate personality is the idea the rest of company law follows from. Limited liability is a consequence of it rather than the idea itself: because the company owes the debt, a member risks only what remains unpaid on their shares.",source:"Companies Act 2016",aliases:["company","companies"],see:["director","shareholder"]},{id:"consideration",term:"consideration",kind:"doctrine",gloss:"The price of a promise — and in Malaysia, a statutory definition.",intermediate:"Under s 2(d), an act or abstinence or promise done at the desire of the promisor, by the promisee or any other person. Section 26 makes an agreement without it void, subject to three exceptions.",advanced:"Two departures from English law are decisive. 'Has done or abstained from doing' means past consideration is good consideration here. 'The promisee or any other person' means consideration need not move from the promisee — though that does not abolish privity, and a stranger to the contract still cannot sue on it. Explanation 2 to s 26 adds that inadequacy does not void the agreement but may bear on whether consent was free.",source:"Contracts Act 1950 ss 2(d) and 26",see:["privity","section-26","contracts-act"],aliases:["consideration"]},{id:"construction",term:"construction",kind:"method",gloss:"How a court reads a piece of writing to settle what it means.",intermediate:"Working out what words mean in law — in a statute, a contract or a document. Nothing to do with building.",advanced:"Construction is a question of law, which is why it can be decided on affidavit without a trial. Where a provision is capable of two readings, the one that promotes the Act's purpose is preferred under s 17A of the Interpretation Acts.",source:"Standard canon of construction",aliases:["construction"],see:["interpretation"]},{id:"contract",term:"contract",kind:"doctrine",gloss:"An agreement the law will enforce.",intermediate:"An agreement that meets what the Act requires, so a court will hold the parties to it. Free consent, capacity, a lawful price and a lawful purpose are the four requirements.",advanced:"Section 10 is the gate, and each of its limbs opens onto its own body of law: consent onto the vitiating factors, capacity onto s 11, and lawful object onto s 24. An answer that asserts a contract exists without naming which limb is in issue has skipped the analysis.",source:"Contracts Act 1950 s 10",aliases:["contract","contracts"],see:["agreement","consideration"]},{id:"supremacy",term:"constitutional supremacy",kind:"doctrine",gloss:"The Constitution outranks every other law; inconsistent law is void.",intermediate:"Article 4(1) provides that law passed after Merdeka Day which is inconsistent with the Constitution is void to the extent of the inconsistency.",advanced:"Two details are routinely dropped. First, the invalidity is partial — 'to the extent of the inconsistency' — so severance is the ordinary course rather than striking down a whole Act. Second, describing Parliament as sovereign is not a loose way of saying it is powerful; it is a category error carried over from English texts and it undermines every constitutional argument built on top of it.",source:"Federal Constitution Art 4(1)",see:["article-4","federal-constitution","ultra-vires"],aliases:["supremacy of the Constitution","constitutional supremacy"]},{id:"contracts-act",term:"Contracts Act 1950",kind:"statute",gloss:"The statute governing contract in Malaysia.",intermediate:"A code covering formation, consideration, free consent, performance, breach and remedies. It is the starting point for every contract question, ahead of any English case.",advanced:"Its structure follows the Indian Contract Act 1872, which is why Indian authority is often closer on the wording than English authority is. Several sections depart from English law in ways that decide cases — past consideration is good under s 2(d), consideration may move from a third party, and s 26 saves three promises that would otherwise fail for want of consideration.",source:"Contracts Act 1950 (Act 136)",see:["codification","consideration","free-consent"],aliases:["Contracts Act 1950","Contracts Act"]},{id:"contributory-negligence",term:"contributory negligence",kind:"doctrine",gloss:"The claimant's own carelessness, reducing the award.",intermediate:"Section 12 of the Civil Law Act 1956: where damage results partly from the claimant's own fault, the claim is not defeated but damages are reduced as the court thinks just and equitable.",advanced:"Before the section it was a complete defence, which is why older material must be read with care. It is now an apportionment exercise, and an answer should reason to a proportion by reference to the claimant's share in the responsibility rather than asserting that damages 'will be reduced'. It is distinct from novus actus, which defeats the claim outright.",source:"Civil Law Act 1956 s 12",see:["novus-actus","negligence","apportionment"],aliases:["contributory negligence"]},{id:"conviction",term:"conviction",kind:"doctrine",gloss:"A court's finding that the accused is guilty.",intermediate:"The formal decision that the prosecution proved its case. Punishment follows conviction; the two are separate steps.",advanced:"A conviction requires proof beyond reasonable doubt on the whole of the evidence. It is not a finding that the accused probably did it, which is why the same facts can fail a prosecution and still succeed in a civil suit.",source:"Criminal Procedure Code",aliases:["conviction","convictions"],see:["acquittal"]},{id:"corporate-veil",term:"corporate veil",kind:"doctrine",gloss:"The separation between a company and its members — and when courts look behind it.",intermediate:"Lifting the veil means treating the company and its controllers as one. It is done rarely and on stated grounds.",advanced:"The recognised routes are statutory — an Act expressly imposing liability, such as s 540 on fraudulent trading — and, at common law, the use of the corporate form to evade an existing obligation or conceal wrongdoing. Genuine agency is a third route but requires an actual agency relationship, not merely control. 'Lifting the veil in the interests of justice' is not a ground however often it is asserted.",source:"Companies Act 2016 s 540; the Malaysian case law on lifting the veil",see:["separate-legal-personality","companies-act"],aliases:["piercing the veil","lifting the veil","corporate veil"]},{id:"court-of-appeal",term:"Court of Appeal",kind:"institution",gloss:"Hears appeals from the High Court, usually in threes.",intermediate:"The intermediate appellate court. For most litigants it is in practice the last court that will hear the case on the merits.",advanced:"It binds the High Court and the subordinate courts and is bound by the Federal Court. A Court of Appeal decision that conflicts with an earlier one of its own creates a genuine difficulty for a first-instance judge, and the usual resolution is to follow the later, fuller reasoning while noting the conflict.",source:"Courts of Judicature Act 1964",see:["federal-court","high-court","stare-decisis"],aliases:["Court of Appeal","CA"]},{id:"creditor",term:"creditor",kind:"doctrine",gloss:"A person to whom money is owed.",intermediate:"Whoever is owed the money. A supplier waiting to be paid and a bank waiting for a loan repayment are both creditors.",advanced:"Creditors deal with the company, not its members, which is what separate personality means in practice: they take everything the company owns first, and only a guarantee or a statute reaches the people behind it.",source:"Companies Act 2016; standard usage",aliases:["creditor","creditors"],see:["debtor","company"]},{id:"criminal-breach-of-trust",term:"criminal breach of trust",kind:"doctrine",gloss:"Misappropriating property you were lawfully entrusted with.",intermediate:"Section 405. The accused was entrusted with property, or with dominion over it, and dishonestly misappropriated or converted it, or used or disposed of it in violation of a legal direction.",advanced:"Entrustment is what separates it from theft: the property came to the accused lawfully. Whether an employee has entrustment or mere custody depends on the scope of what was committed to him, and that question decides which charge fits. The same facts can support alternative charges, and saying which is the better one is part of the answer.",source:"Penal Code s 405",see:["theft","cheating","entrustment"],aliases:["criminal breach of trust","CBT"]},{id:"criminal-procedure-code",term:"Criminal Procedure Code",kind:"statute",gloss:"The statute governing arrest, bail, charge and criminal trial.",intermediate:"Act 593. Its First Schedule classifies every offence as seizable or non-seizable and as bailable, non-bailable or unbailable, and that classification decides most of the procedure.",advanced:"Look the offence up before reasoning about it — the classification, not the seriousness, is what determines whether police may arrest without warrant and whether bail is a right or a discretion. Special legislation, particularly on security and drugs, frequently displaces the Code's scheme with its own, so the statute creating the offence must be checked too.",source:"Criminal Procedure Code (Act 593)",see:["seizable","bailable","remand","prima-facie-case"],aliases:["Criminal Procedure Code","CPC"]},{id:"culpable-homicide",term:"culpable homicide",kind:"doctrine",gloss:"Causing death with the intention or knowledge s 299 specifies.",intermediate:"The genus of which murder is the species: causing death by an act done with intention to cause death, or intention to cause bodily injury likely to cause death, or knowledge that the act is likely to cause death.",advanced:"Every murder is culpable homicide; not every culpable homicide is murder. The route through a homicide problem is to establish culpable homicide under s 299, then ask whether any limb of s 300 elevates it to murder, then whether any Exception to s 300 brings it back down. Skipping to s 300 because someone died inverts the structure.",source:"Penal Code s 299",see:["murder","penal-code","private-defence"],aliases:["culpable homicide not amounting to murder","culpable homicide"]},{id:"damages",term:"damages",kind:"doctrine",gloss:"Money awarded as compensation.",intermediate:"A sum the court orders one side to pay the other to make up for a loss. Damages compensate; they are not usually a punishment.",advanced:"The measure differs by cause of action: in contract the aim is to put the plaintiff where performance would have, in tort where the wrong had not occurred. Note the spelling trap — damage is the harm, damages is the money.",source:"Contracts Act 1950 s 74; standard common law",aliases:["damages"],see:["remedy","remoteness"]},{id:"dealing",term:"dealing",kind:"doctrine",gloss:"A transaction in registered land that takes effect on registration.",intermediate:"Transfers, leases, charges and easements under the Code. Until the instrument is registered it passes nothing at law.",advanced:"This is the point at which a sale and purchase agreement is misdescribed as making the buyer the owner. It does not: it creates contractual rights and an interest capable of protection, and the register decides ownership. Getting that wrong unravels an entire answer on competing interests and priorities.",source:"National Land Code, Division IV",see:["torrens","caveat","charge"],aliases:["dealings","dealing"]},{id:"debtor",term:"debtor",kind:"doctrine",gloss:"A person who owes money.",intermediate:"Whoever owes the money. Winning a case makes you a judgment creditor and the other side a judgment debtor — which is not the same as being paid.",advanced:"A judgment against a debtor with nothing is worth nothing, so what a defendant can actually pay is a question to ask before suing rather than after. Enforcement is a separate exercise with its own procedures and costs.",source:"Standard usage",aliases:["debtor","debtors"],see:["creditor"]},{id:"defamation",term:"defamation",kind:"doctrine",gloss:"Publishing words that lower a person's reputation.",intermediate:"Three elements: the words are defamatory, they refer to the plaintiff, and they were published to at least one person other than the plaintiff.",advanced:"All three must be established before any defence arises, and an answer that opens with qualified privilege has assumed the case it should be proving. The libel–slander distinction still matters because slander generally requires proof of special damage, subject to the statutory exceptions in the Defamation Act 1957. Malice is not an element: it defeats two of the defences.",source:"Defamation Act 1957; standard common law",see:["libel","slander","qualified-privilege","malice"],aliases:["defamation","defamatory"]},{id:"defendant",term:"defendant",kind:"doctrine",gloss:"The person a civil claim is brought against.",intermediate:"The side being sued. They answer the claim in a defence, and an allegation the defence does not answer is generally taken as admitted.",advanced:"Keep the defendant in a civil suit apart from the accused in a criminal trial; the words are not interchangeable, and using them loosely signals working from an English text. A defendant who files nothing risks judgment in default, with the merits never examined.",source:"Rules of Court 2012",aliases:["defendant","defendants"],see:["plaintiff","accused"]},{id:"deferred-indefeasibility",term:"deferred indefeasibility",kind:"doctrine",gloss:"The immediate transferee under a bad instrument takes a defeasible title.",intermediate:"Indefeasibility is postponed one step: the person registered on a forged or void instrument can be unwound, but a later bona fide purchaser for value cannot.",advanced:"The competing rule, immediate indefeasibility, protects even the immediate transferee and was what Adorna Properties adopted. Tan Ying Hong restored the deferred position, treating the proviso to s 340(3) as protecting subsequent purchasers rather than the immediate one. Which rule applies decides who bears the loss when a title is forged, so it is never a merely academic distinction.",source:"National Land Code s 340(3); Tan Ying Hong v Tan Sian San [2010] 2 MLJ 1 (FC)",see:["indefeasibility","torrens"],aliases:["immediate indefeasibility","deferred indefeasibility"]},{id:"desired-retention",term:"desired retention",kind:"method",gloss:"The probability of recall you are scheduling for.",intermediate:"The target the scheduler aims at when it sets the next interval — 0.90 by default, meaning you expect to recall about nine cards in ten when they come up.",advanced:"It is a cost dial, not a quality dial: higher retention means many more reviews for a small gain, lower means fewer reviews and more lapses. It should be left alone until several thousand reviews are logged, because the estimate it feeds is noisy before then.",source:"FSRS parameters",see:["fsrs","spacing"],aliases:["desired retention"]},{id:"director",term:"director",kind:"doctrine",gloss:"A person appointed to manage a company.",intermediate:"Someone who runs the company and signs for it. Directors owe their duties to the company itself, not to the shareholders individually.",advanced:"The statutory duties sit alongside the older equitable ones rather than replacing them. The care-and-skill standard has a floor every director must meet and rises for one who happens to know more, so an accountant on the board is held higher than a lay member.",source:"Companies Act 2016",aliases:["director","directors"],see:["shareholder","company"]},{id:"directors-duty",term:"directors' duties",kind:"doctrine",gloss:"Statutory fiduciary and care obligations owed to the company.",intermediate:"Section 213(1) requires a director to act for a proper purpose and in good faith in the best interest of the company; s 213(2) requires reasonable care, skill and diligence. Section 218 deals with improper use of position, property or information.",advanced:"The care duty has an objective floor and a subjective addition: what may reasonably be expected of a director with those responsibilities, plus any extra knowledge or experience the director actually has. Section 214's business judgement rule is a safe harbour for s 213(2) only — it does not excuse a breach of the fiduciary duty in s 213(1).",source:"Companies Act 2016 ss 213, 214 and 218",see:["business-judgement-rule","fiduciary-duty","companies-act"],aliases:["directors' duties","directors duties","director's duty"]},{id:"discharge-not-amounting",term:"discharge not amounting to an acquittal",kind:"doctrine",gloss:"A discharge that leaves the accused liable to be recharged.",intermediate:"The prosecution is stopped but not concluded: the same facts may be charged again. An acquittal, by contrast, is final.",advanced:"The distinction has to be explained to a client in terms, because 'discharged' is heard as 'finished'. It also matters to any argument about autrefois acquit: only an acquittal supports the plea, and a discharge leaves the accused exposed indefinitely subject to the Public Prosecutor's discretion.",source:"Criminal Procedure Code; Federal Constitution Art 145(3)",see:["public-prosecutor","prima-facie-case"],aliases:["discharge not amounting to an acquittal","DNAA"]},{id:"discretion",term:"discretion",kind:"doctrine",gloss:"A power that may be exercised one way or another.",intermediate:"Where the law lets the decision-maker choose rather than telling them what to do. Bail for a non-bailable offence is a discretion; bail for a bailable one is not.",advanced:"A discretion is never unfettered: it must be exercised for the purpose it was given, on relevant considerations, and by the body it was given to. Those three limits are where most judicial review arguments actually live.",source:"Standard administrative law usage",aliases:["discretion","discretionary"],see:["judicial-review","ultra-vires"]},{id:"dishonestly",term:"dishonestly",kind:"doctrine",gloss:"Acting with intention to cause wrongful gain or wrongful loss.",intermediate:"The Penal Code defines it in s 24 by reference to wrongful gain to one person or wrongful loss to another, and s 23 defines those.",advanced:"Because it is defined, the English case law on what ordinary people would consider dishonest is beside the point. The definitional chain — dishonestly, wrongful gain, wrongful loss — is worth stating in full in a property offence answer, because it is where an apparently obvious element actually gets proved.",source:"Penal Code ss 23 and 24",see:["theft","cheating","criminal-breach-of-trust"],aliases:["dishonestly","dishonest"]},{id:"distinguishing",term:"distinguishing",kind:"doctrine",gloss:"Showing that a binding case turned on a fact your case lacks.",intermediate:"An argument that the earlier decision's reasoning does not reach your facts, because a fact it depended on is absent or different. It is the main legitimate way out of an inconvenient precedent.",advanced:"A difference is only a distinction if the earlier reasoning depended on it — 'that case concerned a lorry and this a van' proves nothing unless something turned on the vehicle. Done properly it is a claim about what the earlier ratio was, which is why it is really an argument about materiality. It is also the only one of the four escapes available to a court bound by the decision.",source:"Standard common law method",see:["ratio-decidendi","material-fact","overruling"],aliases:["distinguishing","distinguished","distinguish"]},{id:"dividend",term:"dividend",kind:"doctrine",gloss:"A payment to members out of a company's profits.",intermediate:"A share of the profits paid out to shareholders. It is not a right: it arrives only if the company declares one and is permitted to pay it.",advanced:"That conditionality is what makes a minority holding in a small private company weak. There is usually no buyer for the shares and no dividend to compel, which is precisely the position the oppression remedy exists to address.",source:"Companies Act 2016",aliases:["dividend","dividends"],see:["shareholder"]},{id:"duty-of-care",term:"duty of care",kind:"doctrine",gloss:"The relationship that makes carelessness actionable.",intermediate:"The first element of negligence: whether this defendant owed this claimant an obligation to take reasonable care. Without it, carelessness causing loss gives no claim.",advanced:"The working test asks about reasonable foreseeability of harm, proximity between the parties, and whether it is fair, just and reasonable to impose a duty. Pure economic loss and psychiatric injury are not simply harder instances of it but categories with their own restrictive rules, and identifying them as separate questions is the step that earns the marks.",source:"Standard common law; the Malaysian authorities on the duty of care",see:["breach-of-duty","causation","remoteness","negligence"],aliases:["duty of care","duty"]},{id:"eggshell-skull",term:"eggshell skull",kind:"doctrine",gloss:"Take your victim as you find them.",intermediate:"A defendant is liable for the full extent of the injury even where an unusual susceptibility made it far worse than it would have been for someone else.",advanced:"It is a rule about extent, not about kind: it does not make a defendant liable for a type of damage that was never foreseeable. It extends beyond physical constitution to include, in some circumstances, the claimant's impecuniosity and pre-existing psychiatric vulnerability.",source:"Standard common law",see:["remoteness","causation"],aliases:["eggshell skull","thin skull"]},{id:"ejusdem-generis",term:"ejusdem generis",kind:"latin",gloss:"General words after a list of specifics are read as limited to the same class.",intermediate:"'Cars, lorries, vans and other vehicles' — the general phrase takes its scope from the specific ones before it. There must be an identifiable class for the principle to work on.",advanced:"The canon fails where the specifics disclose no genus, and it yields where the evident purpose of the Act points the other way — it is an aid, not a rule. Its most common misuse in an answer is to invoke it without ever saying what the class is, which is the step that does the persuading.",source:"Standard canon of construction",see:["noscitur-a-sociis","expressio-unius","purposive-approach"],aliases:["ejusdem generis"]},{id:"enactment",term:"enactment",kind:"doctrine",gloss:"A law as passed by a legislature.",intermediate:"A piece of legislation. In Malaysia the word usually points at a State law, because States make Enactments while Parliament makes Acts.",advanced:"The distinction carries real weight in a federal question: which list in the Ninth Schedule the subject falls under decides who could pass it at all, and a law outside the legislature's list is void under Art 4(1) whatever it says.",source:"Interpretation Acts 1948 and 1967",aliases:["enactment","enactments"],see:["statute"]},{id:"entrustment",term:"entrustment",kind:"doctrine",gloss:"Property committed to someone for a purpose.",intermediate:"The element that makes s 405 apply: the accused received the property or dominion over it lawfully, on terms that constrained what he could do with it.",advanced:"Its opposite in a workplace context is mere custody, where the property remains in the employer's possession and the employee only handles it. The distinction decides whether taking it is theft or criminal breach of trust, and it turns on the scope of what was committed to the person rather than on physical proximity to the goods.",source:"Penal Code s 405",see:["criminal-breach-of-trust","theft"],aliases:["entrustment","entrusted"]},{id:"eot",term:"EOT",kind:"doctrine",gloss:"Extension of time, under a construction contract.",intermediate:"More time to finish, granted under the contract's own machinery. Which events entitle the contractor to it, and what notice they must give, are set by the contract rather than by general law.",advanced:"The machinery matters as much as the entitlement: a claim good on its facts can fail on a notice provision. Read the clause before advising, because standard forms differ on both triggers and timing.",source:"Standard construction contract usage",aliases:["EOT"],see:[]},{id:"evidence",term:"evidence",kind:"doctrine",gloss:"What a court is allowed to consider in deciding facts.",intermediate:"The material the court may look at — what witnesses say, and documents and things produced. Not everything true is evidence, because the Act decides what may be proved.",advanced:"The Malaysian Act inverts the English arrangement: Part I declares the categories of relevant fact, and nothing outside them may be proved. So the question is never whether something is relevant in the ordinary sense, but which section makes it relevant.",source:"Evidence Act 1950",aliases:["evidence"],see:["witness","admissibility"]},{id:"evidence-act",term:"Evidence Act 1950",kind:"statute",gloss:"A closed list of what may be proved and how.",intermediate:"Act 56. Evidence may be given of facts in issue and of such other facts as the Act declares relevant — and of no others.",advanced:"This is a different system from the English law of admissibility, where relevance is a general concept subject to exclusionary rules. Here the question is never simply 'is this relevant?' but 'which section makes this relevant?' If you cannot name one, the evidence does not go in, and an answer that argues fairness instead of citing a section has misunderstood the statute.",source:"Evidence Act 1950 (Act 56) s 5",see:["relevancy","admissibility","fact-in-issue"],aliases:["Evidence Act 1950","Evidence Act"]},{id:"evidential-burden",term:"evidential burden",kind:"doctrine",gloss:"The burden of putting enough evidence on a point to make it live.",intermediate:"Section 103 places the burden of proving any particular fact on the person who wishes the court to believe it. Unlike the legal burden, it shifts as the evidence goes in.",advanced:"It is the burden that is discharged by raising a point, not by persuading the court of it. An accused who raises a defence not covered by s 105 bears only this burden, and the prosecution must then disprove it to the criminal standard; where s 105 applies, the accused carries a legal burden instead.",source:"Evidence Act 1950 s 103",see:["legal-burden","section-105"],aliases:["evidential burden"]},{id:"ex-parte",term:"ex parte",kind:"latin",gloss:"An application made without notice to the other side.",intermediate:"Used where giving notice would defeat the purpose — typically urgent injunctions. It carries a strict duty of full and frank disclosure.",advanced:"The applicant must disclose everything material, including matters that help the absent party; a breach of that duty is itself a ground for discharging the order, regardless of the merits. Ex parte relief is temporary by design, returnable on a date when the other side can be heard inter partes.",source:"Rules of Court 2012 O 29 and O 32",see:["interlocutory-injunction","undertaking-in-damages"],aliases:["ex parte","ex-parte"]},{id:"expressio-unius",term:"expressio unius est exclusio alterius",kind:"latin",gloss:"Expressing one thing implies the exclusion of others.",intermediate:"Where a provision names some cases, the argument runs that the ones it did not name were meant to be left out.",advanced:"The weakest of the linguistic canons and the most over-used. A drafter's silence is often just silence — a list may be illustrative, or the omission may be an oversight — so the canon carries weight only where the enumeration looks deliberate and complete. Courts frequently say so when rejecting it.",source:"Standard canon of construction",see:["ejusdem-generis","noscitur-a-sociis"],aliases:["expressio unius est exclusio alterius","expressio unius"]},{id:"fact-in-issue",term:"fact in issue",kind:"doctrine",gloss:"A fact that must be proved for the claim or charge to succeed.",intermediate:"The facts from which, either by themselves or with others, a right, liability or disability asserted in the proceeding necessarily follows.",advanced:"Facts in issue are fixed by the pleadings in a civil case and by the charge in a criminal one, which is why an imprecise pleading or charge causes evidential problems later. Relevant facts are a wider category: they are admissible because they bear on a fact in issue, not because they are one.",source:"Evidence Act 1950 s 3",see:["relevancy","evidence-act","pleading"],aliases:["facts in issue","fact in issue"]},{id:"federal-constitution",term:"Federal Constitution",kind:"institution",gloss:"The supreme law of the Federation.",intermediate:"The document that creates the Federation, distributes legislative power, guarantees fundamental liberties and establishes the courts. Everything else in Malaysian law is subordinate to it.",advanced:"Its supremacy is stated in Art 4(1) and is the reason a legislative-competence argument exists at all: in a system of parliamentary sovereignty the question cannot arise. It is also amendable, generally by a two-thirds majority in each House, which is what makes the basic structure argument — whether some features are beyond even a valid amendment — worth having.",source:"Federal Constitution",see:["article-4","supremacy","basic-structure"],aliases:["Federal Constitution","the Constitution"]},{id:"federal-court",term:"Federal Court",kind:"institution",gloss:"The apex court of Malaysia.",intermediate:"The final appellate court, and the only court that may determine invalidity for want of legislative competence. Its decisions bind every court below.",advanced:"Access is not as of right in most civil matters: leave to appeal is required and is granted on limited statutory grounds, so a great many disputes end at the Court of Appeal. The Federal Court may depart from its own previous decisions, but does so sparingly and with reasons, which is why the sequence of authority in a moving area is worth stating rather than just the latest case.",source:"Courts of Judicature Act 1964; Federal Constitution Art 128",see:["court-of-appeal","stare-decisis","article-128"],aliases:["Federal Court","FC"]},{id:"fiduciary-duty",term:"fiduciary duty",kind:"doctrine",gloss:"An obligation of loyalty owed by someone trusted to act for another.",intermediate:"Its core is that the fiduciary must not profit from the position or allow a conflict between duty and interest without informed consent.",advanced:"Directors are the standard example, but the category extends to partners, agents, trustees and solicitors. The duty is one of loyalty rather than care, which is why a decision can be perfectly competent and still a breach — and why the business judgement rule protects the care duty only.",source:"Companies Act 2016 ss 213(1) and 218; general equitable principle",see:["directors-duty","business-judgement-rule","undue-influence"],aliases:["fiduciary duty","fiduciary"]},{id:"fraud",term:"fraud",kind:"doctrine",gloss:"A false suggestion, active concealment, or a promise made with no intention of performing.",intermediate:"Section 17's definition, covering acts done with intent to deceive or to induce a party to enter the contract. Mere silence is not fraud unless there is a duty to speak.",advanced:"The explanation to s 17 is the operative part in most problems: silence is fraud where the circumstances impose a duty to speak, or where silence is in itself equivalent to speech. Alleging fraud has procedural consequences too — it must be pleaded specifically and with particulars, and it is proved in civil proceedings on the balance of probabilities.",source:"Contracts Act 1950 s 17; Rules of Court 2012 O 18",see:["misrepresentation","free-consent","pleading"],aliases:["fraudulent","fraud"]},{id:"free-consent",term:"free consent",kind:"doctrine",gloss:"Consent not caused by coercion, undue influence, fraud, misrepresentation or mistake.",intermediate:"Section 14 defines it by what removes it, and ss 15 to 23 define each of the five. A contract requires free consent under s 10.",advanced:"The list is closed and each entry has a statutory definition much narrower than its everyday sense — coercion under s 15 means an act forbidden by the Penal Code or unlawful detention of property, not pressure at large. Consequences differ too: coercion, fraud and misrepresentation make the agreement voidable under s 19, while bilateral mistake as to an essential fact makes it void under s 21.",source:"Contracts Act 1950 ss 10, 14-23",see:["voidable","void","coercion","undue-influence","misrepresentation"],aliases:["free consent"]},{id:"frustration",term:"frustration",kind:"doctrine",gloss:"A contract becoming impossible or unlawful after it is made.",intermediate:"Section 57(2): a contract to do an act which after it is made becomes impossible, or unlawful for a reason the promisor could not prevent, becomes void when the act becomes impossible or unlawful.",advanced:"Malaysian law treats this as a statutory doctrine rather than the English implied-term or construction theories, and the consequence is automatic: the contract becomes void, and s 66 governs restoration. Mere hardship, increased expense or a bad bargain do not frustrate, and self-induced impossibility is not frustration at all.",source:"Contracts Act 1950 s 57",see:["void","section-66","breach"],aliases:["frustration","frustrated"]},{id:"fsrs",term:"FSRS",kind:"method",gloss:"The spacing algorithm scheduling the cards in this app.",intermediate:"A model that estimates how durable each memory is and schedules the next review for the moment recall is predicted to fall to your chosen retention.",advanced:"It fits its estimates to the grades you give, which is why an honest Forgot is worth more than a flattering Hard: using Hard as a soft fail inflates every subsequent interval and quietly wrecks the schedule. Raising desired retention buys marginally better recall for a lot more reviews; the usual right response to poor recall is to re-atomise the cards instead.",source:"FSRS-6 via ts-fsrs, vendored in this app",see:["spacing","desired-retention"],aliases:["FSRS"]},{id:"fundamental-liberties",term:"fundamental liberties",kind:"doctrine",gloss:"The rights in Part II of the Constitution.",intermediate:"Liberty of the person, equality, freedom of movement, speech, assembly and association, freedom of religion, rights in respect of education and property. They are enforceable against the State.",advanced:"Two structural points decide most problems. Some rights are held by citizens only — Art 10(1) speaks of citizens where Art 5 speaks of persons — so the claimant's status is a threshold question. And most rights are subject to restriction on stated grounds, so the argument is rarely whether the right exists and almost always whether the restriction falls within a permitted head.",source:"Federal Constitution Part II",see:["article-10","proportionality","article-5"],aliases:["fundamental liberties","fundamental rights"]},{id:"gchq",term:"GCHQ",kind:"doctrine",gloss:"The case that set out the three grounds of judicial review.",intermediate:"Shorthand for the English decision that sorted judicial review into illegality, irrationality and procedural impropriety. Malaysian courts use the same frame.",advanced:"The name is the initials of the body in the case, not a doctrine. Cite it for the classification of grounds; the Malaysian departure on how far a court may go comes from Rama Chandran, not from here.",source:"Standard classification of the grounds of review",aliases:["GCHQ"],see:["judicial-review","ultra-vires"]},{id:"general-exceptions",term:"general exceptions",kind:"doctrine",gloss:"Chapter IV of the Penal Code, applying to every offence in it.",intermediate:"Sections 76 to 106: mistake of fact, judicial acts, accident, necessity, infancy, unsoundness of mind, intoxication, consent, and private defence.",advanced:"Section 6 makes every offence definition subject to them, though they are not repeated in the definition. The burden of bringing yourself within one lies on the accused under s 105 of the Evidence Act, on the balance of probabilities, and the court presumes their absence — that is a genuine legal burden and not merely an evidential one.",source:"Penal Code ss 6 and 76-106; Evidence Act 1950 s 105",see:["private-defence","section-105","penal-code"],aliases:["General Exceptions","general exceptions"]},{id:"golden-rule",term:"golden rule",kind:"doctrine",gloss:"Depart from the literal meaning where it produces an absurdity.",intermediate:"A traditional escape from a literal reading that would produce a result no legislature could have intended.",advanced:"Largely subsumed by the purposive direction, since an absurd result is unlikely to promote the Act's purpose. It survives as a way of describing the pressure point: the argument is really about how absurd a result has to be before the court concludes the words cannot mean what they appear to say.",source:"Standard canon of construction",see:["literal-rule","purposive-approach"],aliases:["golden rule"]},{id:"guarantee",term:"guarantee",kind:"doctrine",gloss:"A promise to answer for another's default.",intermediate:"A promise that if someone else does not pay, you will. A bank asking a director to sign personally is asking for a guarantee.",advanced:"A guarantee is a secondary obligation, so it depends on the principal debt existing. It is the commonest hole in the protection of separate legal personality — not the shares and not the seat on the board, but a contract signed in the person's own name.",source:"Contracts Act 1950",aliases:["guarantee","guarantees"],see:["indemnity","company"]},{id:"provocation",term:"grave and sudden provocation",kind:"doctrine",gloss:"Exception 1 to s 300 — loss of self-control reducing murder.",intermediate:"Culpable homicide is not murder if the offender, while deprived of the power of self-control by grave and sudden provocation, causes the death of the person who gave the provocation.",advanced:"Both adjectives do work: the provocation must be grave, judged with some regard to the accused's situation, and sudden, which is what a cooling-off period defeats. The Exception carries provisos of its own — it does not apply where the provocation was sought or voluntarily provoked, nor where it was given by something done in obedience to the law or in the lawful exercise of private defence.",source:"Penal Code, Exception 1 to s 300",see:["murder","culpable-homicide","private-defence"],aliases:["grave and sudden provocation","provocation"]},{id:"habeas-corpus",term:"habeas corpus",kind:"latin",gloss:"An order requiring a detainer to justify the detention.",intermediate:"The remedy for unlawful detention: the person holding the detainee must show lawful authority for doing so, or release them.",advanced:"It tests the legality of the detention, not its wisdom, and it is available even where a statute purports to make the detaining authority's decision final. Under detention legislation the practical scope of the inquiry has been narrowed by statute at various times, which is why the current provisions matter as much as the principle.",source:"Federal Constitution Art 5(2); Criminal Procedure Code Chapter XXXVI",see:["article-5","arrest","judicial-review"],aliases:["habeas corpus"]},{id:"high-court",term:"High Court",kind:"institution",gloss:"Unlimited original jurisdiction, and the first of the superior courts.",intermediate:"There are two of coordinate jurisdiction: the High Court in Malaya, and the High Court in Sabah and Sarawak. Neither binds the other.",advanced:"Coordinate means exactly that — a decision of one is persuasive in the other, and a High Court judge is not bound by another High Court judge, though departing from one is done with reasons because inconsistency at the same level is its own mischief. The High Court is also the forum for judicial review under Order 53 and for an order for sale of land held under Registry title.",source:"Courts of Judicature Act 1964",see:["federal-court","court-of-appeal","judicial-review","order-for-sale"],aliases:["High Court in Sabah and Sarawak","High Court in Malaya","High Court","HC"]},{id:"hl",term:"HL",kind:"institution",gloss:"House of Lords — the former highest court in the United Kingdom.",intermediate:"The UK's top court until 2009, when the UK Supreme Court replaced it. Its decisions appear in English citations as (HL).",advanced:"Salomon, the case that settled separate corporate personality, is a House of Lords decision from 1897 that Malaysian courts apply. Age alone is not a reason to distrust a decision; some old ones hold up better than recent ones.",source:"English court hierarchy",aliases:["HL"],see:["uksc","ac"]},{id:"indefeasibility",term:"indefeasibility",kind:"doctrine",gloss:"A registered title that cannot be set aside.",intermediate:"Section 340(1): the title or interest of a registered proprietor is indefeasible, subject to the exceptions in s 340(2) — fraud or misrepresentation, forgery or an insufficient or void instrument, and unlawful acquisition.",advanced:"Malaysian law applies deferred, not immediate, indefeasibility: a proprietor registered through a forged or void instrument takes a defeasible title, while a subsequent purchaser in good faith and for value takes a good one. Adorna Properties held the opposite and stood for nine years before Tan Ying Hong departed from it, so anything written on the topic before 2010 must be dated before it is trusted.",source:"National Land Code s 340; Tan Ying Hong v Tan Sian San [2010] 2 MLJ 1 (FC); Adorna Properties Sdn Bhd v Boonsom Boonyanit [2001] 1 MLJ 241 (FC)",see:["torrens","deferred-indefeasibility","national-land-code"],aliases:["indefeasibility","indefeasible"]},{id:"indemnity",term:"indemnity",kind:"doctrine",gloss:"A promise to make good another's loss.",intermediate:"An undertaking to cover someone else's loss if it happens. It stands on its own, without needing anybody else to default first.",advanced:"That independence is what separates it from a guarantee: an indemnity is a primary obligation, so it survives circumstances that would discharge a surety, and it is not defeated merely because the principal obligation turns out to be unenforceable.",source:"Contracts Act 1950",aliases:["indemnity","indemnities"],see:["guarantee"]},{id:"inference",term:"inference",kind:"method",gloss:"A conclusion drawn from a proved fact rather than stated directly.",intermediate:"Something the court works out from other facts, instead of being told outright. Nobody saw the theft, but the goods were in his room the next morning.",advanced:"An inference must be the reasonable conclusion from proved facts, not a guess dressed as one. Where an inference is permissive the court may draw it and is never bound to, which is the difference between s 114's illustrations and a presumption the court must make.",source:"Evidence Act 1950",aliases:["inference","inferences"],see:["presumption","adverse-inference"]},{id:"interleaving",term:"interleaving",kind:"method",gloss:"Mixing topics in a session rather than blocking them.",intermediate:"Studying contract and criminal law in the same sitting rather than one after the other. It feels worse and produces better discrimination between them.",advanced:"Blocked practice lets you apply the same rule repeatedly without deciding which rule applies — which is the very skill an issue-spotting problem tests. Interleaving forces the choice each time, and the cost is that performance during practice drops, which learners routinely misread as the method not working.",source:"Make It Stick; the interleaving literature",see:["spacing","retrieval-practice"],aliases:["interleaving","interleave"]},{id:"interlocutory-injunction",term:"interlocutory injunction",kind:"doctrine",gloss:"An order holding the position until trial.",intermediate:"The applicant must show a serious question to be tried, that damages would not be an adequate remedy, and that the balance of convenience favours the injunction. An undertaking in damages is ordinarily required.",advanced:"The court does not try the merits, which is why an argument that the applicant will probably win is beside the point. A mandatory injunction — requiring something to be done rather than restrained — attracts a higher threshold, and the Malaysian gloss on American Cyanamid should be cited from a Malaysian decision rather than an English one.",source:"Rules of Court 2012 O 29; American Cyanamid Co v Ethicon Ltd [1975] AC 396 as applied in Malaysia",see:["undertaking-in-damages","ex-parte","caveat","rules-of-court"],aliases:["interlocutory injunction","interim injunction","injunction"]},{id:"interpretation",term:"interpretation",kind:"method",gloss:"Settling what a provision means.",intermediate:"Deciding what the words of an Act actually require. You start with the words themselves, then their place in the Act, then what the Act was for.",advanced:"Section 17A requires a purposive approach, so a reading that promotes the underlying object is preferred to one that does not. The internal aids — long title, marginal notes, provisos, definition sections — come before external material.",source:"Interpretation Acts 1948 and 1967, s 17A",aliases:["interpretation"],see:["construction"]},{id:"irac",term:"IRAC",kind:"method",gloss:"Issue, Rule, Application, Conclusion — a structure for making reasoning visible.",intermediate:"A way of ordering an answer so that the rule is stated before it is used and the application is separated from the recitation. It is scaffolding, not a form to be filled.",advanced:"Its value is that it forces the step people skip when unsure: stating the governing rule with its source before reasoning from it. Its characteristic failure is a long Rule section and a thin Application — an answer that proves recall and not reasoning, which is why rubric bands weight application most heavily.",source:"Standard examination technique",see:["application","material-fact","calibration"],aliases:["IRAC"]},{id:"judicial-power",term:"judicial power",kind:"doctrine",gloss:"The power to decide disputes according to law, and whether the Constitution still vests it.",intermediate:"Before 1988 Article 121(1) vested the judicial power of the Federation in the High Courts. The amendment replaced that with jurisdiction 'conferred by or under federal law'.",advanced:"On one reading the courts' jurisdiction became entirely a creature of statute; on another, judicial power is inherent in a constitution that separates the branches and cannot be removed by rewriting the sentence describing it. Malaysian courts have taken both views at different times, and this is the most unsettled area in the constitutional module — do not state either position as settled without checking the most recent Federal Court authority.",source:"Federal Constitution Art 121(1); Constitution (Amendment) Act 1988",see:["article-121a","basic-structure","ouster-clause"],aliases:["judicial power"]},{id:"judicial-review",term:"judicial review",kind:"doctrine",gloss:"The court reviewing how a public decision was made, not whether it was right.",intermediate:"Brought under Order 53 with leave. The grounds are illegality, irrationality and procedural impropriety, with proportionality argued as a fourth.",advanced:"Review goes to the decision-making process, which is why it is not an appeal. Malaysian law has gone further than English law in places: R Rama Chandran allows a court in an appropriate case to examine substance and to substitute its own decision rather than remitting — though later authority has been careful about the limits, and the case should be cited for what it decided rather than for the proposition that review is now an appeal.",source:"Rules of Court 2012 O 53; R Rama Chandran v Industrial Court of Malaysia [1997] 1 MLJ 145 (FC)",see:["order-53","wednesbury","natural-justice","ultra-vires"],aliases:["judicial review"]},{id:"jurisdiction",term:"jurisdiction",kind:"doctrine",gloss:"The range of people and matters a court may decide.",intermediate:"Whether this court is allowed to hear this case at all. It has two halves: the kind of matter, and the people or the place involved. A court without jurisdiction cannot cure that by deciding the case well.",advanced:"Every Malaysian court below the Constitution's own heads takes its jurisdiction from statute, so the question is always which provision confers it. Keep three things apart: whether a court has jurisdiction, whether it should exercise one it has, and whether the decision it reached was right. Only the first is jurisdiction.",source:"Courts of Judicature Act 1964; Subordinate Courts Act 1948",aliases:["jurisdiction","jurisdictions"],see:["judicial-review","ultra-vires"]},{id:"learning-the-law",term:"Learning the Law",kind:"method",gloss:"Glanville Williams, Learning the Law — the method book this course leans on.",intermediate:"An introduction to reading statutes and cases, solving problem questions and studying law. Edited by A. T. H. Smith, 18th edition, Sweet & Maxwell.",advanced:"Its framing is the English legal system, so take the method and not the substantive law. How to read a section, brief a case and structure an answer transfers to Malaysia unchanged; what the law says does not.",source:"Glanville Williams, Learning the Law, 18th ed (Sweet & Maxwell), ed A. T. H. Smith",aliases:["Learning the Law","Glanville Williams"],see:["irac"]},{id:"lease",term:"lease",kind:"doctrine",gloss:"A registered interest giving the right to occupy land for a term.",intermediate:"A right to occupy someone else's land for a fixed period. A registered lease is an interest in the land itself, which is more than a tenancy agreement between two people.",advanced:"Registration is what makes the difference: a registered lease binds a later proprietor, while an unregistered arrangement generally binds only the parties to it. The register is where you find out which one you are dealing with.",source:"National Land Code",aliases:["lease","leases"],see:["proprietor","registration"]},{id:"legal-burden",term:"legal burden",kind:"doctrine",gloss:"The risk of losing if the fact is not proved. It does not shift.",intermediate:"Section 101: whoever asserts facts on which a right or liability depends must prove them. Section 102 identifies who carries it by asking who would fail if no evidence were given.",advanced:"Its counterpart, the evidential burden under s 103, is the burden of adducing evidence on a particular fact, and that does move as the case develops. Saying 'the burden shifted' without saying which one is the standard imprecision in this area, and it matters most in criminal cases, where the legal burden stays on the prosecution except where a statute places one on the accused.",source:"Evidence Act 1950 ss 101, 102 and 103",see:["evidential-burden","section-105","beyond-reasonable-doubt"],aliases:["burden of proof","legal burden"]},{id:"legislative-competence",term:"legislative competence",kind:"doctrine",gloss:"Whether the legislature had power to pass the law at all.",intermediate:"Parliament may legislate on the Federal and Concurrent Lists; a State Legislature on the State and Concurrent Lists. A law outside the allotted field is invalid however sensible it is.",advanced:"Competence is the prior question in any constitutional problem, and it is often decisive without reaching rights at all: a restriction contained in an ultra vires statute fails before Article 10 is ever considered. The Federal Court has exclusive jurisdiction under Art 128 to determine invalidity on this ground, so getting the forum right is part of the answer.",source:"Federal Constitution Arts 74, 4(1) and 128; Ninth Schedule",see:["ninth-schedule","article-75","article-128","ultra-vires"],aliases:["legislative competence","competence"]},{id:"legitimate-expectation",term:"legitimate expectation",kind:"doctrine",gloss:"An expectation founded on a clear representation or a settled practice.",intermediate:"Most secure in its procedural form: that a person will be consulted or heard before a change. The substantive form — that the benefit itself will be conferred — is more contested.",advanced:"An expectation cannot be legitimate if the representation was outside the decision-maker's power, because a public body cannot bind itself to act unlawfully. The reception of substantive legitimate expectation in Malaysia should be checked against current authority rather than asserted, and a settled practice described in a published leaflet is exactly the kind of material that founds the procedural form.",source:"Standard administrative law; the Malaysian authorities on legitimate expectation",see:["natural-justice","judicial-review","ultra-vires"],aliases:["legitimate expectation"]},{id:"legitimate-interest",term:"legitimate interest",kind:"doctrine",gloss:"What an agreed-damages clause is allowed to protect.",intermediate:"The innocent party's genuine commercial interest in performance, beyond simply being compensated in money. The test asks whether the stipulated sum is out of all proportion to it.",advanced:"It comes into Malaysian law through Cubic Electronics, which drew on Cavendish v Makdessi, and it shifted the focus away from the old genuine-pre-estimate question. Timely completion of a revenue-producing asset is the standard example of such an interest; deterrence for its own sake, unmoored from any interest in performance, is not.",source:"Cubic Electronics Sdn Bhd v Mars Telecommunications Sdn Bhd [2019] 2 MLJ 806 (FC)",see:["section-75","liquidated-damages"],aliases:["legitimate interest"]},{id:"liability",term:"liability",kind:"doctrine",gloss:"Being legally answerable for something.",intermediate:"Being on the hook: the law says you must pay, compensate or answer for what happened. Establishing liability is a separate question from how much is owed.",advanced:"Keep liability and quantum apart in an answer. A party may be liable and owe very little, or be plainly at fault and owe nothing because the damage was too remote. Merging the two is a standard way to lose marks in tort.",source:"Standard common law",aliases:["liability","liable"],see:["negligence","remoteness"]},{id:"libel",term:"libel",kind:"doctrine",gloss:"Defamation in permanent form.",intermediate:"Written, printed or otherwise recorded defamation. It is actionable without proof of special damage.",advanced:"How internet publication is classified has made the permanent-or-transient line harder to apply than it sounds, and the current Malaysian position should be checked rather than assumed. Each republication is generally a fresh publication, which is what makes online material a continuing exposure rather than a single event.",source:"Defamation Act 1957",see:["slander","defamation"],aliases:["libel"]},{id:"lien-holders-caveat",term:"lien-holder's caveat",kind:"doctrine",gloss:"The way a deposited title document is protected as security.",intermediate:"Where the issue document of title is deposited with an intention to create security, the lien is protected — and becomes enforceable — by entering a lien-holder's caveat.",advanced:"Facts that mention a deposited title document are almost always testing this rather than a private caveat, and recognising the cue is faster than reasoning from first principles. The lien is an informal security that the Code accommodates rather than creates, which is why the caveat does more work here than it does elsewhere.",source:"National Land Code, the caveat provisions",see:["caveat","charge","torrens"],aliases:["lien holder's caveat","lien-holder's caveat","lien"]},{id:"limitation",term:"limitation",kind:"doctrine",gloss:"The period within which an action must be brought.",intermediate:"Generally six years for contract and tort under the Limitation Act 1953, and twelve for actions to recover land, running from when the cause of action accrued.",advanced:"Accrual is not the same as the wrongful act: in contract it runs from breach, in negligence generally from when damage occurs, which may be much later. Limitation is a defence that must be pleaded, and other statutes contain their own periods — public authorities and certain claims are subject to shorter ones — so the general period must be checked against the particular claim.",source:"Limitation Act 1953 s 6",see:["cause-of-action","pleading","section-26"],aliases:["limitation period","time-barred","limitation"]},{id:"liquidated-damages",term:"liquidated damages",kind:"doctrine",gloss:"A sum the contract fixes as payable on breach.",intermediate:"An agreed figure intended to save the trouble of proving loss. In Malaysia its effect is governed by s 75 rather than by the English penalty rule.",advanced:"The parties' own description of the sum as a genuine pre-estimate is evidence and not conclusive; a label cannot convert a disproportionate sum into a proportionate one. Under the Cubic Electronics approach the questions are whether the clause protects a legitimate interest and whether the sum is out of all proportion to it, and causation still has to be established — a claimant cannot recover for a loss the breach did not cause.",source:"Contracts Act 1950 s 75",see:["section-75","legitimate-interest","section-74"],aliases:["liquidated damages clause","liquidated damages"]},{id:"literal-rule",term:"literal rule",kind:"doctrine",gloss:"Give the words their ordinary meaning.",intermediate:"The starting point of any construction: read what the provision says. Purpose does not licence ignoring the text.",advanced:"The literal approach is often presented as the opposite of the purposive one, which is misleading. They answer different questions: the literal reading establishes the range of meanings the words can bear, and the purposive direction chooses among them. A provision whose words admit only one meaning is not made ambiguous by the fact that the meaning produces an inconvenient result.",source:"Standard canon of construction",see:["purposive-approach","golden-rule"],aliases:["literal approach","literal rule"]},{id:"locus-standi",term:"locus standi",kind:"latin",gloss:"Standing to bring the proceedings.",intermediate:"Whether this applicant is entitled to ask the court to decide this question. In judicial review the Malaysian test is whether the applicant is adversely affected by the decision.",advanced:"It is a threshold, not a merits question, though the two blur in practice because a person plainly affected usually has a real complaint. The Malaysian formulation is narrower than the English one, which is why an answer that imports 'sufficient interest' has stated the wrong test.",source:"Rules of Court 2012 O 53; the Malaysian authorities on standing",see:["order-53","judicial-review"],aliases:["locus standi","standing"]},{id:"long-title",term:"long title",kind:"doctrine",gloss:"The opening words describing what an Act is for.",intermediate:"'An Act to provide for…' — admissible evidence of the Act's purpose, and part of the enacted text.",advanced:"Unlike a marginal note, the long title is enacted and may be used to resolve an ambiguity, though it cannot cut down clear words in a section. It is the first place to look when an argument needs the Act's object, and it is routinely overlooked.",source:"Standard canon of construction",see:["marginal-note","purposive-approach","preamble"],aliases:["long title"]},{id:"magistrates-court",term:"Magistrates' Court",kind:"institution",gloss:"The base of the ordinary hierarchy.",intermediate:"Handles lower-value civil claims and less serious criminal matters, with sentencing powers capped by statute.",advanced:"It is also the court that authorises remand under s 117 of the Criminal Procedure Code, which is a function quite separate from trying cases and is where most people first encounter it. Its civil and sentencing limits are statutory and are raised from time to time.",source:"Subordinate Courts Act 1948; Criminal Procedure Code s 117",see:["sessions-court","remand","subordinate-courts"],aliases:["Magistrates' Court","Magistrates Court","Magistrate"]},{id:"malice",term:"malice",kind:"doctrine",gloss:"An improper motive that destroys a defence.",intermediate:"In defamation it defeats qualified privilege and fair comment. It is not an element of the tort, and proving hostility does not by itself establish liability.",advanced:"Malice here means using the occasion for a purpose other than the one for which it is protected, or making the statement without honest belief in its truth — spite is evidence of it rather than the definition. Because it is directed at defences, the sequence in an answer matters: elements, then defence, then malice.",source:"Standard common law",see:["qualified-privilege","defamation"],aliases:["malicious","malice"]},{id:"mandamus",term:"mandamus",kind:"latin",gloss:"An order compelling performance of a public duty.",intermediate:"Requires a public body to do what the law obliges it to do. It does not dictate how a discretion is exercised, only that it be exercised.",advanced:"The distinction matters: a court will order an authority to decide, and will not usually order it to decide in the applicant's favour. Where the duty is owed to the public generally rather than to the applicant, standing becomes the difficulty.",source:"Rules of Court 2012 O 53",see:["certiorari","judicial-review","locus-standi"],aliases:["mandamus"]},{id:"mandatory",term:"mandatory",kind:"method",gloss:"A requirement that must be met, as against one that may be.",intermediate:"Something the law says must happen. Shall is usually mandatory; may usually leaves a choice. The two words decide cases.",advanced:"Courts read shall and may in context rather than mechanically, and a may has been read as a duty where the power exists for somebody else's benefit. Where a requirement is mandatory, the further question is what follows from breach — invalidity, or a defect that can be cured.",source:"Standard canon of construction",aliases:["mandatory"],see:["discretion","interpretation"]},{id:"marginal-note",term:"marginal note",kind:"doctrine",gloss:"The heading printed beside a section. Not enacted text.",intermediate:"A drafting convenience indicating what a section is about. It orients a reader but cannot control the meaning of a clear provision.",advanced:"Marginal notes and headings are inserted for arrangement and are not voted on, which is the reason for their limited weight. They may be used as an indication of the drafter's intention where the words are genuinely ambiguous, and citing one as though it were operative is a visible error.",source:"Standard canon of construction",see:["long-title","proviso"],aliases:["marginal notes","marginal note"]},{id:"material-fact",term:"material fact",kind:"method",gloss:"A fact the decision turned on — one whose change might change the result.",intermediate:"The facts that carried legal weight, as opposed to the ones that merely tell the story. Identifying them is most of the work of reading a case.",advanced:"Materiality is a counterfactual test, and it is contestable: two lawyers can read the same judgment and disagree about which facts were doing the work, which is exactly what an argument about the scope of a precedent consists of. In pleading, the phrase means something adjacent but distinct — the facts that must be pleaded to disclose the cause of action, as opposed to the evidence that will prove them.",source:"Standard common law method; Rules of Court 2012 O 18 for the pleading sense",see:["ratio-decidendi","distinguishing","pleading"],aliases:["material facts","material fact"]},{id:"maximum-evaluation",term:"maximum evaluation",kind:"doctrine",gloss:"Testing the prosecution evidence properly at the halfway stage.",intermediate:"The requirement that a court deciding whether a prima facie case exists evaluate the credibility of the prosecution evidence, not merely ask whether any evidence was led.",advanced:"The phrase comes from the judicial discussion around the amendments to s 180 and its predecessor, and the standard has moved more than once — which is why the current formulation should be taken from a recent decision rather than a summary. Its practical effect is that a submission of no case is a real argument about the quality of the evidence.",source:"Criminal Procedure Code s 180 and the case law upon it",see:["prima-facie-case","beyond-reasonable-doubt"],aliases:["maximum evaluation"]},{id:"mens-rea",term:"mens rea",kind:"latin",gloss:"The guilty mind — the mental element of an offence.",intermediate:"Intention, knowledge, recklessness or negligence, as the particular offence requires. It is presumed to be required unless a statute displaces it.",advanced:"In a codified system the phrase is a category rather than a test: the Penal Code specifies the fault element for each offence, and 'intending to cause death' or 'knowing it to be likely' is what has to be proved, not mens rea in the abstract. The presumption that a criminal offence requires a mental element is displaceable expressly or by necessary implication, and strict liability is not lightly inferred.",source:"Penal Code; standard presumption of construction",see:["actus-reus","penal-code","strict-liability"],aliases:["mens rea"]},{id:"merdeka-day",term:"Merdeka Day",kind:"institution",gloss:"31 August 1957 — the date the supremacy clause runs from.",intermediate:"Independence day for the Federation of Malaya, and the reference point in Article 4(1) for which laws are tested against the Constitution.",advanced:"The date matters technically as well as symbolically: Art 4(1) speaks of law passed after Merdeka Day, and pre-Merdeka law is dealt with separately, with Art 162 providing for its continuation subject to modification to bring it into accord with the Constitution. Malaysia itself was formed later, in 1963, which is why the reception dates in the Civil Law Act 1956 differ between the peninsula, Sabah and Sarawak.",source:"Federal Constitution Arts 4(1) and 162",see:["supremacy","civil-law-act","reception"],aliases:["Merdeka Day","Merdeka"]},{id:"mischief-rule",term:"mischief rule",kind:"doctrine",gloss:"Ask what defect in the earlier law the Act was passed to cure.",intermediate:"A construction guided by the problem the statute was enacted to fix, so that the reading which suppresses the mischief is preferred.",advanced:"This is the closest ancestor of s 17A and remains the most useful traditional tool, because it directs attention to the material that establishes purpose: the long title, the preamble, the state of the law before the Act, and the defect it addressed. Where a modern answer says 'purposive', a court is often doing exactly what Heydon's Case described.",source:"Heydon's Case (1584); Interpretation Acts 1948 and 1967, s 17A",see:["purposive-approach","section-17a","long-title"],aliases:["mischief rule"]},{id:"misrepresentation",term:"misrepresentation",kind:"doctrine",gloss:"An untrue assertion that induced the contract, made without knowing it was false.",intermediate:"Section 18 covers a positive assertion not warranted by the information of the person making it, though believed true, and certain breaches of duty. Fraud under s 17 is the dishonest counterpart.",advanced:"The line between ss 17 and 18 is belief: the maker of a s 18 representation believes it. Both render the agreement voidable under s 19, and the innocent party's right to rescind can be lost by affirmation, lapse of time, or the impossibility of restitution. Section 19's proviso denies avoidance where the party had the means of discovering the truth with ordinary diligence, which is a real limit on s 18.",source:"Contracts Act 1950 ss 17, 18 and 19",see:["fraud","free-consent","voidable","rescission"],aliases:["misrepresentation","misrepresent"]},{id:"mitigation",term:"mitigation",kind:"doctrine",gloss:"The duty to take reasonable steps to limit your loss.",intermediate:"A claimant cannot recover for loss he could reasonably have avoided. The explanation to s 74 requires the means available for remedying the inconvenience to be taken into account.",advanced:"It is not a duty owed to the defendant so much as a limit on recovery, and the standard is reasonableness judged at the time, not with hindsight: a claimant who took a reasonable step that turned out badly still recovers. The burden of showing a failure to mitigate is on the defendant.",source:"Contracts Act 1950 s 74, explanation",see:["section-74","remoteness"],aliases:["mitigation","mitigate"]},{id:"mlj",term:"MLJ",kind:"method",gloss:"Malayan Law Journal.",intermediate:"The main Malaysian series of law reports. In a citation like [2010] 2 MLJ 1, MLJ names the series, 2 the volume and 1 the page.",advanced:"Square brackets round the year mean the year is needed to find the volume. Where a case exists in more than one series, cite the report rather than an unreported court-issued judgment, and give the court in brackets at the end.",source:"Malaysian law report series",aliases:["MLJ"],see:["clj","citator"]},{id:"mlra",term:"MLRA",kind:"method",gloss:"Malayan Law Reports, Appellate Courts.",intermediate:"A Malaysian report series for appellate decisions. A single case may carry an MLJ, a CLJ and an MLRA citation at once.",advanced:"Multiple citations for one judgment are a publishing artefact rather than a sign of importance. Give whichever series your reader can actually reach, and give the court.",source:"Malaysian law report series",aliases:["MLRA"],see:["mlj","clj"]},{id:"murder",term:"murder",kind:"doctrine",gloss:"Culpable homicide falling within one of the four limbs of s 300.",intermediate:"Section 300 sets out four ways culpable homicide becomes murder, subject to five Exceptions that reduce it back to culpable homicide not amounting to murder.",advanced:"Limb (c) does most of the work in single-blow cases and asks two questions: did the accused intend to inflict the injury actually inflicted, and is that injury objectively sufficient in the ordinary course of nature to cause death. The second limb is objective, which is why (c) is often provable where an intention to cause death under (a) is not. The mandatory death penalty was abolished in 2023, so sentencing should never be stated from memory or from an older text.",source:"Penal Code s 300",see:["culpable-homicide","provocation","private-defence"],aliases:["murder"]},{id:"national-land-code",term:"National Land Code",kind:"statute",gloss:"The federal statute governing registered land in Peninsular Malaysia.",intermediate:"Act 828 as revised in 2020, covering alienation, dealings, charges, caveats and indefeasibility of title.",advanced:"Land is a State matter, so a federal Code is possible only through Article 76's uniformity route, and it takes effect in a State on adoption by its legislature. Sabah and Sarawak have their own land legislation and are not a footnote to the Code. The 2020 revision renumbered provisions, so any section cited from an older text must be checked against the current one.",source:"National Land Code (Act 828, Revised 2020); Federal Constitution Art 76",see:["torrens","article-76","indefeasibility"],aliases:["National Land Code","NLC"]},{id:"natural-justice",term:"natural justice",kind:"doctrine",gloss:"Two rules: hear the other side, and no one a judge in his own cause.",intermediate:"The procedural minimum a decision affecting a person must meet. Their content varies with what is at stake and with the statutory framework.",advanced:"They are two specific rules, not a general power to require fairness, and an answer should say which one is engaged and what it required on these facts. A decision removing a livelihood attracts far more than a preliminary or investigatory step; an oral hearing, reasons and legal representation are not always required.",source:"Standard administrative law as received in Malaysia",see:["audi-alteram-partem","nemo-judex","judicial-review","legitimate-expectation"],aliases:["natural justice"]},{id:"negligence",term:"negligence",kind:"doctrine",gloss:"Careless conduct causing foreseeable damage, in breach of a duty.",intermediate:"Four questions in order: duty, breach, causation, remoteness. Each assumes the one before it.",advanced:"The order is not stylistic. Arguing remoteness before establishing breach is arguing about nothing, and an answer that opens with the defences has assumed the case it should be proving. Malaysian law has taken its own line in two places worth knowing: the doctor's duty to advise of risks, where Foo Fio Na departed from Bolam, and apportionment for contributory negligence under s 12 of the Civil Law Act 1956.",source:"Standard common law; Foo Fio Na v Dr Soo Fook Mun [2007] 1 MLJ 593 (FC); Civil Law Act 1956 s 12",see:["duty-of-care","breach-of-duty","causation","remoteness"],aliases:["negligence","negligent"]},{id:"nemo-judex",term:"nemo judex in causa sua",kind:"latin",gloss:"No one may be a judge in his own cause.",intermediate:"The rule against bias. Actual bias need not be shown: the test is objective.",advanced:"The working question is whether a fair-minded and informed observer would conclude there was a real danger, or real possibility, of bias — and which formulation Malaysian courts currently use is worth checking, because both appear. Pleading actual bias is a tactical error: it is harder to prove and amounts to an allegation of dishonesty the objective test does not require.",source:"Standard administrative law; the Malaysian authorities on bias",see:["natural-justice","audi-alteram-partem"],aliases:["nemo judex in causa sua","nemo judex","bias"]},{id:"ninth-schedule",term:"Ninth Schedule",kind:"statute",gloss:"The three lists dividing legislative power.",intermediate:"List I is Federal, List II is State, List III Concurrent, with supplementary lists for Sabah and Sarawak. Every competence question starts here.",advanced:"The counter-intuitive entries are the examinable ones: land and Islamic law are State matters, while civil and criminal law and procedure are federal. That is how a State enactment can regulate Muslim family law while the Penal Code is national — and why the National Land Code, a federal statute on a State subject, needs Article 76 to explain it.",source:"Federal Constitution, Ninth Schedule",see:["legislative-competence","article-75","article-76"],aliases:["Concurrent List","Ninth Schedule","Federal List","State List","List III","List II","List I"]},{id:"non-bailable",term:"non-bailable offence",kind:"doctrine",gloss:"An offence for which bail is discretionary, not unavailable.",intermediate:"Section 388: the court may release the accused on bail. The label misleads almost everyone who meets it for the first time.",advanced:"Where the discretion arises the court asks whether the accused will attend trial and whether release creates risks that conditions cannot manage — interference with witnesses, the gravity of the offence and the likely sentence, antecedents and ties to the jurisdiction. Proposing conditions such as sureties, surrender of a passport, or reporting is usually a better answer than asserting that the risk is low.",source:"Criminal Procedure Code s 388",see:["bailable","criminal-procedure-code"],aliases:["non-bailable offence","non-bailable"]},{id:"noscitur-a-sociis",term:"noscitur a sociis",kind:"latin",gloss:"A word takes colour from the words around it.",intermediate:"The meaning of a term is read in the light of its companions in the provision, rather than in isolation.",advanced:"Broader than ejusdem generis, which is really a special case of it: noscitur needs no list of specifics and no genus, only context. It is the canon behind the instruction to read the whole section before the words you came for.",source:"Standard canon of construction",see:["ejusdem-generis"],aliases:["noscitur a sociis"]},{id:"noting-up",term:"noting up",kind:"method",gloss:"Checking a case's later treatment before relying on it.",intermediate:"The step after finding a case: establishing whether it has since been followed, distinguished, doubted or overruled.",advanced:"It is the step most often skipped and the one that most often changes the answer. Adorna Properties stood as an available and citable Federal Court decision on indefeasibility for nine years while being wrong, and nothing in the text of the judgment says so.",source:"Standard research practice",see:["citator","overruling","torrens"],aliases:["noting up","note up"]},{id:"novus-actus",term:"novus actus interveniens",kind:"latin",gloss:"A new intervening act that breaks the chain of causation.",intermediate:"A later event so independent of the defendant's breach that the law treats it, rather than the breach, as the cause of the damage.",advanced:"A deliberate wrongful act by a third party usually breaks the chain; a foreseeable act, or one the defendant's own negligence made likely, usually does not. Ordinary negligent medical treatment following an injury is treated as foreseeable and does not break it, though grossly negligent treatment may. It must be kept distinct from contributory negligence: this defeats the claim, that reduces it.",source:"Standard common law",see:["causation","contributory-negligence","but-for"],aliases:["novus actus interveniens","novus actus"]},{id:"obiter-dictum",term:"obiter dictum",kind:"latin",gloss:"A statement not necessary to the decision. Persuasive at most.",intermediate:"Anything a judge says that the result did not require. It can be quoted and relied on as persuasive, but it binds nobody.",advanced:"A court that expressly declines to decide a point has not decided it, however suggestive its language — reservations of that kind are the most reliably identifiable obiter there is. Considered dicta of a superior court carry real weight in practice, and counsel routinely build arguments on them; the distinction that matters is that a later court is free to disagree without needing any of the machinery for departing from precedent.",source:"Standard common law doctrine",see:["ratio-decidendi","persuasive-authority"],aliases:["obiter dictum","obiter dicta","obiter"]},{id:"offence",term:"offence",kind:"doctrine",gloss:"Conduct that the law makes punishable.",intermediate:"Something a statute says is a crime and attaches a punishment to. An offence has a physical part and usually a mental part, and the prosecution must prove both.",advanced:"In Malaysia each offence is defined with its own mental element written into the section, so reasoning from a general English doctrine of mens rea can mislead. The First Schedule to the Criminal Procedure Code then classifies each offence for arrest, investigation and bail.",source:"Penal Code; Criminal Procedure Code, First Schedule",aliases:["offence","offences"],see:["actus-reus","mens-rea"]},{id:"oppression",term:"oppression",kind:"doctrine",gloss:"A member's remedy for being treated unfairly.",intermediate:"Section 346: that the company's affairs are being conducted, or the directors' powers exercised, in a manner oppressive to a member or in disregard of a member's interests.",advanced:"The complaint is about how the member has been treated, which is what distinguishes it from a derivative action vindicating the company's own right. The court's powers on such a petition are wide and include a buy-out order, which is the outcome most petitions are actually seeking. Pleading oppression and a derivative action together without thought proceeds on inconsistent premises about whose right is in issue.",source:"Companies Act 2016 s 346",see:["derivative-action","reflective-loss","companies-act"],aliases:["oppression","oppressive"]},{id:"order-53",term:"Order 53",kind:"statute",gloss:"The judicial review procedure.",intermediate:"Requires leave, an applicant who is adversely affected by the decision, and an application made within the prescribed time from when the grounds arose.",advanced:"The threshold requirements end more applications than the merits do. The Malaysian standing test — adversely affected — has been stated in the Federal Court and is narrower than the English sufficient interest. The time limit runs from the decision, not from when the applicant gave up on correspondence, so a delay spent writing letters is still delay.",source:"Rules of Court 2012 O 53; QSR Brands Bhd v Suruhanjaya Sekuriti [2006] 3 MLJ 164 (CA)",see:["judicial-review","locus-standi","certiorari"],aliases:["Order 53","O 53"]},{id:"order-for-sale",term:"order for sale",kind:"doctrine",gloss:"The court or Land Administrator ordering charged land to be sold.",intermediate:"The chargee's remedy on unremedied default. The court will order sale unless the chargor shows cause to the contrary.",advanced:"The two tracks — High Court for Registry title, Land Administrator for Land Office title — have different provisions and different appeal routes, and confusing them is the standard error. Because the discretion is narrow, most contested applications are really arguments about whether the statutory notice was valid.",source:"National Land Code, the order-for-sale provisions",see:["charge","cause-to-the-contrary","high-court"],aliases:["order for sale"]},{id:"originating-summons",term:"originating summons",kind:"doctrine",gloss:"The mode of commencement for a question of law on undisputed facts.",intermediate:"Proceeds on affidavit evidence rather than oral testimony, and suits construction questions and applications where the facts are not really in contest.",advanced:"It is unsuitable where credibility is in issue, because affidavits cannot be cross-examined without an order. Some applications must be brought this way by the rules — judicial review being the obvious one — so the choice is not always open.",source:"Rules of Court 2012 O 5 and O 7",see:["writ","order-53","rules-of-court"],aliases:["originating summons"]},{id:"ouster-clause",term:"ouster clause",kind:"doctrine",gloss:"A provision purporting to exclude the courts' jurisdiction.",intermediate:"Statutory wording that says a decision shall be final, or shall not be questioned in any court. Courts construe such clauses narrowly.",advanced:"The presumption against ouster is strong enough that clear words are required, and even clear words face a constitutional limit: judicial review of administrative action is inherent in the civil courts, and there is Malaysian authority treating it as part of the basic structure. The practical effect is that an ouster clause is usually read as protecting a decision made within jurisdiction, and as leaving untouched one made outside it.",source:"Standard presumption of construction; Malaysian authority on judicial power",see:["judicial-review","basic-structure","judicial-power"],aliases:["ouster clauses","ouster clause","ouster"]},{id:"overruling",term:"overruling",kind:"doctrine",gloss:"A superior court declaring an earlier decision in another case wrong.",intermediate:"When a court with the power to do so holds that a previous decision, in a different case, was wrongly decided and should no longer be followed.",advanced:"Only a court above the one that decided it can overrule — or, for the Federal Court, itself. Overruling is generally retrospective in effect, which is one reason apex courts do it rarely: it unsettles arrangements made on the faith of the earlier rule. It is routinely confused with reversing, which is a different act entirely.",source:"Standard common law doctrine",see:["reversing","stare-decisis"],aliases:["overruling","overruled","overrule"]},{id:"pc",term:"PC",kind:"institution",gloss:"Privy Council — the Judicial Committee in London.",intermediate:"A London court that used to hear final appeals from Malaysia. Appeals to it were abolished in stages and ended completely in 1985.",advanced:"Privy Council decisions on appeal from Malaya remain part of our law and are cited as such. Its decisions on appeal from elsewhere are persuasive only, so the jurisdiction an appeal came from is part of reading the citation.",source:"Former final appellate court for Malaysia",aliases:["PC"],see:["federal-court","ac"]},{id:"penal-code",term:"Penal Code",kind:"statute",gloss:"The statute defining offences and the general exceptions.",intermediate:"Malaysia's criminal code, derived from the Indian Penal Code. It defines each offence with its own elements and its own mental element.",advanced:"Because each offence carries its own fault requirement, the general common law vocabulary of actus reus and mens rea is less useful here than a common law training suggests — you reason from the section, not from a general theory. Section 6 makes every definition subject to the general exceptions in Chapter IV, which is why a homicide answer that never considers private defence has looked at half the picture.",source:"Penal Code (Act 574)",see:["general-exceptions","mens-rea","culpable-homicide"],aliases:["Penal Code"]},{id:"per-incuriam",term:"per incuriam",kind:"latin",gloss:"Decided in ignorance of a statute or binding case that would have changed the result.",intermediate:"A decision reached without the court being shown a provision or authority that would have altered the outcome. Such a decision does not bind.",advanced:"The doctrine is narrow on purpose. It is not available because the earlier reasoning was poor, or because a later court would have decided differently: the earlier court must have missed something it was obliged to apply, and the omission must have been capable of changing the result. Invoking it loosely is one of the more visible ways to signal that the hierarchy has not been understood.",source:"Standard common law doctrine",see:["stare-decisis","distinguishing"],aliases:["per incuriam"]},{id:"persuasive-authority",term:"persuasive authority",kind:"doctrine",gloss:"Anything a court may follow but need not.",intermediate:"Obiter dicta, decisions of coordinate or lower courts, foreign judgments, and academic writing. Weight depends on the source and the fit, not on any rule.",advanced:"In Malaysia the most heavily used persuasive material is English, Indian and Singaporean case law, and its weight turns on whether the statutory scheme is comparable. That qualification does the most work in codified subjects: an English contract case bears on a Malaysian problem only where the Contracts Act 1950 raises the same question, and citing one against the words of a section is worse than citing nothing.",source:"Standard common law doctrine",see:["binding-authority","obiter-dictum","codification"],aliases:["persuasive authority","persuasive"]},{id:"plaintiff",term:"plaintiff",kind:"doctrine",gloss:"The person who brings a civil claim.",intermediate:"The side that starts a civil case and asks the court for something. In a criminal case the equivalent side is the prosecution, and it is not called a plaintiff.",advanced:"The label decides who carries the burden: the plaintiff must prove the facts the claim depends on, so an evenly balanced case is one the plaintiff loses. Where proceedings begin by originating summons the equivalent party is the applicant.",source:"Rules of Court 2012",aliases:["plaintiff","plaintiffs"],see:["defendant"]},{id:"pleading",term:"pleading",kind:"doctrine",gloss:"The document setting out a party's case in material facts.",intermediate:"Plead material facts, not the evidence that will prove them and not the law. The pleadings define the issues the trial will decide.",advanced:"Some matters must be pleaded specifically — fraud, misrepresentation, breach of trust, and anything that would take the other side by surprise — and limitation is a defence that must be pleaded, because a court will not take the point for a defendant who has not. A case not pleaded is generally a case that cannot be run at trial.",source:"Rules of Court 2012 O 18",see:["material-fact","striking-out","limitation"],aliases:["statement of claim","pleadings","pleading"]},{id:"preamble",term:"preamble",kind:"doctrine",gloss:"The recital of purpose some Acts carry before the enacting words.",intermediate:"A statement, where one exists, of what the legislature was trying to achieve. It is admissible evidence of purpose.",advanced:"Most modern Malaysian Acts have no preamble and carry their purpose in the long title instead, so an argument that depends on one should first check that it exists. Where there is a preamble it may resolve an ambiguity but cannot cut down clear words in a section — the same limit that applies to the long title.",source:"Standard canon of construction",see:["long-title","purposive-approach","mischief-rule"],aliases:["preamble"]},{id:"presumption",term:"presumption",kind:"doctrine",gloss:"A direction about what the court may or must infer.",intermediate:"Section 4 distinguishes three: 'may presume' is a discretion, 'shall presume' is mandatory unless disproved, and 'conclusive proof' admits no evidence in rebuttal.",advanced:"The three are not interchangeable and the statute's choice of phrase is the whole of the answer to how much room the other side has. Statutory presumptions in drugs and corruption legislation are the practically significant ones, and they are commonly of the 'shall presume' kind, which is what makes them so onerous.",source:"Evidence Act 1950 s 4",see:["adverse-inference","legal-burden"],aliases:["conclusive proof","shall presume","may presume","presumption"]},{id:"presumption-retrospectivity",term:"presumption against retrospectivity",kind:"doctrine",gloss:"Statutes are presumed not to operate backwards.",intermediate:"A provision is read as applying to the future unless it clearly says otherwise, particularly where it affects vested rights or creates criminal liability.",advanced:"The presumption is strongest for substantive provisions and weakest for purely procedural ones, which are often applied to pending proceedings without anybody calling that retrospective. It is displaceable by clear words, and the real argument in a hard case is whether the words are clear enough — and whether the provision is substantive or procedural at all.",source:"Standard presumption of construction",see:["ouster-clause","mens-rea"],aliases:["presumption against retrospectivity","retrospectivity","retrospective"]},{id:"prima-facie",term:"prima facie",kind:"latin",gloss:"On the face of it — enough unless answered.",intermediate:"Used of evidence sufficient to establish a fact in the absence of contrary evidence, and of a case strong enough to require an answer.",advanced:"In criminal procedure it has the specific statutory sense under s 180 of the CPC. Outside that it is a general phrase, and using it loosely — 'there is a prima facie breach' — says only that the point is arguable, which is rarely what an answer needs to establish.",source:"Criminal Procedure Code s 180; general usage",see:["prima-facie-case"],aliases:["prima facie"]},{id:"prima-facie-case",term:"prima facie case",kind:"latin",gloss:"The standard at the close of the prosecution case.",intermediate:"Section 180 of the CPC: evidence which, if unrebutted, would warrant a conviction. If it is made out the accused is called to enter his defence; if not, he is acquitted.",advanced:"The court must undertake a maximum evaluation of the prosecution evidence — testing its credibility rather than merely noting that some evidence exists. The standard at the close of the defence is different and stricter: proof beyond reasonable doubt on the whole of the evidence, with the defence needing only to raise a reasonable doubt rather than to be believed.",source:"Criminal Procedure Code s 180",see:["maximum-evaluation","beyond-reasonable-doubt","criminal-procedure-code"],aliases:["prima facie case"]},{id:"private-defence",term:"private defence",kind:"doctrine",gloss:"The right to defend body or property, within limits.",intermediate:"Sections 96 to 106. The right does not extend to inflicting more harm than necessary, and s 100 sets out when defence of the body may extend to causing death.",advanced:"Section 99(3) removes the right where there is no reasonable apprehension of death or grievous hurt and there is time to have recourse to the public authorities. Exceeding the right does not simply lose it: Exception 2 to s 300 reduces murder to culpable homicide not amounting to murder where the accused exceeded the right in good faith and without premeditation, which is the difference between two very different sentencing regimes.",source:"Penal Code ss 96-106 and Exception 2 to s 300",see:["general-exceptions","culpable-homicide","murder"],aliases:["right of private defence","private defence"]},{id:"privity",term:"privity of contract",kind:"doctrine",gloss:"Only a party to a contract can sue on it.",intermediate:"A person who is not a party acquires no right to enforce the agreement, even if it was made for their benefit.",advanced:"Malaysian law keeps privity while relaxing consideration, and holding the two apart is what the s 2(d) point is really testing: consideration may come from a stranger, but a stranger still cannot sue. There is no Malaysian equivalent of the English Contracts (Rights of Third Parties) Act 1999, so the workarounds — agency, trust of a promise, assignment, collateral contract — carry the weight.",source:"Contracts Act 1950 s 2(d); Kepong Prospecting Ltd v Schmidt [1968] 1 MLJ 170 (PC)",see:["consideration"],aliases:["privity of contract","privity"]},{id:"procedural",term:"procedural",kind:"method",gloss:"About how a case is run, rather than who is right.",intermediate:"The machinery: which document starts a case, what the deadlines are, who must disclose what. Most civil disputes are decided on this rather than on the substantive law.",advanced:"Treating procedure as the boring administrative part is a mistake people make once. Limitation, striking out and summary judgment end more claims than trials do, and a procedural default is often unrecoverable where a weak case is not.",source:"Standard usage",aliases:["procedural"],see:["substantive"]},{id:"promise",term:"promise",kind:"doctrine",gloss:"A proposal that has been accepted.",intermediate:"Once one side proposes something and the other accepts it, the proposal becomes a promise. That is the building block the rest of contract sits on.",advanced:"The Act's vocabulary is deliberate: proposal and acceptance are the acts, promise is what they produce, and consideration is the price of the promise. Using English offer-and-acceptance language loosely obscures which step is in dispute.",source:"Contracts Act 1950 s 2",aliases:["promise","promises"],see:["acceptance","consideration"]},{id:"proportionality",term:"proportionality",kind:"doctrine",gloss:"Asking whether a restriction goes further than its purpose requires.",intermediate:"A test that examines whether a limit on a right is suitable, necessary, and balanced against what it achieves — rather than merely whether it falls within a permitted category.",advanced:"Its status in Malaysia is contested and should be stated as such: it has been accepted in the constitutional context, argued through Art 8(1), and its standing as a free-standing head of administrative review is a separate question that should be checked against current authority rather than assumed. An answer that applies it as settled law overstates the position; one that ignores it understates it.",source:"Sivarasa Rasiah v Badan Peguam Malaysia [2010] 2 MLJ 333 (FC); the Malaysian case law on Art 8(1)",see:["article-8","article-10","judicial-review","wednesbury"],aliases:["proportionality","proportionate"]},{id:"proposal",term:"proposal",kind:"doctrine",gloss:"What English law calls an offer.",intermediate:"Signifying to another your willingness to do or abstain from something, with a view to obtaining that other's assent. Section 2(a).",advanced:"The vocabulary matters because the Act uses proposal, acceptance and promisor throughout, and an answer written in the English vocabulary reads as though the Act had not been opened. A proposal must be distinguished from an invitation to treat, which is not a proposal at all and cannot be accepted into a contract.",source:"Contracts Act 1950 s 2(a)",see:["acceptance","revocation","communication-complete"],aliases:["proposal","proposer","offer"]},{id:"proprietor",term:"proprietor",kind:"doctrine",gloss:"The person named on the register as owner of land.",intermediate:"Whoever the land register says owns the land. Long occupation, family history and a document in a drawer do not make somebody the proprietor.",advanced:"The register is the title, so the proprietor is the owner even against someone with a better moral claim — subject to the exceptions in s 340(2), which is where fraud and forgery are argued.",source:"National Land Code",aliases:["proprietor","proprietors"],see:["indefeasibility","caveat"]},{id:"prosecution",term:"prosecution",kind:"doctrine",gloss:"The side bringing a criminal charge, in the name of the State.",intermediate:"The State's side of a criminal case. It must prove the offence beyond reasonable doubt, and it carries that burden from the first witness to the last.",advanced:"The power to institute, conduct and discontinue criminal proceedings belongs to the Public Prosecutor and is a constitutional discretion rather than an ordinary administrative one. A person who makes a police report does not thereby become the prosecutor.",source:"Federal Constitution Art 145(3); Criminal Procedure Code",aliases:["prosecution","prosecutions"],see:["accused"]},{id:"provision",term:"provision",kind:"doctrine",gloss:"A particular part of an Act — a section, subsection or paragraph.",intermediate:"One piece of a statute, small enough to quote. When you are asked what the law is, the answer usually starts by naming the provision.",advanced:"Read a provision in its place: the Part it sits in, the sections around it, and any definition section or proviso that qualifies it. A clause read alone is the commonest source of a confident wrong answer.",source:"Interpretation Acts 1948 and 1967",aliases:["provision","provisions"],see:["statute","interpretation"]},{id:"proviso",term:"proviso",kind:"doctrine",gloss:"A qualification attached to the provision it sits under.",intermediate:"A clause beginning 'Provided that…' which cuts down or excepts something from the rule stated immediately before it.",advanced:"A proviso is read with its principal provision, not as a free-standing rule, and it is generally construed as doing no more than its words require. The classic student error is to quote a sub-section and stop, having missed a proviso that qualifies precisely the situation in the facts.",source:"Standard canon of construction",see:["marginal-note","long-title"],aliases:["provisos","proviso"]},{id:"public-prosecutor",term:"Public Prosecutor",kind:"institution",gloss:"The office with control of all criminal prosecutions.",intermediate:"The Attorney General, acting as Public Prosecutor, has discretion under Article 145(3) to institute, conduct or discontinue any criminal proceedings.",advanced:"The consequence is that a prosecution is not the complainant's to withdraw: forgiveness may end a civil suit and does not end a charge, though in practice it may influence whether one is continued. The discretion is very broad and the grounds on which it can be reviewed are narrow, which is a recurring topic in administrative law answers.",source:"Federal Constitution Art 145(3)",see:["discharge-not-amounting","criminal-procedure-code"],aliases:["Public Prosecutor","Attorney General","Article 145(3)","PP"]},{id:"purposive-approach",term:"purposive approach",kind:"doctrine",gloss:"Prefer the reading that promotes the Act's purpose. In Malaysia this is statutory.",intermediate:"Where a provision can bear more than one meaning, the court prefers the one that advances the object underlying the Act. Section 17A of the Interpretation Acts 1948 and 1967 makes this a direction, not a choice.",advanced:"Section 17A operates on constructions the words can bear; it does not authorise a reading the language cannot support, and it does not licence rewriting a provision that admits of only one meaning. The practical consequence for an answer is an order of work: show the words are capable of two readings, then use purpose to choose. Starting at purpose is the most common error in the subject, and it comes from working out of English textbooks written before any equivalent direction existed there.",source:"Interpretation Acts 1948 and 1967, s 17A",see:["literal-rule","mischief-rule","section-17a"],aliases:["purposive construction","purposive approach","purposive"]},{id:"qualified-privilege",term:"qualified privilege",kind:"doctrine",gloss:"A protected occasion, defeated by malice.",intermediate:"Where the maker of a statement has a duty or interest in making it and the recipient a corresponding interest in receiving it, the statement is protected unless malice is shown.",advanced:"Reciprocity is the requirement people forget: a duty to speak is not enough without a corresponding interest in the listener. Whether the Reynolds line of responsible-journalism privilege forms part of Malaysian law has been argued here and should not be assumed either way — if an answer needs it, it needs a Malaysian citation.",source:"Standard common law; the Malaysian authorities on privilege",see:["absolute-privilege","malice","defamation"],aliases:["qualified privilege"]},{id:"quantum-meruit",term:"quantum meruit",kind:"latin",gloss:"As much as it is worth — payment for value conferred.",intermediate:"A claim for reasonable remuneration where work has been done but no price is fixed by an enforceable contract.",advanced:"It sits partly in contract, where the parties simply left the price open, and partly in restitution, where the contract was void, discharged or never formed. In Malaysia the restitutionary side is largely handled by ss 65, 66 and 71 of the Contracts Act rather than by an unwritten law of unjust enrichment, so the section should be identified rather than the label used alone.",source:"Contracts Act 1950 ss 66 and 71",see:["section-66","void"],aliases:["quantum meruit"]},{id:"ratio-decidendi",term:"ratio decidendi",kind:"latin",gloss:"The rule the decision actually rests on — the binding part.",intermediate:"The proposition of law a court applied to the material facts in order to reach its result. Everything else in the judgment, however well written, is not binding.",advanced:"The test is necessity, not emphasis: if the outcome would stand without the proposition, it is not ratio. The hard part is not identifying it but stating it at the right level of generality — too narrow and it governs no later case, too broad and you have made the court decide something it did not. Where several judgments are given, the ratio is what commanded a majority, which may be narrower than any single judgment.",source:"Standard common law doctrine",see:["obiter-dictum","stare-decisis","distinguishing","material-fact"],aliases:["ratio decidendi","ratio"]},{id:"reception",term:"reception of English law",kind:"doctrine",gloss:"How and how far English law became part of Malaysian law.",intermediate:"By statute, to fixed dates, subject to local circumstances and displaced by local legislation. It is not a general rule that English law applies.",advanced:"The practical test in an answer is whether a Malaysian statute occupies the field. Contract, criminal law and evidence are codified, so the starting point is the Act and English cases are illustration at most; land is governed by the Code with English land law expressly excluded. Where nothing local governs — much of tort — received common law does the work.",source:"Civil Law Act 1956 s 3(1)",see:["civil-law-act","codification","persuasive-authority"],aliases:["reception of English law","reception"]},{id:"reflective-loss",term:"reflective loss",kind:"doctrine",gloss:"A fall in share value that merely mirrors the company's loss.",intermediate:"Where a wrong to the company reduces the value of every member's shares, the claim belongs to the company and a member cannot sue for the diminution personally.",advanced:"The rule prevents double recovery and preserves the priority of the company's creditors. Its practical effect is to force an unhappy member into the derivative action or the oppression petition, which is why identifying whose loss it is comes before choosing a remedy.",source:"Standard company law; Companies Act 2016 ss 346-350",see:["derivative-action","oppression","separate-legal-personality"],aliases:["reflective loss"]},{id:"registration",term:"registration",kind:"doctrine",gloss:"Entering a dealing or a body on an official register.",intermediate:"The formal step that makes something official. For land it is the moment ownership passes; for a company it is the moment the company exists as a person.",advanced:"Under the National Land Code registration is what creates title rather than merely recording it, which is why a signed agreement leaves the buyer with contractual rights and no title until the transfer is registered.",source:"National Land Code; Companies Act 2016",aliases:["registration"],see:["indefeasibility"]},{id:"relevancy",term:"relevancy",kind:"doctrine",gloss:"The gate: a fact is admissible only because a section makes it relevant.",intermediate:"Sections 6 to 55 declare categories of relevant fact — same transaction, cause or effect, motive and conduct, admissions and confessions, statements of persons who cannot be called, and others.",advanced:"Relevancy under the Act is a legal category, not a measure of probative value, so evidence can be plainly probative and still inadmissible because no section reaches it. Keep it separate from burden: first ask whether the evidence goes in under a named section, then ask who has to prove what and to what standard.",source:"Evidence Act 1950 ss 5-55",see:["evidence-act","admissibility","fact-in-issue"],aliases:["relevant fact","relevancy","relevant"]},{id:"remand",term:"remand",kind:"doctrine",gloss:"Detention authorised by a Magistrate for the purpose of investigation.",intermediate:"An arrested person may not be held beyond twenty-four hours without a Magistrate's order under s 117 of the CPC. The maximum periods are graduated by the sentence the offence carries.",advanced:"The twenty-four hour limit is constitutional, in Art 5(4), not merely statutory. A remand hearing is a real hearing: the police must show why further detention is needed, and the Magistrate sets the period thought fit within the statutory maximum. Those maxima have been amended, so they should be taken from the current text.",source:"Criminal Procedure Code s 117; Federal Constitution Art 5(4)",see:["arrest","article-5","criminal-procedure-code"],aliases:["remand"]},{id:"remedy",term:"remedy",kind:"doctrine",gloss:"What a court can actually give you.",intermediate:"The thing you are asking the court for: money, an order to do something, an order to stop, or a statement of where the parties stand. A right with no remedy attached is of little practical use.",advanced:"Ask what remedy the client wants before choosing the cause of action, because remedies differ in availability: damages are as of right once liability is shown, while specific performance and injunctions are discretionary and equitable.",source:"Standard common law",aliases:["remedy","remedies"],see:["damages"]},{id:"remoteness",term:"remoteness",kind:"doctrine",gloss:"Liability only for damage of a foreseeable kind.",intermediate:"The kind of damage must be reasonably foreseeable; the precise manner of its occurrence and its extent need not be.",advanced:"The eggshell skull principle sits inside this rather than beside it: foreseeability governs the type of injury, and the claimant's particular susceptibility governs how bad it turns out to be without reducing the claim. In contract the equivalent limit is s 74 of the Contracts Act, and the two should not be run together — the contractual test looks at what the parties contemplated when contracting.",source:"The Wagon Mound (No 1) [1961] AC 388; Contracts Act 1950 s 74 for the contractual analogue",see:["causation","eggshell-skull","section-74"],aliases:["remoteness","too remote"]},{id:"repudiation",term:"repudiation",kind:"doctrine",gloss:"Conduct showing an intention no longer to be bound.",intermediate:"A refusal to perform, or disabling oneself from performing, in a way that entitles the innocent party to treat the contract as at an end.",advanced:"It puts the innocent party to an election: terminate and sue, or affirm and keep the contract alive. The election must be made within a reasonable time and once made is irrevocable, and affirming means the contract remains on foot for both parties — including any obligations the affirming party would rather not perform.",source:"Contracts Act 1950 s 40",see:["breach","affirmation"],aliases:["repudiation","repudiated","repudiate"]},{id:"res-ipsa-loquitur",term:"res ipsa loquitur",kind:"latin",gloss:"The thing speaks for itself.",intermediate:"Where an accident is of a kind that does not ordinarily happen without negligence, and the thing was under the defendant's control, the court may infer negligence.",advanced:"It is an evidential aid rather than a rule of law, and its effect is contested: on the better view it permits an inference rather than reversing the legal burden. A defendant answers it by showing how the accident happened without negligence, or that reasonable care was in fact taken.",source:"Standard common law",see:["negligence","breach-of-duty","legal-burden"],aliases:["res ipsa loquitur"]},{id:"res-judicata",term:"res judicata",kind:"latin",gloss:"A matter already decided cannot be litigated again.",intermediate:"Once a court of competent jurisdiction has finally determined an issue between the parties, neither may reopen it in later proceedings.",advanced:"It covers both the cause of action and, in its issue estoppel form, particular issues necessarily decided. The related doctrine in Henderson v Henderson extends it to points that could and should have been raised in the earlier proceedings, which is why splitting a case across two actions is dangerous.",source:"Standard common law; Evidence Act 1950 ss 40-43",see:["cause-of-action","pleading"],aliases:["res judicata"]},{id:"rescission",term:"rescission",kind:"doctrine",gloss:"Unwinding a contract and putting the parties back where they were.",intermediate:"The remedy that follows avoidance of a voidable contract: the contract is treated as at an end and benefits are restored.",advanced:"It is barred where restitutio in integrum is impossible, where the innocent party has affirmed, after undue delay, or where third-party rights have intervened. Section 65 of the Contracts Act deals with the consequences of rescission, and s 66 with restoration of advantages under agreements discovered to be void.",source:"Contracts Act 1950 ss 65 and 66",see:["voidable","section-66","misrepresentation"],aliases:["rescission","rescind"]},{id:"resolution",term:"resolution",kind:"doctrine",gloss:"A decision formally passed at a meeting.",intermediate:"A decision taken by a vote — of the members, or of the board. How many votes it needs depends on which kind of resolution it is.",advanced:"Procedure is not a formality here: notice, quorum and the majority required are conditions of validity, and an irregularity may either be curable or invalidate the resolution outright. Which of the two it is turns on whether the requirement protects the company or the individual member.",source:"Companies Act 2016",aliases:["resolution","resolutions"],see:["shareholder","director"]},{id:"respondent",term:"respondent",kind:"doctrine",gloss:"The party answering an appeal or an application.",intermediate:"The side defending the decision on appeal, or answering an application. Which side that is depends on who lost below.",advanced:"Also the answering party in proceedings begun by originating summons, and in judicial review, where the respondent is the public body whose decision is challenged.",source:"Courts of Judicature Act 1964; Rules of Court 2012",aliases:["respondent","respondents"],see:["appellant","judicial-review"]},{id:"retrieval-practice",term:"retrieval practice",kind:"method",gloss:"Trying to recall, and checking — the thing that actually builds memory.",intermediate:"Attempting to produce an answer from memory, then verifying it. It beats re-reading by a wide margin, even when the attempt fails.",advanced:"The counter-intuitive part is that difficulty is the mechanism, not a side effect: a struggle that ends in a correct check does more than a fluent pass over the text. Fluency during study is a poor guide to later recall, which is why revision that feels smooth should be treated with suspicion.",source:"Make It Stick; the retrieval practice literature",see:["spacing","interleaving"],aliases:["retrieval practice","retrieval"]},{id:"reversing",term:"reversing",kind:"doctrine",gloss:"An appeal court setting aside the decision below in the same case.",intermediate:"What happens when an appeal succeeds: the higher court substitutes its own outcome for the one reached below, in the very same proceedings.",advanced:"Reversing operates on the parties before the court; overruling operates on the law for everybody. A decision can be reversed on appeal without any point of law being overruled — the appeal court may simply take a different view of the facts or the exercise of a discretion.",source:"Standard common law doctrine",see:["overruling"],aliases:["reversing","reversed","reverse"]},{id:"revocation",term:"revocation",kind:"doctrine",gloss:"Withdrawing a proposal before it is accepted.",intermediate:"A proposal may be revoked at any time before communication of its acceptance is complete as against the proposer, but not afterwards. Section 5(1).",advanced:"Because the cut-off is the moment fixed by s 4(2)(a), a posted acceptance can beat a revocation that was posted first. A promise to hold an offer open is not binding without consideration, which means the proposer could have revoked in time — not that they did, and checking the timing under ss 4 and 5 comes before any of that.",source:"Contracts Act 1950 ss 5(1) and 4",see:["acceptance","communication-complete","consideration"],aliases:["revocation","revoked","revoke"]},{id:"rules-of-court",term:"Rules of Court 2012",kind:"statute",gloss:"The rules governing civil proceedings in the High Court and subordinate courts.",intermediate:"They set out how an action is begun, pleaded, disposed of before trial, tried and enforced — Order by Order.",advanced:"Procedure is not administrative detail: most civil cases end on an interlocutory application rather than at trial, so the Orders governing summary judgment, striking out and injunctions decide more disputes than the substantive law does. Order 53 is the judicial review procedure and is the one most likely to be missed in a public law answer.",source:"Rules of Court 2012",see:["summary-judgment","striking-out","interlocutory-injunction","order-53"],aliases:["Rules of Court 2012","Rules of Court"]},{id:"sc-india",term:"SC",kind:"institution",gloss:"Supreme Court — in Indian citations, India's highest court.",intermediate:"In a citation like AIR 1958 SC 465, SC is the Supreme Court of India. Malaysia had a Supreme Court too, between 1985 and 1994, before it became the Federal Court.",advanced:"Read the series before the court abbreviation: AIR points to India, so SC there is not a Malaysian court. Malaysian decisions from 1985 to 1994 cite the Supreme Court as our own apex, which is the same institution the Federal Court now is.",source:"Indian and former Malaysian court hierarchies",aliases:["SC"],see:["air","federal-court"]},{id:"section-10",term:"section 10",kind:"statute",gloss:"Contracts Act 1950 s 10 — what turns an agreement into a contract.",intermediate:"Four requirements: free consent, parties competent to contract, a lawful consideration and a lawful object. Fail any one and there is no contract.",advanced:"Each limb opens onto its own body of law — consent onto the vitiating factors in s 14, capacity onto s 11, lawful object onto s 24. An answer asserting a contract exists without naming the limb in issue has skipped the analysis.",source:"Contracts Act 1950 s 10",aliases:["section 10","s 10"],see:["contract","section-24"]},{id:"section-101",term:"section 101",kind:"statute",gloss:"Evidence Act 1950 s 101 — whoever asserts must prove.",intermediate:"Anyone who wants the court to give judgment on a right that depends on facts must prove those facts. If neither side calls evidence, the person asserting loses.",advanced:"Read with s 102, which asks who would fail if no evidence at all were given — a practical test for locating the legal burden. Section 103 then puts the burden on any particular fact on the person who wants the court to believe it.",source:"Evidence Act 1950 s 101",aliases:["section 101","s 101"],see:["section-102","evidence"]},{id:"section-102",term:"section 102",kind:"statute",gloss:"Evidence Act 1950 s 102 — on whom the burden lies.",intermediate:"The burden sits with the person who would fail if no evidence were given on either side. Picture an empty trial and ask who walks out disappointed.",advanced:"Sections 101 and 102 describe the legal burden, which does not move. The evidential burden — the practical need to answer now — shifts back and forth and is a different thing; saying only that 'the burden shifted' hides which one you mean.",source:"Evidence Act 1950 s 102",aliases:["section 102","s 102"],see:["section-101"]},{id:"section-105",term:"section 105",kind:"statute",gloss:"The accused must prove a general exception.",intermediate:"Where an accused relies on a general exception in the Penal Code, or a special exception or proviso in the law defining the offence, the burden of proving the circumstances is on him and the court presumes their absence.",advanced:"This is a genuine legal burden, discharged on the balance of probabilities — not merely an evidential one, and not the English position on many defences. An answer that says the accused must 'raise' the exception and the prosecution must then disprove it beyond reasonable doubt has stated the wrong rule for this jurisdiction.",source:"Evidence Act 1950 s 105",see:["general-exceptions","legal-burden","balance-of-probabilities"],aliases:["section 105","s 105"]},{id:"section-106",term:"section 106",kind:"statute",gloss:"A fact especially within a person's knowledge is for him to prove.",intermediate:"Where a fact is especially within the knowledge of any person, the burden of proving that fact is upon him.",advanced:"The most over-used provision in the Act. It reaches a specific fact peculiarly within someone's knowledge — a licence, an authority, a reason for being somewhere — and cannot be used to reverse the general burden or to relieve the prosecution of proving its case. Deploying it to shift the whole case is a misreading that is easy for a marker to spot.",source:"Evidence Act 1950 s 106",see:["legal-burden","section-105"],aliases:["section 106","s 106"]},{id:"section-117",term:"section 117",kind:"statute",gloss:"Criminal Procedure Code s 117 — remand beyond twenty-four hours.",intermediate:"Detention past the first twenty-four hours needs a Magistrate's order, made for the investigation and for the period the Magistrate thinks fit. The police cannot extend it themselves.",advanced:"The hearing is short and often in a small room, and it is meant to be a real check rather than a formality: the investigating officer must say why more time is needed, and the person arrested may be heard.",source:"Criminal Procedure Code s 117",aliases:["section 117","s 117"],see:["article-5","accused"]},{id:"section-17a",term:"section 17A",kind:"statute",gloss:"The provision making the purposive approach statutory in Malaysia.",intermediate:"Interpretation Acts 1948 and 1967 s 17A: a construction promoting the purpose or object underlying the Act is to be preferred to one that does not.",advanced:"Its existence is why the English hierarchy of literal, golden and mischief rules is a description of tools rather than a sequence to be worked through here. The older rules survive as ways of getting at meaning — the mischief rule in particular is s 17A's closest ancestor — but the starting point is the section, and an argument that never reaches it has skipped the governing provision.",source:"Interpretation Acts 1948 and 1967, s 17A",see:["purposive-approach","mischief-rule"],aliases:["section 17A","s 17A","17A"]},{id:"section-2-contracts",term:"section 2",kind:"statute",gloss:"Contracts Act 1950 s 2 — the definitions the whole Act runs on.",intermediate:"Where proposal, acceptance, promise, agreement and consideration are each defined. Contract questions start here, because the Act's vocabulary is not the English one.",advanced:"The steps are deliberate: s 2(a) proposal, 2(b) acceptance turning it into a promise, 2(d) consideration, 2(e) agreement. Naming which step is in dispute is most of a formation answer, and s 2(d) is what lets past consideration count here where English law would not.",source:"Contracts Act 1950 s 2",aliases:["section 2","s 2"],see:["contract","consideration","promise"]},{id:"section-213",term:"section 213",kind:"statute",gloss:"Companies Act 2016 s 213 — the core duties of a director.",intermediate:"Two duties. Under 213(1) a director must exercise powers for a proper purpose and in good faith in the best interest of the company. Under 213(2) they must exercise reasonable care, skill and diligence.",advanced:"The care standard has a floor set by the office and rises for a director who happens to know more, so an accountant on the board is held higher. The duty is owed to the company, not to individual shareholders, which decides who may sue.",source:"Companies Act 2016 s 213",aliases:["section 213","s 213"],see:["director","company"]},{id:"section-24",term:"section 24",kind:"statute",gloss:"Contracts Act 1950 s 24 — when consideration or object is unlawful.",intermediate:"Lists what makes the price or the purpose of a deal unlawful: forbidden by law, defeating any law, fraudulent, injurious to person or property, or immoral or against public policy. If it falls in, the whole agreement is void.",advanced:"Do not reach for illegality as one general doctrine. Section 24 sets out categories and s 25 deals with an agreement only partly unlawful, so the analysis is which category and what survives, not whether the court disapproves.",source:"Contracts Act 1950 s 24",aliases:["section 24","s 24"],see:["section-10","void"]},{id:"section-26",term:"section 26",kind:"statute",gloss:"Agreements without consideration are void — with three exceptions.",intermediate:"The exceptions are (a) writing and registration, natural love and affection, parties in a near relation; (b) a promise to compensate a past voluntary act done for the promisor; and (c) a written, signed promise to pay a time-barred debt.",advanced:"Limb (a) is the one most often stated incompletely: writing alone is not enough, registration is required too. Limb (b) is the safe route for the spontaneous good turn, and limb (c) needs a debt actually barred by limitation rather than merely unpaid. Because the Act supplies a formality, reaching for intention to create legal relations instead is the wrong answer even when it produces the right outcome.",source:"Contracts Act 1950 s 26",see:["consideration","limitation"],aliases:["section 26","s 26"]},{id:"section-3-cla",term:"section 3",kind:"statute",gloss:"Civil Law Act 1956 s 3 — the reception of English law.",intermediate:"Malaysian courts apply English common law and equity as they stood at stated cut-off dates, and only so far as local circumstances permit. It is a limited reception, not an open door.",advanced:"Two limits do the work: the date, which freezes what was received, and the local-circumstances proviso, which lets a court decline an English rule that does not suit. Later English decisions are persuasive only, and citing one as though it were binding is the standard error.",source:"Civil Law Act 1956 s 3",aliases:["section 3","s 3"],see:["statute"]},{id:"section-300",term:"section 300",kind:"statute",gloss:"Penal Code s 300 — when culpable homicide is murder.",intermediate:"Sets out the four limbs that raise culpable homicide to murder, and the Exceptions that bring it back down. Establish culpable homicide under s 299 first.",advanced:"Going straight to s 300 because someone died inverts the structure and usually picks the wrong limb. Section 300(c) is close to a rule rather than a standard: did you intend the injury, and would an injury like that normally kill.",source:"Penal Code s 300",aliases:["section 300","s 300"],see:["section-6-penal","offence"]},{id:"section-340",term:"section 340",kind:"statute",gloss:"National Land Code s 340 — indefeasibility of registered title.",intermediate:"Registered title is indefeasible, subject to the exceptions in s 340(2) — fraud, forgery and an instrument that was void or insufficient. The register is the title, not merely evidence of it.",advanced:"Whether a purchaser from a forger takes good title is the immediate-versus-deferred question. Adorna Properties read it as immediate for nine years; Tan Ying Hong departed from that in 2010 and restored deferred indefeasibility.",source:"National Land Code s 340",aliases:["section 340","s 340"],see:["indefeasibility","proprietor"]},{id:"section-415",term:"section 415",kind:"statute",gloss:"Penal Code s 415 — cheating.",intermediate:"Delivery of property induced by deception. What separates it from theft and criminal breach of trust is how possession was obtained: never given, given lawfully, or given by a trick.",advanced:"Ask the possession question before naming the offence. Theft under s 378 is property moved out of possession without consent; criminal breach of trust under s 405 is property entrusted and then misappropriated; cheating is consent obtained by deception.",source:"Penal Code s 415",aliases:["section 415","s 415"],see:["offence"]},{id:"section-6-penal",term:"section 6",kind:"statute",gloss:"Penal Code s 6 — every offence is read with the General Exceptions.",intermediate:"Every definition of an offence in the Code is understood subject to the General Exceptions, even though the section defining the offence never mentions them.",advanced:"This is why a homicide answer that discusses only the Exceptions to s 300 has looked at half the picture. Sections 76 to 106 apply to every offence in the Code, and private defence lives there rather than in the offence sections.",source:"Penal Code s 6",aliases:["section 6","s 6"],see:["section-300","offence"]},{id:"section-66",term:"section 66",kind:"statute",gloss:"Restore the advantage received under a void agreement.",intermediate:"A person who has received any advantage under an agreement discovered to be void, or under a contract that becomes void, must restore it or make compensation.",advanced:"It does the work an English lawyer would look for in the law of restitution, and it is the provision to reach for when an answer has concluded that an agreement is void and stopped there. It applies both to agreements void from the outset and to contracts that become void, for example on frustration under s 57.",source:"Contracts Act 1950 s 66",see:["void","frustration","rescission"],aliases:["section 66","s 66"]},{id:"section-74",term:"section 74",kind:"statute",gloss:"The measure of damages for breach.",intermediate:"Compensation for loss arising naturally in the usual course of things from the breach, or which the parties knew when contracting to be likely to result. Remote and indirect loss is excluded.",advanced:"This is the rule in Hadley v Baxendale enacted, which changes how it is argued: the starting point is the section's words and the English cases illustrate how the two limbs have been applied. The explanation to s 74 requires the means available for remedying the inconvenience to be taken into account, which is the statutory foothold for mitigation.",source:"Contracts Act 1950 s 74; Hadley v Baxendale (1854) 9 Exch 341",see:["section-75","remoteness","mitigation","breach"],aliases:["section 74","s 74"]},{id:"section-75",term:"section 75",kind:"statute",gloss:"A sum named in the contract as payable on breach.",intermediate:"Reasonable compensation not exceeding the sum named, whether or not actual damage is proved to have been caused.",advanced:"The Malaysian position has moved. Selva Kumar required proof of actual loss and treated the named sum as a ceiling; Cubic Electronics reformulated the approach, drawing on Cavendish v Makdessi and directing attention to whether the clause protects a legitimate interest and whether the sum is out of all proportion to it. An answer giving only one of the two has not shown that it knows the position changed — and this is the most movable point in the contract module.",source:"Contracts Act 1950 s 75; Selva Kumar a/l Murugiah v Thiagarajah a/l Retnasamy [1995] 1 MLJ 817 (FC); Cubic Electronics Sdn Bhd v Mars Telecommunications Sdn Bhd [2019] 2 MLJ 806 (FC)",see:["section-74","liquidated-damages","legitimate-interest"],aliases:["section 75","s 75"]},{id:"section-99",term:"section 99",kind:"statute",gloss:"Penal Code s 99 — the outer limits of private defence.",intermediate:"Says when there is no right of private defence at all, and how far the right can ever go. If there was time to go to the authorities and no reasonable fear of death or grievous hurt, the right does not arise.",advanced:"Excess does not destroy a right that existed; it goes to whether the right extended this far. Answering those two questions in the wrong order is the commonest error in this area, and s 100 is where the right extends to causing death.",source:"Penal Code s 99",aliases:["section 99","s 99"],see:["section-6-penal"]},{id:"seizable",term:"seizable offence",kind:"doctrine",gloss:"An offence for which police may arrest without a warrant.",intermediate:"The Malaysian term for what English law calls an arrestable offence. Classification is done offence by offence in the First Schedule to the CPC.",advanced:"Using the English vocabulary signals that the answer is being written out of an English textbook, and the underlying scheme is not the same. A non-seizable offence generally requires a warrant or a summons, which changes the lawfulness of an arrest and therefore whether resisting it was an offence at all.",source:"Criminal Procedure Code, First Schedule",see:["criminal-procedure-code","bailable","arrest"],aliases:["seizable offence","non-seizable","seizable"]},{id:"separate-legal-personality",term:"separate legal personality",kind:"doctrine",gloss:"A company is a person in law, distinct from its members.",intermediate:"It owns its own property, makes its own contracts, sues and is sued in its own name, and its members are not liable for its obligations by reason only of membership.",advanced:"Everything else in company law follows from this: limited liability, the rule that a wrong to the company is the company's to complain of, and the concept of reflective loss. Salomon establishes that it holds even where one person owns and controls the whole company, and control alone is never a reason to disregard it.",source:"Companies Act 2016; Salomon v A Salomon & Co Ltd [1897] AC 22",see:["corporate-veil","reflective-loss","companies-act"],aliases:["separate legal personality","legal personality"]},{id:"sessions-court",term:"Sessions Court",kind:"institution",gloss:"A subordinate court with a substantial civil limit and wide criminal jurisdiction.",intermediate:"Above the Magistrates' Court. It tries all offences except those punishable with death, and civil claims up to a statutory monetary limit.",advanced:"The monetary limits are statutory figures raised periodically, so they should be cited from a current source rather than remembered — a stale figure is the fastest way to be confidently wrong. On the criminal side the significant limit is the death penalty: a capital charge goes to the High Court.",source:"Subordinate Courts Act 1948",see:["magistrates-court","high-court","subordinate-courts"],aliases:["Sessions Court"]},{id:"shareholder",term:"shareholder",kind:"doctrine",gloss:"A person who owns shares in a company.",intermediate:"Someone who owns part of the company. They own shares — not the things the company owns — and they cannot hand the directors instructions.",advanced:"Also called a member. The distinction matters for who may sue: a wrong done to the company is the company's to complain of, and a fall in the value of every member's shares is reflective of that loss rather than a loss of their own.",source:"Companies Act 2016",aliases:["shareholder","shareholders"],see:["director","company"]},{id:"slander",term:"slander",kind:"doctrine",gloss:"Defamation in transient form.",intermediate:"Spoken defamation, generally actionable only on proof of special damage — with statutory exceptions that dispense with that requirement.",advanced:"The Defamation Act 1957 preserves and modifies the exceptions: words imputing unchastity or adultery to a woman or girl, and words calculated to disparage a person in an office, profession, calling, trade or business held at the time of publication, are actionable without special damage. Those categories carry the practical weight, because most slander claims fall inside one.",source:"Defamation Act 1957 ss 4 and 5",see:["libel","defamation"],aliases:["slander"]},{id:"spacing",term:"spacing",kind:"method",gloss:"Reviewing at growing intervals rather than in a block.",intermediate:"Distributing study over time so that each review happens as the memory begins to fade. This is what FSRS schedules for you.",advanced:"Intervals lengthen because each successful recall makes the trace more durable, so the optimal moment to test it again moves further out. Massed practice produces better performance during the session and worse retention after it, which is why a study method judged by how it feels will reliably pick the wrong one.",source:"Make It Stick; FSRS",see:["retrieval-practice","interleaving","fsrs"],aliases:["spacing","spaced"]},{id:"specific-performance",term:"specific performance",kind:"doctrine",gloss:"An order compelling actual performance rather than damages.",intermediate:"A discretionary remedy governed by the Specific Relief Act 1950, not the Contracts Act. Section 11 sets out when it may be granted, s 20 when it may not.",advanced:"The gateway is the adequacy of damages, which is why it is a live remedy in a sale of land — each parcel being treated as unique — and rare for ordinary goods. Contracts requiring continuous supervision, and contracts for personal service, are outside it. Answering a specific performance question out of the Contracts Act is a category error.",source:"Specific Relief Act 1950 ss 11 and 20",see:["interlocutory-injunction","breach","section-74"],aliases:["specific performance"]},{id:"ssm",term:"SSM",kind:"institution",gloss:"Companies Commission of Malaysia.",intermediate:"The body you register a company with, and where company records are filed. Suruhanjaya Syarikat Malaysia is the Malay name the initials come from.",advanced:"Registration with SSM is the moment the company begins to exist as a separate person. Its filed records are also where a searcher establishes who the directors and shareholders actually are.",source:"Companies Act 2016",aliases:["SSM"],see:["company","registration"]},{id:"stare-decisis",term:"stare decisis",kind:"latin",gloss:"Stand by what has been decided: a court is bound by the courts above it.",intermediate:"The doctrine that a court must follow the decisions of courts above it in the same hierarchy on the same point of law. It is what makes the law predictable enough to advise on.",advanced:"Three things have to line up before a decision binds: the same hierarchy, a superior court, and the same point of law. Malaysian courts sit in one hierarchy topped by the Federal Court, and decisions of foreign courts — including English ones — are never binding however eminent. The Federal Court may depart from its own previous decisions but does so sparingly and with reasons.",source:"Standard common law doctrine",see:["ratio-decidendi","binding-authority","per-incuriam"],aliases:["stare decisis"]},{id:"derivative-action",term:"statutory derivative action",kind:"doctrine",gloss:"A member suing on the company's behalf, with leave.",intermediate:"Sections 347 to 350: a member, director or the Registrar may with leave of the court bring proceedings on behalf of the company to enforce the company's own right.",advanced:"Leave requires good faith and that the action is prima facie in the company's best interest, with notice to the company. It exists because a wrong to the company is the company's to complain of and the wrongdoers may control the board — the problem the old rule in Foss v Harbottle created and the statutory action solves.",source:"Companies Act 2016 ss 347-350",see:["oppression","reflective-loss","separate-legal-personality"],aliases:["statutory derivative action","derivative action"]},{id:"srs",term:"SRS",kind:"method",gloss:"Spaced repetition system.",intermediate:"Software that schedules review at growing gaps, so you meet a card just as it starts to fade. This app uses one.",advanced:"An SRS trains recognition and recall of things you have already understood. It cannot teach reasoning, which is why the problem questions and the checkpoint blocks exist alongside it.",source:"Standard study-method usage",aliases:["SRS"],see:["fsrs","spacing"]},{id:"statute",term:"statute",kind:"doctrine",gloss:"A law made by a legislature.",intermediate:"An Act passed by Parliament or a State Legislature. A statute is the law itself; a case is evidence of what it means.",advanced:"Research runs in that order for a reason: find the Act, read the section, check it is the current reprint and that any amendment is in force, and only then look for cases. An answer that reasons from a case without naming the provision it construes has started in the middle.",source:"Interpretation Acts 1948 and 1967",aliases:["statute","statutes","statutory"],see:["provision","enactment"]},{id:"strict-liability",term:"strict liability",kind:"doctrine",gloss:"An offence needing no proof of a mental element.",intermediate:"Liability that attaches on proof of the prohibited act alone. It is the exception: the law presumes an offence requires a mental element unless the statute displaces it.",advanced:"The presumption is displaced expressly or by necessary implication, and courts look at the subject matter, the penalty, and whether requiring fault would frustrate the statute's purpose — regulatory offences with small penalties are the usual candidates. Even where the offence is strict, a defence of reasonable mistake of fact may survive, and the general exceptions in Chapter IV of the Penal Code continue to apply to offences under it.",source:"Standard presumption of construction; Penal Code s 6",see:["mens-rea","penal-code","general-exceptions"],aliases:["strict liability"]},{id:"striking-out",term:"striking out",kind:"doctrine",gloss:"Removing a pleading that is bad as a document.",intermediate:"Order 18 rule 19: no reasonable cause of action or defence, scandalous or vexatious, prejudicial or embarrassing, or otherwise an abuse of process.",advanced:"On the first ground no evidence is admissible: the pleaded facts are assumed true and the question is whether they disclose a case. That is what separates it from summary judgment, which looks at the evidence. The jurisdiction is used sparingly and only in plain and obvious cases, and a difficult point of law is not by itself a reason to strike out.",source:"Rules of Court 2012 O 18 r 19",see:["summary-judgment","pleading"],aliases:["Order 18 rule 19","striking out","strike out"]},{id:"subordinate-courts",term:"subordinate courts",kind:"institution",gloss:"The Sessions and Magistrates' Courts.",intermediate:"The lower tier of the ordinary civil and criminal hierarchy, created by the Subordinate Courts Act 1948 rather than by the Courts of Judicature Act.",advanced:"The two statutes are the quickest way to keep the hierarchy straight: Courts of Judicature Act 1964 for the superior courts, Subordinate Courts Act 1948 for these. Their jurisdiction is entirely statutory, so a question about what one of them can do is always answered from the Act rather than from any inherent power.",source:"Subordinate Courts Act 1948",see:["sessions-court","magistrates-court","high-court"],aliases:["subordinate courts","subordinate court"]},{id:"subsidiary-legislation",term:"subsidiary legislation",kind:"doctrine",gloss:"Law made under power delegated by an Act.",intermediate:"Rules, regulations, orders and by-laws made by a minister or other body under authority conferred by a parent Act. Valid only within the powers the parent confers.",advanced:"This is where the operative detail usually lives, and a research answer that reads the Act and stops has often missed the provision that decides the case. Its validity is always a question about the grant of power in the parent Act, which makes ultra vires the standard line of attack.",source:"Interpretation Acts 1948 and 1967",see:["ultra-vires","legislative-competence"],aliases:["subsidiary legislation","delegated legislation"]},{id:"substantive",term:"substantive",kind:"method",gloss:"About what the rights and duties are, rather than how they are enforced.",intermediate:"The part of law that says who owes what to whom. Contract and tort are substantive; the rules about filing and deadlines are not.",advanced:"The line matters for more than tidiness. Procedure is generally the law of the forum, and a change in procedure can apply to existing cases in a way a change in substantive rights usually cannot.",source:"Standard usage",aliases:["substantive"],see:["procedural"]},{id:"summary-judgment",term:"summary judgment",kind:"doctrine",gloss:"Judgment without trial where there is no triable issue.",intermediate:"Order 14. The plaintiff says the defence is hopeless; the defendant resists by showing an issue that ought to be tried, or some other reason for a trial.",advanced:"The threshold is not whether the defence will succeed but whether it is triable, and an answer that weighs the merits as if at trial has applied the wrong test. Where a defence is shadowy the court may give conditional leave to defend — typically on payment into court — which is the middle outcome most students omit.",source:"Rules of Court 2012 O 14",see:["striking-out","rules-of-court"],aliases:["summary judgment","Order 14","O 14"]},{id:"syariah-court",term:"Syariah court",kind:"institution",gloss:"A State court with jurisdiction over Muslims on listed matters.",intermediate:"Established by State law under List II Item 1, running Syariah Subordinate Court, Syariah High Court and Syariah Appeal Court. Its jurisdiction reaches only persons professing the religion of Islam, and only the listed subjects.",advanced:"It is a separate hierarchy, not a lower tier of the civil one, and there is no appeal from it into the Federal Court. Because both limbs — the person and the subject matter — must be satisfied, the hardest cases are those where a dispute has civil and Syariah aspects at once, and the answer usually turns on how the question is characterised rather than on any disagreement about the rule.",source:"Federal Constitution Ninth Schedule List II Item 1; State Syariah enactments",see:["article-121a","ninth-schedule"],aliases:["Syariah courts","Syariah court","Syariah"]},{id:"theft",term:"theft",kind:"doctrine",gloss:"Dishonestly moving movable property out of another's possession without consent.",intermediate:"Section 378. The property must be moved, taken out of someone's possession, and taken without that person's consent, with dishonest intention.",advanced:"The organising question across the property offences is how possession was obtained, and theft is the branch where it was never given. 'Dishonestly' has its own statutory definition in terms of wrongful gain or wrongful loss, and possession — as opposed to mere custody — is the concept that decides whether an employee who takes what passes through his hands has stolen or committed criminal breach of trust.",source:"Penal Code ss 378 and 24",see:["criminal-breach-of-trust","cheating","dishonestly"],aliases:["theft"]},{id:"thinking-like-a-lawyer",term:"Thinking Like a Lawyer",kind:"method",gloss:"Frederick Schauer, Thinking Like a Lawyer — on rules, precedent and analogy.",intermediate:"A book about what kind of thinking legal reasoning is: authority, rules against standards, precedent and argument by analogy. Harvard University Press.",advanced:"Read it after you have briefed several cases rather than before. Its argument about analogy only lands once you have felt how much work the choice of a comparison case does, which reading about it in advance does not give you.",source:"Frederick Schauer, Thinking Like a Lawyer (Harvard University Press)",aliases:["Thinking Like a Lawyer","Schauer"],see:["ratio-decidendi"]},{id:"tol",term:"TOL",kind:"doctrine",gloss:"Temporary occupation licence.",intermediate:"Yearly permission to occupy State land. It is permission, not ownership, and it does not turn into ownership however long it runs.",advanced:"A TOL is renewed annually at the State's discretion, so it gives no security of tenure and cannot be dealt with as an interest in land. Long occupation under one does not give title to registered land.",source:"National Land Code",aliases:["TOL"],see:["proprietor","registration"]},{id:"torrens",term:"Torrens system",kind:"doctrine",gloss:"Title by registration: the register creates the title.",intermediate:"Under the National Land Code an interest in land exists when it is registered. A purchaser deals with the register rather than investigating the history behind it.",advanced:"The phrase to hold onto is title by registration, not registration of title — the register is not a record of a title acquired elsewhere, it is the source of it. Section 6 of the Civil Law Act 1956 excludes English land law precisely so that imported doctrines of notice and equitable interests cannot undercut that. Between contract and registration the purchaser has contractual and equitable rights only, which is what the caveat machinery exists to protect.",source:"National Land Code; Civil Law Act 1956 s 6",see:["indefeasibility","caveat","dealing","national-land-code"],aliases:["Torrens system","Torrens"]},{id:"tort",term:"tort",kind:"doctrine",gloss:"A civil wrong, other than a breach of contract.",intermediate:"A wrong the law lets you sue over even though you never agreed anything with the other side — being injured by careless driving, for example. Negligence and defamation are torts.",advanced:"The duty in tort is imposed by law rather than undertaken, which is what separates it from contract and explains why the measure of damages differs: tort restores the position before the wrong, contract the position performance would have produced.",source:"Standard common law",aliases:["tort","torts","tortious"],see:["negligence","liability"]},{id:"tribunal",term:"tribunal",kind:"institution",gloss:"A body that decides disputes without being an ordinary court.",intermediate:"A panel set up by statute to decide a particular kind of dispute — tenancy, employment, consumer claims. It is not part of the ordinary court hierarchy.",advanced:"Because a tribunal's powers come from its own statute, the first questions are what it may decide and what route of challenge exists. Where no appeal is given, judicial review of how the decision was made may still be available.",source:"Standard administrative law usage",aliases:["tribunal","tribunals"],see:["judicial-review"]},{id:"trustee",term:"trustee",kind:"doctrine",gloss:"A person who holds property for the benefit of another.",intermediate:"Someone holding property that is not theirs to enjoy, for somebody else's benefit. They must act in that person's interest, not their own.",advanced:"The obligation is fiduciary, so the trustee may not profit from the position or place themselves where duty and interest conflict, and it is no answer that the beneficiary lost nothing. The same reasoning underlies a director's duty to the company.",source:"Trustee Act 1949",aliases:["trustee","trustees"],see:["director"]},{id:"uksc",term:"UKSC",kind:"institution",gloss:"United Kingdom Supreme Court.",intermediate:"The UK's highest court since 2009, replacing the House of Lords. Cavendish Square Holding v Makdessi [2015] UKSC 67 is one of its decisions.",advanced:"Its decisions are persuasive in Malaysia and no more. Where our Federal Court has drawn on one — as it did in Cubic Electronics on penalty clauses — the Malaysian reformulation is what you cite, not the English case.",source:"English court hierarchy",aliases:["UKSC"],see:["hl"]},{id:"ultra-vires",term:"ultra vires",kind:"latin",gloss:"Beyond the powers — and therefore invalid.",intermediate:"An act done outside the authority conferred by the statute or instrument granting it. The act is not merely wrong; it has no legal effect.",advanced:"The concept spans several subjects: a State enactment outside List II, a regulation outside its parent Act, a decision outside a public body's powers, and historically a company acting outside its objects. In administrative law it is the root of the illegality ground of judicial review, and its opposite, intra vires, is rarely used except to make the contrast.",source:"Standard doctrine; Federal Constitution Art 4(1) for the constitutional sense",see:["judicial-review","subsidiary-legislation","legislative-competence"],aliases:["ultra vires"]},{id:"undertaking-in-damages",term:"undertaking in damages",kind:"doctrine",gloss:"The applicant's promise to compensate if the injunction was wrongly granted.",intermediate:"A condition of interim relief: if it turns out at trial that the order should not have been made, the applicant pays for the loss it caused.",advanced:"It is given to the court rather than to the other party, and the court may require it to be fortified by security where the applicant's means are doubtful. Its existence is why interim relief is not a free option, and advising a client to seek an injunction without explaining it is incomplete advice.",source:"Rules of Court 2012 O 29",see:["interlocutory-injunction","ex-parte"],aliases:["undertaking as to damages","undertaking in damages"]},{id:"undue-influence",term:"undue influence",kind:"doctrine",gloss:"Using a position of dominance to obtain an unfair advantage.",intermediate:"Section 16: where the relations between the parties are such that one can dominate the other's will and uses that position to get an unfair advantage.",advanced:"Section 16(2) gives instances — real or apparent authority, a fiduciary relation, mental or bodily distress — and s 16(3) shifts the burden onto the dominant party where the transaction appears unconscionable. The burden-shifting provision is what most cases turn on, and it is the part that gets left out of an answer that stops at the definition.",source:"Contracts Act 1950 s 16",see:["free-consent","voidable","fiduciary-duty"],aliases:["undue influence"]},{id:"vicarious-liability",term:"vicarious liability",kind:"doctrine",gloss:"An employer's liability for an employee's tort.",intermediate:"Liability without fault, imposed on one person for the tort of another committed in the course of employment.",advanced:"Two questions decide it: whether the relationship is one of employment or akin to it, and whether the tort was sufficiently connected to what the employee was engaged to do. An independent contractor generally does not attract it, though non-delegable duties can produce liability by another route.",source:"Standard common law",see:["negligence","duty-of-care"],aliases:["vicarious liability","vicariously liable"]},{id:"void",term:"void",kind:"doctrine",gloss:"Of no legal effect from the beginning.",intermediate:"A void agreement never created rights. Nothing can be affirmed and no election arises, though s 66 requires restoration of any advantage received under it.",advanced:"The distinction from voidable is not terminological: a void agreement cannot pass title, so a third party taking under it takes nothing, whereas a voidable contract passes title until it is avoided. Bilateral mistake as to an essential fact (s 21), and an unlawful object or consideration (s 24), make an agreement void.",source:"Contracts Act 1950 ss 2(g), 21, 24 and 66",see:["voidable","section-66","free-consent"],aliases:["void"]},{id:"voidable",term:"voidable",kind:"doctrine",gloss:"Valid until the innocent party elects to avoid it.",intermediate:"An agreement enforceable at the option of one party. Coercion, fraud and misrepresentation make a contract voidable under s 19(1).",advanced:"The right to rescind is an election and it can be lost — by affirmation, by lapse of time, by the intervention of third-party rights, or where restitution has become impossible. Until it is exercised the contract is fully effective, which is why a third party who buys in good faith before avoidance keeps what he bought.",source:"Contracts Act 1950 s 19",see:["void","rescission","free-consent"],aliases:["voidable"]},{id:"volenti",term:"volenti non fit injuria",kind:"latin",gloss:"No injury is done to one who consents.",intermediate:"A complete defence where the claimant freely and knowingly accepted the risk of the very injury suffered.",advanced:"It requires real consent to the risk, not merely knowledge of it, which is why it rarely succeeds against employees or rescuers. Since contributory negligence became an apportionment exercise, courts have generally preferred to reduce damages rather than defeat the claim entirely.",source:"Standard common law; Civil Law Act 1956 s 12",see:["contributory-negligence","negligence"],aliases:["volenti non fit injuria","volenti"]},{id:"wednesbury",term:"Wednesbury unreasonableness",kind:"doctrine",gloss:"A decision so unreasonable no reasonable authority could have reached it.",intermediate:"The irrationality ground of judicial review. It is deliberately hard to satisfy, because it is not an invitation to substitute the court's view.",advanced:"The threshold is high enough that successful challenges usually rest on illegality or procedural impropriety instead, with irrationality pleaded in support. Proportionality is the more demanding alternative that has been argued into Malaysian law in the constitutional context; its status as a free-standing head of administrative review is a separate and unsettled question.",source:"Associated Provincial Picture Houses Ltd v Wednesbury Corporation [1948] 1 KB 223, as received in Malaysia",see:["judicial-review","proportionality"],aliases:["Wednesbury unreasonableness","irrationality","Wednesbury"]},{id:"witness",term:"witness",kind:"doctrine",gloss:"A person who gives evidence in court.",intermediate:"Someone who tells the court what they saw, heard or otherwise perceived. Evidence must generally be direct, so a witness speaks to what they themselves perceived rather than to what somebody else told them.",advanced:"Failing to call a witness who was available and material may attract an adverse inference under s 114 illustration (g). The inference is permissive, and it does not arise where the evidence would merely repeat what is already proved.",source:"Evidence Act 1950",aliases:["witness","witnesses"],see:["adverse-inference"]},{id:"wlr",term:"WLR",kind:"method",gloss:"Weekly Law Reports — an English series.",intermediate:"Another English report series. Like AC, it carries English decisions, which are persuasive in Malaysia rather than binding.",advanced:"Where the same English case appears in both WLR and AC, the AC report is the one usually cited, because it is the fuller and later-settled version.",source:"English law report series",aliases:["WLR"],see:["ac"]},{id:"writ",term:"writ",kind:"doctrine",gloss:"The mode of commencement where the facts are in dispute.",intermediate:"Used where there is likely to be a substantial dispute of fact, so that evidence is given orally and tested by cross-examination.",advanced:"The alternative, an originating summons, suits a question of construction of a document or statute, or of law on essentially undisputed facts, and proceeds on affidavit. Choosing wrongly is not fatal — the court can order the proceedings to continue as if begun the other way — but it costs time and costs.",source:"Rules of Court 2012 O 5",see:["originating-summons","pleading","rules-of-court"],aliases:["writ"]}],le={kinds:U,terms:z},$=[{id:"x-tan-ying-hong",moduleId:"m08-property",lessonId:"l-torrens",case:"Tan Ying Hong v Tan Sian San",citation:"[2010] 2 MLJ 1 (FC)",court:"Federal Court",year:2010,find:"Malaysian Federal Court decisions from 2003 onwards are on CommonLII (commonlii.org, Malaysia > Federal Court). The government Court Case Judgment Search at malaysia.gov.my also carries written grounds. If neither has it, the MLJ citation below will find it in any law library, and many public university libraries admit visitors.",why:"This is the case the property lessons rest on, and it is also a court correcting itself in public. Read it once for the land law and once for what a court does when it decides an earlier decision of its own was wrong.",read:[{passage:"The court's account of what Adorna Properties had decided, and why it was being revisited.",look_for:"Notice that the court states the earlier holding before disagreeing with it. You cannot attack a decision you have not first stated fairly."},{passage:"The passage dealing with the proviso to section 340(3) of the National Land Code.",look_for:"Follow the words of the section as the court reads them. Ask which word carries the result."},{passage:"Anything the court says about immediate and deferred indefeasibility.",look_for:"The distinction is the whole case. Write it in one sentence of your own before reading on."}],questions:[{q:"State the ratio in one sentence, at the level of generality the result actually required.",model:"A good answer names the proposition the outcome depended on and no more. Too wide ('registration never protects a forger's transferee') and it decides cases this court did not have; too narrow ('this charge was void') and it decides nothing beyond the parties. Check your sentence against the order the court made: if the sentence would not produce that order, it is not the ratio."},{q:"Find one passage that is obiter and say how you know.",model:"Obiter is anything the result did not need. The usual test: remove the passage and ask whether the order still follows. If it does, the passage is obiter — however emphatic the language and however senior the judge."},{q:"What did the court say about its own earlier decision, and what does that tell you about how far 'binding' goes?",model:"The lesson already tells you this decision superseded the earlier one. What to take from the judgment is the mechanism: which court, sitting how, may depart from what — and the fact that a wrong decision stays law until a court with power to correct it says otherwise."}],trap:"Do not write the land law essay. The question asks for the ratio, not for everything you know about indefeasibility.",source:"Tan Ying Hong v Tan Sian San [2010] 2 MLJ 1 (FC), as cited in the lessons l-torrens, l-caveats, pd-l-land-paperwork and l-citation.",verify:"Confirm the citation and read the court's own words on the proviso to s 340(3). Check whether any later Federal Court decision or amendment to the National Land Code has moved this ground since 2010.",lastVerified:"2026-09-09"},{id:"x-adorna",moduleId:"m08-property",lessonId:"l-caveats",case:"Adorna Properties Sdn Bhd v Boonsom Boonyanit",citation:"[2001] 1 MLJ 241 (FC)",court:"Federal Court",year:2001,find:"Older than CommonLII's Malaysian coverage, which starts at 2003. Use the MLJ citation in a law library, or the Malaysian Bar's document library. Do not rely on a student summary for the words of the judgment — a summary is someone else's ratio.",why:"Read the decision that was later held to be wrong, and read it before you read the criticism. Being able to see how a court reached a conclusion that did not survive is worth more than being told it was wrong.",read:[{passage:"The court's reading of section 340 and the route it took to its conclusion.",look_for:"Identify the step you think does not hold. Mark it before you look at any commentary."}],questions:[{q:"Where exactly does the reasoning turn? Name the sentence, not the paragraph.",model:"A good answer points at a specific move in the reasoning — a reading of a word, a step taken as obvious — and says why that move carries the result. 'The whole approach was wrong' is not an answer."},{q:"If you were arguing against this decision the day after it was handed down, what would you have said?",model:"Argue from the words of the section and from the structure of the Act, because those were available on day one. Later criticism is not an argument you could have made then."}],trap:"A decision that was later departed from is not a decision that was stupid. If your answer makes the court look foolish, you have probably misread it.",source:"Adorna Properties Sdn Bhd v Boonsom Boonyanit [2001] 1 MLJ 241 (FC), as cited in l-caveats. Its later treatment is covered in l-torrens.",verify:"Check the citation, and confirm from a current text how this decision now stands after Tan Ying Hong.",lastVerified:"2026-09-09"},{id:"x-cubic-electronics",moduleId:"m06-contract",lessonId:"l-remedies",case:"Cubic Electronics Sdn Bhd v Mars Telecommunications Sdn Bhd",citation:"[2019] 6 MLJ 15 (FC)",court:"Federal Court",year:2019,find:"Malaysian Federal Court decisions from 2003 onwards are on CommonLII (commonlii.org, Malaysia > Federal Court). The government Court Case Judgment Search at malaysia.gov.my also carries written grounds. If neither has it, the MLJ citation below will find it in any law library, and many public university libraries admit visitors.",why:"A recent Federal Court decision on section 75 of the Contracts Act, and a good place to watch a court handle English authority: adopting some of it, and saying why it is free to do so under a Malaysian statute.",read:[{passage:"The treatment of section 75 of the Contracts Act 1950 and what a claimant must show.",look_for:"Statute first. The section is the law; the cases explain it."},{passage:"Any discussion of English authority on penalties.",look_for:"Ask what work the English case is doing: is it binding, persuasive, or being used to explain a phrase already in the Malaysian section?"}],questions:[{q:"Does a claimant have to prove actual loss under section 75? State the position and the authority for it.",model:"State the rule as the court states it, then cite the paragraph you took it from. An answer with no paragraph reference is an answer you cannot check."},{q:"How does the court use English authority here, and what does that tell you about when English cases help in a Malaysian contract question?",model:"The answer must start from the statute. English authority can illuminate a concept the section uses; it cannot displace the section. Say which of those is happening here."}],trap:"Do not import the English penalty rule wholesale. Malaysia has a section, and the section governs.",source:"Cubic Electronics Sdn Bhd v Mars Telecommunications Sdn Bhd [2019] 6 MLJ 15 (FC), also reported at [2019] 2 CLJ 723, as cited in l-remedies.",verify:"Confirm the citation and check for any later Federal Court decision on s 75, and any amendment to the Contracts Act 1950.",lastVerified:"2026-09-09"},{id:"x-hadley",moduleId:"m06-contract",lessonId:"l-remedies",case:"Hadley v Baxendale",citation:"(1854) 9 Exch 341",court:"Court of Exchequer (England)",year:1854,find:"An English decision, free in full on BAILII (bailii.org). Search the case name. Read the judgment itself rather than a headnote: the headnote is the publisher's summary and is not what binds anyone.",why:"One of the shortest foundational judgments you will read, and still the starting point for remoteness. Read it to see how much law a court can settle in a few pages.",read:[{passage:"The famous two-limb passage on what damages are recoverable.",look_for:"Write out the two limbs in your own words. Most misuse of this case is a failure to keep them apart."},{passage:"The facts about the mill shaft and what the carrier was told.",look_for:"The facts are the second limb. Notice what was not communicated."}],questions:[{q:"State the two limbs, and say which one the case was actually decided on.",model:"Both limbs must be stated accurately, and then the answer must commit to which one carried the result on these facts. Being able to name the limb that did the work is the difference between citing this case and using it."},{q:"Malaysia has section 74 of the Contracts Act 1950. What is the relationship between the section and this case?",model:"The section governs. The case is where the idea in the section comes from and is used to explain it. An answer that applies Hadley without opening s 74 has skipped the law."}],trap:"Reciting 'Hadley v Baxendale' is not analysis. Name the limb, apply it to the facts you were given.",source:"Hadley v Baxendale (1854) 9 Exch 341, as cited in l-remedies; s 74 Contracts Act 1950.",verify:"Read the judgment itself on BAILII and check s 74 in a current copy of the Contracts Act 1950.",lastVerified:"2026-09-09"},{id:"x-sivarasa",moduleId:"m03-constitutional",lessonId:"l-liberties",case:"Sivarasa Rasiah v Badan Peguam Malaysia",citation:"[2010] 2 MLJ 333 (FC)",court:"Federal Court",year:2010,find:"Malaysian Federal Court decisions from 2003 onwards are on CommonLII (commonlii.org, Malaysia > Federal Court). The government Court Case Judgment Search at malaysia.gov.my also carries written grounds. If neither has it, the MLJ citation below will find it in any law library, and many public university libraries admit visitors.",why:"Read it alongside PP v Pung Chen Choon. Two Federal Court decisions, two different temperatures on how closely a court examines a law that limits a liberty.",read:[{passage:"Anything on how Part II rights are to be read.",look_for:"Note the language the court uses about the generosity or narrowness of the reading."},{passage:"Anything on whether a restriction must be reasonable, and who decides.",look_for:"This is where the two cases pull apart. Mark the sentences you would quote."}],questions:[{q:"Set the two decisions side by side. Where precisely do they differ?",model:"The lesson tells you there is a tension. Your job in the judgments is to locate it in words: find the sentence in each that a lawyer on the other side would have to deal with."},{q:"If you were advising a client today, which do you lead with, and how do you deal with the other?",model:"Lead with the one that helps you, state the other fairly, and give a reason a court could accept for preferring yours — later, more considered, different question. Pretending the unhelpful case does not exist is how you lose."}],trap:"Do not say 'the law is unclear' and stop. Advising means committing to a position and dealing with the objection.",source:"Sivarasa Rasiah v Badan Peguam Malaysia [2010] 2 MLJ 333 (FC) and PP v Pung Chen Choon [1994] 1 MLJ 566 (FC), both cited in l-liberties.",verify:"This is a live area. Check both citations and whether any later Federal Court decision has resolved the tension. If one has, this exercise changes shape.",lastVerified:"2026-09-09"},{id:"x-pung-chen-choon",moduleId:"m03-constitutional",lessonId:"l-liberties",case:"PP v Pung Chen Choon",citation:"[1994] 1 MLJ 566 (FC)",court:"Federal Court",year:1994,find:"Older than CommonLII's Malaysian coverage, which starts at 2003. Use the MLJ citation in a law library, or the Malaysian Bar's document library. Do not rely on a student summary for the words of the judgment — a summary is someone else's ratio.",why:"The other half of the pair. Read this one first if you want to feel the shift; read it second if you want to test whether the shift is as large as commentary says.",read:[{passage:"The court's approach to a law that restricts a liberty in Part II.",look_for:"Ask what the court treats as Parliament's business and what it treats as its own."}],questions:[{q:"What does this decision treat as the court's role when a statute limits a right?",model:"State it from the judgment, in the court's own terms, before you compare it with anything else."},{q:"Is the difference from the later case a difference of principle, or of the question asked?",model:"A strong answer considers that two decisions may sit together because they answer different questions. That is often how a court later reconciles them, and it is the argument you may need."}],trap:"Older is not automatically overruled. A decision stands until something displaces it.",source:"PP v Pung Chen Choon [1994] 1 MLJ 566 (FC), cited in l-liberties.",verify:"Confirm the citation and check the current standing of this decision in a text published this year.",lastVerified:"2026-09-09"},{id:"x-foo-fio-na",moduleId:"m07-tort",lessonId:"l-negligence",case:"Foo Fio Na v Dr Soo Fook Mun",citation:"[2007] 1 MLJ 593 (FC)",court:"Federal Court",year:2007,find:"Malaysian Federal Court decisions from 2003 onwards are on CommonLII (commonlii.org, Malaysia > Federal Court). The government Court Case Judgment Search at malaysia.gov.my also carries written grounds. If neither has it, the MLJ citation below will find it in any law library, and many public university libraries admit visitors.",why:"A Malaysian court choosing between two foreign standards and explaining the choice. Read it with Bolam and Rogers v Whitaker beside you — all three are short enough.",read:[{passage:"The court's treatment of the Bolam test.",look_for:"Note exactly what is being rejected: the test everywhere, or the test for one kind of question?"},{passage:"The court's treatment of Rogers v Whitaker.",look_for:"An Australian decision is not binding here. Watch the court explain why it is following it anyway."}],questions:[{q:"What is the standard in Malaysia after this decision, and for which question?",model:"Be precise about scope. A standard for advice and a standard for diagnosis or treatment may not be the same, and an answer that blurs them is answering a different question."},{q:"Why was an Australian decision persuasive here? Give the court's reason, not yours.",model:"Quote or paraphrase the court's stated reason. 'Because it is better law' is your view; the question asks for theirs."}],trap:"Bolam is not gone from the law generally. Say what it was displaced for.",source:"Foo Fio Na v Dr Soo Fook Mun [2007] 1 MLJ 593 (FC); Rogers v Whitaker (1992) 175 CLR 479 (High Court of Australia); Bolam v Friern Hospital Management Committee [1957] 1 WLR 582. All three cited in l-negligence.",verify:"Check all three citations and confirm from a current text how the standard stands today, including any later Federal Court treatment.",lastVerified:"2026-09-09"},{id:"x-rama-chandran",moduleId:"m12-administrative",lessonId:"l-judicial-review",case:"R Rama Chandran v The Industrial Court of Malaysia",citation:"[1997] 1 MLJ 145 (FC)",court:"Federal Court",year:1997,find:"Older than CommonLII's Malaysian coverage, which starts at 2003. Use the MLJ citation in a law library, or the Malaysian Bar's document library. Do not rely on a student summary for the words of the judgment — a summary is someone else's ratio.",why:"The case the administrative law lesson is built around, and a long judgment. Read it for scope: how far a court reviewing a decision may go into its merits.",read:[{passage:"Anything on the difference between reviewing how a decision was made and reviewing the decision itself.",look_for:"This distinction is the subject. Everything else in the case hangs off it."}],questions:[{q:"How far does this decision let a court go into the merits? State it as a rule you could apply.",model:"A usable rule names what the court may examine and what it must leave alone. If your rule cannot decide the next case, it is a summary, not a rule."},{q:"A long judgment contains a great deal that is not the ratio. Pick one passage often quoted and say whether the result needed it.",model:"Apply the removal test. Being able to say 'this is quoted constantly and is obiter' is a real skill and is worth marks in an exam."}],trap:"The lesson also cites Semenyih Jaya. Do not treat this area as frozen in 1997.",source:"R Rama Chandran v The Industrial Court of Malaysia [1997] 1 MLJ 145 (FC) and Semenyih Jaya Sdn Bhd v Pentadbir Tanah Daerah Hulu Langat [2017] 3 MLJ 561 (FC), both cited in l-judicial-review.",verify:"Check both citations and read how a current administrative law text describes the relationship between them.",lastVerified:"2026-09-09"},{id:"x-pepper-v-hart",moduleId:"m14-statutory-interpretation",lessonId:"l-aids",case:"Pepper v Hart",citation:"[1993] AC 593 (HL)",court:"House of Lords (England)",year:1993,find:"An English decision, free in full on BAILII (bailii.org). Search the case name. Read the judgment itself rather than a headnote: the headnote is the publisher's summary and is not what binds anyone.",why:"When may a court look at what a minister said in Parliament? Read the conditions, because they are the point, and almost everyone remembers the permission and forgets them.",read:[{passage:"The conditions under which parliamentary material may be used.",look_for:"Write them as a list. There is more than one, and they are cumulative."},{passage:"Any dissent or expression of caution.",look_for:"The objections tell you what the rule is for."}],questions:[{q:"List the conditions. All of them.",model:"A complete list, in your own words. An answer that says 'you can look at Hansard now' has learned the headline and none of the law."},{q:"This is an English decision. What is its status in a Malaysian statutory interpretation question?",model:"Persuasive, not binding, and to be considered alongside the Interpretation Acts and Malaysian authority on the same question. Say where you would check that before relying on it."}],trap:"The permission is narrow and conditional. Treating it as an open door to Hansard is the standard error.",source:"Pepper v Hart [1993] AC 593 (HL), cited in l-aids.",verify:"Read the conditions in the judgment itself on BAILII, and check how Malaysian courts have treated this decision.",lastVerified:"2026-09-09"}],ue=Object.freeze(Object.defineProperty({__proto__:null,default:$},Symbol.toStringTag,{value:"Module"})),Z=[{id:"x-caparo-dickman",moduleId:"m07-tort",lessonId:"l-negligence",case:"Caparo Industries plc v Dickman",citation:"[1990] 2 AC 605 (HL)",court:"House of Lords",year:1990,find:"English House of Lords decisions of this period are on BAILII (bailii.org) without charge, under United Kingdom House of Lords Decisions. The Appeal Cases citation will also find it in any law library that carries the English reports, and most Malaysian university libraries do.",why:"This is the case the duty question in your negligence lesson rests on, and it is also a court explaining why it distrusts a single grand test. Read it once for the elements and once for the argument against tidiness — the second reading is the one that changes how you write about duty.",read:[{passage:"The passages dealing with how a duty of care is established, and what the court says about incremental development.",look_for:"Notice how much work the word incremental is doing. Ask what the court thinks goes wrong if a court reasons from a single principle instead."},{passage:"The treatment of the relationship between the parties, and what the maker of a statement knew about who would rely on it.",look_for:"Follow which facts the court treats as making the relationship close enough. Write down the two or three that carry the weight."},{passage:"Anything said about the purpose for which information was produced.",look_for:"Purpose does a great deal of work here. Ask whether the result would change if the same words had been produced for a different reason."}],questions:[{q:"State the elements the court uses for establishing a duty, in your own words, without looking at the lesson.",model:"A good answer names each element and, crucially, says what each one is doing that the others are not. If your three elements collapse into one another when you try to explain them, you have restated a formula rather than understood a test — and that is the exact complaint the court makes about single grand principles."},{q:"The court warns against a single general test. What is the practical cost of ignoring that warning?",model:"A good answer connects the warning to consequences rather than repeating it. Reasoning from one broad principle lets a court reach a duty in a situation nobody has considered, with no comparison case to discipline it. The incremental method forces you to name the decided case you are arguing from, which is checkable in a way an appeal to principle is not."},{q:"How would you use this case in a Malaysian negligence answer, given it is an English decision?",model:"A good answer does not assume it applies. It asks whether a Malaysian court has adopted the reasoning, and says so. English decisions after the reception date under the Civil Law Act 1956 are persuasive rather than automatically part of Malaysian law, and treating one as binding is a mistake an examiner will see immediately."}],trap:"Reciting three elements as a checklist and applying none of them. The elements are not a spell; each is a question about these facts, and an answer that names them without asking them has done nothing.",source:"Citation taken from the source field of the negligence lesson in content/lessons.",verify:"Check the citation against the report itself before relying on it, and check whether the Malaysian courts have adopted this reasoning rather than assuming they have.",lastVerified:"2026-09-09"},{id:"x-ampang-jaya-phoa",moduleId:"m07-tort",lessonId:"l-negligence",case:"Majlis Perbandaran Ampang Jaya v Steven Phoa Cheng Loon",citation:"[2006] 2 MLJ 389 (FC)",court:"Federal Court",year:2006,find:"Malaysian Federal Court decisions from 2003 onwards are on CommonLII (commonlii.org, under Malaysia, Federal Court). The government Court Case Judgment Search at malaysia.gov.my also carries written grounds. The MLJ citation will find it in a law library.",why:"A Malaysian apex court working out how far a public authority's duty runs. This is the case to read when you want to know how a Malaysian court actually reasons about duty, rather than how an English one does — and the difference is the point.",read:[{passage:"The court's treatment of whether a duty of care was owed by the authority.",look_for:"Watch which English authorities the court engages with and which it sets aside. That choosing is itself the reasoning, not a preliminary to it."},{passage:"Anything said about policy, resources, or the consequences of imposing a duty on a public body.",look_for:"Ask whether these are being used as reasons against a duty, or as reasons for confining it. They are different moves and courts do not always separate them."},{passage:"The passages dealing with the scope of the loss recoverable.",look_for:"Duty and damage are separate questions. Notice where the court moves from one to the other, and whether it says so."}],questions:[{q:"How does this court's approach to duty differ from a mechanical application of an English test?",model:"A good answer identifies at least one place where the court adapts rather than adopts, and says what local consideration drove it. The general claim that Malaysian courts follow English law with modifications is worth nothing without an instance; the instance is what an examiner is looking for."},{q:"What role does the defendant being a public authority play in the reasoning?",model:"A good answer distinguishes two uses. Public status can be a reason to deny a duty altogether, or a reason to shape its content — what the authority had to do rather than whether it owed anything. Say which the court is doing here, and quote nothing; describe it."}],trap:"Treating this as merely the Malaysian version of an English case. It is a court deciding for itself which imported reasoning fits local circumstances, and the deciding is what you are reading it for.",source:"Citation taken from the source field of the negligence lesson in content/lessons.",verify:"Check the citation and the court against the report. Read the whole judgment rather than a headnote — the headnote will give you the holding and not the method.",lastVerified:"2026-09-09"},{id:"x-bolam-friern",moduleId:"m07-tort",lessonId:"l-negligence",case:"Bolam v Friern Hospital Management Committee",citation:"[1957] 1 WLR 582",court:"Queen's Bench Division",year:1957,find:"On BAILII (bailii.org) under England and Wales High Court decisions. The Weekly Law Reports citation will also find it in a library. It is short — this is a first-instance direction to a jury, not an appellate judgment, and it reads quickly.",why:"The origin of the professional standard test, and a good lesson in how a passage in a jury direction can become a rule cited for decades. Read it noticing how little text the whole doctrine rests on.",read:[{passage:"The direction on the standard expected of a person professing a special skill.",look_for:"Write out the standard in your own words. Then ask who decides whether it is met — the court, or the profession."},{passage:"Anything said about a body of responsible opinion.",look_for:"The word body is doing real work. Ask whether it means a majority, and what follows if two responsible bodies disagree."}],questions:[{q:"Who, on this direction, decides whether a professional acted reasonably?",model:"A good answer notices that the effect of the test is to hand much of that judgement to the profession itself, and says why that is both sensible and uncomfortable. Sensible, because a court has no independent expertise; uncomfortable, because a profession setting its own standard is marking its own work."},{q:"Why does it matter that this passage comes from a direction to a jury rather than an appellate judgment?",model:"A good answer takes the point about weight and provenance. A first-instance direction is not binding in the way an apex court's ratio is, so a doctrine resting on it is more open to being confined or departed from than its long citation history suggests. Where a rule comes from affects how firmly it holds."},{q:"Is this test the law in Malaysia today for medical negligence?",model:"A good answer does not assert. It says the position has been considered by the Malaysian courts and that the reader must check the current authority, naming where they would look. Confidently stating an English test as current Malaysian law is exactly the error this tier exists to train out."}],trap:"Citing this as though it settled the Malaysian position. It is the starting point of a long argument, and other cases in this module carry that argument forward.",source:"Citation taken from the source field of the negligence lesson in content/lessons.",verify:"Check the citation against the report, and check the current Malaysian position on the professional standard before relying on this in an answer.",lastVerified:"2026-09-09"},{id:"x-rogers-whitaker",moduleId:"m07-tort",lessonId:"l-negligence",case:"Rogers v Whitaker",citation:"(1992) 175 CLR 479",court:"High Court of Australia",year:1992,find:"On AustLII (austlii.edu.au) under High Court of Australia decisions, free and complete. The Commonwealth Law Reports citation will find it in a library.",why:"An apex court declining to follow the professional standard where the duty is to warn. This is the clearest example in the module of a court separating two things that had been treated as one, and it is why your negligence lesson does not stop at the earlier test.",read:[{passage:"The passages distinguishing diagnosis and treatment from the duty to warn of risk.",look_for:"Ask why the distinction is drawn. What is different about warning that makes professional opinion less decisive?"},{passage:"Anything about what a particular patient would want to know.",look_for:"Notice the shift from what a profession thinks proper to what this patient needed. That shift is the case."},{passage:"The court's treatment of the earlier English approach.",look_for:"Watch how it declines to follow without saying the earlier reasoning was foolish. That is a technique worth copying."}],questions:[{q:"Why does the court treat the duty to warn differently from diagnosis and treatment?",model:"A good answer gives the reason rather than the result. Deciding what treatment is appropriate is a matter of clinical skill, where a court has no independent standard; deciding what a patient needs to know in order to choose is not purely clinical, and the patient's own position bears on it. If your answer does not explain why the two are unalike, it has restated the holding."},{q:"This is an Australian decision. What weight does it carry in Malaysia, and how would you use it?",model:"A good answer is precise about status. It is not binding, and it was not received under the Civil Law Act 1956. It is persuasive, and it is useful precisely because a Malaysian court may have considered it — so the honest use is to check whether it has been adopted here and cite that, rather than citing the Australian case as if it were local law."}],trap:"Using this to say the professional standard is dead. The case draws a line between kinds of duty; it does not abolish the earlier test for the areas the line leaves on the other side.",source:"Citation taken from the source field of the negligence lesson in content/lessons.",verify:"Check the citation on AustLII, and check whether and how the Malaysian courts have taken up this reasoning before using it in an answer.",lastVerified:"2026-09-09"},{id:"x-zulhasnimar-kuppu",moduleId:"m07-tort",lessonId:"l-negligence",case:"Zulhasnimar bt Hasan Basri v Dr Kuppu Velumani P",citation:"[2017] 5 MLJ 438 (FC)",court:"Federal Court",year:2017,find:"On CommonLII (commonlii.org, Malaysia, Federal Court) and through the government Court Case Judgment Search at malaysia.gov.my. The MLJ citation will find it in a law library.",why:"The Federal Court settling which standard applies to which limb of medical negligence in Malaysia. If you read only one case in this module for the current local position, read this one — and read it after the two it is answering.",read:[{passage:"The court's statement of which standard governs diagnosis and treatment, and which governs the duty to advise.",look_for:"Write the two-part answer in one sentence before reading further. Then check your sentence against the order the court made."},{passage:"The court's discussion of the earlier Malaysian authority on the same question.",look_for:"Notice whether the court is following, confining, or departing. The three are different and the words used matter."},{passage:"Anything said about why a different standard suits a different limb.",look_for:"This is the reasoning you can transfer. The result tells you the law; the reason tells you how to argue the next case."}],questions:[{q:"State, in one sentence, which standard applies to which limb after this decision.",model:"A good answer is one sentence with two halves and no case names in it. Test it the way you test any ratio: run the conditions and see whether they produce the order the court actually made. If your sentence would decide a case about diagnosis the same way as one about advice, it has lost the distinction the case exists to draw."},{q:"How does this decision relate to the earlier cases in this module?",model:"A good answer places it. It should say which reasoning the court accepted, which it did not, and — the part most answers omit — what remains open. A case that settles one question usually leaves an adjacent one unsettled, and naming that is what distinguishes a reader from a summariser."},{q:"Why is it safer to cite this than the English or Australian cases in a Malaysian answer?",model:"A good answer names the reason rather than asserting the preference: this is a decision of the apex court of this jurisdiction, so it binds the courts below in a way persuasive foreign authority does not. The foreign cases remain useful for the reasoning, which is a different job from supplying authority."}],trap:"Reading this as simply choosing between two foreign tests. It is a Malaysian court deciding what Malaysian law is, using foreign reasoning as material rather than as instruction.",source:"Citation taken from the source field of the negligence lesson in content/lessons.",verify:"Check the citation and the court against the report, and check whether anything has since qualified it before relying on it.",lastVerified:"2026-09-09"},{id:"x-lok-kok-beng",moduleId:"m07-tort",lessonId:"l-negligence",case:"Lok Kok Beng v Loh Chiak Eong",citation:"[2015] 4 MLJ 734 (FC)",court:"Federal Court",year:2015,find:"On CommonLII (commonlii.org, Malaysia, Federal Court) and through the government Court Case Judgment Search at malaysia.gov.my. The MLJ citation will find it in a law library.",why:"A Federal Court decision on when a duty of care arises alongside a contract, and on pure economic loss. Read it for the question every commercial negligence problem eventually reaches: what tort adds when the parties already have an agreement.",read:[{passage:"The court's treatment of whether a duty in tort can co-exist with contractual obligations.",look_for:"Ask what work the tort duty would do that the contract does not. If the answer is none, notice what the court says follows."},{passage:"Anything about pure economic loss and why it is treated differently from physical damage.",look_for:"The distinction is not arbitrary. Find the reason the court gives and write it in one sentence."},{passage:"The court's approach to establishing duty generally.",look_for:"Compare this with the approach in the other Malaysian case in this module. Where they differ, ask whether it is a real difference or a difference of emphasis."}],questions:[{q:"What does a duty in tort add where the parties are already in a contract?",model:"A good answer resists the easy reply that it adds nothing. Sometimes it adds a different limitation period, a different measure of damages, or a claim available to someone who is not a party to the contract. The useful answer names what it would add on these facts, which is a question about the facts and not about doctrine."},{q:"Why are courts more cautious about pure economic loss than about physical damage?",model:"A good answer gives the reason rather than the label. Economic loss ripples: one negligent act can cause loss to an indefinite number of people to an indefinite extent, and the usual limits that physical damage supplies are absent. The caution is about determinacy, not about economic loss being less real."}],trap:"Treating pure economic loss as never recoverable. The category is treated with caution and confined, which is a different thing, and an answer that states a flat prohibition will be wrong on the facts where it is recoverable.",source:"Citation taken from the source field of the negligence lesson in content/lessons.",verify:"Check the citation and the court against the report, and check the current position on pure economic loss in Malaysia rather than relying on this summary.",lastVerified:"2026-09-09"}],me=Object.freeze(Object.defineProperty({__proto__:null,default:Z},Symbol.toStringTag,{value:"Module"})),pe=[{id:"w-ratio-sentence",moduleId:"m00-foundations",lessonId:"l-precedent",level:"foundation",kind:"case-note",title:"State a ratio in one sentence",minutes:20,brief:"Take a decision you have already met in a lesson and write the ratio as a single sentence. One sentence. Not a summary of the facts, not what the court said along the way — the proposition the result actually turned on.",audience:"Yourself, six months from now, revising at speed.",before:["Read the precedent lesson first: you need the difference between ratio and obiter before this makes sense.","Have the case in front of you, or the lesson's account of it."],scaffold:[{step:"Write the order first",prompt:"In one line, what did the court actually do? Who won, and what were they given or refused?",why:"The ratio is the reason that produced this order. If you cannot state the order you cannot check your sentence against it, and checking is the whole method."},{step:"Write the proposition",prompt:"Now one sentence beginning 'Where...' — the circumstances — followed by what legally follows.",why:"The 'where' clause forces you to name the conditions. A ratio without conditions is a slogan."},{step:"Test it against the order",prompt:"Read your sentence, then the order. Would your sentence produce that order? If not, it is the wrong sentence.",why:"This is the only test that works without a textbook to check against."},{step:"Test it for width",prompt:"Ask: does my sentence decide cases this court did not have in front of it? Narrow it until it does not.",why:"Too wide and you have invented law. Too narrow and you have described one dispute."}],structure:[{part:"The conditions",does:"Names the circumstances the rule applies to",length:"a clause"},{part:"The consequence",does:"States what legally follows in those circumstances",length:"a clause"}],rubric:[{band:"Not yet",test:"The sentence recites facts, or names the parties, or says who won."},{band:"Close",test:"It states a rule, but wide enough to decide disputes this court never considered."},{band:"There",test:"It states conditions and a consequence, and running the conditions produces the order the court actually made."}],faults:["Writing the headnote instead of the ratio. A headnote is an editor's summary; the ratio is the reason the order followed.","Including the emphatic passage the judge clearly enjoyed writing. Emphasis is not authority.","Naming the parties. A ratio that names the parties decides one case and no other."],model:"A good answer is one sentence with two moving parts: a 'where' clause naming the circumstances, and a consequence. It does not mention the parties by name. Tested against the order, it produces it; widened by one word, it would decide a case the court did not have. If your sentence needs a second sentence to be true, the second sentence is doing the work and you have not found the ratio yet.",source:"Method, not doctrine. The technique is the standard one taught for reading judgments.",lastVerified:"2026-09-09",verify:"Compare your sentence with how the lesson states the same case's ratio. If they differ, work out which of you is wider and why."},{id:"w-plain-explanation",moduleId:"m00-foundations",lessonId:"l-vocabulary",level:"foundation",kind:"advice",title:"Explain one rule to someone at home",minutes:20,brief:"Pick one rule you have learned this week. Write an explanation of it for a person you actually know who has never studied law — a parent, a neighbour, a friend after their shift. Two hundred words at most. No legal words unless you define them in the same sentence.",audience:"One real person, named in your own head before you start.",before:["Pick the rule before you start writing. Not a topic — a rule.","Decide who you are writing to and keep them in mind. A general reader is nobody, and writing for nobody is why most legal writing is bad."],scaffold:[{step:"Name the situation",prompt:"Start with a concrete situation your reader could actually be in. Not 'where a party breaches' — a person, a place, a thing that went wrong.",why:"The lessons put the scene before the doctrine for the same reason: an abstract term with nothing under it is a weight your reader has to carry until you finally explain it."},{step:"State what the law does about it",prompt:"One or two sentences. What does the law say happens?",why:"If you cannot say it in two sentences you do not yet know it well enough to teach it."},{step:"Say what it does not do",prompt:"Add the limit. What does this rule not cover, that your reader might assume it does?",why:"Most harm from half-understood law comes from people assuming a rule reaches further than it does."},{step:"Read it aloud",prompt:"Read the whole thing out loud. Anything you stumble over, rewrite.",why:"Your mouth finds tangled sentences faster than your eye does."}],structure:[{part:"The situation",does:"A concrete scene the reader recognises",length:"two or three sentences"},{part:"The rule",does:"What the law does about that situation",length:"two sentences"},{part:"The limit",does:"What it does not reach",length:"one or two sentences"}],rubric:[{band:"Not yet",test:"Legal words appear undefined, or it opens with a definition rather than a situation."},{band:"Close",test:"Clear, but no limit is stated, so a reader could walk away thinking the rule covers more than it does."},{band:"There",test:"A real person could read it once, tell you what the rule does and where it stops, and not need a dictionary."}],faults:["Opening with 'In law, ...'. Your reader is not in law.","Using a term and defining it two sentences later. Define in the same breath or not at all.","Writing two hundred words of hedging. A limit is not a hedge — say the limit plainly and stop."],model:"A good answer opens on something that happened, not something that is defined. It uses ordinary words throughout, and where a legal term is unavoidable it is glossed in the same sentence rather than the next. It ends by naming what the rule does not cover, which is the part most explanations leave out and the part that actually protects the reader. Test it by giving it to the person you wrote it for. If they can tell it back to you, it works.",source:"Method. The rule about the concrete before the abstract is stated in docs/STYLE.md.",lastVerified:"2026-09-09",verify:"Give it to the person. That is the test, and there is no substitute for it."},{id:"w-irac-first",moduleId:"m06-contract",lessonId:"l-formation",level:"foundation",kind:"problem-answer",title:"Your first problem answer, in four parts",minutes:30,brief:"A short problem is set below. Write an answer in four labelled parts: Issue, Rule, Application, Conclusion. Label them for now — you will stop labelling them once the shape is automatic.",audience:"An examiner who has read forty of these today.",before:["Read the formation lesson. You cannot apply a rule you cannot state.","Read the problem twice before writing anything."],scaffold:[{step:"Find the issue",prompt:"Write the question the dispute turns on, as a question. Usually it starts 'Whether...'.",why:"An answer without a stated issue wanders, because nothing tells it when to stop."},{step:"State the rule",prompt:"State the rule you will apply, and where it comes from — a section, or a case. State it in the abstract, with no names from the problem in it.",why:"Mixing the rule and the facts is the commonest fault in a first answer. Keep them apart and each becomes checkable."},{step:"Apply it",prompt:"Now take the facts one at a time and run them against the rule you just stated. Say which fact satisfies which part of the rule, and which does not.",why:"This is the only part that earns real marks, and the part beginners write least of."},{step:"Conclude",prompt:"Answer the question you asked in the issue. One sentence. Commit.",why:"An answer that will not commit has not applied anything."}],structure:[{part:"Issue",does:"The question, as a question",length:"one sentence"},{part:"Rule",does:"The rule and its source, with no facts in it",length:"two to four sentences"},{part:"Application",does:"Facts run against the rule, one at a time",length:"the bulk of the answer"},{part:"Conclusion",does:"Answers the issue",length:"one sentence"}],rubric:[{band:"Not yet",test:"The rule section restates the facts, or the application section restates the rule."},{band:"Close",test:"All four parts present, but the application is shorter than the rule."},{band:"There",test:"Application is the longest part, each fact is tied to a part of the rule, and the conclusion answers the issue asked."}],faults:["Writing everything you know about the topic. The issue tells you what to leave out; that is what it is for.","An application section that says 'here, the rule is satisfied' without saying which fact satisfies it.","Refusing to conclude because the facts are unclear. Say what follows on the better view, then say what would change it."],model:"A good answer is mostly application. The rule section is short and clean, stated without the problem's names in it, so a reader can check it independently. The application takes each fact that matters and says what it does to the rule — and says so about the facts that cut against the conclusion too, because an answer that only marshals helpful facts is not an analysis. The conclusion commits, in one sentence, to an answer to the question the issue asked.",source:"Method. The four-part shape is the standard one; the emphasis on application is what the marks follow.",lastVerified:"2026-09-09",verify:"Count your words. If Rule is longer than Application, rewrite before checking anything else."},{id:"w-case-note-full",moduleId:"m13-legal-reasoning",lessonId:"l-legal-reasoning",level:"advanced",kind:"case-note",title:"A full case note",minutes:45,brief:"Write a case note on a judgment you have read in the case-reading tier. Six hundred words. It must be usable by someone who has not read the case and does not intend to.",audience:"A colleague who needs to know whether this case helps them, in two minutes.",before:["You need to have actually read the judgment, not the lesson's account of it. Use the case-reading tier.","Have the citation exact, including the court. A note with a loose citation is not usable."],scaffold:[{step:"Facts, but only the ones that mattered",prompt:"Write the facts in under a hundred words. Include only facts the reasoning actually used.",why:"Which facts you leave out shows whether you understood the reasoning. This is the hardest part of the note, not the easiest."},{step:"The issue as the court framed it",prompt:"State the question the court set itself — not the question you would have asked.",why:"Courts often reframe. Where they reframe, that move is frequently the most important thing in the judgment."},{step:"The holding and the reasoning",prompt:"What was decided, and by what route. Distinguish the steps that were necessary from the steps that were commentary.",why:"This is the ratio work from the foundation exercise, now at length."},{step:"What it changes",prompt:"Say what a lawyer can now do that they could not before, or vice versa. If nothing changed, say that.",why:"A note that does not say what changed has not explained why the case is worth knowing."},{step:"Cut to six hundred",prompt:"You will be over. Cut the facts first, then any sentence that praises or criticises without evidence.",why:"The discipline of the limit is the exercise."}],structure:[{part:"Citation line",does:"Case, citation, court, year",length:"one line"},{part:"Facts",does:"Only the operative ones",length:"under 100 words"},{part:"Issue",does:"As the court framed it",length:"one or two sentences"},{part:"Held and why",does:"Outcome and the necessary steps",length:"200 to 250 words"},{part:"Significance",does:"What is now different",length:"100 words"}],rubric:[{band:"Not yet",test:"Facts run over two hundred words, or the note reproduces the court's phrasing rather than restating it."},{band:"Close",test:"Accurate but inert — it says what happened without saying what changed."},{band:"There",test:"A reader who has not opened the case could decide from your note whether it helps them, and would be right."}],faults:["Copying the headnote. The headnote is someone else's work and often frames the case for a different purpose than yours.","Quoting at length. If you find yourself quoting three sentences, you have not understood them well enough to restate them.","Grading the judgment ('the court rightly held'). Say what it held and what follows; leave the applause out."],model:"A good note is short on facts and long on reasoning, because facts are cheap and reasoning is what the reader came for. It restates the court's reasoning in the writer's own words — which is both the honest thing and the only way to prove you followed it. It separates what the result needed from what the judge added. And it ends by saying what is now possible or foreclosed, in terms a working lawyer could act on.",source:"Method. The structure is the conventional one for a case note.",lastVerified:"2026-09-09",verify:"Give the note to someone who has not read the case and ask them what the case decided. If they get it wrong, the note is wrong."},{id:"w-negligence-problem",moduleId:"m07-tort",lessonId:"l-negligence",level:"advanced",kind:"problem-answer",title:"A negligence problem, unlabelled",minutes:45,brief:"Answer the negligence problem in continuous prose. No headings, no labels. The four-part shape should still be there — a reader should be able to point at where each part starts — but you should not have to announce it.",audience:"An examiner who will notice structure without being told about it.",before:["The negligence lesson, and its diagram of the four questions in order.","Have the elements in your head, not on the page in front of you."],scaffold:[{step:"Take the elements in order",prompt:"Duty, breach, causation, remoteness. Deal with them in that order and do not skip one because it is obvious.",why:"An element you skip is an element the examiner cannot give you marks for, and 'obvious' is where the trap usually sits."},{step:"Spend your words where the fight is",prompt:"One of the four is genuinely arguable on these facts. Find it. Give it half your answer.",why:"Equal treatment of four elements signals that you have not identified which one the problem is about."},{step:"Argue the other side",prompt:"On the contested element, write the best case against your own conclusion, then say why it does not win.",why:"This is the difference between an answer and an assertion, and it is the largest single source of marks at this level."},{step:"Remove the labels",prompt:"If you wrote headings, delete them. The prose must carry the structure by itself.",why:"Signposting words — 'the first question is', 'that leaves' — do the work headings were doing, and read like a lawyer rather than a form."}],structure:[{part:"Opening",does:"Names the claim and the question that decides it",length:"two sentences"},{part:"The uncontested elements",does:"Dealt with quickly but not skipped",length:"short"},{part:"The contested element",does:"Argued both ways, then resolved",length:"half the answer"},{part:"Close",does:"States the outcome and what would change it",length:"two sentences"}],rubric:[{band:"Not yet",test:"All four elements get equal space, or one is skipped as obvious."},{band:"Close",test:"The right element is identified but argued only one way."},{band:"There",test:"The contested element dominates, both sides are put, and the resolution says which argument is stronger and why."}],faults:["Reciting the test for duty at length when duty is not in issue on the facts.","'It is submitted that' as a substitute for a reason. Delete the phrase and see whether a reason remains.","Concluding without saying what fact would change the answer. Examiners are testing whether you know what the answer depends on."],model:"A good answer is visibly unbalanced, and correctly so: the element the facts put in issue takes half the space and the other three are disposed of properly but briefly. On the contested element it states the opposing argument at its strongest — not a straw version — and then explains what defeats it. It closes by naming the fact on which the result turns, so a reader knows exactly how fragile the conclusion is.",source:"Method. The elements are those set out in the negligence lesson.",lastVerified:"2026-09-09",verify:"Highlight the contested element in your answer. If it is under a third of the words, you have written a summary rather than an argument."},{id:"w-statutory-argument",moduleId:"m14-statutory-interpretation",lessonId:"l-interpretation",level:"advanced",kind:"argument",title:"Argue a section two ways",minutes:40,brief:"Take one section of a statute the course has already used. Write the strongest argument that it means X, and then the strongest argument that it means not-X. Equal length. Then say which you think is right and why.",audience:"A judge who has both parties in front of them.",before:["The interpretation lesson, and the lesson on aids to construction.","The actual words of the section, in front of you, from the statute itself."],scaffold:[{step:"Copy out the words",prompt:"Write out the operative words of the section by hand. Underline every word that could carry the result.",why:"Arguments about statutes are won on particular words. You cannot argue about words you have not looked at closely."},{step:"Build side X",prompt:"Ordinary meaning first, then structure — what the surrounding sections imply — then purpose. Use aids in that order.",why:"The order is the discipline. An argument that reaches for purpose before it has dealt with the words is skipping the strongest ground."},{step:"Build side not-X",prompt:"Same order, same length. Make it genuinely strong. If you cannot, you have misunderstood one side.",why:"You do not know what a provision means until you know the best case against your reading."},{step:"Decide",prompt:"Say which is right, and name the specific thing that tips it — a word, a structural point, a consequence.",why:"'On balance' with no named tipping point is a refusal to decide dressed as judgement."}],structure:[{part:"The words",does:"The operative text and the words in dispute",length:"short"},{part:"Case for X",does:"Ordinary meaning, then structure, then purpose",length:"a third"},{part:"Case for not-X",does:"Same, equally strong",length:"a third"},{part:"Resolution",does:"Which wins, and the one thing that decides it",length:"a third"}],rubric:[{band:"Not yet",test:"One side is a straw argument, or the two sides are different lengths by more than half."},{band:"Close",test:"Both sides are fair, but the resolution appeals to 'balance' without naming what tips it."},{band:"There",test:"Both sides are genuinely arguable, and the resolution identifies a specific word, structural feature or consequence that decides it."}],faults:["Starting with what the section is 'obviously for'. Purpose is an aid, not a shortcut past the words.","Treating a dictionary as decisive. It tells you the range of ordinary meanings, not which one a statute uses.","Arguing from what the law should be. That is a different exercise and it belongs in the essay."],model:"A good answer treats both readings as if it were paid to advance each. It works words, then structure, then purpose, in that order on both sides, so the two arguments are comparable. The resolution does not average the two — it identifies the specific feature that one reading explains and the other does not, and rests on that. Naming the tipping point is the whole skill; everything before it is preparation.",source:"Method. The order of aids follows the statutory interpretation lessons.",lastVerified:"2026-09-09",verify:"Cover your resolution and give both arguments to someone else. If they cannot tell which side you actually hold, the two sides are properly balanced."},{id:"w-llb-essay",moduleId:"m08-property",lessonId:"l-torrens",level:"llb",kind:"essay",title:"An essay that takes a position",minutes:90,brief:"Fifteen hundred words. Take a contested question from land law that the course has raised and argue a position on it. Not a survey of views — a position, defended, with the strongest objection answered.",audience:"A marker who has read the same survey essay thirty times and will reward an argument.",before:["The Torrens lesson and its case reading. You need to have read at least one judgment in full.","Decide your position before you start writing. An essay that discovers its position in the last paragraph reads exactly like one."],scaffold:[{step:"Write the thesis as one sentence",prompt:"One sentence, arguable, that someone competent could disagree with. Put it at the top of your page and keep it visible.",why:"If nobody could disagree, it is a description and not a thesis. The visible sentence is what stops the essay drifting."},{step:"Map the ground you must cover",prompt:"List the three or four things a reader must accept for your thesis to hold. Those are your sections.",why:"This builds a structure out of the argument rather than out of the topic — which is why survey essays feel shapeless."},{step:"Write the objection first",prompt:"Before drafting your own case, write the strongest argument against your thesis in full.",why:"Written last, the objection is always weak. Written first, it shapes the essay honestly and often changes the thesis."},{step:"Draft the case",prompt:"Now make your argument, section by section, answering the objection where it bites rather than in a separate paragraph at the end.",why:"An objection quarantined in one paragraph has been acknowledged, not answered."},{step:"Cut a fifth",prompt:"Remove three hundred words. Take them from description of what the law is, not from argument about what follows.",why:"At this level, description is what a marker assumes you know. Argument is what is being assessed."}],structure:[{part:"Thesis",does:"States the position in one arguable sentence",length:"opening paragraph"},{part:"Ground",does:"The minimum law the argument needs, no more",length:"a fifth"},{part:"Argument",does:"Each claim the thesis rests on, in turn",length:"half"},{part:"Objection answered",does:"The best case against, met on its merits",length:"a fifth"},{part:"Close",does:"What follows if the thesis holds",length:"a paragraph"}],rubric:[{band:"Not yet",test:"The essay surveys positions without adopting one, or the thesis appears only in the conclusion."},{band:"Close",test:"A clear thesis, but the objection is answered in a single closing paragraph rather than where it bites."},{band:"There",test:"A stated thesis, argued in sections that follow from it, with the strongest objection met on its merits and the essay changed by having met it."}],faults:["Describing the law for a thousand words and arguing for five hundred. At this level the balance is the assessment.","An objection chosen because it is easy to answer. The marker knows what the strong objection is.","Citing more authority to make an argument look stronger. One case that does the work beats five that gesture."],model:"A good essay is an argument with law in it, not a description with an opinion at the end. Its sections come from the claims the thesis needs rather than from the topic's conventional divisions. It states the strongest counter-argument in a form its proponent would accept, and answers it at the point where it bites. Crucially, it shows signs of having been changed by that counter-argument — a qualification, a narrower claim, a concession — because an essay that meets a real objection and emerges untouched has not really met it.",source:"Method. The doctrinal ground is the Torrens lesson and its case reading.",lastVerified:"2026-09-09",verify:"Show your thesis sentence to someone and ask them to argue against it. If they cannot, it is not a thesis."},{id:"w-llb-advice",moduleId:"m09-company",lessonId:"l-members-remedies",level:"llb",kind:"advice",title:"A letter of advice, with the bad news in it",minutes:75,brief:"A client has come to you about their position in a company. Write them a letter of advice: what their position is, what they can do, what each option costs and risks, and what you recommend. Eight hundred words. They are not a lawyer.",audience:"A real client who will make a decision based on this and cannot afford a wrong one.",before:["The members' remedies lesson.","Decide what you would actually advise before you start. A letter that is still deciding is a letter that hedges."],scaffold:[{step:"Answer the question first",prompt:"First paragraph: what you advise. Not the background, not the law. The answer.",why:"A client who must read nine hundred words before finding out where they stand is being served by the writer's convenience, not their own."},{step:"Set out the position",prompt:"What their legal position is, in plain words. Where a legal term is unavoidable, define it in the same sentence.",why:"This is the plain-explanation exercise again, under pressure and at length."},{step:"Lay out the options",prompt:"Each realistic option, with what it costs, how long it takes, and what can go wrong. Include doing nothing.",why:"Doing nothing is always an option and is sometimes the right one. An advice letter that omits it has narrowed the client's choice without telling them."},{step:"State the risks plainly",prompt:"Say what could go wrong, in the same plain words as the rest. Do not soften it and do not bury it in the middle.",why:"Bad news moved to the middle and written in longer words is bad news the client will miss, and they will not thank you later."},{step:"Recommend, and say what would change it",prompt:"Recommend one course. Then name the fact that, if different, would change your recommendation.",why:"It tells the client what to come back to you about, which is the most useful sentence in the letter."}],structure:[{part:"The answer",does:"What you advise, up front",length:"one paragraph"},{part:"Your position",does:"The legal position in plain words",length:"a quarter"},{part:"Options",does:"Each one, with cost, time and risk — including doing nothing",length:"a third"},{part:"Risks",does:"What can go wrong, stated plainly",length:"a paragraph"},{part:"Recommendation",does:"One course, and what would change it",length:"a paragraph"}],rubric:[{band:"Not yet",test:"The advice appears at the end, or legal terms are used without definition, or no option is recommended."},{band:"Close",test:"Clear and well organised, but the risks are softened or the 'do nothing' option is missing."},{band:"There",test:"The client learns where they stand in the first paragraph, understands every word, sees every real option with its cost, and knows what would change the advice."}],faults:["Hedging so heavily that no advice is given. A client who wanted a list of possibilities did not need a lawyer.","Writing to protect yourself rather than to inform them. It is visible, and it is the thing clients most resent.","Assuming the client will ask if they do not understand. Most will not."],model:"A good letter answers in its first paragraph and spends the rest earning that answer. Every legal term is glossed where it appears. The options are real ones, costed and timed, and include doing nothing. The bad news is in plain words and in a prominent place. The recommendation is singular and the letter names the fact that would change it — which is both honest and the sentence that tells the client when to come back.",source:"Method. The doctrinal ground is the members' remedies lesson.",lastVerified:"2026-09-09",verify:"Read only your first paragraph. Does the client now know what you advise? If not, rewrite it before touching anything else."},{id:"w-llb-submission",moduleId:"m12-administrative",lessonId:"l-judicial-review",level:"llb",kind:"argument",title:"Written submissions on a review ground",minutes:90,brief:"Write submissions for an applicant seeking judicial review, on one ground. Twelve hundred words. You are writing for a judge who will read this before hearing anyone speak.",audience:"A judge with a full list, reading this cold, who will decide whether you have an arguable case.",before:["The judicial review lesson, and the natural justice lesson.","Pick one ground and commit to it. Submissions that run three grounds badly lose to submissions that run one well."],scaffold:[{step:"State the relief sought",prompt:"Open with exactly what you want the court to do. Not what you say — what order you seek.",why:"A judge reads to find out what is being asked for. Making them hunt for it is the first thing that costs you."},{step:"State the ground in one sentence",prompt:"Name the ground and the decision it attacks, in a sentence.",why:"If it takes a paragraph, you have not decided what your case is."},{step:"Set out the law, minimally",prompt:"The smallest statement of law your argument needs. Resist the survey.",why:"The judge knows the law better than you do. What they do not know is your case."},{step:"Apply it to the decision under challenge",prompt:"Point to the specific thing the decision-maker did or failed to do, and tie it to the ground.",why:"Judicial review is about the decision-making, not the decision's merits. Vague submissions slide into arguing the merits and lose."},{step:"Meet the answer",prompt:"State the respondent's best answer and deal with it.",why:"The judge will think of it. Better that they read your answer to it than form their own."},{step:"Close on relief",prompt:"Return to the order sought and say why it is the appropriate remedy.",why:"Remedy is discretionary. An applicant who never addresses it invites a court to find the ground made out and refuse relief anyway."}],structure:[{part:"Relief sought",does:"The order asked for, exactly",length:"opening"},{part:"The ground",does:"Named, in a sentence",length:"one sentence"},{part:"Law",does:"The minimum needed",length:"a fifth"},{part:"Application",does:"What the decision-maker did, tied to the ground",length:"half"},{part:"The answer met",does:"Respondent's best point, dealt with",length:"a fifth"},{part:"Relief",does:"Why this remedy",length:"a paragraph"}],rubric:[{band:"Not yet",test:"The submissions argue that the decision was wrong on its merits rather than that the decision-making was flawed."},{band:"Close",test:"The ground is properly run, but relief is never addressed as a separate question."},{band:"There",test:"One ground, tied to identified conduct of the decision-maker, the respondent's best answer met, and relief argued as its own question."}],faults:["Running every ground you can think of. It reads as having no confidence in any of them.","Reciting the law of judicial review at length. The judge applies it weekly.","Forgetting that relief is discretionary, and so writing as though establishing the ground ends the matter."],model:"Good submissions tell the judge in the first lines what order is sought and on what ground, then spend their length on the only thing the judge does not already know: what this decision-maker actually did, and why that engages the ground. They state the law thinly and the facts thickly. They put the respondent's best answer in the applicant's own document and deal with it there. And they treat relief as a separate question requiring its own argument, because a court that finds a ground made out may still refuse the remedy.",source:"Method. The doctrinal ground is the judicial review and natural justice lessons.",lastVerified:"2026-09-09",verify:"Read the first three lines. Do they say what order is sought and on what ground? If not, nothing after them will rescue it."},{id:"w-llb-exam-problem",moduleId:"m10-evidence",lessonId:"l-burden",level:"llb",kind:"problem-answer",title:"An exam-length problem, under a clock",minutes:60,brief:"One problem, forty-five minutes of writing, no notes. Then fifteen minutes marking your own answer against the rubric before you look at anything else.",audience:"An examiner, and then yourself as a harsher one.",before:["Everything in the evidence module. This is a closed-book exercise and the preparation is the point.","Set an actual timer. An exam answer written in ninety comfortable minutes teaches you nothing about writing one in forty-five."],scaffold:[{step:"Five minutes: plan",prompt:"Do not write prose yet. List the issues in the order you will take them and mark which one is the real fight.",why:"Five minutes of planning buys more marks than five minutes of extra writing, and it is the first thing abandoned under pressure."},{step:"Thirty-five minutes: write",prompt:"Write continuously. If you get stuck on an issue, write your best view and move on.",why:"An unfinished answer loses more than a weak paragraph does. Finishing is a skill and it is trained here."},{step:"Five minutes: close",prompt:"Make sure every issue you listed has a conclusion, even a short one.",why:"The commonest way to lose marks under time is to run out before concluding on issues you had already analysed."},{step:"Fifteen minutes: mark yourself",prompt:"Against the rubric, honestly. Write one line on what you would do differently before you look at any answer or note.",why:"Self-marking before comparison is what makes the comparison useful. Marking after reading a model measures your memory, not your judgement."}],structure:[{part:"Plan",does:"Issues in order, the real fight marked",length:"not submitted"},{part:"Answer",does:"Each issue analysed and concluded",length:"45 minutes of writing"},{part:"Self-mark",does:"Rubric applied to your own work, before comparison",length:"15 minutes"}],rubric:[{band:"Not yet",test:"The answer stops before the last issue, or issues are raised and never concluded."},{band:"Close",test:"Complete, but time was spread evenly rather than concentrated on the issue in dispute."},{band:"There",test:"Every issue concluded, the contested one given the most space, and the self-mark identifies a specific fault rather than a general one."}],faults:["Writing an introduction. In a timed problem it earns nothing and costs three minutes.","Perfecting the first issue and abandoning the last. Marks are spread across issues, not concentrated in the first.","A self-mark that says 'could be better'. Name the fault or the exercise did nothing."],model:"A good answer under time looks different from a good answer without it, and knowing the difference is the skill. It has no introduction. It reaches the contested issue early and spends its length there. Every issue raised is concluded, some in a single sentence. The self-mark afterwards names one specific, repeatable fault — not a mood — because the point of the fifteen minutes is to produce something you can act on next time.",source:"Method. The doctrinal ground is the evidence module; the timing follows the exam technique lesson.",lastVerified:"2026-09-09",verify:"Compare your self-mark with how you feel about the answer a day later. If they disagree, trust the rubric."}],fe=[{id:"st-cla-s3",moduleId:"m01-malaysian-legal-system",lessonId:"l-sources",act:"Civil Law Act 1956",actId:"civil-law-act-1956",provision:"Section 3",find:"The Attorney General's Chambers publishes the Laws of Malaysia online without charge; search for the Act by name and open the current reprint. A law library will have it in print. Read the section itself rather than a summary of it, including any provisos.",why:"This one section is why Malaysian law contains English common law and equity at all. Everything the course says about received law rests on it, and the qualifications inside it are the part most readers skip.",read:[{passage:"The opening words that apply the common law and rules of equity, and the dates attached to them.",look_for:"There is more than one date. Note which territory each belongs to, and write down what that means for a case decided in England after the relevant date."},{passage:"The qualifying words about local circumstances.",look_for:"This is the phrase that lets Malaysian law diverge. Ask what work it does that the dates do not, and try to state the difference in one sentence."},{passage:"Anything subjecting the section to other written law.",look_for:"Follow the order of priority it creates. Where a Malaysian statute covers the ground, ask whether received law reaches it at all."}],questions:[{q:"State in one sentence what this section did, and one thing it did not do.",model:"A good answer names both halves. It applied English common law and equity as administered at stated dates — and it did not make Malaysian law a moving copy of English law, because the reception is fixed at those dates and qualified twice over. An answer giving only the first half describes reception without its limits, which is the misunderstanding this section most often causes."},{q:"A litigant cites an English decision from 2019. What is the correct way to describe its status?",model:"A good answer avoids both errors: it is not binding, and it is not irrelevant. It postdates the reception, so it is not part of Malaysian law by force of this section; a Malaysian court may find its reasoning persuasive and adopt it, and that adoption is what a litigant must point to. The distinction between authority and persuasion is the whole point."},{q:"What is the difference between the date limit and the local circumstances limit?",model:"A good answer separates two kinds of limit. The date is a cut-off in time and is mechanical: anything after it is not received. Local circumstances is a limit in substance and requires judgement: a rule received in principle may still not apply here if conditions differ. The first can be checked from a calendar, the second cannot."}],trap:"Treating reception as meaning English law simply is Malaysian law. The section makes it a source, at a date, subject to conditions — and each of those three words is doing work.",source:"Provision cited in the source fields of the legal system, tort, property and equity lessons in this corpus.",verify:"Read the current reprint from the Attorney General's Chambers. Confirm the reception dates for the States of Malaya, Sabah and Sarawak from the section itself rather than from this page.",lastVerified:"2026-09-10"},{id:"st-fc-art121-1a",moduleId:"m17-syariah",lessonId:"l-syariah-jurisdiction",act:"Federal Constitution",actId:"federal-constitution",provision:"Article 121(1A)",find:"The Federal Constitution is published by the Attorney General's Chambers and is available online without charge; open Part IX and read Article 121 whole, not just the sub-article. Print copies are inexpensive and widely sold.",why:"One sentence that reorganised the relationship between two court systems. It is short, it is constantly paraphrased, and the paraphrases are usually wrong — which makes it the best possible exercise in reading words rather than summaries.",read:[{passage:"Article 121(1) and (1A) together, in that order.",look_for:"Read (1) first so you know what (1A) is carving out of. The clause only makes sense against the jurisdiction it removes."},{passage:"The words identifying whose jurisdiction is removed and in respect of what.",look_for:"Two things are named — a set of courts, and a class of matters. Underline both. The class is defined by reference to another court's jurisdiction, which is where the difficulty starts."},{passage:"The absence of any words about hierarchy or appeal.",look_for:"Notice what the clause does not say. That absence is the answer to the commonest misstatement of it."}],questions:[{q:"Write the clause's effect in one sentence, without using the words higher, superior or supreme.",model:"A good answer says the civil High Courts have no jurisdiction in respect of matters within the jurisdiction of the Syariah courts. It is a withdrawal of jurisdiction from one set of courts over a defined class, and nothing else. If your sentence needed a word about rank, you were describing an inference rather than the clause."},{q:"The clause defines the excluded matters by reference to Syariah court jurisdiction. What does that make the real question in any dispute?",model:"A good answer identifies the circularity that is actually a signpost: because the exclusion is defined by the other court's jurisdiction, the working question is never which court ranks higher but whether this matter falls within Syariah jurisdiction at all — which is answered by the State List and the person's religion, not by this clause."},{q:"Why is it wrong to say this clause gives Syariah courts power?",model:"A good answer keeps grant and removal apart. Their power comes from State law made under the Ninth Schedule; this clause removes a competing jurisdiction. Remove a rival's power and you have not enlarged your own, though the practical effect may resemble it — and the distinction decides cases where a matter is outside Syariah jurisdiction."}],trap:"Reading it as a ranking of courts. It withdraws jurisdiction over a defined class of matters and says nothing about seniority, appeals, or which court may correct the other.",source:"Provision cited in the source fields of the Syariah and family lessons in this corpus.",verify:"Read Article 121 in the current reprint. Check the Ninth Schedule State List entry on Islamic law separately, since the class of excluded matters depends on it.",lastVerified:"2026-09-10"},{id:"st-fc-art5",moduleId:"m05-criminal-procedure",lessonId:"l-criminal-procedure",act:"Federal Constitution",actId:"federal-constitution",provision:"Article 5, especially clauses (3) and (4)",find:"In the Federal Constitution, Part II, published free by the Attorney General's Chambers. Read the whole Article; the clauses are short and the sequence matters.",why:"The clock and the two rights that run from an arrest. This is the provision a person actually needs at the moment they are least able to look it up, and the one the criminal procedure lessons rest on.",read:[{passage:"Clause (3), and the two distinct things it provides for.",look_for:"Separate them: being informed of the grounds, and access to a legal practitioner. They are different rights with different triggers, and answers that merge them lose marks."},{passage:"Clause (4) and the period it names.",look_for:"Note what starts the clock and what must happen before it expires. Ask what is excluded from the computation, if anything, and where you would look to find out."},{passage:"Any exceptions or qualifications elsewhere in the Article.",look_for:"Constitutional rights here come with their own carve-outs. Read to the end before concluding what the rule is."}],questions:[{q:"What event starts the period in clause (4), and why does that matter more than the time of questioning?",model:"A good answer identifies arrest — the moment the person is no longer free to leave — rather than arrival at a station or the start of an interview. It matters because the police control when questioning begins and do not control when the arrest happened, so tying the clock to the arrest is what makes it a limit rather than a formality."},{q:"A detainee is told the grounds of arrest six hours later. Which clause is engaged and what is the argument?",model:"A good answer engages clause (3) and argues from the word the clause uses about timing rather than from general fairness. The strength of the argument depends on that word, so an answer that does not quote or paraphrase it precisely has not engaged the provision — which is why this exercise asks you to read it rather than recall it."}],trap:"Working from the twenty-four hours alone and forgetting the rights in clause (3). Most real complaints involve both, and an answer that runs only the clock misses half the case.",source:"Provision cited in the source fields of the criminal procedure lessons in this corpus.",verify:"Read Article 5 in the current reprint, and check the Criminal Procedure Code for the machinery that gives effect to it. This page gives no time computation rules; find them in the text.",lastVerified:"2026-09-10"},{id:"st-ia-s17a",moduleId:"m14-statutory-interpretation",lessonId:"l-interpretation",act:"Interpretation Acts 1948 and 1967",actId:"interpretation-acts",provision:"Section 17A",find:"Published by the Attorney General's Chambers as Act 388. The section is one sentence; read it in the Act rather than in a textbook's paraphrase, because the paraphrases differ from each other.",why:"The statutory direction to prefer a purposive construction. Almost every interpretation argument in Malaysian practice runs through it, and it is short enough to read in a minute and argue about for a career.",read:[{passage:"The whole section, twice.",look_for:"First for what it directs. Second for its conditions — what has to be true before the direction bites."},{passage:"The words describing what is preferred, and to what.",look_for:'It sets up a comparison. Name both sides of it precisely; an answer that says only "purpose wins" has not read the comparison.'}],questions:[{q:"Does this section let a court prefer purpose over clear words? Answer from the text.",model:"A good answer works the words rather than reaching for a slogan. The section directs a preference between constructions, which presupposes that more than one construction is available. What follows where only one construction is available is the argument, and the honest answer says the section's own terms are the place that argument starts — not a textbook's summary of it."},{q:"How does this section change the order in which you argue an interpretation point?",model:"A good answer connects the provision to method. With a statutory direction available, purpose is not a last resort reached after ordinary meaning fails; it is something a court is directed to prefer between constructions. But it still needs constructions to choose between, so the work of establishing an ambiguity comes first — which is why the ordering in the lessons puts words, then structure, then purpose."}],trap:"Citing the section as though it settled every interpretation dispute. It directs a preference between constructions, and the fight is usually about whether there is more than one.",source:"Provision cited in the source fields of the statutory interpretation lessons in this corpus.",verify:"Read s 17A in the current reprint of Act 388, and check whether any later amendment has altered it before relying on this.",lastVerified:"2026-09-10"},{id:"st-ea-burden",moduleId:"m10-evidence",lessonId:"l-burden",act:"Evidence Act 1950",actId:"evidence-act-1950",provision:"Sections 101 to 106",find:"In the Evidence Act 1950, published free by the Attorney General's Chambers. Read the run of sections together rather than one at a time; they are a scheme and each is written against the others.",why:"The burden of proof is where most evidence answers go wrong, and the reason is almost always that the reader learned a slogan instead of a scheme. These sections are the scheme.",read:[{passage:"Sections 101 and 102 together.",look_for:"They are not saying the same thing twice. Work out what each adds, and write down the difference before reading on."},{passage:"Section 103.",look_for:"Ask what shifts and what does not. The distinction between the burden of proof and the burden of adducing evidence lives here."},{passage:"Sections 105 and 106, and their illustrations.",look_for:"These are the exceptions people misremember. Read the illustrations — they were enacted with the sections and they are the clearest statement of scope you will find."}],questions:[{q:"State the difference between the two burdens in one sentence each, using the sections rather than a textbook phrase.",model:"A good answer distinguishes the burden that stays where the statute puts it from the burden that moves as evidence is led, and grounds each in a section rather than in the phrases legal burden and evidential burden — which are useful shorthand and are not what the Act says. Naming the section is what makes the answer checkable."},{q:"Why do the illustrations matter more here than in most Acts?",model:"A good answer notes that the illustrations were enacted with the sections and show the intended scope concretely, which is exactly what is contested about ss 105 and 106. A reader who skips them is choosing to argue about scope while ignoring the drafter's own examples of it."}],trap:'Reciting "he who asserts must prove" and stopping. The Act sets out a scheme with exceptions, and the exceptions are where the marks and the real disputes are.',source:"Provisions cited in the source fields of the evidence lessons in this corpus.",verify:"Read ss 101 to 106 with their illustrations in the current reprint. Check whether the Act's numbering has changed before citing a section number in an exam.",lastVerified:"2026-09-10"},{id:"st-nlc-s340",moduleId:"m08-property",lessonId:"l-torrens",act:"National Land Code",actId:"national-land-code",provision:"Section 340",find:"In the National Land Code, published by the Attorney General's Chambers. Read the whole section including every subsection and the proviso; the proviso is the part the arguments are about.",why:"Indefeasibility of title, and the exceptions to it, in one section. The property lessons and the leading cases all turn on how its subsections fit together, so reading it whole is the difference between following those cases and taking someone's word for them.",read:[{passage:"Subsection (1), stating the general position.",look_for:"Note precisely whose title is protected and against what. The generality here is what the later subsections cut into."},{passage:"Subsection (2) and its list.",look_for:"These are the circumstances in which title is not indefeasible. Take them one at a time and ask what each is aimed at."},{passage:"The proviso to subsection (3).",look_for:"Read it slowly and work out which words carry the result. This proviso is the whole of a well-known controversy, and the controversy is about its grammar as much as its policy."}],questions:[{q:"Explain, from the section alone, how a purchaser can be protected where their predecessor's title was defective.",model:"A good answer traces the route through the subsections rather than naming a doctrine. It should identify where the protection comes from, what conditions attach to it, and which words in the proviso do that work. If your answer uses the phrase deferred indefeasibility without pointing at the words that produce it, you have named a conclusion and skipped the reasoning."},{q:"Why is it important that you read the proviso rather than a summary of it?",model:"A good answer connects to the case law: two Federal Court decisions read this proviso differently, and the disagreement is about what the words attach to. A summary reports whichever reading its author accepted, so a reader working from a summary cannot see what the argument was about — and cannot assess a later case that revisits it."}],trap:"Learning the labels — immediate and deferred indefeasibility — without being able to point at the words producing either. The labels are a shorthand for a reading of this section, not a substitute for it.",source:"Provision cited in the source fields of the property lessons in this corpus.",verify:"Read s 340 in the current reprint. The National Land Code has been amended; confirm the current text and numbering before relying on this.",lastVerified:"2026-09-10"},{id:"st-ca-s213",moduleId:"m09-company",lessonId:"l-company",act:"Companies Act 2016",actId:"companies-act-2016",provision:"Section 213",find:"In the Companies Act 2016, published free by the Attorney General's Chambers. Read both subsections together and note the different language each uses.",why:"Directors' duties, stated by statute rather than left to case law. The two subsections are drafted differently on purpose, and noticing that is the exercise.",read:[{passage:"Subsection (1).",look_for:"Identify whose interests are named and what mental element the words import. Ask whether the test it sets is one a court assesses from inside the director's head or from outside it."},{passage:"Subsection (2).",look_for:"Compare the language with (1). The standard is expressed differently, and the difference is the point."}],questions:[{q:"One subsection sets a largely subjective standard and the other a largely objective one. Which is which, and what words tell you?",model:"A good answer points at the words rather than asserting the labels. It should name the phrase in each subsection that carries the standard, and say what follows in practice: a director's honest belief matters more under one, and what a reasonable person in that position would have done matters more under the other. The practical consequence is what turns a label into an answer."},{q:"Why does it matter that these duties are in statute rather than only in case law?",model:"A good answer gives at least one consequence that follows from the form: the words are fixed and can be construed like any other provision, they apply regardless of what a company's constitution says, and breach engages whatever the Act attaches to breach. An answer that says only that codification makes things clearer has not said what changes."}],trap:"Reciting duties of good faith and care from general company law without checking what this Act actually says. The statutory formulation is the starting point in Malaysia, and it may not match a textbook written for another jurisdiction.",source:"Provision cited in the source fields of the company lessons in this corpus.",verify:"Read s 213 in the current reprint and check the sections dealing with consequences of breach, which this page does not address.",lastVerified:"2026-09-10"},{id:"st-cta-s26",moduleId:"m06-contract",lessonId:"l-consideration",act:"Contracts Act 1950",actId:"contracts-act-1950",provision:"Section 26 and its illustrations",find:"In the Contracts Act 1950, published free by the Attorney General's Chambers. Read the section with its illustrations, which were enacted with it.",why:"Malaysian contract law departs from English law here, and this section is where. A reader who learns consideration from an English textbook will get this wrong, which makes it worth reading in the original.",read:[{passage:"The opening general rule.",look_for:"State it in your own words before reading further, then check your sentence against the words."},{passage:"The exceptions that follow.",look_for:"Take each separately and ask what circumstance it is aimed at. One of them is the well-known departure from English law; identify which and why it matters."},{passage:"The illustrations.",look_for:"They show the intended reach concretely. Where an illustration surprises you, that is the point at which your prior understanding came from somewhere other than this Act."}],questions:[{q:"Identify the exception that most clearly departs from the English position, and state the practical difference.",model:"A good answer names the exception and then says what a party can do here that they could not do in England — that is the practical difference, and it is what an examiner is testing. Naming the exception without stating its effect describes a difference without showing that you understand it."},{q:"How should an illustration be used in an answer?",model:"A good answer treats illustrations as part of the enacted text showing intended scope, not as decoration or as case law. They are strong support for a reading of the section, and they are not authority for propositions beyond it."}],trap:"Importing English consideration doctrine wholesale. The Act sets out its own rule with its own exceptions, and s 3 of the Civil Law Act does not override a Malaysian statute that covers the ground.",source:"Provision cited in the source fields of the contract lessons in this corpus.",verify:"Read s 26 with its illustrations in the current reprint before relying on this, and check the surrounding sections for the definitions it uses.",lastVerified:"2026-09-10"},{id:"st-pc-homicide",moduleId:"m04-criminal-law",lessonId:"l-homicide",act:"Penal Code",actId:"penal-code",provision:"Sections 299 and 300",find:"In the Penal Code, published free by the Attorney General's Chambers. Read the two sections side by side, with their explanations and illustrations; reading either alone is what makes this topic confusing.",why:"The line between culpable homicide and murder is drawn by two sections whose wording overlaps deliberately. Almost every difficulty students have here comes from meeting them one at a time.",read:[{passage:"Section 299, and each limb of it.",look_for:"Number the limbs as you read. You will need to refer to them individually and the section does not number them for you."},{passage:"Section 300, clause by clause.",look_for:"Set each clause of 300 against the limb of 299 it corresponds to. The correspondence is the architecture of the offence, and seeing it is the whole exercise."},{passage:"The explanations and illustrations attached to both.",look_for:"They resolve several of the questions the bare words raise. Read them as part of the text, because they were enacted as part of it."}],questions:[{q:"Set out the relationship between the two sections in three sentences.",model:"A good answer explains that one defines a wider offence and the other identifies when conduct within it amounts to the graver one, so the clauses map onto the limbs rather than standing apart. Getting the direction of the relationship right matters — an answer that treats them as two unrelated definitions will misapply both."},{q:"Why does this topic reward reading the illustrations more than most?",model:"A good answer notes that the distinctions turn on fine gradations of intention and knowledge, which are hard to state abstractly and easy to show by example — which is what the illustrations do. They are also enacted text, so they are evidence of intended scope rather than one commentator's view."}],trap:"Learning the clauses of s 300 as a list without mapping them back to s 299. The mapping is what the sections are for and it is where problem questions are decided.",source:"Provisions cited in the source fields of the criminal law lessons in this corpus.",verify:"Read ss 299 and 300 with explanations and illustrations in the current reprint, and check the exceptions to s 300 separately — this page does not deal with them.",lastVerified:"2026-09-10"},{id:"st-fc-art4",moduleId:"m03-constitutional",lessonId:"l-basic-structure",act:"Federal Constitution",actId:"federal-constitution",provision:"Article 4(1)",find:"The opening of Part I of the Federal Constitution, published free by the Attorney General's Chambers. It is one sentence; read the rest of Article 4 with it, because the later clauses qualify how it is invoked.",why:"Constitutional supremacy in a single sentence, and the foundation every constitutional argument in the course stands on. It is also a good lesson in how much a short provision leaves unsaid.",read:[{passage:"Clause (1) itself.",look_for:"Note what is declared supreme, what happens to inconsistent law, and — the part usually missed — the words describing the extent of the invalidity."},{passage:"The remaining clauses of Article 4.",look_for:"They restrict how and where the supremacy may be raised. Ask what practical difference those restrictions make to a litigant."}],questions:[{q:"The clause says inconsistent law is void. To what extent, and why does that qualification matter?",model:"A good answer catches that invalidity runs to the extent of the inconsistency rather than to the whole law, and explains the consequence: a court may strike down part of a provision and leave the rest standing, so an argument should identify precisely what is inconsistent rather than attacking a statute wholesale. That is also why severability is worth pleading in the alternative."},{q:"Does Article 4(1) by itself tell you which court may declare a law void, or how?",model:"A good answer says no and points to where those answers live — the later clauses of Article 4 and the provisions on jurisdiction. The useful observation is that a declaration of supremacy is not self-executing: something else must supply the forum and the procedure, and a litigant who cites only 4(1) has not yet said how to get there."}],trap:"Quoting the clause and stopping. Supremacy is the premise of a constitutional argument, not the argument — the work is showing the inconsistency and identifying its extent.",source:"Provision cited in the source fields of the constitutional lessons in this corpus.",verify:"Read Article 4 whole in the current reprint. This page does not address the amendment power or the basic structure debate; both are separate and contested.",lastVerified:"2026-09-10"}];export{me as _,ee as a,te as b,X as c,ae as d,ie as e,ne as f,se as g,re as h,de as i,he as j,ce as k,Q as l,le as m,ue as n,pe as o,oe as p,fe as s};
